window.__TIFTN_META__={"sections":{"I":{"title":"ТИРИК ҲАЙВОНЛАР: КЕЛИБ ЧИҚИШИ ҲАЙВОНЛАРГА МАНСУБ МАҲСУЛОТЛАР","notes":["1. Ушбу бўлимда ҳайвонларнинг маълум бир жинси ёки турига берилган ҳар қандай ҳавола, агар бошқача кўрсатилмаган бўлса, шу жинс ёки тур ёш ҳайвонларга ҳам тегишли.","2. Бутун номенклатурада “қуритилган” маҳсулотлар атамаси, агар бошқача кўрсатилмаган бўлса, сувсизланиш, буғланиш ёки музлатиш орқали қуритилган маҳсулотларни ҳам англатади."],"excl":[]},"II":{"title":"КЕЛИБ ЧИҚИШИ ЎСИМЛИКЛАРГА МАНСУБ МАҲСУЛОТЛАР","notes":[],"excl":[]},"III":{"title":"ҲАЙВОНОТ, ЎСИМЛИК ЁКИ МИКРОБИОЛОГИК КЕЛИБ ЧИҚИШГА ЭГА ЁҒ ВА МОЙЛАР ҲАМДА","notes":[],"excl":[]},"IV":{"title":"ТАЙЁР ОЗИҚ-ОВҚАТ МАҲСУЛОТЛАРИ; АЛКОГОЛЛИ ВА АЛКОГОЛСИЗ ИЧИМЛИКЛАР ВА УКСУС","notes":[],"excl":[]},"V":{"title":"МИНЕРАЛ МАҲСУЛОТЛАР","notes":[],"excl":[]},"VI":{"title":"КИМЁ ВА УНГА БОҒЛИҚ БЎЛГАН САНОАТ ТАРМОҚЛАРИ МАҲСУЛОТЛАРИ","notes":[],"excl":[]},"VII":{"title":"ПЛАСТМАССАЛАР ВА УЛАРДАН ТАЙЁРЛАНГАН ТОВАРЛАР, КАУЧУК, РЕЗИНА ВА УЛАРДАН","notes":[],"excl":[]},"VIII":{"title":"ИШЛОВ БЕРИЛМАГАН ТЕРИ, ЧАРМ, ТАБИИЙ МЎЙНА ВА УЛАРДАН ТАЙЁРЛАНГАН МАҲСУЛОТЛАР;","notes":[],"excl":[]},"IX":{"title":"ЁҒОЧ ВА УНДАН ТАЙЁРЛАНАДИГАН БУЮМЛАР: ПИСТА КЎМИР; ПЎКАК ВА УНДАН","notes":[],"excl":[]},"X":{"title":"ЁҒОЧДАН ЁКИ БОШҚА ТОЛАЛИ ЦЕЛЛЮЛОЗА МАТЕРИАЛЛАРИДАН МАССА; ҚАЙТА ТИКЛАНУВЧАН","notes":[],"excl":[]},"XI":{"title":"ТЎҚИМАЧИЛИК МАТЕРИАЛЛАРИ ВА ТЎҚИМАЧИЛИК БУЮМЛАРИ","notes":[],"excl":[]},"XII":{"title":"ПОЙАБЗАЛ, БОШ КИЙИМ, СОЯБОН, ҚУЁШ СОЯБОНЛАРИ, ҲАССА, ҲАССА-ЎРИНДИҚЛАР,","notes":[],"excl":[]},"XIII":{"title":"ТОШ, ГИПС, ЦЕМЕНТ, АСБЕСТ, СЛЮДА ЁКИ ШУ КАБИ МАТЕРИАЛЛАРДАН ТАЙЁРЛАНГАН","notes":[],"excl":[]},"XIV":{"title":"ТАБИИЙ ЁКИ СУНЪИЙ ЕТИШТИРИЛГАН МАРВАРИД, ҚИММАТБАҲО ЁКИ ЯРИМ ҚИММАТБАҲО","notes":[],"excl":[]},"XV":{"title":"НОҚИММАТБАҲО МЕТАЛЛАР ВА УЛАРДАН ТАЙЁРЛАНГАН БУЮМЛАР","notes":[],"excl":[]},"XVI":{"title":"МАШИНА, УСКУНА ВА МЕХАНИЗМЛАР; ЭЛЕКТРОТЕХНИК УСКУНА; УЛАРНИНГ ҚИСМЛАРИ;","notes":[],"excl":[]},"XVII":{"title":"ЕР УСТИ ТРАНСПОРТИ, УЧИШ АППАРАТЛАРИ, СУЗУВЧИ ВОСИТАЛАР ҲАМДА ТРАНСПОРТГА","notes":[],"excl":[]},"XVIII":{"title":"ОПТИК, ФОТОГРАФИК, КИНЕМАТОГРАФИК, ЎЛЧОВ, НАЗОРАТ, АНИҚЛИК, ТИББИЙ ЁКИ","notes":[],"excl":[]},"XIX":{"title":"ҚУРОЛ ВА ЎҚ-ДОРИЛАР; УЛАРНИНГ ҚИСМ ВА ЖИҲОЗЛАРИ","notes":[],"excl":[]},"XX":{"title":"ТУРЛИ САНОАТ ТОВАРЛАРИ","notes":[],"excl":[]},"XXI":{"title":"САНЪАТ АСАРЛАРИ, КОЛЛEКЦИЯЛАШ БУЮМЛАРИ ВА АНТИКВАРИАТ","notes":[],"excl":[]}},"chapters":{"1":{"title":"ТИРИК ҲАЙВОНЛАР","section":"I","notes":["1. Ушбу гуруҳга барча турдаги тирик ҳайвонлар киритилади, қуйидагилардан ташқари: (а) 0301, 0306, 0307 ёки 0308-товар позицияларидаги балиқ ва қисқичбақасимонлар, моллюска ва бошқа умуртқасиз сув ҳайвонлари; (б) 3002-товар позициясидаги микроорганизм културалари ва бошқа маҳсулотлар; ва (в) 9508-товар позициясидаги ҳайвонлар."],"excl":["1. Ушбу гуруҳга барча турдаги тирик ҳайвонлар киритилади, қуйидагилардан ташқари: (а) 0301, 0306, 0307 ёки 0308-товар позицияларидаги балиқ ва қисқичбақасимонлар, моллюска ва бошқа умуртқасиз сув ҳайвонлари; (б) 3002-товар позициясидаги микроорганизм културалари ва бошқа маҳсулотлар; ва (в) 9508-товар позициясидаги ҳайвонлар."]},"2":{"title":"ГЎШТ ВА ГЎШТЛИ ОЗИҚ-ОВҚАТ СУБМАҲСУЛОТЛАРИ","section":"I","notes":[],"excl":[]},"3":{"title":"БАЛИҚ ВА ҚИСҚИЧБАҚАСИМОНЛАР, МОЛЛЮСКА ВА БОШҚА УМУРТҚАСИЗ СУВ ҲАЙВОНЛАРИ","section":"I","notes":["1. Ушбу гуруҳга киритилмайди: (а) 0106-товар позициясига кирувчи сутэмизувчилар; (б) 0106 товар позициясидаги (0208 ёки 0210-товар позицияларидаги) сутэмизувчиларнинг гўшти; (в) Ўлик ва инсон истеъмоли учун яроқсиз ёки тўғри келмайдиган ёки ўз табиатига ёки ҳолатига (05-гуруҳ) кўра истеъмол учун тўғри келмайдиган балиқ (шу жумладан, унинг жигари, икраси ва сути) ёки қисқичбақасимонлар, моллюскалар ёки бошқа умуртқасиз сув ҳайвонлари; инсон истеъмоли учун яроқсиз майда ва дағал балиқ уни ёки балиқ ёки қисқичбақасимонлар, моллюскалар ёки бошқа умуртқасиз сув ҳайвонларидан тайёрланган гранулалар (2301-товар позицияси) ёки; (г) балиқ икрасидан тайёрланган осётр икраси ёки осётр икраси ўрнини босувчилар (1604- товар позицияси).","2. Ушбу гуруҳдаги “гранулалар” атамаси агломерацияланган ёки тўғридан - тўғри прессланган ёки оз миқдорда боғловчи модда қўшилган маҳсулотларни англатади.","3. 0305—0308-товар позицияларига инсон истеъмоли учун яроқсиз майда ва дағал балиқ уни ва гранулалар (0309-товар позицияси) киритилмайди"],"excl":["1. Ушбу гуруҳга киритилмайди: (а) 0106-товар позициясига кирувчи сутэмизувчилар; (б) 0106 товар позициясидаги (0208 ёки 0210-товар позицияларидаги) сутэмизувчиларнинг гўшти; (в) Ўлик ва инсон истеъмоли учун яроқсиз ёки тўғри келмайдиган ёки ўз табиатига ёки ҳолатига (05-гуруҳ) кўра истеъмол учун тўғри келмайдиган балиқ (шу жумладан, унинг жигари, икраси ва сути) ёки қисқичбақасимонлар, моллюскалар ёки бошқа умуртқасиз сув ҳайвонлари; инсон истеъмоли учун яроқсиз майда ва дағал балиқ уни ёки балиқ ёки қисқичбақасимонлар, моллюскалар ёки бошқа умуртқасиз сув ҳайвонларидан тайёрланган гранулалар (2301-товар позицияси) ёки; (г) балиқ икрасидан тайёрланган осётр икраси ёки осётр икраси ўрнини босувчилар (1604- товар позицияси).","3. 0305—0308-товар позицияларига инсон истеъмоли учун яроқсиз майда ва дағал балиқ уни ва гранулалар (0309-товар позицияси) киритилмайди"]},"4":{"title":"СУТ МАҲСУЛОТЛАРИ, ПАРРАНДА ТУХУМИ, ТАБИИЙ АСАЛ, БОШҚА ЖОЙДА НОМЛАНМАГАН ЁКИ","section":"I","notes":["1. “Сут” атамаси тўлиқ сутни, шунингдек, қисман ёки тўлиқ ёғсизлантирилган сутни англатади.","2. 0403-товар позициясидаги йогурт ҳар қандай қўшилган ингредиент сутнинг бирон бир таркибий қисмини тўлиқ ёки қисман алмаштириш учун қўлланилмаса ва маҳсулот йогуртнинг муҳим хусусиятларини сақлаб қолса концентрланган ёки хушбўйлантирилган бўлиши мумкин, шунингдек, шакар ёки бошқа ширин таъм берувчи моддалар, мевалар, ёнғоқлар, какао, шоколад, зираворлар, кофе ёки унинг экстрактлари, ўсимликлар, ўсимликларнинг қисмлари, дон ёки нон маҳсулотлари ва унли қандолат маҳсулотларини ўз ичига олиши мумкин","3. 0405-товар позициясида: (а) “сариёғ” атамаси фақат сутдаги ёғ миқдори 80% ёки кўпроқ, лекин 95% дан ошмаган, қуруқ (ёғи олинган) сут қолдиғининг максимал миқдори 2% ва сувнинг максимал миқдори 16% бўлган сутдан тайёрланган табиий сариёғ, зардоб ёғи ёки рекомбинация ланган сариёғ (янги тузланган, қуритилган ёки ачитилган, шу жумладан, консерваланган сариёғ)ни англатади. Сариёғ таркибида қўшимча эмульгаторлар бўлмайди, лекин натрий хлорид, озиқ-овқат буёқлари, нейтралловчи тузлар ва сут кислотаси ҳосил қилувчи зарарсиз бактерия култураларини ўз ичига олиши мумкин;0403 20 710 (б) “сут пастаси” атамаси таркибида 39% ёки кўпроқ лекин 80% дан кам бўлган сут ёғини ягона ёғ сифатида ўз ичига олган, ёғдаги сув типида суртилиш хусусиятига эга эмулсияни англатади.","4. Сут зардобини концентратлаш ва сут ёки сут ёғи қўшиш орқали олинган маҳсулотлар қуйидаги учта хусусиятга эга бўлса, 0406-товар позициясига пишлоқ сифатида киритилади: (а) таркибидаги сут ёғи, қуруқ модда ҳисобида, 5 % ёки кўпроқ; (б) таркибида қуруқ модда 70% дан кам бўлмаган, лекин 85% дан кўп бўлмаган; ва (в) улар шаклга эга ёки уларга шакл бериш мумкин.","5. Ушбу гуруҳга киритилмайди: (а) тирик ҳашаротлар, истеъмолга яроқсиз (0511-товар позицияси); (б) сувсиз лактоза сифатида ифодаланувчи, қуруқ модда ҳисоби бўйича таркибида 95% дан кўп лактоза сақловчи сут зардобидан олинган маҳсулотлар (1702-товар позицияси); (в) сутнинг бир ёки бир нечта таркибий қисмларини (масалан сут ёғларини) бошқа моддалар (масалан олеин ёғи) билан алмаштириш орқали олинган маҳсулотлар (1901 ёки 2106-товар позицияси); ёки (г) альбуминлар (шу жумладан, қуруқ модда ҳисобида таркибида 80% зардоб оқсиллари бўлган, икки ёки ундан ортиқ зардоб оқсиллари консентратлари) (3502-товар позицияси) ёки глобулинлар (3504-товар позицияси).","6. 0410 товар позициясида “ҳашаротлар” атамаси истеъмол учун яроқли тирик бўлмаган бутун ёки қисмларга ажратилган кўринишдаги янги, совутилган, музлатилган, қуритилган, дудланган, тузланган ёки тузли сувдаги, шунингдек, ҳашаротлардан олинган майда ва йирик унни англатади. Лекин бу атама бошқа усуллар билан тайёрланган ёки консерваланган истеъмолга яроқли тирик бўлмаган ҳашаротларни ўз ичига олмайди (одатда IV бўлим). Субпозицияларга изоҳ:","1. 0404 10-субпозициясидаги “кўриниши ўзгартирилган сут зардоби” атамаси сут зардоби таркибий қисмларидан ташкил топган, яъни таркибидан лактоза, оқсиллар ёки минерал моддалар тўлиқ ёки қисман олиб ташланган зардоб, таркибига табиий зардоб компонентлари қўшилган зардоб ва зардобнинг табиий компонентларини аралаштириш натижасида олинган маҳсулотлар.","2. 0405 10-субпозициясидаги “сариёғ” атамаси сувсизлантирилган ёки куйдирилган ёғни билдирмайди (0405 90-субпозицияси)"],"excl":["5. Ушбу гуруҳга киритилмайди: (а) тирик ҳашаротлар, истеъмолга яроқсиз (0511-товар позицияси); (б) сувсиз лактоза сифатида ифодаланувчи, қуруқ модда ҳисоби бўйича таркибида 95% дан кўп лактоза сақловчи сут зардобидан олинган маҳсулотлар (1702-товар позицияси); (в) сутнинг бир ёки бир нечта таркибий қисмларини (масалан сут ёғларини) бошқа моддалар (масалан олеин ёғи) билан алмаштириш орқали олинган маҳсулотлар (1901 ёки 2106-товар позицияси); ёки (г) альбуминлар (шу жумладан, қуруқ модда ҳисобида таркибида 80% зардоб оқсиллари бўлган, икки ёки ундан ортиқ зардоб оқсиллари консентратлари) (3502-товар позицияси) ёки глобулинлар (3504-товар позицияси)."]},"5":{"title":"БОШҚА ЖОЙДА НОМЛАНМАГАН ЁКИ КИРИТИЛМАГАН ҲАЙВОНЛАРГА МАНСУБ МАҲСУЛОТЛАР","section":"I","notes":["1. Ушбу гуруҳга киритилмайди: (а) Озиқ-овқат маҳсулотлари (ҳайвонларнинг бутун ёки бўлакларга бўлинган ичаклари, ошқозон ва пуфакчалари, шунингдек, ҳайвонларнинг суюқ ёки қуруқ қони); (б) тери ( шу жумладан, мўйна), 0505-товар позициясидан ташқари, шунингдек, 0511-товар позициясидаги тери ва тери хомашёси кесимлари ва шунга ўхшаш чиқиндилар (41 ёки 43- гуруҳ); (в) от сочи ва унинг чиқиндиларидан ташқари, ҳайвонлардан олинадиган тўқимачилик материаллари (XI бўлим); ёки (г) супурги ёки чўткасимон буюмлар ишлаб чиқариш учун тайёрланган тугун ва тутамлар (9603-товар позицияси).","2. 0501-товар позициясидаги узунлиги бўйича сараланган соч ишлов берилмаган ҳисобланади (соч илдизи ва соч учлари белгиланган тартибда жойлаштирилмаган шарти асосида)","3. Бутун номенклатура бўйлаб “фил суяги” атамаси фил, бегемот, морж, нарвал ва тўнғизнинг тишлари ва қозиқ тишлари, каркидоннинг шохи ва барча ҳайвонларнинг тишларини англатади.","4. Бутун номенклатура бўйлаб “от сочи” атамаси отсимонлар оиласига мансуб ҳайвонларнинг ёки йирик шохли молларнинг ёл ва дум сочларини англатади. 0511-товар позициясига inter alia, от сочи ва унинг чиқиндилари, шу жумладан, субстрат устида ёки усиз мато кўринишида ёки усиз бўлганлари киритилади."],"excl":["1. Ушбу гуруҳга киритилмайди: (а) Озиқ-овқат маҳсулотлари (ҳайвонларнинг бутун ёки бўлакларга бўлинган ичаклари, ошқозон ва пуфакчалари, шунингдек, ҳайвонларнинг суюқ ёки қуруқ қони); (б) тери ( шу жумладан, мўйна), 0505-товар позициясидан ташқари, шунингдек, 0511-товар позициясидаги тери ва тери хомашёси кесимлари ва шунга ўхшаш чиқиндилар (41 ёки 43- гуруҳ); (в) от сочи ва унинг чиқиндиларидан ташқари, ҳайвонлардан олинадиган тўқимачилик материаллари (XI бўлим); ёки (г) супурги ёки чўткасимон буюмлар ишлаб чиқариш учун тайёрланган тугун ва тутамлар (9603-товар позицияси)."]},"6":{"title":"ТИРИК ДАРАХТЛАР ВА БОШҚА ЎСИМЛИКЛАР; ПИЁЗЛАРИ, ИЛДИЗЛАРИ","section":"II","notes":["1. 0601-позициянинг иккинчи қисмида кўрсатилган истиснолардан ташқари, ушбу гуруҳ фақат экиш ёки безак мақсадларида одатда, кўчатхоналардан ёки иссиқхоналардан етказиб бериладиган тирик дарахтлар ва ўсимликларни (шу жумладан, сабзавот кўчатларини) қамраб олади, аммо бу гуруҳга 07-гуруҳда таснифланадиган картошка илдизлари, шолғомсимон думалоқ пиёз, саримсоқпиёз ёки бошқа маҳсулотлар кирмайди.","2. 0603 ёки 0604-товар позицияларидаги ҳар қандай турдаги товарларга тегишли ҳар қандай ҳаволалар гулдасталар, гул саватлари, гулчамбарлар ва шунга ўхшаш маҳсулотларга тўлиқ ёки қисман бошқа материаллардан аксессуарлар бундан мустасно сифатида қаралиши керак. Бироқ бу изоҳлар 9701-позициясидаги (коллаж) – ўсимликларнинг чизма тасвирлари ёки шунга ўхшаш декоратив чизмаларини ўз ичига олмайди."],"excl":["1. 0601-позициянинг иккинчи қисмида кўрсатилган истиснолардан ташқари, ушбу гуруҳ фақат экиш ёки безак мақсадларида одатда, кўчатхоналардан ёки иссиқхоналардан етказиб бериладиган тирик дарахтлар ва ўсимликларни (шу жумладан, сабзавот кўчатларини) қамраб олади, аммо бу гуруҳга 07-гуруҳда таснифланадиган картошка илдизлари, шолғомсимон думалоқ пиёз, саримсоқпиёз ёки бошқа маҳсулотлар кирмайди."]},"7":{"title":"САБЗАВОТЛАР ВА БАЪЗИ ИСТЕЪМОЛГА ЯРОҚЛИ БЎЛГАН ИЛДИЗЛИ МЕВАЛАР ВА ҚУЛУПНАЙ","section":"II","notes":["1. Ушбу гуруҳга ем-хашак озуқа маҳсулотлари кирмайди 1214-товар позицияда.","2. 0709 дан 0712 гача товар позицияларида “сабзавотлар” атамаси, шунингдек, истеъмол қилинадиган қўзиқоринлар, трюфель, маслина ёки зайтун, ковул, кабачки, қовоқ, бақлажон, шакарли маккажўхорини ўз ичига олади (Zea mays var. saccharata), меваларнинг турлари Capsicum ёки Pimenta, арпабодиён, петрушка, купир, эстрагон, кресс салату ва боғ маёран (Majorana hortensis ёки Origanum majorana).","3. 0712-товар позициясига 0701–0711 товар позицияларидаги барча қуритилган сабзавотлари киради‚ қуйидагилардан ташқари: а) қуритилган ловия (дуккакли) сабзавотлар ва тозаланганлари (0713-товар позиция); б) 1102 дан 1104 гача товар позицияларидаги ширин маккажўхори; в) картошка уни, ун, кукун, ёрма, гранулалар (1105-товар позиция); г) 0713-товар позициядаги (1106-товар позиция) қуритилган дуккакли сабзавотларнинг ун ва кукунлари.","4. Ушбу гуруҳга Capsicum ёки Pimenta турларига мансуб турнинг қуритилган ёки майдаланган ёки майдаланган мевалари кирмайди. (0904-товар позиция).","5. 0711-товар позициясига ишлов берилган фақат ташиш ёки ишлатишдан олдин сақлаш вақтида қисқа муддатли сақланишни таъминлаш учун қайта ишланган сабзавотлар (масалан, олтингугурт диоксид гази, шўр сувда, олтингугуртли сувда ёки бошқа вақтинча сақловчи эритмаларда), агар бу ҳолатда улар тўғридан-тўғри истеъмол қилиш учун яроқсиз бўлиб қолганда."],"excl":["1. Ушбу гуруҳга ем-хашак озуқа маҳсулотлари кирмайди 1214-товар позицияда.","3. 0712-товар позициясига 0701–0711 товар позицияларидаги барча қуритилган сабзавотлари киради‚ қуйидагилардан ташқари: а) қуритилган ловия (дуккакли) сабзавотлар ва тозаланганлари (0713-товар позиция); б) 1102 дан 1104 гача товар позицияларидаги ширин маккажўхори; в) картошка уни, ун, кукун, ёрма, гранулалар (1105-товар позиция); г) 0713-товар позициядаги (1106-товар позиция) қуритилган дуккакли сабзавотларнинг ун ва кукунлари.","4. Ушбу гуруҳга Capsicum ёки Pimenta турларига мансуб турнинг қуритилган ёки майдаланган ёки майдаланган мевалари кирмайди. (0904-товар позиция)."]},"8":{"title":"ИСТЕЪМОЛ ҚИЛИНАДИГАН МЕВАЛАР ВА ЁНҒОҚЛАР,","section":"II","notes":["1. Ушбу гуруҳга истеъмол қилинмайдиган ёнғоқлар ёки мевалар кирмайди.","2. Совутилган мевалар ва ёнғоқлар мос келадиган янги мева ва ёнғоқлар билан бир хил позицияга киритилиши керак.","3. Ушбу гуруҳнинг қуритилган мевалари ёки ёнғоқлари қуйидаги мақсадларда, қисман регидратация ёки бошқа ишлов берилишдан ўтказилиши мумкин: (а) сақлаш муддатини ошириш ёки барқарорлаштириш (масалан, ўртача иссиқлик билан ишлов бериш, олтингугуртлаш, сорбин кислотаси ёки калий сорбат қўшилиши); (б) ташқи кўринишини яхшилаш ёки сақлаб қолиш (масалан, ўсимлик мойи ёки оз миқдорда глюкоза сиропи қўшиб); қуритилган мевалар ёки қуритилган ёнғоқларнинг ўзига хос хусусиятини сақлаб қолиш шарти билан.","4. Мевалар ва ёнғоқлар 0812-товар позицияга, улар фойдаланишидан олдин ташиш ёки сақлаш вақтида фақат қисқа муддатли сақлаш учун (масалан, олтингугурт диоксид газида, шўр сувда, нордон сувда ёки бошқа вақтинча сақловчи эритмаларда), ишлов берилган мевалар ва ёнғоқлар киради, агар шарти улар тўғридан-тўғри истеъмол қилиш учун яроқсиз бўлиб қолган ҳолатларда."],"excl":["1. Ушбу гуруҳга истеъмол қилинмайдиган ёнғоқлар ёки мевалар кирмайди."]},"9":{"title":"ҚАҲВА, ЧОЙ, МАТЕ ЁКИ ПАРАГВАЙ ЧОЙИ ВА ЗИРАВОРЛАР","section":"II","notes":["1. 0904 дан 0910 гача товар позицияларида бўлган товарларнинг аралашмалари қуйидагича таснифланади: а) бир хил товар позициясига кирувчи икки ёки ундан ортиқ маҳсулотнинг аралашмалари бир хил товар туркумига кирса; (б) икки ёки ундан ортиқ маҳсулотнинг ҳар хил товар туркумига кирувчи аралашмалари 0910 товар позициясига киради. 0904 дан 0910 гача бўлган товар позицияларида товарларга (ёки юқоридаги (а) ёки (б) бандларида кўрсатилган аралашмаларга) бошқа моддаларнинг қўшилиши, агар олинган аралашмалар ушбу позициялар товарларининг муҳим хусусиятларини сақлаб қолган бўлса, уларнинг таснифига таъсир қилмайди. Акс ҳолда, бундай аралашмалар ушбу гуруҳга киритилмайди. Хушбўй моддалар ёки зираворлар аралашмалари бўлган маҳсулотлар 2103-товар позициясига киради. 2.Ушбу гуруҳга кубеба қалампири (Piper cubeba) ёки 1211-позициядаги бошқа маҳсулотлар кирмайди."],"excl":["1. 0904 дан 0910 гача товар позицияларида бўлган товарларнинг аралашмалари қуйидагича таснифланади: а) бир хил товар позициясига кирувчи икки ёки ундан ортиқ маҳсулотнинг аралашмалари бир хил товар туркумига кирса; (б) икки ёки ундан ортиқ маҳсулотнинг ҳар хил товар туркумига кирувчи аралашмалари 0910 товар позициясига киради. 0904 дан 0910 гача бўлган товар позицияларида товарларга (ёки юқоридаги (а) ёки (б) бандларида кўрсатилган аралашмаларга) бошқа моддаларнинг қўшилиши, агар олинган аралашмалар ушбу позициялар товарларининг муҳим хусусиятларини сақлаб қолган бўлса, уларнинг таснифига таъсир қилмайди. Акс ҳолда, бундай аралашмалар ушбу гуруҳга киритилмайди. Хушбўй моддалар ёки зираворлар аралашмалари бўлган маҳсулотлар 2103-товар позициясига киради. 2.Ушбу гуруҳга кубеба қалампири (Piper cubeba) ёки 1211-позициядаги бошқа маҳсулотлар кирмайди."]},"10":{"title":"ДОНЛАР","section":"II","notes":[],"excl":[]},"11":{"title":"УН ВА УН ЁРМАЛАРНИ ЯНЧИШГА МЎЛЖАЛЛАНГАН САНОАТ МАҲСУЛОТЛАРИ; СОЛОД;","section":"II","notes":["1. Ушбу гуруҳга қуйидагилар кирмайди: (а) қаҳва ўрнини босувчи сифатида ишлатиладиган қовурилган солод (0901 ёки 2101 товар позициялар); (б) 1901–позициядаги қайта ишлашдан кейинги унлар, ёрмалар ёки крахмаллар; (в) маккажўхори доналари ёки 1904-позициядаги бошқа маҳсулотлар; (г) 2001, 2004 ёки 2005 товар позицияларидаги тайёрланган ёки консерваланган сабзавотлар; (д) фармацевтика маҳсулотлари (30-гуруҳ); (е) парфюмерия, косметика ёки тозалаш воситалари хусусиятларига эга бўлган крахмаллар (33- гуруҳ).","2. (А) Қуйидаги жадвалда келтирилган ун саноати маҳсулотлари ушбу гуруҳга киритилган, қуруқ моддалар массаси асосида: (а) крахмал миқдори (Эверс усули бўйича поларизациянинг ўзгариши билан аниқланади) 2- устунда кўрсатилганидан ошади; ва (б) кул даражаси (барча қўшилган минераллар учун тузатилгандан кейин) 3-устунда кўрсатилган кўрсаткичлардан ошмайди. Акс ҳолда, улар 2302-позицияга киритилади. Бироқ бутун, яссиланган, майдаланган ёки майдаланган дон уруғи ҳар доим 1104-позицияга киради. (Б) Юқоридаги талабларга мувофиқ ушбу гуруҳга киритилган маҳсулотлар, агар тўрнинг ўлчами 4- ёки 5-устунларда кўрсатилган металл тўрли элакдан ўтказилганда маҳсулотнинг ҳосилдорлиги 1101 ёки 1102 товар белгиларига таснифланади, мос келадиган дон учун кўрсатилганидан кам эмас. Акс ҳолда улар 1103 ёки 1104 товар позицияларига киради. Кул Металл тўрли элакдан ўтказиш Донли крахмал даражаси даражаси кам эмас‚ мас. % Дон миқдори кўпроқ‚ миқдори 315 мкм 500 мкм мас. % кўпроқ‚ мас. % 1 2 3 4 5 Буғдой ва жавдар 45 2,5 80 – Арпа 45 3 80 – Сули 45 5 80 – Маккажўхори ва жўхори 45 2 – 90 Гуруч 45 1,6 80 – Қорабуғдой 45 4 80 – Бошқа донлар 45 2 50 –","3. 1103-товар позициядаги “ёрмалар” ва “йирик тортилган ун” атамалари донни парчалаш маҳсулотларини англатади: а) маккажўхори эзилган маҳсулотларга нисбатан камида 95 % оғирлиги 2 мм металл тўрли элакдан ўтадиган; б) 1,25 мм металл тўрли элакдан ўтадиган камида 95 % оғирлик бошқа ёрмаларнинг майдаланган маҳсулотларида."],"excl":["1. Ушбу гуруҳга қуйидагилар кирмайди: (а) қаҳва ўрнини босувчи сифатида ишлатиладиган қовурилган солод (0901 ёки 2101 товар позициялар); (б) 1901–позициядаги қайта ишлашдан кейинги унлар, ёрмалар ёки крахмаллар; (в) маккажўхори доналари ёки 1904-позициядаги бошқа маҳсулотлар; (г) 2001, 2004 ёки 2005 товар позицияларидаги тайёрланган ёки консерваланган сабзавотлар; (д) фармацевтика маҳсулотлари (30-гуруҳ); (е) парфюмерия, косметика ёки тозалаш воситалари хусусиятларига эга бўлган крахмаллар (33- гуруҳ)."]},"12":{"title":"МОЙЛИ УРУҒЛАР ВА МЕВАЛАР; БОШҚА УРУҒЛАР, МЕВА ВА ДОН; ДОРИВОР ЎСИМЛИКЛАР ВА","section":"II","notes":["1. 1207-товар позицияга қуйидагилар киради: inter alia, пальма ёнғоқлари ва мағизлари, пахта чигитлари, канакунжут, кунжут, хантал, сафлор, кўкнори уруғлари ва ши ёнғоқлари (каритэ ёнғоқлари). 0801 ёки 0802 товар позицияларининг маҳсулотлари ёки маслина ёки зайтун киритилмайди (07 ёки 20-гуруҳлар).","2. 1208-позициядаги нафақат тўлиқ ёғли ун ва овқатлар, балки ёғсизланган ун ва овқатлар, шунингдек, ёғсизлантирилган, сўнгра ёғ қўшилиши билан ёғ таркиби тўла тикланган ун ва таомлар ҳам киради. Ушбу товар позицияга маҳсулотларнинг қолдиқлари 2304 дан 2306 товар позициясига кирадиган товарлари кирмайди.","3. 1209-товар позициясига лавлаги, ўтлар, боғ гуллари, сабзавотлар, ўрмон ва мевали дарахтлар, ҳар хил турдаги вики (Vicia faba туридан ташқари) ёки люпин экиш учун мўлжалланган уруғлари киради. Бироқ 1209-товар позициясига қуйидаги маҳсулотлар, ҳатто экиш учун мўлжалланган бўлса ҳам киритилмайди: (а) дуккакли сабзавотлар ёки шакарли маккажўхори (07-гуруҳ); (б) зираворлар ёки 09-гуруҳнинг бошқа маҳсулотлари; (в) ғалла экинлари (10-гуруҳ); (г) 1201 – 1207 ёки 1211-товар позициясига тааллуқли маҳсулотлар.","4. 1211-позицияга қуйидаги interalia, ўсимликлар ёки уларнинг қисмлари киради: райҳон, бодринг ўти‚ женшень, иссоп, қизилмия, ялпизнинг барча турлари, розмарин, рута, мармарак ва шувоқ. 1211-товар позициясига қуйидагилар киритилмайди: (а) 30-гуруҳ доривор воситалари; (б) 33-гуруҳнинг парфюмерия, косметика ёки пардоз маҳсулотлари; (в) инсектицидлар, фунгицидлар, гербицидлар, дезинфекциялаш воситалари ёки 3808- товар позициясидаги шунга ўхшаш маҳсулотлар.","5. 1212-позициядаги “денгиз ўтлари ва бошқа сув ўтлар” атамаси қуйидагиларга тадбиқ этилмайди: (а) 2102-товарлар позициясидаги ўлик бир ҳужайрали микроорганизмлар учун; (б) 3002-товар позициясидаги микроорганизм культуралари учун; (в) 3101 ёки 3105-товар позициясидаги ўғитлар учун. Субпозицияларга изоҳ:","1. 1205 10 субпозициядаги “рапс уруғи, ёки паст эрук кислотали колза уруғи ” атамаси оғирлиги бўйича 2%дан кам эрук кислота ва 30 мкмол/г дан кам глюкозинолатларни ҳамда қаттиқ компонентни ўз ичига олган қаттиқ ёғ ҳосил қилувчи рапс ёки колза уруғини англатади. Подсубпозицияга изоҳ:","1. 1211 90 860 5 подсубпозицияда “майдаланган” атамаси майда бўлакларга бўлинган, илдизнинг бутунлиги бузилган ва илдизнинг бутун узлуксиз кесмасини олиш мумкин бўлмаган қизилмия илдизларини, унинг қисмлари ўлчамларини англатади, ўлчами энг катта кенглигида 1 см дан ошмайди."],"excl":["1. 1207-товар позицияга қуйидагилар киради: inter alia, пальма ёнғоқлари ва мағизлари, пахта чигитлари, канакунжут, кунжут, хантал, сафлор, кўкнори уруғлари ва ши ёнғоқлари (каритэ ёнғоқлари). 0801 ёки 0802 товар позицияларининг маҳсулотлари ёки маслина ёки зайтун киритилмайди (07 ёки 20-гуруҳлар).","2. 1208-позициядаги нафақат тўлиқ ёғли ун ва овқатлар, балки ёғсизланган ун ва овқатлар, шунингдек, ёғсизлантирилган, сўнгра ёғ қўшилиши билан ёғ таркиби тўла тикланган ун ва таомлар ҳам киради. Ушбу товар позицияга маҳсулотларнинг қолдиқлари 2304 дан 2306 товар позициясига кирадиган товарлари кирмайди.","3. 1209-товар позициясига лавлаги, ўтлар, боғ гуллари, сабзавотлар, ўрмон ва мевали дарахтлар, ҳар хил турдаги вики (Vicia faba туридан ташқари) ёки люпин экиш учун мўлжалланган уруғлари киради. Бироқ 1209-товар позициясига қуйидаги маҳсулотлар, ҳатто экиш учун мўлжалланган бўлса ҳам киритилмайди: (а) дуккакли сабзавотлар ёки шакарли маккажўхори (07-гуруҳ); (б) зираворлар ёки 09-гуруҳнинг бошқа маҳсулотлари; (в) ғалла экинлари (10-гуруҳ); (г) 1201 – 1207 ёки 1211-товар позициясига тааллуқли маҳсулотлар.","4. 1211-позицияга қуйидаги interalia, ўсимликлар ёки уларнинг қисмлари киради: райҳон, бодринг ўти‚ женшень, иссоп, қизилмия, ялпизнинг барча турлари, розмарин, рута, мармарак ва шувоқ. 1211-товар позициясига қуйидагилар киритилмайди: (а) 30-гуруҳ доривор воситалари; (б) 33-гуруҳнинг парфюмерия, косметика ёки пардоз маҳсулотлари; (в) инсектицидлар, фунгицидлар, гербицидлар, дезинфекциялаш воситалари ёки 3808- товар позициясидаги шунга ўхшаш маҳсулотлар."]},"13":{"title":"ТОЗАЛАНМАГАН ТАБИИЙ СМОЛА; КАМЕДИ ЁКИ БОШҚА ЎСИМЛИК ШАРБАТИ ВА ЭКСТРАКТЛАРИ","section":"II","notes":[],"excl":[]},"14":{"title":"ТЎҚИЛГАН БУЮМЛАРНИ ТАЙЁРЛАШ УЧУН ЎСИМЛИК МАТЕРИАЛЛАРИ; БОШҚА ЖОЙДА","section":"II","notes":["1. Бу гуруҳга қуйидаги товарлар киритилмайди, XI гуруҳга киритилиши керак бўлган ва ушбу гуруҳга киритилмаган қуйидаги маҳсулотлар: асосан, тўқимачилик материаллар ишлаб чиқаришда, ишлов даражасидан қатъий назар ёки бошқа ўсимлик материаллари, ишлов бериш натижасида тўқимачилик материали сифатида ишлатилиши мумкин бўлган маҳсулотлар.","2. 1401-товар позициясига қуйидагилар киритилган: inter alia, бамбук (титилган ёки титилмаган, узунасига арраланган ёки арраланмаган, узунасига кесилган ҳамда кесилмаган, учи думалоқланган ёки думалоқланмаган, оқланган ёки оқланмаган, ёнишга қарши ишлов берилган ёки ишлов берилмаган, текисланган ёки текисланмаган, бўялган ёки бўялмаган), титилган тол, қамиш ва шунга ўхшаш, ротанг пальмаси ўзаги, ўзагидан тозаланган ёки узунасига титилган, ротанг пальмаси, хурмо пальмаси поялари бўйлаб ўралган ёки бўлинган. Ушбу товар позициясига тозаланган ёғоч, шилинган ёғоч киритилмайди (4404-товар позицияси). Қўшмча"],"excl":["1. Бу гуруҳга қуйидаги товарлар киритилмайди, XI гуруҳга киритилиши керак бўлган ва ушбу гуруҳга киритилмаган қуйидаги маҳсулотлар: асосан, тўқимачилик материаллар ишлаб чиқаришда, ишлов даражасидан қатъий назар ёки бошқа ўсимлик материаллари, ишлов бериш натижасида тўқимачилик материали сифатида ишлатилиши мумкин бўлган маҳсулотлар.","2. 1401-товар позициясига қуйидагилар киритилган: inter alia, бамбук (титилган ёки титилмаган, узунасига арраланган ёки арраланмаган, узунасига кесилган ҳамда кесилмаган, учи думалоқланган ёки думалоқланмаган, оқланган ёки оқланмаган, ёнишга қарши ишлов берилган ёки ишлов берилмаган, текисланган ёки текисланмаган, бўялган ёки бўялмаган), титилган тол, қамиш ва шунга ўхшаш, ротанг пальмаси ўзаги, ўзагидан тозаланган ёки узунасига титилган, ротанг пальмаси, хурмо пальмаси поялари бўйлаб ўралган ёки бўлинган. Ушбу товар позициясига тозаланган ёғоч, шилинган ёғоч киритилмайди (4404-товар позицияси). Қўшмча"]},"15":{"title":"ҲАЙВОНОТ, ЎСИМЛИК ЁКИ МИКРОБИОЛОГИК КЕЛИБ ЧИҚИШГА ЭГА ЁҒ ВА МОЙЛАР ҲАМДА","section":"III","notes":["1. Ушбу гуруҳга киритилмайди: (а) Чўчқа ва парранда ёғи (0209-товар позицияси); (б) Какао мойи (1804-товар позицияси); (в) Таркибида 15% 0405-товар позициясидаги маҳсулотлар бўлган тайёр озиқ-овқат маҳсулотлари (асосан 21-гуруҳ); (г) Жизза (2301-товар позицияси) ёки 2304–2306-товар позициясида кўрсатилган қолдиқлар; (д) ёғ кислоталари, тайёр мумлар, дори воситалари, бўёқлар, лаклар, совунлар, парфюмерия, косметика ёки пардоз буюмлари, сульфатланган мойлар ёки VI бўлимга кирувчи бошқа товарлар; (е) Мойлардан олинган фактис (4002-товар позицияси).","2. 1509-товар позициясига маслина ёки зайтун мевасини эритувчи экстракция қилиш билан олинган мойлар киритилмайди (1510-товар позицияси).","3. 1518-товар позициясига фақат оддий тарзда денатурация қилинган, товар позицияларига киритилиши керак бўлган шунга ўхшаш денатурацияланмаган ёғлар, мойлар ва уларнинг фракциялари киритилмайди.","4. Соапстоклар, мойли уруғлар ҳамда ёғ қолдиқлари, стеаринли пек, глицеринли пек ва тер безлари қолдиқлари 1522-товар позициясига киритилади. Субпозицияларга изоҳлар:","1. 1509 30-субпозициясида қайта ишланмаган қўшимча зайтун мойи 2,0 г/100 гдан ортиқ бўлмаган концентрацияда эркин кислоталикка эга (олеин кислотаси билан ифодаланган) ва унинг бошқа қайта ишланмаган қўшимча зайтун мойларидан фарқи 33-1981 Алиментариус кодекси стандартида кўрсатилган хусусиятлар билан аниқланиши мумкин.","2. 1514 11 ва 1514 19 пастки сарлавҳаларида \"эрук кислота миқдори паст бўлган рапс ёғи (рапс ёки кольза)\" атамаси таркибида 2 мас.% кам бўлган эрук кислотаси сақловчи, лекин учувчан бўлмаган ёғни англатади.%."],"excl":["1. Ушбу гуруҳга киритилмайди: (а) Чўчқа ва парранда ёғи (0209-товар позицияси); (б) Какао мойи (1804-товар позицияси); (в) Таркибида 15% 0405-товар позициясидаги маҳсулотлар бўлган тайёр озиқ-овқат маҳсулотлари (асосан 21-гуруҳ); (г) Жизза (2301-товар позицияси) ёки 2304–2306-товар позициясида кўрсатилган қолдиқлар; (д) ёғ кислоталари, тайёр мумлар, дори воситалари, бўёқлар, лаклар, совунлар, парфюмерия, косметика ёки пардоз буюмлари, сульфатланган мойлар ёки VI бўлимга кирувчи бошқа товарлар; (е) Мойлардан олинган фактис (4002-товар позицияси).","2. 1509-товар позициясига маслина ёки зайтун мевасини эритувчи экстракция қилиш билан олинган мойлар киритилмайди (1510-товар позицияси).","3. 1518-товар позициясига фақат оддий тарзда денатурация қилинган, товар позицияларига киритилиши керак бўлган шунга ўхшаш денатурацияланмаган ёғлар, мойлар ва уларнинг фракциялари киритилмайди."]},"16":{"title":"ГЎШТ, БАЛИҚ, ҚИСКИЧБАҚАСИМОНЛАР, МОЛЛЮСКАЛАР ЁКИ БОШҚА СУВДА ЯШОВЧИ","section":"IV","notes":["1. Ушбу гуруҳга 02 ёки 03-гуруҳлар, 04-гуруҳнинг 6 - изоҳида ёки 0504 - товар позициясининг кўрсатилган усуллар билан тайёрланган ёки консерваланган гўшт, гўшт маҳсулотлари, балиқ, қисқичбақасимонлар, моллюскалар ёки бошқа сувда яшовчи умуртқасизлар ҳамда ҳашаротлар кирмайди.","2. Ушбу гуруҳга тайёр озиқ-овқат маҳсулотлари киради, агар улар таркибида колбаса, гўшт, гўштнинг ярим маҳсулотлари, қон, ҳашаротлар, балиқ ёки қисқичбақасимонлар, моллюскалар ёки бошқа сувда яшовчи умуртқасиз ҳайвонлар оғирлик бўйича 20% дан ортиқ бўлса. Агар тайёр маҳсулот таркибида юқорида кўрсатилган икки ёки ундан ортиқ таркибий қисмлар мавжуд бўлса, улар оғирлиги бўйича миқдори кўп бўлган компонент ёки таркибий қисмларга кўра16–гуруҳда таснифланади. Ушбу қоидалар 1902-товар позициясининг начинкали маҳсулотларига ёки 2103 ёки 2104-товар позицияларининг тайёр маҳсулотларига тааллуқли эмас. Субпозицияларга берилган изоҳлар:","1. 1602 10-субпозицияда “бир хил таркибли тайёр овқатлар” атамаси гўшт, гўштнинг ярим маҳсулотлари, қон ёки ҳашаротлардан тайёрланган, майда майдаланган, илк ёшдаги болалар учун учун ёки парҳез овқатланиш учун мўлжалланган озиқ-овқат сифатида чакана савдога чиқарилган, соф оғирликдаги ўрамларда 250 г дан кўп бўлмаган қадоқларда тайёрланган маҳсулотларни англатади. Бу тайёр маҳсулотларга зираворлар, консервантлар ёки бошқа мақсадларда қўшилган ҳар қандай ингредиентларнинг оз миқдорини ҳисобга олмайди. Ушбу тайёр маҳсулотлар оз миқдорда кўзга кўринадиган даражада гўшт бўлаги, гўшт субмаҳсулотлари ёки ҳашаротларни ўз ичига олиши мумкин. Ушбу субпозицияда 1602- товар позицияси барча бошқа субпозияцияларига нисбатан устунликка эга.","2. 1604 ёки 1605-позициядаги балиқлар, қисқичбақасимонлар, моллюскалар ва бошқа сувда яшовчи умуртқасизлари фақат уларнинг умумий номлари остида санаб ўтилган ва 03-гуруҳда худди шу номларида кўрсатилган турлар билан бир хилдир."],"excl":["1. Ушбу гуруҳга 02 ёки 03-гуруҳлар, 04-гуруҳнинг 6 - изоҳида ёки 0504 - товар позициясининг кўрсатилган усуллар билан тайёрланган ёки консерваланган гўшт, гўшт маҳсулотлари, балиқ, қисқичбақасимонлар, моллюскалар ёки бошқа сувда яшовчи умуртқасизлар ҳамда ҳашаротлар кирмайди.","2. Ушбу гуруҳга тайёр озиқ-овқат маҳсулотлари киради, агар улар таркибида колбаса, гўшт, гўштнинг ярим маҳсулотлари, қон, ҳашаротлар, балиқ ёки қисқичбақасимонлар, моллюскалар ёки бошқа сувда яшовчи умуртқасиз ҳайвонлар оғирлик бўйича 20% дан ортиқ бўлса. Агар тайёр маҳсулот таркибида юқорида кўрсатилган икки ёки ундан ортиқ таркибий қисмлар мавжуд бўлса, улар оғирлиги бўйича миқдори кўп бўлган компонент ёки таркибий қисмларга кўра16–гуруҳда таснифланади. Ушбу қоидалар 1902-товар позициясининг начинкали маҳсулотларига ёки 2103 ёки 2104-товар позицияларининг тайёр маҳсулотларига тааллуқли эмас. Субпозицияларга берилган изоҳлар:"]},"17":{"title":"ШАКАР ВA ШАКАРДАН ТАЙЁРЛАНГАН ҚАНДОЛАТ МАҲСУЛОТЛАРИ","section":"IV","notes":[],"excl":[]},"18":{"title":"КАКАО ВА КАКАОДАН ТАЙЁРЛАНГАН МАҲСУЛОТЛАР","section":"IV","notes":["1. Ушбу гуруҳга қуйидагилар кирмайди: (a) тайёр озиқ-овқат маҳсулотлари, таркибида масса улуши 20 % дан кўп колбаса, гўшт, гўштли ярим маҳсулотлар, қон, ҳашаротлар, балиқ ёки қисқичбақасимонлар, моллюскалар ёки бошқа сувда яшовчи умуртқасизлар ёки ушбу маҳсулотларнинг таркиби ҳар қандай комбинациясини ўз ичига олган товарлар (16-гуруҳ); (б) 0403, 1901, 1902, 1904, 1905, 2105, 2202, 2208, 3003 ёки 3004-товар позициясидаги тайёр маҳсулотлар.","2. 1806-товар позициясига таркибида какао бўлган қандли қандолат маҳсулотлари ва ушбу гуруҳнинг 1-изоҳида келтирилган қоидаларига риоя қилган ҳолда, какао қўшилган бошқа озиқ-овқат маҳсулотлари киради."],"excl":["1. Ушбу гуруҳга қуйидагилар кирмайди: (a) тайёр озиқ-овқат маҳсулотлари, таркибида масса улуши 20 % дан кўп колбаса, гўшт, гўштли ярим маҳсулотлар, қон, ҳашаротлар, балиқ ёки қисқичбақасимонлар, моллюскалар ёки бошқа сувда яшовчи умуртқасизлар ёки ушбу маҳсулотларнинг таркиби ҳар қандай комбинациясини ўз ичига олган товарлар (16-гуруҳ); (б) 0403, 1901, 1902, 1904, 1905, 2105, 2202, 2208, 3003 ёки 3004-товар позициясидаги тайёр маҳсулотлар."]},"19":{"title":"БОШОҚЛИ ДОНЛАР, УН, КРАХМАЛ ЁКИ СУТДАН ТАЙЁРЛАНГАН МАҲСУЛОТЛАР; УНДАН","section":"IV","notes":["1. Ушбу гуруҳга қуйидагилар кирмайди: (а) таркиби масса улушидан 20 % ортиқ колбаса, гўшт, гўштли субмаҳсулотлар, қон, ҳашаротлар, балиқ ёки қисқичбақасимонлар, моллюскалар ёки бошқа сувда яшовчи умуртқасизлар ёки бу маҳсулотларнинг ҳар қандай кўринишлари (16-гуруҳ), 1902-товар позициясидаги начинкали тайёр озиқ-овқат маҳсулотлари бундан мустасно; (б) қуруқ печенье ёки бошқа ун ҳамда крахмалдан тайёрланган маҳсулотлар, ҳайвонлар учун махсус тайёрланган озуқалар (2309-товар позицияси); ёки (в) дори воситалари ёки бошқа маҳсулотлар 30-гуруҳ","2. 1901-товар позициясида: (а) “ёрма” ибораси 11-гуруҳдаги бошоқли дон ёрмаларини англатади; (б) “майда тортилган ун” ва “Йирик тортилган ун” ибораси қуйидагиларни англатади: (1) 11-гуруҳдаги бошоқли донлардан майда ва йирик тортилган ун. (2) майда ва йирик тортилган ун ҳамда ҳар қандай гуруҳдаги ўсимликдан кукун, майда ва йирик тортилган ун ёки қуритилган сабзавотлар кукуни (0712-товар позицияси), картошка (1105-товар позицияси) ёки қуритилган дуккакли сабзавотлар (1106-товар позицияси)дан ташқари.","3. 1904-товар позициясига таркиби тўлиқ ёғсизлантириш асосида ҳисобланган масса улуши 6 % дан ортиқ какао бўлган ва тўлиқ қиёмли шоколад ёки таркиби какаоли бошқа озиқ-овқат маҳсулотлар (1806-товар позицияси) кирмайди.","4. 1904-маҳсулот позициясида “бошқа усулда тайёрланган” ибораси 10 ёки 11-гуруҳлар изоҳида ёки кўрсатилган товар позициясида махсус пазандалик ишловидан ўтказилган маҳсулотларни англатади."],"excl":["1. Ушбу гуруҳга қуйидагилар кирмайди: (а) таркиби масса улушидан 20 % ортиқ колбаса, гўшт, гўштли субмаҳсулотлар, қон, ҳашаротлар, балиқ ёки қисқичбақасимонлар, моллюскалар ёки бошқа сувда яшовчи умуртқасизлар ёки бу маҳсулотларнинг ҳар қандай кўринишлари (16-гуруҳ), 1902-товар позициясидаги начинкали тайёр озиқ-овқат маҳсулотлари бундан мустасно; (б) қуруқ печенье ёки бошқа ун ҳамда крахмалдан тайёрланган маҳсулотлар, ҳайвонлар учун махсус тайёрланган озуқалар (2309-товар позицияси); ёки (в) дори воситалари ёки бошқа маҳсулотлар 30-гуруҳ","2. 1901-товар позициясида: (а) “ёрма” ибораси 11-гуруҳдаги бошоқли дон ёрмаларини англатади; (б) “майда тортилган ун” ва “Йирик тортилган ун” ибораси қуйидагиларни англатади: (1) 11-гуруҳдаги бошоқли донлардан майда ва йирик тортилган ун. (2) майда ва йирик тортилган ун ҳамда ҳар қандай гуруҳдаги ўсимликдан кукун, майда ва йирик тортилган ун ёки қуритилган сабзавотлар кукуни (0712-товар позицияси), картошка (1105-товар позицияси) ёки қуритилган дуккакли сабзавотлар (1106-товар позицияси)дан ташқари.","3. 1904-товар позициясига таркиби тўлиқ ёғсизлантириш асосида ҳисобланган масса улуши 6 % дан ортиқ какао бўлган ва тўлиқ қиёмли шоколад ёки таркиби какаоли бошқа озиқ-овқат маҳсулотлар (1806-товар позицияси) кирмайди."]},"20":{"title":"САБЗАВОТЛАР, МЕВАЛАР, ЁНҒОҚЛАР ЁКИ ЎСИМЛИКЛАР ЁКИ УЛАРНИНГ БОШҚА ҚИСМЛАРИНИ","section":"IV","notes":["1. Бу гуруҳга қуйидагилар киритилмайди: (а) 07, 08 ёки 11-гуруҳларда кўрсатилган усуллар ёрдамида тайёрланган ёки консерваланган сабзавотлар, мевалар ёки ёнғоқлар; (б) ўсимлик мойлари ва ёғлар (15-гуруҳ); (в) 20% массага нисбатан ортиқ колбаса, гўшт, гўшт ярим маҳсулотлари, қон, ҳашаротлар, балиқлар ёки қисқичбақасимонлар, моллюскалар ва бошқа умуртқасиз сув ҳайвонлари ёки ҳар қандай ушбу маҳсулотлар комбинацияларини ўзида тутган тайёр озиқ-овқат маҳсулотлари (16-гуруҳ); (г) нон, унли кондитер маҳсулотлари ва 1905-товар позициясидаги бошқа маҳсулотлар; (д) 2104-товар позициясидаги тайёр озиқ-овқат маҳсулотларининг гомогенланган таркибий қисмлари.","2. 2007 ва 2008-товар позицияларига мевали желеси, мевалар пастаси, шакарланган бодом ёки қандолат маҳсулоти кўринишидаги шунга ўхшаш (1704-товар позицияси) ёки шоколадли қандолат маҳсулотлари (1806-товар позицияси) киритилмайди.","3. 2001, 2004 ва 2005-товар позицияларига фақат 1 (а) изоҳида кўрсатилган усуллардан фарқли равишда тайёрланган ёки консерваланган 07-гуруҳ ёки 1105 ёки 1106-товар позициялари (фақат нозик ва дағал майдалаш орқали олинган кукун ҳамда 08 гуруҳ маҳсулотлари кукунидан ташқари) маҳсулотлари киритилади.","4. Таркибида 7% ёки ундан кўп қуруқ модда тутган помидор шарбати 2002-товар позициясига киритилади.","5. 2007-товар позициясида “иссиқлик билан ишлов бериш натижасида олинган” ибораси атмосфера босими ёки пасайтирилган босим остида иссиқлик билан ишлов бериш йўли билан сув миқдорини камайтириш ёки бошқа сабабдан маҳсулот қовушқоқлигини ошириш мақсадида олинган маҳсулотларни англатади.","6. 2009-товар позициясида “ачитилмаган ва таркибига спирт қўшилмаган шарбатлар” ибораси таркибида спирт 0,5% ҳажмдан кўп бўлмаган шарбатларни англатади (22-гуруҳнинг 2-изоҳига қаранг). Субпозицияларга изоҳ:","1. 2005 10-субпозициядаги “гомогенланган сабзавотлар” ибораси ўта майдаланган ва қадоқланган сабзавотлардан, илк ёшдаги болалар учун ёки парҳез таомланиш учун мўлжалланган, оғирлиги 250 г кўп бўлмаган қадоқларда озиқ-овқат маҳсулотлари сифатида чакана савдода сотиш учун мўлжалланган тайёр маҳсулотларни англатади. Бунда ушбу маҳсулотларга зиравор, консервант ёки бошқа мақсадларда оз миқдорда қўшилган ҳар қандай ингредиентлар эътиборга олинмайди. Бу маҳсулотлар таркибида сабзавотларнинг кўз билан кўриш мумкин бўлган кичик бўлаклари бўлиши мумкин. 2005 10-субпозиция 2005- товар позициясида биринчи даражали устунликка эга.","2. 2007 10 субпозицияда “гомогенланган тайёр маҳсулотлар” ибораси ўта майдаланган ва қадоқланган мевалардан, илк ёшдаги болалар учун ёки парҳез таомланиш учун мўлжалланган, оғирлиги 250 г кўп бўлмаган қадоқларда озиқ-овқат маҳсулотлари сифатида чакана савдода сотиш учун мўлжалланган тайёр маҳсулотларни англатади. Бунда ушбу маҳсулотларга зиравор, консервант ёки бошқа мақсадларда оз миқдорда қўшилган ҳар қандай ингредиентлар эътиборга олинмайди. Бу маҳсулотлар таркибида меваларнинг кўз билан кўриш мумкин бўлган кичик бўлаклари бўлиши мумкин. 2007 10 субпозициясида 2007 товар позициясида биринчи даражали устунликка эга.","3. 2009 12, 2009 21, 2009 31, 2009 41, 2009 61 ва 2009 71 субпозицияларда “Брикс рақами” ибораси Брикс ареометрида бевосита ҳисобланган ареометрик градуслар сони ёки рефрактометрда аниқланган синдириш кўрсаткичи бўлиб, 20оС ҳароратда ёки бошқа ҳароратда ўлчанган бўлса, 20оС га қайта ҳисобланган сахарозанинг фоизларда ифодаланган миқдори тушунилади."],"excl":["1. Бу гуруҳга қуйидагилар киритилмайди: (а) 07, 08 ёки 11-гуруҳларда кўрсатилган усуллар ёрдамида тайёрланган ёки консерваланган сабзавотлар, мевалар ёки ёнғоқлар; (б) ўсимлик мойлари ва ёғлар (15-гуруҳ); (в) 20% массага нисбатан ортиқ колбаса, гўшт, гўшт ярим маҳсулотлари, қон, ҳашаротлар, балиқлар ёки қисқичбақасимонлар, моллюскалар ва бошқа умуртқасиз сув ҳайвонлари ёки ҳар қандай ушбу маҳсулотлар комбинацияларини ўзида тутган тайёр озиқ-овқат маҳсулотлари (16-гуруҳ); (г) нон, унли кондитер маҳсулотлари ва 1905-товар позициясидаги бошқа маҳсулотлар; (д) 2104-товар позициясидаги тайёр озиқ-овқат маҳсулотларининг гомогенланган таркибий қисмлари.","2. 2007 ва 2008-товар позицияларига мевали желеси, мевалар пастаси, шакарланган бодом ёки қандолат маҳсулоти кўринишидаги шунга ўхшаш (1704-товар позицияси) ёки шоколадли қандолат маҳсулотлари (1806-товар позицияси) киритилмайди.","3. 2001, 2004 ва 2005-товар позицияларига фақат 1 (а) изоҳида кўрсатилган усуллардан фарқли равишда тайёрланган ёки консерваланган 07-гуруҳ ёки 1105 ёки 1106-товар позициялари (фақат нозик ва дағал майдалаш орқали олинган кукун ҳамда 08 гуруҳ маҳсулотлари кукунидан ташқари) маҳсулотлари киритилади."]},"21":{"title":"ТУРЛИ ОЗИҚ-ОВҚАТ МАҲСУЛОТЛАРИ","section":"IV","notes":["1. Ушбу гуруҳга қуйидагилар кирмайди: (а) 0712-товар позициясининг сабзавотли аралашмалари (б) қовурилган қаҳва ўрнини босувчи моддалар, таркибида ҳар қандай нисбатдаги қаҳва (0901-товар позицияси); (в) хушбўй таъм-ҳидли қўшимчалари бўлган чой (0902-товар позицияси); (г) 0904 – 0910-товар позициясининг зираворли, хушбўй ва бошқа маҳсулотлари; (д) тайёр озиқ-овқат маҳсулотлари, 2103 ёки 2104-товар позициядагилардан ташқари, таркибида 20 мас% дан ортиқ колбаса, гўшт, гўшт ярим маҳсулотлари, қон, ҳашаротлар, балиқ ёки қисқичбақасимонлар, моллюскалар ёки бошқа сувда яшовчи умуртқасизлар ёки ушбу маҳсулотларнинг ҳар қандай комбинацияси (16-гуруҳ) ); (е) 2404-товар позицияси маҳсулоти; (ж) хамиртурушлар, дори воситалари сифатида фойдаланиладиган 3003- ёки 3004- товар позициясининг бошқа маҳсулотлари; ёки (з) 3507-товар позициясининг ферментли препаратлари.","2. Табиий қаҳва ўрнини босувчиларининг қовурилган экстрактлари юқорида 1(б)-изоҳида айтиб ўтилганидек, 2101-товар позициясига киради.","3. 2104-товар позициясида “гомогенлаштирилган таркибли тайёр озиқ-овқат маҳсулотлари” ибораси гўшт, балиқ, сабзавотлар, мевалар ёки ёнғоқлар каби икки ёки ундан ортиқ асосий компонентларнинг майда бўлинган аралашмасидан иборат бўлган, болаларнинг илк ёшидан ёки парҳез овқатланиш учун мўлжалланган озуқавий маҳсулот сифатида чакана савдога чиқариш учун қадоқланган, ўрамда соф массаси 250 г дан ошмаган тайёр озиқ-овқат маҳсулотларини англатади. Бунда зираворлар, консервантлар ёки бошқа мақсадлар учун қўшилган ҳар қандай ингредиентларнинг оз миқдори эътиборга олинмайди."],"excl":["1. Ушбу гуруҳга қуйидагилар кирмайди: (а) 0712-товар позициясининг сабзавотли аралашмалари (б) қовурилган қаҳва ўрнини босувчи моддалар, таркибида ҳар қандай нисбатдаги қаҳва (0901-товар позицияси); (в) хушбўй таъм-ҳидли қўшимчалари бўлган чой (0902-товар позицияси); (г) 0904 – 0910-товар позициясининг зираворли, хушбўй ва бошқа маҳсулотлари; (д) тайёр озиқ-овқат маҳсулотлари, 2103 ёки 2104-товар позициядагилардан ташқари, таркибида 20 мас% дан ортиқ колбаса, гўшт, гўшт ярим маҳсулотлари, қон, ҳашаротлар, балиқ ёки қисқичбақасимонлар, моллюскалар ёки бошқа сувда яшовчи умуртқасизлар ёки ушбу маҳсулотларнинг ҳар қандай комбинацияси (16-гуруҳ) ); (е) 2404-товар позицияси маҳсулоти; (ж) хамиртурушлар, дори воситалари сифатида фойдаланиладиган 3003- ёки 3004- товар позициясининг бошқа маҳсулотлари; ёки (з) 3507-товар позициясининг ферментли препаратлари."]},"22":{"title":"АЛКОГОЛЛИ ВА АЛКОГОЛСИЗ ИЧИМЛИКЛАР ҲАМДА СИРКА","section":"IV","notes":[],"excl":[]},"23":{"title":"ОЗИҚ-ОВҚАТ САНОАТИНИНГ ҚОЛДИҚЛАРИ ВА ЧИҚИНДИЛАРИ;","section":"IV","notes":[],"excl":[]},"24":{"title":"ТАМАКИ ВА САНОАТДА УНИНГ ЎРНИНИ БОСУВЧИЛАР; ЁНДИРМАСДАН НАФАС ОЛИШ УЧУН","section":"IV","notes":["1. Ушбу гуруҳга доривор сигареталар киритилмаган (30-гуруҳ).","2. 2404-товар позициясига ҳам, ушбу гуруҳнинг бошқа ҳар қандай позициясига киритилиши мумкин бўлган ҳар қандай маҳсулот, 2404-товар позициясига киритилиши керак.","3. 2404-позициядаги “ёнмасдан нафас олиш учун” ибораси иситиш ёрдамида ёки бошқа усуллар билан ёнмасдан нафас олишни англатади. Субпозициясига изоҳ:","1. 2403-субпозицияда “чилим учун тамаки” атамаси кальян орқали чекиш учун мўлжалланган ҳамда тамаки ва глицерин аралашмасидан ташкил топган, таркибида ароматик мойлар ва экстрактлар, мелассу ёки шакар бўлган ёки бўлмаган, мевали ёки мевали бўлмаган, хушбўй ҳидга эга бўлган ёки бўлмаган тамакини англатади. Бироқ кальян ёрдамида чекиш учун мўлжалланган тамакисиз бўлган маҳсулотлар ушбу субпозициядан чиқариб ташланади."],"excl":[]},"25":{"title":"ТУЗ; ОЛТИНГУГУРТ; ТУПРОҚЛАР ВА ТОШ;","section":"V","notes":["1. Контекст ёкиушбу гуруҳнинг 4-изоҳида бошқа маълумотлар учрамаса, ушбу гуруҳга фақат хом ёки ювилган (шу жумладан, маҳсулот тузилишини ўзгартирмасдан зарарли аралашмаларни йўқ қиладиган кимёвий моддалардан фойдаланган ҳолда), парчаланган, туйилган, кукунга айлантирилган, элакдан ўтказилган, флотация йўли билан, магнитли ажратиш ёки бошқа механик ва физик жараёнларни ишлатган ҳолда бойитилган маҳсулотлар киритилади. Қиздириш ёки аралаштириш йўли билан билан олинган, кальцинацияланган ёки ҳар бир маҳсулот позицияларида кўрсатилмаган усуллар билан ишловлар берилган маҳсулотлар мазкур гуруҳга киритилмайди. Мазкур гуруҳ маҳсулотлари чанг бостирадиган агентларнинг қўшимчаларини, маҳсулотни анъанавий қўллашдан кўра, ўзига хос ҳолатларда қўллашга мослаштириб, унинг хусусиятларини ўзгартирмаслик шарти билан ўз ичига олиши мумкин.","2. Мазкур гуруҳга қуйидагилар киритилмайди: (а) сублимацияланган, тиндирилган ёки коллоид олтингугурт (товар позицияси – 2802); (б) Fe O га қайта ҳисоблаганда таркибида масса улуши 70% ёки янада кимёвий боғланган 2 3 темири бўлган минерал бўёқлар (товар позицияси – 2821); (в) доривор воситалар ёки 30-гуруҳнинг бошқа маҳсулотлари; (г) парфюмерия, косметик ёки ювиш воситалари (33-гуруҳ); (д) доломит тўлдириш учун аралашмаси (товар позицияси – 3816); (е) брусчатка, бордюр тошлари ёки кўчага ётқизиладиган плиталар (товар позицияси – 6801); мозаикалар учун кубиклар ёки ўхшаш буюмлар (товар позицияси – 6802); том ёпадиган сланецлар, қопламалар ёки гидроизоляциялар (товар позицияси – 6803); (ж) қимматбаҳо ёки яримқимматбаҳо тошлар (товар позицияси – 7102 ёки 7103); (з) ҳар бирининг оғирлиги 2,5 граммдан кам бўлмаган, сунъий йўл билан етиштирилган натрий хлориди ёки магний оксиди кристаллари (оптик элементлардан ташқари), (товар"],"excl":["1. Контекст ёкиушбу гуруҳнинг 4-изоҳида бошқа маълумотлар учрамаса, ушбу гуруҳга фақат хом ёки ювилган (шу жумладан, маҳсулот тузилишини ўзгартирмасдан зарарли аралашмаларни йўқ қиладиган кимёвий моддалардан фойдаланган ҳолда), парчаланган, туйилган, кукунга айлантирилган, элакдан ўтказилган, флотация йўли билан, магнитли ажратиш ёки бошқа механик ва физик жараёнларни ишлатган ҳолда бойитилган маҳсулотлар киритилади. Қиздириш ёки аралаштириш йўли билан билан олинган, кальцинацияланган ёки ҳар бир маҳсулот позицияларида кўрсатилмаган усуллар билан ишловлар берилган маҳсулотлар мазкур гуруҳга киритилмайди. Мазкур гуруҳ маҳсулотлари чанг бостирадиган агентларнинг қўшимчаларини, маҳсулотни анъанавий қўллашдан кўра, ўзига хос ҳолатларда қўллашга мослаштириб, унинг хусусиятларини ўзгартирмаслик шарти билан ўз ичига олиши мумкин.","2. Мазкур гуруҳга қуйидагилар киритилмайди: (а) сублимацияланган, тиндирилган ёки коллоид олтингугурт (товар позицияси – 2802); (б) Fe O га қайта ҳисоблаганда таркибида масса улуши 70% ёки янада кимёвий боғланган 2 3 темири бўлган минерал бўёқлар (товар позицияси – 2821); (в) доривор воситалар ёки 30-гуруҳнинг бошқа маҳсулотлари; (г) парфюмерия, косметик ёки ювиш воситалари (33-гуруҳ); (д) доломит тўлдириш учун аралашмаси (товар позицияси – 3816); (е) брусчатка, бордюр тошлари ёки кўчага ётқизиладиган плиталар (товар позицияси – 6801); мозаикалар учун кубиклар ёки ўхшаш буюмлар (товар позицияси – 6802); том ёпадиган сланецлар, қопламалар ёки гидроизоляциялар (товар позицияси – 6803); (ж) қимматбаҳо ёки яримқимматбаҳо тошлар (товар позицияси – 7102 ёки 7103); (з) ҳар бирининг оғирлиги 2,5 граммдан кам бўлмаган, сунъий йўл билан етиштирилган натрий хлориди ёки магний оксиди кристаллари (оптик элементлардан ташқари), (товар"]},"26":{"title":"РУДА, ШЛАК ВА КУЛ","section":"V","notes":["1. Мазкур гуруҳга киритилмайди: (а) шлак ёки макадама кўринишидаги шунга ўхшаш бўлган саноат чиқиндилари (товар"],"excl":["1. Мазкур гуруҳга киритилмайди: (а) шлак ёки макадама кўринишидаги шунга ўхшаш бўлган саноат чиқиндилари (товар"]},"27":{"title":"МИНЕРАЛ ЁҚИЛҒИ, НЕФТЬ ВА УНИ ҚАЙТА ИШЛАШ МАҲСУЛОТЛАРИ; БИТУМЛАШГАН","section":"V","notes":["1. Мазкур гуруҳга қуйидагилар киритилмайди: (а) маълум кимёвий таркибга эга бўлган органик бирикмалар, товар позицияси 2711 бўлган соф метан ва пропандан ташқари; (б) товар позицияси 3003 ёки 3004 бўлган дори воситалари; (в) товар позицияси 3301, 3302 ёки 3805 бўлган аралаш тўйинмаган углеводородлар.","2. Товар позицияси 2710 бўлган “битумлашган жинслардан олинган, нефть ва нефть маҳсулотлари” атамаси фақат битумлашган жинслардан олинган, нефть ва нефть маҳсулотларини эмас, балки, асосан, аралаш тўйинмаган углеводородлардан ташкил топган, ноароматик массаси ароматик массасидан юқори бўлиши шарти билан ҳар қандай усулда олинган шу каби нефть маҳсулотларини ҳам англатади. Аммо бу ерга 60 % масса улуши кам миқдори, 1013 Мбар босимга келтирилган паст босимда, 300°С ҳароратгача дистиллаш усулида дистилланган синтетик суюқ полиолефинлар киритилмайди (39-гуруҳ).","3. Товар позицияси 2710 бўлган “чиқинди (ишлатилган) нефть маҳсулотлар” ибораси, сув билан аралашган ёки аралашмаган, асоси “битумлашган жинслардан олинган” (мазкур гуруҳнинг 2 к изоҳида келтирилган) нефть ёки нефть маҳсулотлари бўлган чиқиндиларни англатади. Буларга қуйидагилар киради: (а) келгусида асосий (бирламчи) маҳсулот сифатида фойдаланишга яроқсиз нефть маҳсулотлари (масалан, ишлатилган (чиқинди) мойловчи мойлар, ишлатилган гидравлик ва трансформатор мойлари); (б) нефть маҳсулотларини сақлаш учун ишлатиладиган идиш(бак)лардан олинган, таркиби асосан мазкур нефть маҳсулотлари ва асосий (бирламчи) маҳсулотлар ишлаб чиқаришда фойдаланилган юқори концентрацияли қўшимчалар (масалан, кимёвий моддалар) бўлган шлам кўринишидаги нефть маҳсулотлари; (в) нефть маҳсулотларини сақлаш учун ишлатиладиган идиш(бак)ларни ювиш вақтида сизиб чиқадиган нефть маҳсулотлари ёки механик ишлов бериш жараёнида ишлатиладиган совутиш-мойлаш суюқликларидан ҳосил бўладиган сув эмульсиялари ёки сув аралашмалари шаклидаги нефть маҳсулотлари. Субпозицияларга изоҳ:","1. 2701 11-субпозициясидаги “антрацит” ибораси учувчи моддалар миқдори (қуруқ кулсиз асосга ҳисобланган) 14 % дан юқори бўлмаган кўмирни англатади.","2. 2701 12-субпозициясидаги “битумлашган кўмир” атамаси учувчи моддалар миқдори (қуруқ кулсиз асосга ҳисобланган) 14 % дан юқори ва ёнишдаги максимал иссиқлиги (нам кулсиз асосга ҳисобланган) 5 833 ккал/кг дан кам бўлмаган кўмирни англатади.","3. 2707 10, 2707 20, 2707 30 ва 2707 40-субпозициялардаги “бензол”, “толуол”, “ксилол” ва “нафталин” иборалари таркибида мос равишда 50 % ҳажм миқдоридан юқори бензол, толуол, ксилол ёки нафталин бўлган маҳсулотларни англатади.","4. 2710 12 “енгил дистиллят ва маҳсулотлар” ибораси масса улуши 90 % (йўқотишлар билан) ёки ундан юқори ISO 3405 (ASTM D 86 эквивалент усулда) усулида 210 С ҳароратгача дистилланган нефть маҳсулотларини англатади.","5. Товар позицияси 2710 бўлган субпозициялардаги “биодизель” ибораси ишлатилган ёки ишлатилмаган, ёқилғи сифатида фойдаланиладиган, келиб чиқиши ҳайвон, ўсимлик ёки микробиологик ёғ ва мойлардан олинадиган ёғли кислоталарни моноалкил мураккаб эфирларини англатади. 1 1. (А ) 2844- ва 2845-товар позицияларининг изоҳларига мос келадиган маҳсулотлар . (радиоактив рудалардан фарқли равишда), товар позицияларига киритилиши ва бошқа товарлар позицияларининг Номенклатурасига киритилмаслиги лозим. (Б) Юқоридаги 1 (А) изоҳ қоидаларига риоя қилган ҳолда, 2843, 2846 ёки 2852-товар позициялари изоҳларига мос келадиган маҳсулотлар мазкур товарлар позицияларига киритилиши ва ушбу бўлимнинг хеч қайси бошқа товар позицияларига киритилмаслиги лозим. 2 2. Юқоридаги 1-изоҳ қоидаларига риоя қилган ҳолда, ўлчанган дозаларда ёки чакана сотув . асосида етказиб бериладиган 3004, 3005, 3006, 3212, 3303, 3304, 3305, 3306, 3307, 3506, 3707 ёки 3808-товар позицияларига тегишли мазкур товарлар позициясига киритилиши ва Номенклатуранинг бошқа товар позицияларига киритилмаслиги лозим. 3 3. Икки ва ундан ортиқ алоҳида йиғилган компонентлардан иборат бўлган товарлар, . уларнинг айримлари ёки барчаси ушбу бўлимга киритилади ва VI ёки VII бўлимга тегишли маҳсулотларни олиш мақсадида аралаштириш учун мўлжалланган. Улар бўлим товар маҳсулотлари позициясининг қуйидаги шартларига мос келганида киритилиши лозим: (а) уларни дастлабки қайта қадоқлаш ёки қайта жойлаштириб ўрашларсиз усулларидан аниқ фойдаланишни ҳисобга олган ҳолда ишлатиш учун мўлжалланганлиги; (б) биргаликда етказиб берилиши; ва (в) бир-бирини тўлдириб турувчи компонент сифатида табиий хусусияти ёки нисбий нисбат пропорцияларига қараб идентификация қилинади. 4 4. Агар маҳсулот номи ёки уни бажарадиган вазифаси бўйича VI бўлимнинг бир ёки бир . нечта товар позициялари изоҳига мос келса ва 3827-товар позициясининг матнига кўра, у ҳолда бу товар маҳсулот 3827-товар позициясига эмас, балки ўзининг берилган изоҳлари ёки функциясидан келиб чиқиб, мос товар позициясига киритилади."],"excl":["1. Мазкур гуруҳга қуйидагилар киритилмайди: (а) маълум кимёвий таркибга эга бўлган органик бирикмалар, товар позицияси 2711 бўлган соф метан ва пропандан ташқари; (б) товар позицияси 3003 ёки 3004 бўлган дори воситалари; (в) товар позицияси 3301, 3302 ёки 3805 бўлган аралаш тўйинмаган углеводородлар.","2. Товар позицияси 2710 бўлган “битумлашган жинслардан олинган, нефть ва нефть маҳсулотлари” атамаси фақат битумлашган жинслардан олинган, нефть ва нефть маҳсулотларини эмас, балки, асосан, аралаш тўйинмаган углеводородлардан ташкил топган, ноароматик массаси ароматик массасидан юқори бўлиши шарти билан ҳар қандай усулда олинган шу каби нефть маҳсулотларини ҳам англатади. Аммо бу ерга 60 % масса улуши кам миқдори, 1013 Мбар босимга келтирилган паст босимда, 300°С ҳароратгача дистиллаш усулида дистилланган синтетик суюқ полиолефинлар киритилмайди (39-гуруҳ)."]},"28":{"title":"НООРГАНИК КИМЁ МАҲСУЛОТЛАРИ; ҚИММАТБАҲО МЕТАЛЛАР, НОДИР МЕТАЛЛАР,","section":"VI","notes":["1. Агар контекстда бошқача кўрсатилмаган бўлса, ушбу гуруҳ товар позициясига қуйидагилар киритилади: (а) таркибида алоҳида кимёвий элементлар ва маълум бир кимёвий таркибдаги аралашма бирикмаларни сақловчи ёки сақламаган қўшимчалар; (б) юқоридаги (а) бандда кўрсатилган, сувда эрийдиган маҳсулотлар; (в) юқоридаги (а) бандда кўрсатилган маҳсулотлар, бошқа эритувчиларда эриган агар эритиш уларни сақлаш ва ташиш учун нормал ва зарур шарт бўлса, бу маҳсулотларнинг бошқа мақсадларда фойдаланишга имкон бермайдиган хусусиятларини сақлаб қолган ҳолда анъанавийдан оддийроқ бўлиши; (г) уларни сақлаш ва ташиш учун барқарорлаштирувчи моддалар қўшилган (шу жумладан қотишга (ёпишқоқликка) қарши восита) юқоридаги (а), (б) ёки (в) бандда келтирилган маҳсулотлар; (д) чангланишга қарши воситалар ёки уларни индентификация қилишни осонлаштириш учун бўяш моддалари қўшилган ёки ушбу маҳсулотлар хусусиятларини сақлаб туриш учун бошқа мақсадларда фойдаланилмаган хавфсизлик нуқтаи назаридан қўшилган юқоридаги (а), (б), (в) ёки (г) бандларидаги маҳсулотлар.","2. Дитионит ва сульфоксилатлардан ташқари органик моддалар (2831-товар позицияси), ноорганик асосли карбонат ва пероксокарбонатлар (2836-товар позицияси), ноорганик асосли цианидлар, цианид оксиди ва мураккаб таркибли цианидлар (2837-товар позицияси), ноорганик асосли фульминатлар, цианидлар ва тиоцианатлар (2842-товар позицияси), 2843– 2846 ва 2852-товар позициясига киритилган органик маҳсулотлар ҳамда карбидлар (2849- товар позицияси) билан барқарорлаштирилганлар билан бир қаторда ушбу гуруҳга қуйидаги углерод бирикмалари киритилади: (а) углерод оксидлари, водород цианиди, портловчи, изоцианли, тиоцианли ва бошқа оддий ёки циан кислотасининг мураккаб бирикмалари (2811-товар позицияси); (б) углероднинг галогенли оксидлари (2812-товар позицияси); (в) углерод дисульфиди (2813-товар позицияси); (г) тиокарбонатлар, селенокарбонатлар, теллурокарбонатлар, селеноцианатлар, теллуроцианатлар, тетратиоцианатодиамминохроматлар (рейнекатлар) ва бошқа ноорганик асосли цианатлар мажмуаси (2842-товар позицияси); (д) тоза ёки қўшимчалар билан аралашган цианамиддан ташқари (31-гуруҳ) мочевина билан қотирилган водород пероксиди (2847-товар позицияси), углерод оксисульфиди, тиокарбонилгаллогенлар, циан, циан галлогенлар, цианамид ва унинг металл билан ҳосил қилган бирикмалари (2853-товар позицияси).","3. VI бўлимнинг 1-бандида келтирилган ҳолатларга амал қилинганда, ушбу гуруҳга қуйидагилар киритилмайди: (а) соф ёки аралашган хлорид натрийси ёки магний оксиди ҳамда V бўлимга тегишли бошқа маҳсулотлар; (б) Ушбу гуруҳнинг 2-изоҳида келтирилгандан ташқари органик-ноорганик бирикмалар; (в) 31-гуруҳга тегишли бўлган 2-,3-,4- ёки 5-изоҳларда келтирилган маҳсулотлар; (г) 3206-товар позициясидаги люминофор сифатида фойдаланиладиган ноорганик маҳсулотлар; 3207-товар позициясидаги шишасимон фритта ва бошқа шиша кукунлари, гранулалари ёки парчалари; (д) сунъий графит (3801-товар позицияси); 3813-товар позициясидаги ёнғинга қарши заряд сифатида ишлатиладиган маҳсулотлар ёки ёнғинни ўчиришда ишлатиладиган гранаталар таркибидаги маҳсулотлар; 3824-товар позициясидаги сиёҳ доғларидан тозалайдиган, чакана савдо учун қадоқланган таркиблар (состав); 3824-товар позициясидаги ҳар бири 2,5 граммдан кам бўлмаган оғирликдаги ишқорли ёки ишқор-ер металлари галогенидларининг сунъий етиштирилган кристаллари (оптик элементлардан ташқари); (е) қимматбаҳо ёки ярим қимматбаҳо тошлар (табиий, сунъий, қайта тикланган), шу жумладан, ушбу тошларнинг парчалари ёки кукунлари (7102–7105-товар позициялари), ёки 71-гуруҳнинг қимматбаҳо металлари ёки қимматбаҳо металларнинг қотишмаси; (ж) XV бўлимдаги тоза ёки аралашмали металлар, уларнинг қотишмаси ёки металлокерамика, шу жумладан, металларнинг қиздирилган карбидлари (металл карбидлари, металл билан қиздирилган), ёки (з) оптик элементлар, мисол учун ишқорли ёки ишқор-ер металларнинг галогенидлари (9001-товар позицияси).","4. II кичик гуруҳ нометаллардан ҳосил бўлган кислоталардан ташкил топган кислоталар комплекси ва IV кичик гуруҳ металларидан ҳосил бўлган кислоталар 2811-товар позициясига киритилади.","5. 2826–2842-товар позицияларига фақат металл ёки аммоний тузлари ёки перексо тузлари киритилади. Агар контекстда бошқа талаблар қўйилмаса қўш тузлар ёки комплекс тузлар 2842-товар позициясига киритилади. 2826–2842-товар позицияларига фақат металл ёки аммоний тузлари ёки перексо тузлари киритилади. Агар контекстда бошқа талаблар қўйилмаса қўш тузлар ёки комплекс тузлар 2842-товар позициясига киритилади.","6. 2844-товар позициясига фақат қуйидагилар киритилади: (а) технеций (тартиб рақами – 43), прометий (тартиб рақами – 61), полоний (тартиб рақами – – 84) ва тартиб рақами – 84 баланд бўлган барча элементлар; (б) аралашма ёки алоҳида бўлган табиий ёки суннъий радиоактив изотоплар (шу жумладан XIV ва XV бўлимларда кўрсатилган қимматбаҳо ёки қимматбаҳо бўлмаган металларнинг изотоплар); (в) ушбу элементлар ва изотопларнинг бирикмалари, органик ёки ноорганик, аниқланган ёки аниқланмаган кимёвий таркиб, аралашма ёки алоҳида; (г) қотишмалар, дисперсиялар (шу жумладан, металлокерамика), ушбу элементлардан ёки уларнинг изотопидан ташкил топган керамика маҳсулотлари ва аралашмалар, шу жумладан, номи келтирилган элементлар ва радиоактивлик даражаси 0,002 мкКи/г (74 Бк/г) дан ортиқ бўлган изотопларнинг ноорганик ва органик бирикмалари; (д) ядро реакторларининг ишлатилган (нурланган) ўзидан иссиқлик чиқарувчи (твэл) элементлари; (е) фойдаланишга яроқли ва яроқсиз ядро чиқиндилари. Ушбу изоҳларда ва 2844- ҳамда 2845-товар позицияларида келтирилган номларда “изотоплар” қуйидаги маънони англатади: – Индивидуал нуклидлар (табиатда моноизотоп ҳолатда учрайдиган нуклидлар бундан мустасно); – Юқорида кўрсатилган, яъни табиий изотоплар таркиби сунъий равишда ўзгартирилган, бир ёки бир неча изотоплар билан бойитилган, бир элемент изотоплари аралашмаси. 2852-товар позициясига таркибининг масса улуши 15% фосфордан иборат бўлган мис фосфиди киритилади.","8. Электроника соҳасида фойдаланиладиган кимёвий элементлар (масалан кремний ва селен) агар улар қайта ишланмаган чўзилган ёки цилиндр шаклда ёки стержень шаклида бўлса. Агар улар диск, пластина ва бошқа шундай формаларда бўлса, 3818-товар позициясига киритилади. Субпозицияларга изоҳ:","1. 285210 субпоизциядаги “маълум кимёвий таркиб” ибораси 28–гуруҳнинг 1(а)–1(д) ва 29 гуруҳнинг 1(а)–1(з) изоҳлари талабларига жавоб берадиган барча органик ва ноорганик симоб бирикмаларини англатади."],"excl":["2. Дитионит ва сульфоксилатлардан ташқари органик моддалар (2831-товар позицияси), ноорганик асосли карбонат ва пероксокарбонатлар (2836-товар позицияси), ноорганик асосли цианидлар, цианид оксиди ва мураккаб таркибли цианидлар (2837-товар позицияси), ноорганик асосли фульминатлар, цианидлар ва тиоцианатлар (2842-товар позицияси), 2843– 2846 ва 2852-товар позициясига киритилган органик маҳсулотлар ҳамда карбидлар (2849- товар позицияси) билан барқарорлаштирилганлар билан бир қаторда ушбу гуруҳга қуйидаги углерод бирикмалари киритилади: (а) углерод оксидлари, водород цианиди, портловчи, изоцианли, тиоцианли ва бошқа оддий ёки циан кислотасининг мураккаб бирикмалари (2811-товар позицияси); (б) углероднинг галогенли оксидлари (2812-товар позицияси); (в) углерод дисульфиди (2813-товар позицияси); (г) тиокарбонатлар, селенокарбонатлар, теллурокарбонатлар, селеноцианатлар, теллуроцианатлар, тетратиоцианатодиамминохроматлар (рейнекатлар) ва бошқа ноорганик асосли цианатлар мажмуаси (2842-товар позицияси); (д) тоза ёки қўшимчалар билан аралашган цианамиддан ташқари (31-гуруҳ) мочевина билан қотирилган водород пероксиди (2847-товар позицияси), углерод оксисульфиди, тиокарбонилгаллогенлар, циан, циан галлогенлар, цианамид ва унинг металл билан ҳосил қилган бирикмалари (2853-товар позицияси).","3. VI бўлимнинг 1-бандида келтирилган ҳолатларга амал қилинганда, ушбу гуруҳга қуйидагилар киритилмайди: (а) соф ёки аралашган хлорид натрийси ёки магний оксиди ҳамда V бўлимга тегишли бошқа маҳсулотлар; (б) Ушбу гуруҳнинг 2-изоҳида келтирилгандан ташқари органик-ноорганик бирикмалар; (в) 31-гуруҳга тегишли бўлган 2-,3-,4- ёки 5-изоҳларда келтирилган маҳсулотлар; (г) 3206-товар позициясидаги люминофор сифатида фойдаланиладиган ноорганик маҳсулотлар; 3207-товар позициясидаги шишасимон фритта ва бошқа шиша кукунлари, гранулалари ёки парчалари; (д) сунъий графит (3801-товар позицияси); 3813-товар позициясидаги ёнғинга қарши заряд сифатида ишлатиладиган маҳсулотлар ёки ёнғинни ўчиришда ишлатиладиган гранаталар таркибидаги маҳсулотлар; 3824-товар позициясидаги сиёҳ доғларидан тозалайдиган, чакана савдо учун қадоқланган таркиблар (состав); 3824-товар позициясидаги ҳар бири 2,5 граммдан кам бўлмаган оғирликдаги ишқорли ёки ишқор-ер металлари галогенидларининг сунъий етиштирилган кристаллари (оптик элементлардан ташқари); (е) қимматбаҳо ёки ярим қимматбаҳо тошлар (табиий, сунъий, қайта тикланган), шу жумладан, ушбу тошларнинг парчалари ёки кукунлари (7102–7105-товар позициялари), ёки 71-гуруҳнинг қимматбаҳо металлари ёки қимматбаҳо металларнинг қотишмаси; (ж) XV бўлимдаги тоза ёки аралашмали металлар, уларнинг қотишмаси ёки металлокерамика, шу жумладан, металларнинг қиздирилган карбидлари (металл карбидлари, металл билан қиздирилган), ёки (з) оптик элементлар, мисол учун ишқорли ёки ишқор-ер металларнинг галогенидлари (9001-товар позицияси)."]},"29":{"title":"ОРГАНИК КИМЁВИЙ БИРИКМАЛАР","section":"VI","notes":["1. Агар контекстда бошқача кўрсатилмаган бўлса, ушбу гуруҳнинг маҳсулот позицияларига фақат қуйидагилар киради: (а) таркибида аралашмалар бўлган ёки бўлмаган аниқ бир кимёвий таркибдаги алоҳида органик бирикмалар; (б) бир хил органик бирикманинг икки ёки ундан ортиқ компонентли изомер аралашмалари (таркибида аралашмалар бўлган ёки бўлмаган), тўйинган ёки тўйинмаган (27-гуруҳ) ациклик углеводородлар (лекин стереоизомерлар эмас), изомерларининг аралашмалари бундан мустасно; (в) 2936 – 2939-товар позициялари ёки оддий шакар эфирлари, шакар ацеталлари, мураккаб шакар эфирлари ва уларнинг тузлари, аниқ ёхуд ноаниқ кимёвий таркибдаги 2940-товар позицияси ёки 2941-товар позицияси маҳсулотлари; (г) юқоридаги (а), (б) ёки (в) бандларда кўрсатилган, сувда эрийдиган маҳсулотлар; (д) юқоридаги (а), (б) ёки (в) бандларда кўрсатилган, бошқа эритмаларда эритилган маҳсулотлар, эритиш фақат ушбу маҳсулотларни сақлаш ёки ташиш учун ишлатиладиган оддий ва зарур усул бўлган ва эритувчи маҳсулотни анъанавий фойдаланишдан бошқача маълум бир ўзига хос қўллаш учун яроқли қилмайдиган шартларда; (е) юқорида кўрсатилган (а), (б), (в), (г) ёки (д) бандлардаги маҳсулотлар, уларни сақлаш ёки ташиш учун зарур бўлган барқарорлаштирувчи модда (шу жумладан, ёпишиб қолишга қарши агент) қўшилган ҳолда; (ж) юқорида кўрсатилган (а), (б), (в), (г), (д) ёки (е)бандлардаги маҳсулотлар чангга қарши восита ёки бўёвчи хушбўй моддалар ёки қайд қилдирадиган восита қўшилиши билан уларни идентификациялашни осонлаштириш учун ёки хавфсизлик мақсадида, ушбу қўшимчалар маҳсулотни анъанавий қўллашдан бошқача ўзига хос қўллаш учун яроқли қилмайдиган шартларда; (з) азобўёқларини ишлаб чиқариш учун стандарт концентрацияга эга суюлтирилган қуйидаги маҳсулотлар: диазоний тузлари, ушбу тузлар билан биргаликда реакцияга киришадиган моддалар, диазотловчи аминлар ва уларнинг тузларини.","2. Ушбу гуруҳга қуйидагилар кирмайди: (а) 1504 товар позицияси маҳсулотлари ёки 1520-товар позицияси хом глицерини; (б) этил спирти (2207- ёки 2208-товар позицияси); (в) метан ёки пропан (2711-товар позицияси); (г) 28-гуруҳга 2-изоҳда кўрсатилган углерод бирикмалари; (д) 3002-товар позициясининг иммунологик маҳсулотлари; (е) мочевина (3102- ёки 3105-товар позицияси); (ж) ўсимлик ёки ҳайвонот манбаларидан келиб чиққан бўёвчи моддалар (3203-товар позицияси), синтетик органик бўёвчи моддалар, оптик оқартирувчи ёки люминофорлар сифатида ишлатиладиган синтетик органик маҳсулотлар (3204-товар позицияси) ёки чакана савдо учун қолиплар ёки идишларга қадоқланган бўёқлар ёки бўёвчи моддалар (3212-товар позицияси); (з) ферментлар (3507-товар позицияси) (и) ёқилғи сифатида ишлатиш учун мўлжалланган, қолипларга(масалан, таблетка, таёқчалар ёки шунга ўхшаш шакллар) қадоқланган металдегид, гексаметиленетрамин ёки шунга ўхшаш моддалар сигарета учун зажигалкаларни тўлдириш ёки қайта тўлдириш учун ишлатиладиган сиғими 300 см³ дан ортиқ бўлмаган контейнерлардаги суюқ ёки суюлтирилган газсимон ёқилғи (3606-товар позицияси); (к) 3813-товар позициядаги ёнғинларни ўчириш учун ўт ўчиргич ёки гранаталар учун заряд сифатида етказиб бериладиган маҳсулотлар; 3824-товар позицияли чакана сотув учун қадоқланган сиёҳ доғларини йўқотиш таркиблари; л) оптик элементлар, масалан, этилендиаминтратдан тайёрланган (9001-товар позицияси).","3. Ушбу гуруҳнинг икки ёки ундан ортиқ маҳсулот позицияларига киритилиши мумкин бўлган маҳсулотлар товар позициясига киритилади, охиргиси ушбу Номенклатура гуруҳидаги кодларнинг ўсиш тартибида киритилади."],"excl":["2. Ушбу гуруҳга қуйидагилар кирмайди: (а) 1504 товар позицияси маҳсулотлари ёки 1520-товар позицияси хом глицерини; (б) этил спирти (2207- ёки 2208-товар позицияси); (в) метан ёки пропан (2711-товар позицияси); (г) 28-гуруҳга 2-изоҳда кўрсатилган углерод бирикмалари; (д) 3002-товар позициясининг иммунологик маҳсулотлари; (е) мочевина (3102- ёки 3105-товар позицияси); (ж) ўсимлик ёки ҳайвонот манбаларидан келиб чиққан бўёвчи моддалар (3203-товар позицияси), синтетик органик бўёвчи моддалар, оптик оқартирувчи ёки люминофорлар сифатида ишлатиладиган синтетик органик маҳсулотлар (3204-товар позицияси) ёки чакана савдо учун қолиплар ёки идишларга қадоқланган бўёқлар ёки бўёвчи моддалар (3212-товар позицияси); (з) ферментлар (3507-товар позицияси) (и) ёқилғи сифатида ишлатиш учун мўлжалланган, қолипларга(масалан, таблетка, таёқчалар ёки шунга ўхшаш шакллар) қадоқланган металдегид, гексаметиленетрамин ёки шунга ўхшаш моддалар сигарета учун зажигалкаларни тўлдириш ёки қайта тўлдириш учун ишлатиладиган сиғими 300 см³ дан ортиқ бўлмаган контейнерлардаги суюқ ёки суюлтирилган газсимон ёқилғи (3606-товар позицияси); (к) 3813-товар позициядаги ёнғинларни ўчириш учун ўт ўчиргич ёки гранаталар учун заряд сифатида етказиб бериладиган маҳсулотлар; 3824-товар позицияли чакана сотув учун қадоқланган сиёҳ доғларини йўқотиш таркиблари; л) оптик элементлар, масалан, этилендиаминтратдан тайёрланган (9001-товар позицияси)."]},"30":{"title":"ФАРМАЦЕВТИКА МАҲСУЛОТЛАРИ","section":"VI","notes":["1. Ушбу гуруҳга кирмайди: (а) венатомири ичига юбориладиган озуқавий препаратлардан ташқари, озиқ-овқат ёки ичимликлар (масалан парҳез, диабет ёки озуқавий қўшимчалар билан бойитилган озиқ овқатлар, озуқавий қўшимчалар, организмнинг тонусини оширувчи ичимликлар ва минерал сувлар) (IV бўлим); (б) никотин сақловчи ва тамаки чекишни ташлашга ёрдам бериш учун мўлжалланган таблеткалар, сақичлар ёки пластирлар (трансдермал тизимлар (системалар) каби маҳсулотлар (2404-товар позицияси); (в) стоматологияда ишлатиш учун махсус кальцийлаштирилган ёки майдаланган гипслар (2520-товар позицияси); (г) тиббий мақсадда қўлланилишига мўлжалланган эфир мойларининг сувли эритмалари ёки сувли дистиллятлари (3301-товар позицияси) (д) 3303–3307-товар позицияларидаги препаратлар, гарчи терапевтик ёки профилактик хусусиятларга эга бўлган бўлса ҳам; (е) 3401-товар позициясидаги доривор қўшимчаларни сақловчи совун ва бошқа маҳсулотлар; (ж) стоматологияда ишлатиш учун гипс асосидаги воситалар (3407-товар позицияси); (з) терапевтик ёки профилактик мақсадларда ишлатиш учун мўлжалланмаган қон альбумини (3502-товар позицияси); ёки (и) 3822-товар позициясидаги диагностик реагентлар товар позицияси – 3822.","2. 3002-товар позициясидаги, моноклонал антителолар (МАВ), антитело фрагментлари, антитело коньюгатлари ва антителолар фрагментлари коньюгатлари, интерлейкинлар, интерферонлар (IFN), хемокинлар ва ўсимта некрози факторларининг баъзилари (TNF), ўсиш фактори (GF), гематопоэтинлар ва колониястимулловчи факторлар (CSF) каби бевосита иммунологик жараёнларни тартибга солишда иштирок этадиган “иммунобиологик препаратлар” тушунчаси пептидлар ва оқсилларга тегишли (2937-товар позициясидан ташқари)","3. Ушбу гуруҳда 3003- ва 3004-товар позициялари ва 4 (г) изоҳида қуйидагилар тушунилиши керак: (а) аралашмаган маҳсулотлар деб: (1) сувда эрийдиган аралашмаган маҳсулотлар; (2) 28- ёки 29-гуруҳларидаги барча маҳсулотлар; (3) фақат ҳар қандай эритувчида эритилган ва стандартлаштирилган 1302 товар позициясидаги оддий ўсимлик экстрактлари; (б) аралашган маҳсулотлар: (1) коллоид эритмалар ва суспензиялар (коллоид олтингугуртдан ташқари); (2) ўсимлик хом ашёси аралашмасини қайта ишлаш натижасида олинган ўсимлик; (3) табиий минерал сувларни буғлантириш орқали олинган тузлар ва концентратлар.","4. 3006-товар позициясига фақат ушбу гуруҳга киритилиши керак бўлган ва Номенклатура товар позициясининг бошқа ҳеч қандай гуруҳга киритилмайдиган қуйидаги маҳсулотлар киради: (а) стерил жарроҳлик кетгутитикиш учун шунга ўхшаш стерил материаллар (жумладан стерил сўрилиб кетувчи жарроҳлик ёки стоматологик иплар) ва жароҳатларни жарроҳлик йўли билан ёпиш учун стерил адгезив матолар ; (б) стерил ламинария ва ламинариядан стерил тампонлар; (в) стерил сўрилиб кетувчи жарроҳлик ёки стоматологик қон тўхтатувчи воситалар (гемостатиклар), сўрилиб кетувчи ёки сўрилмайдиган стерил жарроҳлик ёки стоматологик адгезион барьерлар; (г) беморларга юбориш учун мўлжалланган, дозаланган шаклдаги аралашмаган моддалар ҳисобланувчи ёки икки ёки ундан кўп компонентлардан ташкил топган, шунга ўхшаш ишлатишга мўлжалланган аралашган моддалар рентгенографик текшириш учун контраст препаратлар ва диагностик реагентлар; (д) маъқулланган клиник тадқиқотларни оддий яширин (ёки икки томонлама яширин) усул билан ўтказиш учун дозаланган шакллар кўринишида қадоқланган плацебо ва клиник тадқиқотлар учун атайин тайёрланган препаратлар тўплами, агар ҳатто улар фаол (таъсир этувчи) дори моддалари сақлаши мумкин бўлса ҳам; (е) тиш цементлари ва тишларни пломбалаш учун бошқа материаллар, суяк реконструкцияси учун цементлар; (ж) санитар сумкалар ва биринчи тиббий ёрдам кўрсатиш учун тўпламлар; (з) гормонлар асосидаги кимёвий контрацевтик воситалар, 2937-товар позициясидаги бошқа бирикмалар ёки спермицидлар; (и) тиббиётда ёки ветеринарияда жарроҳлик операциялари ёки физик тадқиқотларда тана қисмларига суртиш учун мўлжалланган ёки тана ва тиббий асбоб-ускуна ўртасида бириктирувчи агент сифатида қўлланиладиган гель шаклидаги препаратлар; (к) яроқсиз фармацевтика воситалари, яъни бирламчи кўрсатмасига асосан қўллашга яроқсиз, масалан, яроқлилик муддати тугаган, фармацевтика маҳсулоти; (л) стомик ишлатиш учун мосламалар, яъни шаклига кўра кесилган, колостом, илеостом ва уростом қоплар, уларнинг ёпишқоқ пластиналари ёки юз қисмлари деб идентификацияланган мосламалар. Субпозицияларга изоҳлар:","1. 3002 13- ва 3002 14-субпозицияларда тушунилиш керак: (a) аралашмаган маҳсулотлар – ёт моддалар сақловчи ёки сақламаган тоза моддалар; (б) аралашган маҳсулотлар: (1) сувда ёки бошқа эритувчиларда эритилган (а) пунктда келтирилган маҳсулотлар; (2) (a) ва (б) (1) пунктларда келтирилган, сақлаш ва ташиш учун зарур бўлган стабилизаторлар қўшилган маҳсулотлар; ҳамда (3) юқоридаги (a), (б) (1) и (б) (2) бандларда келтирилган, бошқа ҳар қандай қўшимчалар билан маҳсулотлар.","2. 3003 60- ва 3004 60-субпозицияларга бошқа фармацевтик фаол моддалар билан мажмуавий таркибда ёки бошқа қуйидаги фаол (таъсир этувчи) моддалар билан мажмуавий ёки алоҳида таркибда: амодиахин (INN); артелинат кислотаси ёки унинг тузлари; артенимол (INN); артемотил (INN); артеметер (INN); артесунат (INN); хлорохин (INN); дигидроартемизинин (INN); лумефантрин (INN); мефлохин (INN); пиперахин (INN); пириметамин (INN) ёки сульфадоксин (INN), ичга қабул қилиш учун мўлжалланган артемизинин (INN) сақловчи дори воситалари."],"excl":["1. Ушбу гуруҳга кирмайди: (а) венатомири ичига юбориладиган озуқавий препаратлардан ташқари, озиқ-овқат ёки ичимликлар (масалан парҳез, диабет ёки озуқавий қўшимчалар билан бойитилган озиқ овқатлар, озуқавий қўшимчалар, организмнинг тонусини оширувчи ичимликлар ва минерал сувлар) (IV бўлим); (б) никотин сақловчи ва тамаки чекишни ташлашга ёрдам бериш учун мўлжалланган таблеткалар, сақичлар ёки пластирлар (трансдермал тизимлар (системалар) каби маҳсулотлар (2404-товар позицияси); (в) стоматологияда ишлатиш учун махсус кальцийлаштирилган ёки майдаланган гипслар (2520-товар позицияси); (г) тиббий мақсадда қўлланилишига мўлжалланган эфир мойларининг сувли эритмалари ёки сувли дистиллятлари (3301-товар позицияси) (д) 3303–3307-товар позицияларидаги препаратлар, гарчи терапевтик ёки профилактик хусусиятларга эга бўлган бўлса ҳам; (е) 3401-товар позициясидаги доривор қўшимчаларни сақловчи совун ва бошқа маҳсулотлар; (ж) стоматологияда ишлатиш учун гипс асосидаги воситалар (3407-товар позицияси); (з) терапевтик ёки профилактик мақсадларда ишлатиш учун мўлжалланмаган қон альбумини (3502-товар позицияси); ёки (и) 3822-товар позициясидаги диагностик реагентлар товар позицияси – 3822.","2. 3002-товар позициясидаги, моноклонал антителолар (МАВ), антитело фрагментлари, антитело коньюгатлари ва антителолар фрагментлари коньюгатлари, интерлейкинлар, интерферонлар (IFN), хемокинлар ва ўсимта некрози факторларининг баъзилари (TNF), ўсиш фактори (GF), гематопоэтинлар ва колониястимулловчи факторлар (CSF) каби бевосита иммунологик жараёнларни тартибга солишда иштирок этадиган “иммунобиологик препаратлар” тушунчаси пептидлар ва оқсилларга тегишли (2937-товар позициясидан ташқари)","3. Ушбу гуруҳда 3003- ва 3004-товар позициялари ва 4 (г) изоҳида қуйидагилар тушунилиши керак: (а) аралашмаган маҳсулотлар деб: (1) сувда эрийдиган аралашмаган маҳсулотлар; (2) 28- ёки 29-гуруҳларидаги барча маҳсулотлар; (3) фақат ҳар қандай эритувчида эритилган ва стандартлаштирилган 1302 товар позициясидаги оддий ўсимлик экстрактлари; (б) аралашган маҳсулотлар: (1) коллоид эритмалар ва суспензиялар (коллоид олтингугуртдан ташқари); (2) ўсимлик хом ашёси аралашмасини қайта ишлаш натижасида олинган ўсимлик; (3) табиий минерал сувларни буғлантириш орқали олинган тузлар ва концентратлар.","4. 3006-товар позициясига фақат ушбу гуруҳга киритилиши керак бўлган ва Номенклатура товар позициясининг бошқа ҳеч қандай гуруҳга киритилмайдиган қуйидаги маҳсулотлар киради: (а) стерил жарроҳлик кетгутитикиш учун шунга ўхшаш стерил материаллар (жумладан стерил сўрилиб кетувчи жарроҳлик ёки стоматологик иплар) ва жароҳатларни жарроҳлик йўли билан ёпиш учун стерил адгезив матолар ; (б) стерил ламинария ва ламинариядан стерил тампонлар; (в) стерил сўрилиб кетувчи жарроҳлик ёки стоматологик қон тўхтатувчи воситалар (гемостатиклар), сўрилиб кетувчи ёки сўрилмайдиган стерил жарроҳлик ёки стоматологик адгезион барьерлар; (г) беморларга юбориш учун мўлжалланган, дозаланган шаклдаги аралашмаган моддалар ҳисобланувчи ёки икки ёки ундан кўп компонентлардан ташкил топган, шунга ўхшаш ишлатишга мўлжалланган аралашган моддалар рентгенографик текшириш учун контраст препаратлар ва диагностик реагентлар; (д) маъқулланган клиник тадқиқотларни оддий яширин (ёки икки томонлама яширин) усул билан ўтказиш учун дозаланган шакллар кўринишида қадоқланган плацебо ва клиник тадқиқотлар учун атайин тайёрланган препаратлар тўплами, агар ҳатто улар фаол (таъсир этувчи) дори моддалари сақлаши мумкин бўлса ҳам; (е) тиш цементлари ва тишларни пломбалаш учун бошқа материаллар, суяк реконструкцияси учун цементлар; (ж) санитар сумкалар ва биринчи тиббий ёрдам кўрсатиш учун тўпламлар; (з) гормонлар асосидаги кимёвий контрацевтик воситалар, 2937-товар позициясидаги бошқа бирикмалар ёки спермицидлар; (и) тиббиётда ёки ветеринарияда жарроҳлик операциялари ёки физик тадқиқотларда тана қисмларига суртиш учун мўлжалланган ёки тана ва тиббий асбоб-ускуна ўртасида бириктирувчи агент сифатида қўлланиладиган гель шаклидаги препаратлар; (к) яроқсиз фармацевтика воситалари, яъни бирламчи кўрсатмасига асосан қўллашга яроқсиз, масалан, яроқлилик муддати тугаган, фармацевтика маҳсулоти; (л) стомик ишлатиш учун мосламалар, яъни шаклига кўра кесилган, колостом, илеостом ва уростом қоплар, уларнинг ёпишқоқ пластиналари ёки юз қисмлари деб идентификацияланган мосламалар. Субпозицияларга изоҳлар:"]},"31":{"title":"ЎҒИТЛАР","section":"VI","notes":["1. Ушбу гуруҳга қуйидагилар киритилмайди: (а) 0511-товар позициясидаги ҳайвонлар қони; (б) маълум кимёвий таркибга эга бўлган алоҳида бирикмалар (2 (а), 3 (а), 4 (а) ёки 5- бандларда кўрсатилганлар бундан мустасно); ёки (в) 3824-товар позицияси киритиладиган, ҳар бирининг оғирлиги 2,5 г дан кам бўлмаган, калий хлориднинг сунъий равишда ўстирилган кристаллари (оптик элементлардан ташқари); калий хлориднинг оптик элементлари (9001 товар позицияси).","2. 3102-товар позициясига фақат қуйидаги маҳсулотлар киради: агар улар 3105-товар позициясида назарда тутилган ўрамлар ёки шаклларига қадоқланмаган бўлса: (а) қуйида келтирилган тавсифларнинг бирига ёки бошқасига мос келадиган маҳсулотлар: (i) натрий нитрати, қўшимча аралашмалар билан ёки қўшимча аралашмаларсиз; (ii) аммоний нитрати, қўшимча аралашмалар билан ёки қўшимча аралашмаларсиз; (iii) аммоний сульфати ва аммоний нитратининг қўш тузлари, қўшимча аралашмалар билан ёки қўшимча аралашмаларсиз; (iv) аммоний сульфати, қўшимча аралашмалар билан ёки қўшимча аралашмаларсиз; (v) қўш тузлар (қўшимча аралашмалар билан ёки қўшимча аралашмаларсиз) ёки кальций нитрати ва аммоний нитрати аралашмалари; (vi) қўш тузлар (қўшимча аралашмалар билан ёки қўшимча аралашмаларсиз) ёки кальций нитрати ва магний нитрати аралашмалари; (vii) қўшимча аралашмалар билан ёки қўшимча аралашмаларсиз, ёғ билан ишлов берилган ёки ишлов берилмаган кальций цианамиди; (viii) қўшимча аралашмалар билан ёки қўшимча аралашмаларсиз, мочевина (карбамид); (б) 2 (а) изоҳида кўрсатилган ҳар қандай моддаларнинг аралашмаларидан ташкил топган ўғитлар; (в) аммоний хлоридидан таркиб топган ёки 2 (а) ёки 2 (б) изоҳларда кўрсатилган, ўғит бўлмаган бўр, гипс ёки бошқа ноорганик моддалар билан аралаштирилган ҳар қандай бошқа моддадан иборат бўлган ўғитлар; (г) 2 (а) (ii) ёки 2 (а) (viii) изоҳларида кўрсатилган маҳсулотлардан ёки ушбу маҳсулотларнинг сувли ёки аммиак эритмасидаги аралашмаларидан ташкил топган суюқ ўғитлар.","3. 3103-маҳсулот позицияга фақат қуйидаги маҳсулотлар киради‚ агар улар 3105-товар позицияда назарда тутилган шакллар ёки ўрамларга қадоқланмаган бўлса: (а) қуйида келтирилган тавсифлардан бирига ёки бошқасига мос келадиган маҳсулотлар: (i) асосий шлак; (ii) кальцинацияланган ёки қўшимча аралашмаларни олиб ташлаш учун зарур бўлгандан юқорироқ ҳароратда ишлов берилган, 2510-товар позициясидаги табиий фосфатлар; (iii) суперфосфатлар (оддий, икки ёки уч ҳиссали); (iv) қуруқ сувсиз маҳсулотга қайта ҳисобланганда фторнинг камида 0,2% масса улушини ўз ичига олган кальций водородфосфати; (б) 3(а) изоҳда кўрсатилган ҳар қандай маҳсулотларнинг аралашмаларидан ташкил топган ўғитлар, лекин фторнинг максимал миқдорини ҳисобга олмаганда; (в) 3 (а) ёки 3 (б) изоҳларда кўрсатилган ҳар қандай маҳсулотлардан ташкил топган, лекин фторнинг максимал миқдорини ҳисобга олмаган, ўғит бўлмаган бўр, гипс ёки бошқа ноорганик моддалар билан аралаштирилган ўғитлар.","4. 3104-товар позицияга фақат қуйидаги маҳсулотлар киради: агар улар 3105-товар позициясида назарда тутилган шакллар ёки ўрамларга қадоқланмаган бўлмаса: (а) қуйидаги тавсифлардан бирига ёки бошқасига мос келадиган маҳсулотлар: (i) ишлов берилмаган калий тузлари (масалан, карналлит, каинит ва сильвит); (ii) калий хлориди, қўшимча аралашмалар билан ёки қўшимча аралашмаларсиз, юқоридаги 1 (в) изоҳда кўрсатилганлар бундан мустасно; (iii) калий сульфати, қўшимча аралашмалар билан ёки қўшимча аралашмаларсиз; (iv) калий–магний сульфати, қўшимча аралашмалар билан ёки қўшимча аралашмаларсиз; (б) юқорида 4(а) изоҳда кўрсатилган ҳар қандай моддалар аралашмасидан ташкил топган ўғитлар.","5. Аммоний диводородфосфат (моноаммоний фосфат) ва диаммоний водород фосфат (диаммоний фосфат), қўшимча аралашмалар билан ёки қўшимча аралашмаларсиз, шунингдек уларнинг аралашмалари 3105-товар позициясига киритилиши керак.","6. 3105-товар позициясида “бошқа ўғитлар” атамаси фақат ўғит сифатида ишлатиладиган ва асосий таркибий қисм сифатида қуйидаги озуқавий моддалардан камида биттасини ўз ичига олган маҳсулотларни англатади: азот, фосфор ёки калий."],"excl":["1. Ушбу гуруҳга қуйидагилар киритилмайди: (а) 0511-товар позициясидаги ҳайвонлар қони; (б) маълум кимёвий таркибга эга бўлган алоҳида бирикмалар (2 (а), 3 (а), 4 (а) ёки 5- бандларда кўрсатилганлар бундан мустасно); ёки (в) 3824-товар позицияси киритиладиган, ҳар бирининг оғирлиги 2,5 г дан кам бўлмаган, калий хлориднинг сунъий равишда ўстирилган кристаллари (оптик элементлардан ташқари); калий хлориднинг оптик элементлари (9001 товар позицияси)."]},"32":{"title":"КЎНЧИЛИК ЁКИ РАНГ БЕРУВЧИ ЭКСТРАКТЛАР; ТАНИНЛАР ВА УЛАРНИНГ ҲОСИЛАЛАРИ; БЎЁҚЛАР,","section":"VI","notes":["1. Ушбу гуруҳга қуйидагилар киритилмайди: (а) маълум кимёвий таркибга эга бўлган алоҳида элементлар ёки бирикмалар (3203- ёки 3204- товар позициясидаги маҳсулотлар, фосфорлар сифатида ишлатиладиган ноорганик маҳсулотлар (3206-позиция), 3207-товар позициясидаги шаклларда кўрсатилган эритилган кварц ёки бошқа эритилган силикалардан олинган шиша, шунингдек, 3212-товар позициясининг чакана савдога чиқариш учун шаклларда ёки ўрамларда қадоқланган бўёқлар ва бошқа ранг берувчи моддалар бундан мустасно); (б) 2936 – 2939, 2941- ёки 3501 – 3504-товар позицияларининг таннатлар ёки бошқа танин моддаси ҳосилалари; ёки (в) асфальт ёки бошқа битумли мастикалар (2715-товар позицияси).","2. 3204-товар позициясига барқарорлаштирилган диазоний тузлари аралашмалари ва азо-ранг берувчилар олиш учун мўлжалланган компонентлар киритилади.","3. 3203– 3206-товар позицияларига шунингдек, ранг берувчи моддалар (жумладан, 3206-товар позициясидаги ҳолатлар, 2530-товар позицияси ёки 28-гуруҳдаги ранг берувчи пигментлар, металл парчалари ёки металл кукунлари) асосида ишлаб чиқарилган, ҳар қандай материални бўяш учун компонент сифатида фойдаланиладиган маҳсулотлар киради. Ушбу маҳсулот позицияларига бўёқлар ишлаб чиқаришда фойдаланиладиган, сувсиз муҳитда диспергирланган, суюқ ёки паста шаклида тарқалган пигментлар, шу жумладан, эмаллар (3212- товар позицияси) ёки 3207–3210, 3212-, 3213-, 3215-товар позицияларидаги бошқа маҳсулотлар киритилмайди.","4. 3208-товар позициясига 3901–3913-товар позицияларининг ҳар қандай маҳсулотидан ташкил топган эритмалар (коллоид бирикмалардан ташқари) учувчан органик эритувчилар, агар таркибидаги эритувчининг миқдори эритманинг умумий массасига нисбатан 50% дан ошгандагина киритилади.","5. Мазкур гуруҳдаги “ранг берувчи модда” атамаси елимли бўёқлар учун яроқли ёки яроқсизлигидан қатъи назар, ёғли бўёқлар учун тўлдирувчи сифатида ишлатиладиган маҳсулотларга тааллуқли эмас.","6. 3212-товар позициясидаги “бўрттирма учун фольга” атамаси фақат китоб муқоваси ёки шляпа бош кийими ленталарига нақш босиш учун ишлатиладиган юпқа қатламли материалларни англатади ва улар қуйидагилардан иборат: а) елим, желатин ёки бошқа боғловчи модда билан агломерацияланган металл кукуни (шу жумладан, қимматбаҳо металлар кукуни) ёки пигмент; ёхуд: (б) ҳар қандай материалдан тайёрланган лист кўринишдаги тагликка туширилган металл (шу жумладан, қимматбаҳо металлар) ёки пигмент."],"excl":["1. Ушбу гуруҳга қуйидагилар киритилмайди: (а) маълум кимёвий таркибга эга бўлган алоҳида элементлар ёки бирикмалар (3203- ёки 3204- товар позициясидаги маҳсулотлар, фосфорлар сифатида ишлатиладиган ноорганик маҳсулотлар (3206-позиция), 3207-товар позициясидаги шаклларда кўрсатилган эритилган кварц ёки бошқа эритилган силикалардан олинган шиша, шунингдек, 3212-товар позициясининг чакана савдога чиқариш учун шаклларда ёки ўрамларда қадоқланган бўёқлар ва бошқа ранг берувчи моддалар бундан мустасно); (б) 2936 – 2939, 2941- ёки 3501 – 3504-товар позицияларининг таннатлар ёки бошқа танин моддаси ҳосилалари; ёки (в) асфальт ёки бошқа битумли мастикалар (2715-товар позицияси).","3. 3203– 3206-товар позицияларига шунингдек, ранг берувчи моддалар (жумладан, 3206-товар позициясидаги ҳолатлар, 2530-товар позицияси ёки 28-гуруҳдаги ранг берувчи пигментлар, металл парчалари ёки металл кукунлари) асосида ишлаб чиқарилган, ҳар қандай материални бўяш учун компонент сифатида фойдаланиладиган маҳсулотлар киради. Ушбу маҳсулот позицияларига бўёқлар ишлаб чиқаришда фойдаланиладиган, сувсиз муҳитда диспергирланган, суюқ ёки паста шаклида тарқалган пигментлар, шу жумладан, эмаллар (3212- товар позицияси) ёки 3207–3210, 3212-, 3213-, 3215-товар позицияларидаги бошқа маҳсулотлар киритилмайди.","4. 3208-товар позициясига 3901–3913-товар позицияларининг ҳар қандай маҳсулотидан ташкил топган эритмалар (коллоид бирикмалардан ташқари) учувчан органик эритувчилар, агар таркибидаги эритувчининг миқдори эритманинг умумий массасига нисбатан 50% дан ошгандагина киритилади.","5. Мазкур гуруҳдаги “ранг берувчи модда” атамаси елимли бўёқлар учун яроқли ёки яроқсизлигидан қатъи назар, ёғли бўёқлар учун тўлдирувчи сифатида ишлатиладиган маҳсулотларга тааллуқли эмас."]},"33":{"title":"ЭФИР МОЙЛАРИ ВА РЕЗИНОИДЛАР; АТТОРЛИК,","section":"VI","notes":[],"excl":[]},"34":{"title":"СОВУН, СИРТ-ФАОЛ ОРГАНИК МОДДАЛАР, ЮВИШ ВОСИТАЛАРИ, МОЙЛАШ МАТЕРИАЛЛАРИ,","section":"VI","notes":[],"excl":[]},"35":{"title":"ОҚСИЛ МОДДАЛАРИ; МОДИФИКАЦИЯЛАНГАН КРАХМАЛЛАР; ЕЛИМ; ФЕРМЕНТЛАР","section":"VI","notes":["1. Мазкур гуруҳга киритилмайди: (а) хамиртуруш (2102-товар позицияси); (б) қон фракциялари (альбуминдан ташқари қон зардобидан ажратиб олинган даволаш ёки профилактик мақсадларда ишлатиш учун тайёрланмаган), даволаш воситалари ёки 30-гуруҳнинг бошқа маҳсулотлари; (в) дастлабки ошлаш учун ажратилган ферментли препаратлар (3202-товар позицияси); (г) ювиш ёки ҳўллаш учун ферментли препаратлар ва 34-гуруҳнинг бошқа маҳсулотлари; (д) қотирилган протеинлар (3913-товар позицияси); ёки (е) полиграфия саноати учун желатиндан тайёрланган маҳсулотлар (49-гуруҳ).","2. 3505-товар позициясидаги “декстринлар” атамасида - декстроза сифатида акс этган, таркибида пасайган (редукциялашган) шакар билан крахмали парчаланган маҳсулотларга тегишли қуруқ модда таркибида 10%дан кўп бўлмаган маҳсулотларни ичига олади . Таркибида пасайган (редукциялашган) шакар 10% дан кўп бўлмаган бундай маҳсулотлар 1702-товар позициясига киритилади."],"excl":["1. Мазкур гуруҳга киритилмайди: (а) хамиртуруш (2102-товар позицияси); (б) қон фракциялари (альбуминдан ташқари қон зардобидан ажратиб олинган даволаш ёки профилактик мақсадларда ишлатиш учун тайёрланмаган), даволаш воситалари ёки 30-гуруҳнинг бошқа маҳсулотлари; (в) дастлабки ошлаш учун ажратилган ферментли препаратлар (3202-товар позицияси); (г) ювиш ёки ҳўллаш учун ферментли препаратлар ва 34-гуруҳнинг бошқа маҳсулотлари; (д) қотирилган протеинлар (3913-товар позицияси); ёки (е) полиграфия саноати учун желатиндан тайёрланган маҳсулотлар (49-гуруҳ)."]},"36":{"title":"ПОРТЛОВЧИ МОДДАЛАР, ПИРОТЕХНИКА ВОСИТАЛАРИ, ГУГУРТЛАР, ПИРОФОР ҚОТИШМАЛАРИ,","section":"VI","notes":["1. Ушбу гуруҳ қуйида 2(а) ёки 2(б) изоҳларида тавсифланганлардан бошқа аниқланган кимёвий таркибга эга бўлган алоҳида бирикмаларни ўз ичига олмайди.","2. 3606-позициядаги “ёнувчи материаллардан ясалган буюмлар” атамаси фақат қуйидаги маҳсулотларга нисбатан қўлланилади: а) метальдегид, гексаметилентетрамин ва ёқилғи сифатида фойдаланиш учун шаклларда (масалан, таблеткалар, таёқчалар ёки шунга ўхшаш шаклларда) қўйилган шунга ўхшаш моддалар; спиртли ёқилғи ва шунга ўхшаш қаттиқ ёки ярим қаттиқ ёқилғи; б) тамаки маҳсулотлари ёки шунга ўхшаш зажигалкаларни тўлдириш ёки тўлдириш учун мўлжалланган, сиғими 300 см3 ортиқ бўлмаган идишлардаги суюқ ёки суюлтирилган газсимон ёқилғи; ва (с) смолали машъалалар, таёқчалар ва шунга ўхшашлар."],"excl":[]},"37":{"title":"ФОТО ВА КИНО МАҲСУЛОТЛАРИ","section":"VI","notes":["1. Ушбу гуруҳга чиқиндилар ёки парчалар киритилмайди.","2. Ушбу гуруҳдаги “фотографик” атамаси ёруғлик нурлари ёки бошқа нурланишлар таъсирида тўғридан тўғри ёки билвосита кўринадиган тасвирларни фотосезгир, жумладан термосезгир юзада олиш жараёнини англатади."],"excl":["1. Ушбу гуруҳга чиқиндилар ёки парчалар киритилмайди."]},"38":{"title":"БОШҚА КИМЁВИЙ МАҲСУЛОТЛАР","section":"VI","notes":["1. Ушбу гуруҳга киритилмайди: (а) маълум бир кимёвий таркибга эга бўлган алоҳида элементлар ёки бирикмалар, қуйидагилар бундан мустасно: (1) сунъий графит (3801-товар позицияси); (2) инсектицидлар, родентицидлар, фунгицидлар, гербицидлар, пайдо бўлишга қарши воситалар ва ўсимликларнинг ўсиш регуляторлари, дезинфекциялаш воситалари ва шунга ўхшаш маҳсулотлар 3808-товар позициясида тасвирланганидек қадоқланган; (3) ёнғинни ўчириш учун ўт ўчирувчи заряд ёки зарядланган граната сифатида ишлатиладиган таркиблар (3813-товар позицияси); (4) ушбу гуруҳдаги 2-изоҳда кўрсатилган сертификатланган эталон материаллар; (5) ушбу гуруҳдаги 3 (а) ёки 3 (б) изоҳда кўрсатилган товарлар; (б) озиқ-овқат маҳсулотларини тайёрлашда ишлатиладиган, озуқавий қийматга эга бўлган озиқ-овқат маҳсулотлари ёки бошқа моддалар билан кимёвий моддалар аралашмалари (қоида тариқасида, 2106-товар позицияси); (в) 2404-товар позицияси маҳсулоти; (г) 26-гуруҳ 3 (а) ёки 3 (б) изоҳ талабларига жавоб берадиган шлак, кул ва таркибида металл бўлган қолдиқлар (шлам, оқова сувлар шламидан ташқари), маргимуш ёки унинг аралашмалари (2620-товар позицияси); (д) дори воситалари (3003- ёки 3004-товар позицияси); ёки (е) қимматбаҳо бўлмаган металларни қазиб олиш ёки уларнинг кимёвий бирикмаларини ишлаб чиқариш учун ишлатиладиган катализаторлар (2620-товар позицияси), асосан қимматбаҳо металларни қазиб олиш учун ишлатиладиган катализаторлар (7112-товар позицияси), металлар ёки металл қотишмаларидан иборат катализаторлар, масалан, майдаланган кукун ёки склетли катализаторлари (ХIV ёки ХV бўлим).","2. (А) 3822-товар позициясида “сертификатланган эталон материаллари” атамаси сертификатланган хусусиятлар кўрсаткичларида келтирилган, сертификат билан таъминланган, уларни аниқлаш учун ишлатиладиган усуллар, ҳар бир кўрсаткичнинг ўлчов хатоси ва таҳлиллари, калибрлаш ёки эталон мақсадлар учун яроқли бўлган эталон материалларини англатади. (Б) 28- ёки 29-товар гуруҳлари бундан мустасно, сертификатланган маълумот материалларини таснифлашда 3822-товар позицияси номенклатуранинг бошқа ҳар қандай товар маҳсулотидан устун туради.","3. Номенклатуранинг бошқа бирорта товар позициясига киритилмаган 3824-товар позициясига қуйидаги товарлар киритилган: (а) магний оксидининг сунъий равишда ўстирилган кристаллари (оптик элементлардан ташқари) ёки ҳар бир кристаллнинг массаси камида 2,5 г бўлган ишқорий ёки ишқорий- ер металларининг галогенидлари; (б) сивуш ёғлари; суяк смола ёғи; (в) чакана савдо учун қадоқланган ўрамдаги, сиёҳ доғларини йўқотиш учун препаратлар, (г) чакана савдо учун қадоқланган ўрамдаги босма матнларни, бошқа тузатиш суюқликларини ва тузатиш ленталарини (9612-товар позицияда кўрсатилганлардан ташқари) тузатиш учун бирикмалар; ва (д) сопол (керамик) пироэлементлар, эрувчан (масалан, Зегер конуслари).","4. Жами Номенклатурада “шаҳар чиқиндилари” атамаси уйлардан, меҳмонхоналардан, ресторанлардан, касалхоналардан, дўконлардан, идоралардан, йўл ва йўлка чиқиндилари, шунингдек, биноларни қуриш ва бузиш чиқиндилари ва ҳоказолардан йиғилган турдаги чиқиндиларни англатади. Одатда коммунал чиқиндилар таркибида пластмасса, резина, ёғоч, қоғоз, матолар, шиша, металлар, озиқ-овқат чиқиндилари, синган мебель ва бошқа зарарланган ёки ташлаб юборилган буюмлар каби турли хил материаллар мавжуд. Бироқ, “шаҳар чиқиндилари” атамаси қуйидагиларга тегишли эмас: (а) чиқиндилардан ажратилган алоҳида материаллар ёки буюмлар, масалан, пластмасса, резина, ёғоч, қоғоз, матолар, шиша ёки металларнинг чиқиндилари, электр ва электрон маҳсулотларнинг чиқиндилари ва қолдиқлари (шу жумладан ишлатилган батареялар), улар номенклатуранинг тегишли товар буюмларига киритилган; (б) саноат чиқиндилари; (в) 30-гуруҳдаги 4 (к) изоҳда тасвирланган яроқсиз фармацевтика маҳсулотлари; ёки (г) мазкур гуруҳнинг 6 (а) изоҳида тасвирланган тиббиёт чиқиндилари.","5. 3825-товар позициясида “оқова сувлар шлами” атамаси шаҳар корхоналарида чиқинди сувларни тозалаш иншоотларида ҳосил бўлган шламни англатади ва олдиндан ишлов бериладиган чиқиндиларни, ювиш сувлари ва барқарор бўлмаган шламни ўз ичига олади. Барқарорлашган шлам, агар у ўғит сифатида фойдаланишга яроқли бўлса, чиқариб ташланади (31-гуруҳ).","6. 3825-товар позициясида “бошқа чиқиндилар” атамаси қуйидгини англатади: (а) тиббиёт соҳасида илмий тадқиқотлар, диагностика, даволаш ёки бошқа зарарсизлантириш учун махсус процедураларни талаб этадиган (мисол учун, ифлосланган кийим, ишлатилган қўлқоп ва шприцлар) одатда патоген ва фармацевтик моддалардан иборат бўлган тиббиёт, хирургик, стоматологик ёки ветеринар процедуралари натижасида ҳосил бўладиган клиник чиқиндилар, яъни ифлосланган чиқиндилар; (б) ишлатиб бўлинган органик эритувчилар; (в) металларга ишлов бериш ишлатилган эритмалари, гидравлик суюқликлар, тормоз суюқликлари ва антифризлар; ва (г) саноатда кимёвий ва унга боғлиқ соҳаларнинг бошқа чиқиндилари. Бироқ, “бошқа чиқиндилар” атамаси асосан битумли жинслардан олинган нефть ва нефть маҳсулотларини ўз ичига олган чиқиндиларга тааллуқли эмас (2710-товар позицияси).","7. 3826-товар позициясида “биодизель” атамаси ёқилғи сифатида фойдаланиладиган, келиб чиқиши ҳайвонот, ўсимлик ёки микробиологик бўлган, ишлатилган ёки қайта ишланмаган ёғлардан олинадиган ёғ кислоталарининг моноалкил мураккаб эфирларини англатади. Субпозицияга изоҳлар:","1. 3808 52- ва 3808 59-субпозицияларига фақат 3808-товар позицияларидаги алахлор (ISO); алдикарб (ISO); альдрин (ISO); азинфос метил (ISO); бинапакрил (ISO); камфехлор (ISO) (токсафен); каптафол (ISO); карбофуран (ISO); хлордан (ISO); хлордимеформ (ISO); хлоробензилат (ISO); ДДТ (ISO) (клофенотан(INN), 1,1,1–трихлор–2,2–бис (п– хлорофенил)этан); диэлдрин (ISO, INN); 4,6–динитро–о–кресол (ДНОC (ISO)) ёки унинг тузлари; диносеб (ISO), унинг тузлари ёки мураккаб эфирлари; эндосулфан (ISO); этилендибромид (ISO) (1,2–дибромоэтан); этилендихлорид (ISO) (1,2–диклорэтан); фторацетамид (ISO); гептахлор (ISO); гексахлорбензол (ISO); 1,2,3,4,5,6-гексахлорциклогексан (ҲЧ (ISO)), шу жумладан, линдан (ISO, INN); симоб бирикмалари; метамидофос (ISO); монокротофос (ISO); оксиран (этиленоксид); паратион (ISO); паратион метил (ISO) (метилпаратион); пентахлорфенол (ISO), унинг тузлари ёки мураккаб эфирлари; перфтороктансульфоник кислота ва унинг тузлари; перфтороктансульфонамидлар; перфтороктансульфонилфторид; фосфамидон (ISO); 2,4,5–Т (ISO) (2,4,5- трихлорфеноксисирка кислота), унинг тузлари ёки мураккаб эфирлари; трибутилолова бирикмалари; трихлорфон (ISO) киради.","2. 3808 61 – 3808 69- субпозицияда фақатгина 3808-товар позициясидаги альфа–пиперметрин (ISO), бендиокарб (ISO), бифентрин (ISO), хлорфенапир (ISO), цифлутрин (ISO), дельтаметрин (INN, ISO), этофенпрокс (INN), фенитротион (ISO), лямбда–цигалотрин, малатион (ISO), пиримифос–метил (ISO) ёки пропоксур (ISO) товарлари киради.","3. 3824 81- 3824 89 субпозицияларга фақат қуйидаги моддаларнинг бир ёки бир нечтасини ўз ичига олган аралашмалар ва препаратлар киради: оксиран (етилен оксиди); полибромобифениллар (ПББ); поликлорли бифениллар (ПCБ); поликлоротерфениллар (ПCТ); трис(2,3-дибромопропил)фосфат; алдрин (ISO); камфехлор (ISO) (токсафен); хлордан (ISO); хлордекон (ISO); ДДТ (ISO) (клофенотан (ИНН), 1,1,1-триклоро-2,2-бис(п-клорофенил)етан); диелдрин (ИСО, ИНН); эндосулфан (ИСО); эндрин (ИСО); ҳептаклор (ISO); мирех (ISO); 1,2,3,4,5,6-гексахлороциклогексан (ҲЧ (ISO)), шу жумладан линдан (ISO), ИНН); пентаклорбензол (ISO); гексахлорбензол (ISO); перфтороктансулфоник кислота, унинг тузлари; перфтороктансулфаниламидлар; перфтороктансулфонил фторид; тетра-, пента-, ҳекса-, ҳепта- ёки октабромодифенил эфирлари; қисқа занжирли хлорли парафинлар. Қисқа занжирли хлорли керосинлар – хлорланиш даражаси 48 мас.% дан ортиқ бўлган бирикмалар аралашмаси бўлиб, қуйидаги молекуляр формулага эга: C H Cl , х (2х- y +2) y","1. Икки ёки ундан ортиқ алоҳида компонентлардан ташкил топган тўпламларда тақдим этилган маҳсулотлар, уларнинг баъзилари ёки барчаси ушбу бўлимга киритилган ва VI ёки VII бўлимга киритилган маҳсулотни олиш учун аралаштириш учун мўлжалланган бўлиб, ушбу маҳсулотга мос келадиган товар позициясига киритилиши керак, агар бу компонентлар қуйидаги шартларни бажарса: (а) қадоқлаш усулини ҳисобга олган ҳолда, уларни қайта қадоқламасдан биргаликда ишлатиш учун мўлжалланган бўлса; (б) қадоғи билан биргаликда тақдим этилади; ва (в) уларнинг асли қандай усулда тайёрланиши ёки бир-бирини тўлдирувчи сифатида қандай нисбатда берилганлиги билан белгиланади.","2. 3918- ёки 3919-товар позициясидаги товарлардан ташқари, уларнинг асосий мақсадлари учун маxсус қўлланиладиган босма нақшлар, чизмалар ёки тасвирлар бўлган пластмассалар, каучук ва улардан тайёрланган маҳсулотлар 49-гуруҳга киради."],"excl":["1. Ушбу гуруҳга киритилмайди: (а) маълум бир кимёвий таркибга эга бўлган алоҳида элементлар ёки бирикмалар, қуйидагилар бундан мустасно: (1) сунъий графит (3801-товар позицияси); (2) инсектицидлар, родентицидлар, фунгицидлар, гербицидлар, пайдо бўлишга қарши воситалар ва ўсимликларнинг ўсиш регуляторлари, дезинфекциялаш воситалари ва шунга ўхшаш маҳсулотлар 3808-товар позициясида тасвирланганидек қадоқланган; (3) ёнғинни ўчириш учун ўт ўчирувчи заряд ёки зарядланган граната сифатида ишлатиладиган таркиблар (3813-товар позицияси); (4) ушбу гуруҳдаги 2-изоҳда кўрсатилган сертификатланган эталон материаллар; (5) ушбу гуруҳдаги 3 (а) ёки 3 (б) изоҳда кўрсатилган товарлар; (б) озиқ-овқат маҳсулотларини тайёрлашда ишлатиладиган, озуқавий қийматга эга бўлган озиқ-овқат маҳсулотлари ёки бошқа моддалар билан кимёвий моддалар аралашмалари (қоида тариқасида, 2106-товар позицияси); (в) 2404-товар позицияси маҳсулоти; (г) 26-гуруҳ 3 (а) ёки 3 (б) изоҳ талабларига жавоб берадиган шлак, кул ва таркибида металл бўлган қолдиқлар (шлам, оқова сувлар шламидан ташқари), маргимуш ёки унинг аралашмалари (2620-товар позицияси); (д) дори воситалари (3003- ёки 3004-товар позицияси); ёки (е) қимматбаҳо бўлмаган металларни қазиб олиш ёки уларнинг кимёвий бирикмаларини ишлаб чиқариш учун ишлатиладиган катализаторлар (2620-товар позицияси), асосан қимматбаҳо металларни қазиб олиш учун ишлатиладиган катализаторлар (7112-товар позицияси), металлар ёки металл қотишмаларидан иборат катализаторлар, масалан, майдаланган кукун ёки склетли катализаторлари (ХIV ёки ХV бўлим).","3. Номенклатуранинг бошқа бирорта товар позициясига киритилмаган 3824-товар позициясига қуйидаги товарлар киритилган: (а) магний оксидининг сунъий равишда ўстирилган кристаллари (оптик элементлардан ташқари) ёки ҳар бир кристаллнинг массаси камида 2,5 г бўлган ишқорий ёки ишқорий- ер металларининг галогенидлари; (б) сивуш ёғлари; суяк смола ёғи; (в) чакана савдо учун қадоқланган ўрамдаги, сиёҳ доғларини йўқотиш учун препаратлар, (г) чакана савдо учун қадоқланган ўрамдаги босма матнларни, бошқа тузатиш суюқликларини ва тузатиш ленталарини (9612-товар позицияда кўрсатилганлардан ташқари) тузатиш учун бирикмалар; ва (д) сопол (керамик) пироэлементлар, эрувчан (масалан, Зегер конуслари).","6. 3825-товар позициясида “бошқа чиқиндилар” атамаси қуйидгини англатади: (а) тиббиёт соҳасида илмий тадқиқотлар, диагностика, даволаш ёки бошқа зарарсизлантириш учун махсус процедураларни талаб этадиган (мисол учун, ифлосланган кийим, ишлатилган қўлқоп ва шприцлар) одатда патоген ва фармацевтик моддалардан иборат бўлган тиббиёт, хирургик, стоматологик ёки ветеринар процедуралари натижасида ҳосил бўладиган клиник чиқиндилар, яъни ифлосланган чиқиндилар; (б) ишлатиб бўлинган органик эритувчилар; (в) металларга ишлов бериш ишлатилган эритмалари, гидравлик суюқликлар, тормоз суюқликлари ва антифризлар; ва (г) саноатда кимёвий ва унга боғлиқ соҳаларнинг бошқа чиқиндилари. Бироқ, “бошқа чиқиндилар” атамаси асосан битумли жинслардан олинган нефть ва нефть маҳсулотларини ўз ичига олган чиқиндиларга тааллуқли эмас (2710-товар позицияси).","2. 3918- ёки 3919-товар позициясидаги товарлардан ташқари, уларнинг асосий мақсадлари учун маxсус қўлланиладиган босма нақшлар, чизмалар ёки тасвирлар бўлган пластмассалар, каучук ва улардан тайёрланган маҳсулотлар 49-гуруҳга киради."]},"39":{"title":"ПЛАСТМАССАЛАР ВА УЛАРДАН ТАЙЁРЛАНГАН БУЮМЛАР","section":"VII","notes":["1. Барча номенклатурада “пластмассалар” атамаси 3901–3914-товар позицияларининг материаллари бўлиб, улар полимеризация ёки кейинги босқичларда ташқи таъсир остида (одатда ҳарорат ва босим, агар керак бўлса, эритувчи ёки пластификатор ёрдамида) маълум бир шаклга синдирилиши мумкин бўлган товарларни англатади. Эритувчи ёки пластификатордан фойдаланган ҳолда уни пресслаш, қуйиш, экструзия, каландрлаш ёки бошқалар каби ташқи таъсирларни олиб ташлангандан кейин сақланади. Барча номенклатурада “пластмассалар” атамаси вулканизация қилинган толаларни англатади, аммо XI бўлимда келтирилган тўқимачилик материалларига нисбатан қўлланилмайди.","2. Ушбу гуруҳга қуйидагилар кирмайди: (а) 2710- ёки 3403-товар позициясидаги мойлаш материаллари; (б) 2712- ёки 3404-товар позициясидаги (воски) мумлар; (в) муайян кимёвий таркибли алоҳида органик бирикмалари (29-гуруҳ); (г) гепарин ёки унинг тузлари (3001-товар позицияси); (д) эритмалар (коллодий эритмалардан ташқари), 3901–3913-товар позицияларининг ҳар қандай маҳсулотларидан иборат, агар ҳал қилувчи массаси эритма массасининг 50 %дан ортиқ бўлса, (3208-товар позицияси) штамплаш учун фолга (3212-товар позицияси); (е) органик сирт фаол моддалар ёки 3402-товар позициясидаги воситалари; (ж) эритилган смолалар ёки мураккаб эфирли смолалар (3806-товар позицияси); (з) нефт маҳсулотлари учун присадкалар (шу жумладан бензин) ёки нефт маҳсулотлари билан бир xил мақсадларда ишлатиладиган бошқа суюқликларга тайёр қўшимчалар (3811-товар позицияси); (и) 39-гуруҳнинг полигликоллари, силиконлари ёки бошқа полимерларига асосланган тайёр гидравлик суюқликлар (товар позицияси – 3819); (к) диагностик ёки лаборатория реагентлари (товар позицияси – 3822); (л) 40-гуруҳдаги синтетик каучуклар ёки ундан тайёрланган маҳсулотлар; (м) эгар ёки жабдуқлар (товар позицияси – 4201) ёки йўл анжомлари, чамадонлар, сумкалар ёки бошқа буюмлар 4202-товар позициясида; (н) тўқилган, сават буюмлари ёки 46-гуруҳдаги бошқа буюмлар; (о) 4814-товар позицияси девор қопламалари; (п) XI бўлими маҳсулотлари (тўқимачилик материаллари ва тўқимачилик буюмлари; (р) XII бўлим маҳсулотлари (масалан пойафзал, бош кийимлар, соябонлар, қуёшдан сақловчи соябонлар, тростлар, қамчилар ва уларнинг қисмлари); (с) 7117-товар позициясидаги заргарлик буюмлари; (т) XVI бўлим товарлари (машина ва меxаник ёки электр қурилмалар); (у) XVII бўлимдаги учиш аппаратлари ёки транспорт воситаларининг қисмлари; (ф) 90-гуруҳ маҳсулотлари (масалан, оптик элементлар, кўзойнаклар учун рамкалар, чизмачилик асбоблари); (х) 91-гуруҳ маҳсулотлари (масалан, барча турдаги соатлар корпуслари); (ц) 92-гуруҳ маҳсулотлари (масалан, мусиқа асбоблари ёки уларнинг қисмлари); (ч) 94-гуруҳдаги маҳсулотлар (масалан, мебел, ёритгичлар ва ёритиш ускуналари, ёруғлик белгилари, қурилиш иншоотлари); (ш) 95-гуруҳдаги маҳсулотлар (масалан, ўйинчоқлар, ўйинлар, спорт анжомлари); ёки (щ) 96-гуруҳ маҳсулотлари (масалан, чўткалар, тугмалар, фурнитуралар, тароқлар, мундштук ёки найчалар ёки шу каби буюмлар, термослар учун қисмлар ёки шу каби буюмлар, стрелка ва моноопорали қаламлар, икки оёқли, триподлар ва шу каби буюмлар).","3. 3901 – 3911-товар позициялари фақат қуйидаги кимёвий синтез қилинган маҳсулотларини ўз ичига олади: (а) ҳажми 60 % дан кам бўлган суюқ синтетик полиолефинлар, 300 °С ҳароратда тортилган ва 1013 мбар босими остида тортилган (товар позициялари – 3901 ва 3902); (б) кумар-инден типидаги паст полимеризация даражасидаги смолалар (3911-товар позицияси); (в) ўртача камида 5 та мономер боғланишни ўз ичига олган бошқа синтетик полимерлар; (г) силиконлар (товар позицияси – 3910); (д) резоллар (3909-товар позицияси) ва бошқа форполимерлар.","4. “Сополимер” атамаси полимер таркибнинг умумий миқдорининг 95 % мас ёки ундан ортиқ мономер бирлиги бўлган полимерларни англатади. Ушбу гуруҳда, агар контекстда бошқача тартиб назарда тутилмаган бўлса, сополимерлар (шу жумладан, сополиконденсатлар, қўшимча сополимер маҳсулотлари, блок-сополимерлар ва привитые сополимерлар) ва полимерларнинг аралашмалари бошқа ҳар қандай индивидуал сомономер боғланишидан устун бўлган сомономер боғининг полимерлари билан бир xил товар туркумда таснифланади. Ушбу изоҳда бир xил товар позициясига кирадиган полимерларни ташкил этувчи сомономер боғланишлар биргаликда кўриб чиқилиши керак. Агар бирон-бир сомономер боғлари устунлик қилмаса, сополимер ёки полимер аралашмалари муайян ҳолатга қараб товар позициясига киритилиши керак, иккинчиси эса кўриб чиқилаётган тенг товар позициялари орасида товар код рақамларини ортиб бориши тартибида таснифланади.","5. Кимёвий модификацияланган полимерлар, унда асосий полимер занжирининг фақат ён занжирлари кимёвий таъсир билан ўзгартирилади, ўзгармаган полимерга мос келадиган товар позициясига киритилади. Бу ҳолат пайванд қилинган сополимерларга тааллуқли эмас.","6. 3901–3914-товар позицияларида “биринчи форма” атамаси фақат қуйидаги шаклларни билдиради: (а) суюқликлар ва пасталар, шу жумладан дисперсиялар (эмулсиялар, суспензиялар) ва эритмалар; (б) тартибсиз шаклдаги блоклар, парчалар, кукунлар (шу жумладан пресс-қолиплар), гранулалар, доналар ва шу каби қуйма қолиплар.","7. 3915-товар позициясига бирламчи қолипларга қайта ишланган битта термопластик материалнинг чиқиндилари, чақмоқлари ва парчалари (3901–3914-товар позициялари) кирмайди","8. 3917-товар позициясида “трубалар, трубкачалар ва шланглар” атамаси газлар ёки суюқликларни ташиш ёк тарқатиш учун кенг фойдаланадиган ичи бўш буюмлар ёки ярим тайёр маҳсулотларни англатади (масалан, рифелланган боғ шланглар, тешикли трубалар). Бу атама шунингдек текис шаклга эга бўлган бошқа трубалар ва колбаса учун қобиқларни ҳам англатади. Шу билан бирга, иккинчисидан ташқари, доира, тасвирлар, тўртбурчакдан (узунлиги 1,5 марта кенглигидан ошмаган) ёки мунтазам кўпбурчакдан бошқа шаклдаги ички кесимга эга бўлган маҳсулотлар трубалар ва шланглар сифатида эмас, балки шаклли профиллар сифатида қаралади.","9. 3918-товар позициясида “деворлар учун қопламалар ёки пластмассадан шифтлар” атамаси, девор ёки шифтларни безаш учун ишлатиладиган, қоғоздан ташқари ҳар қандай материалнинг тагига маҳкамланган пластмассалардан ташкил топган, кенглиги камида 45 см бўлган рулонли буюмларни англатади; бу ҳолда пластмасса қатлами (олд юзада) одатда бўрттирма, рифеллаш билан бўяш, босма нақшни қўллаш ёки бошқа йўллар билан безатилган.","10. 3920- ва 3921-товар позицияларида” плиталар, листлар, плёнка ва тасмалар ёки ленталар” атамаси фақат плиталар, листлар, плёнка ва тасмалар ёки ленталар (54-гуруҳдаги товарлардан ташқари), шунингдек, нақшли ёки нақшсиз мунтазам геометрик шаклдаги блоклар ёки бошқа усулда ишлов берилган сирт билан кесилмайди ёки тўртбурчакларга (шу жумладан квадратларга) кесилган, аммо бошқа ишлов берилмаган (ҳатто бундай операциялар натижасида тайёр маҳсулот бўлса ҳам).","11. 3925-товар позициясига фақат ушбу гуруҳнинг II кичик бўлимининг олдинги товар позицияларига киритилган маҳсулоти бўлмаган қуйидаги маҳсулотлар киради: (а) 300 литрдан ортиқ сув резервуарлари, резервуарлар, (шу жумладан, септик резервуарлар), бочкалар ва шунга ўхшаш идишлар; (б) қурилиш элементлари, масалан поллар, деворлар ёки бўлмалар, шифтлар ёки томлар учун ишлатилади: (в) водостоки и фитинги к ним; дренаж ва уларнинг қисмлари; (г) эшиклар, деразалар ва улар учун рамкалар; (д) балконлар, балустрадлар, тўсиқлар, эшикчалар ва шунга ўxшаш тўсиқлар; (е) деразалар, пардалар (шу жумладан венеция жалюзалари) ва шунга ўxшаш буюмлар ва уларнинг қисмлари ва жиҳозлари; (ж) дўкон, устаxоналар, омборларда, масалан, йиғиш ва доимий ўрнатиш учун стеллажларнинг катта габаритли конструктив элементлари; (з) декоратив меъморий деталлар, масалан, канелюралар, гумбазлар, “кабутархоналар”; ва (и) эшиклар, деразалар, зинапоялар, деворлар ёки биноларнинг бошқа қисмларига доимий ўрнатиш учун мўлжалланган арматура ва фурнитуралар, масалан, тугмалар, тутқичлар, илгаклар, штапеллар, сочиқ илгичлари, калитлар, выключателлар учун платлар ва бошқа ҳимоя плиталари. Субпозициялар учун изоҳлар:","1. Ушбу гуруҳнинг ҳар қандай товар позициясида полимерлар (шу жумладан сополимерлар) ва кимёвий модификацияланган полимерлар қуйидаги қоидаларга мувофиқ таснифланиши керак: (а) бир xил даражадаги “бошқалар” субпозицияси мавжуд бўлганда: (1) “полимерлар” субпозициясида “поли” префиксининг мавжудлиги (масалан, полиэтилен ва полиамид-6,6) ушбу полимернинг асосий смола занжири ёки смола занжири биргаликда олинган 95% мас. бўлиши керак деган маънони англатади, умумий полимер таркибидан 95 % ёки ундан кўп; (2) товар субпозициясида сополимерлари 3901 30, 3901 40, 3903 20, 3903 30 ва 3904 30 юқоридаги сополимерларнинг сомономерик шаклли 95% мас. бўлса, бир xил субпозицияга киритилиши керак, умумий полимер таркибидан 95% ёки ундан кўп; (3) кимёвий ўзгартирилган полимерлар бошқа, ўзига xос, субпозицияга киритилмаган бўлса, кимёвий модификацияланган полимерлар “бошқалар” субпозицияга киритилиши керак; (4) 1-, 2- ёки 3-бандда юқорида санаб ўтилмаган полимерлар бир xил даражадаги қолган субпозициялар сонига киритилиши керак, бу эса бошқа барча индивидуал сомономерик боғланишлардан устун бўлган смола звеноли полимерларни ўз ичига олади. Шу мақсадда полимерларнинг бир xил субпозицияга тушадиган полимерларни ташкил этувчи асосий смола звенолари биргаликда кўриб чиқилиши керак. Фақат битта даражадаги субпозицияга киритилган полимер сомономерик боғланишлар таққосланиши керак; (б) бир xил даражадаги “бошқалар” субпозиция бўлмаган тақдирда: (1) полимерлар бошқа барча индивидуал сомономерик йўналишларга нисбатан масса томонидан устун бўлган смола боғланишининг полимерларини ўз ичига олган субпозицияга киритилиши керак. Шу мақсадда бир xил субпозицияга кирадиган полимерларнинг асосий смола звенолари биргаликда кўриб чиқилиши керак. Фақат битта даражадаги субпозицияга киритилган полимер сомономерик боғланишлар таққосланиши керак; (2) кимёвий модификацияланган полимерлар ўзгармаган полимерга мос келадиган субпозицияга киритилиши керак. Полимер аралашмалари бир xил смолали боғланишларнинг полимерлари билан бир xил нисбатда бир xил субпозицияга киритилиши керак.","2. 3920 43-субпозициясида “пластификаторлар” атамаси иккинчи даражали пластификаторларга қўлланилади."],"excl":["2. Ушбу гуруҳга қуйидагилар кирмайди: (а) 2710- ёки 3403-товар позициясидаги мойлаш материаллари; (б) 2712- ёки 3404-товар позициясидаги (воски) мумлар; (в) муайян кимёвий таркибли алоҳида органик бирикмалари (29-гуруҳ); (г) гепарин ёки унинг тузлари (3001-товар позицияси); (д) эритмалар (коллодий эритмалардан ташқари), 3901–3913-товар позицияларининг ҳар қандай маҳсулотларидан иборат, агар ҳал қилувчи массаси эритма массасининг 50 %дан ортиқ бўлса, (3208-товар позицияси) штамплаш учун фолга (3212-товар позицияси); (е) органик сирт фаол моддалар ёки 3402-товар позициясидаги воситалари; (ж) эритилган смолалар ёки мураккаб эфирли смолалар (3806-товар позицияси); (з) нефт маҳсулотлари учун присадкалар (шу жумладан бензин) ёки нефт маҳсулотлари билан бир xил мақсадларда ишлатиладиган бошқа суюқликларга тайёр қўшимчалар (3811-товар позицияси); (и) 39-гуруҳнинг полигликоллари, силиконлари ёки бошқа полимерларига асосланган тайёр гидравлик суюқликлар (товар позицияси – 3819); (к) диагностик ёки лаборатория реагентлари (товар позицияси – 3822); (л) 40-гуруҳдаги синтетик каучуклар ёки ундан тайёрланган маҳсулотлар; (м) эгар ёки жабдуқлар (товар позицияси – 4201) ёки йўл анжомлари, чамадонлар, сумкалар ёки бошқа буюмлар 4202-товар позициясида; (н) тўқилган, сават буюмлари ёки 46-гуруҳдаги бошқа буюмлар; (о) 4814-товар позицияси девор қопламалари; (п) XI бўлими маҳсулотлари (тўқимачилик материаллари ва тўқимачилик буюмлари; (р) XII бўлим маҳсулотлари (масалан пойафзал, бош кийимлар, соябонлар, қуёшдан сақловчи соябонлар, тростлар, қамчилар ва уларнинг қисмлари); (с) 7117-товар позициясидаги заргарлик буюмлари; (т) XVI бўлим товарлари (машина ва меxаник ёки электр қурилмалар); (у) XVII бўлимдаги учиш аппаратлари ёки транспорт воситаларининг қисмлари; (ф) 90-гуруҳ маҳсулотлари (масалан, оптик элементлар, кўзойнаклар учун рамкалар, чизмачилик асбоблари); (х) 91-гуруҳ маҳсулотлари (масалан, барча турдаги соатлар корпуслари); (ц) 92-гуруҳ маҳсулотлари (масалан, мусиқа асбоблари ёки уларнинг қисмлари); (ч) 94-гуруҳдаги маҳсулотлар (масалан, мебел, ёритгичлар ва ёритиш ускуналари, ёруғлик белгилари, қурилиш иншоотлари); (ш) 95-гуруҳдаги маҳсулотлар (масалан, ўйинчоқлар, ўйинлар, спорт анжомлари); ёки (щ) 96-гуруҳ маҳсулотлари (масалан, чўткалар, тугмалар, фурнитуралар, тароқлар, мундштук ёки найчалар ёки шу каби буюмлар, термослар учун қисмлар ёки шу каби буюмлар, стрелка ва моноопорали қаламлар, икки оёқли, триподлар ва шу каби буюмлар).","5. Кимёвий модификацияланган полимерлар, унда асосий полимер занжирининг фақат ён занжирлари кимёвий таъсир билан ўзгартирилади, ўзгармаган полимерга мос келадиган товар позициясига киритилади. Бу ҳолат пайванд қилинган сополимерларга тааллуқли эмас.","7. 3915-товар позициясига бирламчи қолипларга қайта ишланган битта термопластик материалнинг чиқиндилари, чақмоқлари ва парчалари (3901–3914-товар позициялари) кирмайди","8. 3917-товар позициясида “трубалар, трубкачалар ва шланглар” атамаси газлар ёки суюқликларни ташиш ёк тарқатиш учун кенг фойдаланадиган ичи бўш буюмлар ёки ярим тайёр маҳсулотларни англатади (масалан, рифелланган боғ шланглар, тешикли трубалар). Бу атама шунингдек текис шаклга эга бўлган бошқа трубалар ва колбаса учун қобиқларни ҳам англатади. Шу билан бирга, иккинчисидан ташқари, доира, тасвирлар, тўртбурчакдан (узунлиги 1,5 марта кенглигидан ошмаган) ёки мунтазам кўпбурчакдан бошқа шаклдаги ички кесимга эга бўлган маҳсулотлар трубалар ва шланглар сифатида эмас, балки шаклли профиллар сифатида қаралади.","9. 3918-товар позициясида “деворлар учун қопламалар ёки пластмассадан шифтлар” атамаси, девор ёки шифтларни безаш учун ишлатиладиган, қоғоздан ташқари ҳар қандай материалнинг тагига маҳкамланган пластмассалардан ташкил топган, кенглиги камида 45 см бўлган рулонли буюмларни англатади; бу ҳолда пластмасса қатлами (олд юзада) одатда бўрттирма, рифеллаш билан бўяш, босма нақшни қўллаш ёки бошқа йўллар билан безатилган.","10. 3920- ва 3921-товар позицияларида” плиталар, листлар, плёнка ва тасмалар ёки ленталар” атамаси фақат плиталар, листлар, плёнка ва тасмалар ёки ленталар (54-гуруҳдаги товарлардан ташқари), шунингдек, нақшли ёки нақшсиз мунтазам геометрик шаклдаги блоклар ёки бошқа усулда ишлов берилган сирт билан кесилмайди ёки тўртбурчакларга (шу жумладан квадратларга) кесилган, аммо бошқа ишлов берилмаган (ҳатто бундай операциялар натижасида тайёр маҳсулот бўлса ҳам)."]},"40":{"title":"КАУЧУК, РЕЗИНА ВА УЛАРДАН ТАЙЁРЛАНГАН БУЮМЛАР","section":"VII","notes":["1. Агар контекстда бошқача тартиб назарда тутилмаган бўлса, унда “каучук” ва “резина” атамалари вулканизацияланган ёки вулканизацияланмаган, қаттиқ ёки қаттиқ бўлмаган қуйидаги маҳсулотларни англатади: табиий каучук, балату, гуттаперча, гваюла, чикл ва шунга ўxшаш табиий смолалар, синтетик каучук, ёғлардан олинган фактик ва шу каби материаллар қайта тикланган шакли.","2. Ушбу гуруҳга киритилмайди: (а) XI бўлим маҳсулотлари (тўқимачилик материаллари ва тўқимачилик маҳсулотлари); (б) 64-гуруҳдаги пойабзал ёки унинг қисмлари; (в) 65-гуруҳдаги бош кийимлар ёки уларнинг қисмлари (жумладан, чўмилиш қалпоқчалари); (г) XVI бўлимдаги меxаник ёки электр қурилмалари ёки уларнинг қисмлари (барча турдаги электр теxника) қаттиқ резинадан; (д) 90-, 92-, 94- ёки 96-гуруҳ маҳсулотлари; (е) 95-гуруҳдаги маҳсулотлар (спорт қўлқоплари, қўлқоп ва 4011-4013товар позициядаги маҳсулотлар бундан мустасно).","3. 4001–4003 ва 4005-товар позициялардаги \"бирламчи шакл\" атамалар қуйидагиларни билдиради: (а) суюқлик ва пасталар (вулканизацияланган ва вулканизацияланмаган ва бошқалар дисперсия ва эритмалар); (б) тартибсиз шаклдаги блоклар, қисмлар, киплар, кукунлар, гранулалар, бурмалар ва шунга ўxшаш оммавий шакллар.","4. Ушбу гуруҳга берилган 1-изоҳ ва 4002-товар позициясидаги “синтетик каучук” атамаси қуйидагиларни англатади: (а) 18 – 29 °С ҳароратда, унинг асл чўзилиши 3 мартадан ошганда ҳам узилмаган, балки термопластик моддалар, олтингугурт билан вулканизацияланган қайтмас ҳолатга тўйинмаган синтетик моддалар ва 5 дақиқа давомида аввалги узунлигидан кўпи бир ярим марта каттароқ, узунликка қайтади. Ушбу синовда кўндаланг алоқаларни, xусусан, фаоллаштирувчи ёки вулканизация тезлаткичларини шакллантириш учун зарур бўлган моддалар қўшилиши мумкин. 5 (Б) (ii) ва (iii) изоҳларда кўрсатилган моддаларнинг мавжуд бўлиши ҳам мумкин. Шу билан бирга суюлтирувчилар, пластификаторлар ва тикувчи моддалар ва тўлдирувчилар каби бўлмаслиги керак; (б) тиопластлар( ТМ); ва (в) табиий каучук, пайвандлаш ёки пластмасса билан аралаштириш томонидан ўзгартирилган, деполимеризацияланган табиий каучук, тўйинган синтетик юқори молекуляр оғирлиги полимер билан тўйинмаган синтетик моддалар аралашмаси, вулканизация, бўшлиққа ва ўлчамларни тиклаш билан боғлиқ юқорида кўрсатилган барча маҳсулотлар 4 (а) бандда кўрсатилган талабларга мувофиқ келади.","5. (А) (А) 4001- ва 4002-товар позицияларида каучук ёки каучук аралашмаси, агар улар коагуляциядан олдин ёки кейин аралаштирилса: (i) вулканизация агентлари, тезлаткичлар, секинлаштирувчи ёки автиваторлар (вулканизация қилинган каучук латексни тайёрлаш учун қўшилганлар бундан мустасно); (ii) пигментлар ёки бошқа бўёқлар, фақат идентификациялаш учун ишлатиладиганлардан ташқари; (iii) пластификаторлар ёки тўлдирувчи моддалар (минерал ёғлар билан тўлдирилган каучук учун минерал мойдан ташқари), агентларни, органик эритувчиларни ёки 5 (Б) бандида кўсатилганлардан ташқари бошқа моддаларни кучайтиради. (Б) Каучук ёки каучук аралашмасида қуйидаги моддаларнинг мавжудлиги, бундай каучук ёки каучук аралашмаси xом ашёнинг асосий xусусиятини сақлаб қолиши шарти билан, уларнинг 4001- ёки 4002-товар позициясига киритилишига таъсир қилмайди: (i) эмулгаторлар ёки антиадгезифлар; (ii) парчаланган эмульгаторларнинг кичик миқдори; (iii) иссиқликка сезгир агентлари жуда кичик миқдорда (асосан иссиқлик-сезгир резина латекс ишлаб чиқариш учун), катион сирт фаол моддалар (одатда электр мусбат каучук латекс ишлаб чиқариш учун), антиоксидантлар, коагулянтлар, каучукни майдалашга ёрдам берувчи моддалар, совуққа чидамлилиги, пептизаторлар, антикоагулянтлар, стабилизаторлар, қовушоқликни тартибга солувчи моддалар, ёки шунга ўxшаш маxсус қўшимчалар.","6. 4004-товар позициясида \"чиқиндилар, қолдиқлар\" атамаси каучук ва ундан тайёрланган маҳсулотларни ишлаб чиқариш ёки қайта ишлаш жараёнида ҳосил бўлган чиқиндилар, қолдиқлар ва скрабларни англатади, улар кесиш, кийиш ёки бошқалар сабабларга кўра фойдаланишга мутлақо мос келмайди.","7. Тўлиқ вулканизацияланган каучукдан иборат тўлиқ кўндаланг кесими 5 мм дан ортиқ бўлган иплар 4008-товар позициясига чизиқлар ёки ленталар, таёқчалар ёки шаклли профиллар сифатида киритилган.","8. 4010-товар позициясига конвейер бантлари, узатма ременлари ёки каучук билан қопланган ёки иккиланган мато ёки тўқимачилик ипидан ёки каучук билан қопланган ёки иккиланган ипдан тайёрланган матолар киради.","9. 4001-, 4002-, 4003-, 4005- ва 4008-товар позицияларида “пластиналар”, “листлар” ва “тасма ёки ленталар” сўзлари фақат текис геометрик шаклдаги плиталар, плиталар ва чизиқлар ёки чизиқлар ва блоклар деган маънони англатади, кесилмаган ёки тўртбурчак (квадрат, шу жумладан) шаклларга бўлинади, улар тайёр бўлмаган кесма маҳсулотлар‚ тасма ёки бошқалар ишлов берилмаган сирт, бошқа шаклдаги бўлакларга кесилган ёки қайта ишланган материаллардан ташқари. 4008-савдо позициясида “таёқчалар” ва “фасон профиллар” атамалари фақат ишлов берилган ёки ишлов берилмаган сирт билан кесилган, аммо кейинчалик қайта ишланмаган маҳсулотларни англатади."],"excl":["2. Ушбу гуруҳга киритилмайди: (а) XI бўлим маҳсулотлари (тўқимачилик материаллари ва тўқимачилик маҳсулотлари); (б) 64-гуруҳдаги пойабзал ёки унинг қисмлари; (в) 65-гуруҳдаги бош кийимлар ёки уларнинг қисмлари (жумладан, чўмилиш қалпоқчалари); (г) XVI бўлимдаги меxаник ёки электр қурилмалари ёки уларнинг қисмлари (барча турдаги электр теxника) қаттиқ резинадан; (д) 90-, 92-, 94- ёки 96-гуруҳ маҳсулотлари; (е) 95-гуруҳдаги маҳсулотлар (спорт қўлқоплари, қўлқоп ва 4011-4013товар позициядаги маҳсулотлар бундан мустасно).","5. (А) (А) 4001- ва 4002-товар позицияларида каучук ёки каучук аралашмаси, агар улар коагуляциядан олдин ёки кейин аралаштирилса: (i) вулканизация агентлари, тезлаткичлар, секинлаштирувчи ёки автиваторлар (вулканизация қилинган каучук латексни тайёрлаш учун қўшилганлар бундан мустасно); (ii) пигментлар ёки бошқа бўёқлар, фақат идентификациялаш учун ишлатиладиганлардан ташқари; (iii) пластификаторлар ёки тўлдирувчи моддалар (минерал ёғлар билан тўлдирилган каучук учун минерал мойдан ташқари), агентларни, органик эритувчиларни ёки 5 (Б) бандида кўсатилганлардан ташқари бошқа моддаларни кучайтиради. (Б) Каучук ёки каучук аралашмасида қуйидаги моддаларнинг мавжудлиги, бундай каучук ёки каучук аралашмаси xом ашёнинг асосий xусусиятини сақлаб қолиши шарти билан, уларнинг 4001- ёки 4002-товар позициясига киритилишига таъсир қилмайди: (i) эмулгаторлар ёки антиадгезифлар; (ii) парчаланган эмульгаторларнинг кичик миқдори; (iii) иссиқликка сезгир агентлари жуда кичик миқдорда (асосан иссиқлик-сезгир резина латекс ишлаб чиқариш учун), катион сирт фаол моддалар (одатда электр мусбат каучук латекс ишлаб чиқариш учун), антиоксидантлар, коагулянтлар, каучукни майдалашга ёрдам берувчи моддалар, совуққа чидамлилиги, пептизаторлар, антикоагулянтлар, стабилизаторлар, қовушоқликни тартибга солувчи моддалар, ёки шунга ўxшаш маxсус қўшимчалар.","9. 4001-, 4002-, 4003-, 4005- ва 4008-товар позицияларида “пластиналар”, “листлар” ва “тасма ёки ленталар” сўзлари фақат текис геометрик шаклдаги плиталар, плиталар ва чизиқлар ёки чизиқлар ва блоклар деган маънони англатади, кесилмаган ёки тўртбурчак (квадрат, шу жумладан) шаклларга бўлинади, улар тайёр бўлмаган кесма маҳсулотлар‚ тасма ёки бошқалар ишлов берилмаган сирт, бошқа шаклдаги бўлакларга кесилган ёки қайта ишланган материаллардан ташқари. 4008-савдо позициясида “таёқчалар” ва “фасон профиллар” атамалари фақат ишлов берилган ёки ишлов берилмаган сирт билан кесилган, аммо кейинчалик қайта ишланмаган маҳсулотларни англатади."]},"41":{"title":"ХОМ ТЕРИЛАР (ТАБИИЙ МЎЙНАДАН ТАШҚАРИ)","section":"VIII","notes":[],"excl":[]},"42":{"title":"ЧАРМ БУЮМЛАРИ: ЭГАР-ЖАБДУҚ МАҲСУЛОТЛАРИ ВА ЮГАНЛАР; САФАР УЧУН АНЖОМЛАР, СУМКАЛАР","section":"VIII","notes":["1. Ушбу гуруҳда “табиий чарм” атамаси замш (шу жумладан, комбинацияланган замш), лакланган, ламинатланган ва металл тузлари билан ишлов берилган чармни ўз ичига олади.","2. Ушбу гуруҳга қуйидагилар кирмайди: (а) стерилланган жарроҳлик кетгути ёки шунга ўхшаш жарроҳлик чокларида қўлланиладиган бошқа стерил материаллар (3006-товар позицияси); (б) астарлик қисми табиий ёки сунъий мўйнадан, ёки айримларда устки томони табиий ёки сунъий мўйна билан қопланган ҳамда мўйнадан фақат пардозловчи сифатида фойдаланилган кийим-кечак ва унга оид буюмлар (товар позицияси – 4303 ёки 4304) (в) тўрдан ясалган буюмлар (товар позицияси – 5608); (г) 64-гуруҳ буюмлари; (д) 65-гуруҳ оид бош кийимлар ёки уларнинг қисмлари; (е) товар позицияси 6602 бўлган қамчи, хивчин ва бошқа буюмлар; (ж) тугма, билагузук ёки бошқа бижутериялар (товар позицияси – 7117); (з) от абзаллари учун пардозловчи деталлар, масалан узангилар, сувлуқ, эгар-жабдуқ учун металл атторлик буюмлари ва тасмалар алоҳида келтирилган (асосан XV бўлимда); (и) торлар, барабанлар учун хом чарм ёки бошқа мусиқа асбоблари учун қўлланиладиган шу каби буюмлар (товар позицияси – 9209); (к) 94-гуруҳга оид буюмлар (масалан, мебель, ёриткичлар ва ёритувчи жиҳозлар); (л) 95-гуруҳга оид буюмлар (масалан, ўйинчоқлар, ўйинлар, спорт анжомлари); (м) тугмалар, кнопка, илгаклар, тугмалар учун шакл ёки улар учун қўлланиладиган бошқа буюмлар, товар позицияси 9606 бўлган тугмалар учун ярим маҳсулотлар;","3. (А) 2– изоҳнинг қоидаларига қўшимча равишда, 4202-позиция қуйидагиларни истисно қилади: (а) пластмассадан тайёрланган, расмсиз ва расм туширилган, дастакли ва узоқ муддат фойдаланиш учун мўлжалланмаган сумкалар (товар позицияси – 3923) (б) тўқилган материаллардан тайёрланган буюмлар (товар позицияси – 4602). (Б) Товар позицияси 4202 ва 4203 бўлган, қимматбаҳо металл ва металл сақлаган қисмлардан, қимматбаҳо металлар, табиий ва сунъий марваридлар, қимматбаҳо ва ярим қимматбаҳо тошлар (табиий, сунъий ёки қайта ишланган) қопланган буюмлар билан безатилган ва бу орқали буюмнинг асосий қисмларини ўзгартирмаган буюмлар киритилади. Акс ҳолда мазкур буюмлар 71-гуруҳга киритилади.","4. 4203-товар позицияси бўйича “кийим ва кийимга тегишли нарсалар” inter alia атамаси, қўлқоплар ва махсус қўлқоплар (ҳимоя ва спортда қўлланиладиганлар ҳам киради), фартуклар ва бошқа ҳимоя кийимлари, илгаклар, камарлар, соат боғичларидан ташқари буюмлар киради"],"excl":["2. Ушбу гуруҳга қуйидагилар кирмайди: (а) стерилланган жарроҳлик кетгути ёки шунга ўхшаш жарроҳлик чокларида қўлланиладиган бошқа стерил материаллар (3006-товар позицияси); (б) астарлик қисми табиий ёки сунъий мўйнадан, ёки айримларда устки томони табиий ёки сунъий мўйна билан қопланган ҳамда мўйнадан фақат пардозловчи сифатида фойдаланилган кийим-кечак ва унга оид буюмлар (товар позицияси – 4303 ёки 4304) (в) тўрдан ясалган буюмлар (товар позицияси – 5608); (г) 64-гуруҳ буюмлари; (д) 65-гуруҳ оид бош кийимлар ёки уларнинг қисмлари; (е) товар позицияси 6602 бўлган қамчи, хивчин ва бошқа буюмлар; (ж) тугма, билагузук ёки бошқа бижутериялар (товар позицияси – 7117); (з) от абзаллари учун пардозловчи деталлар, масалан узангилар, сувлуқ, эгар-жабдуқ учун металл атторлик буюмлари ва тасмалар алоҳида келтирилган (асосан XV бўлимда); (и) торлар, барабанлар учун хом чарм ёки бошқа мусиқа асбоблари учун қўлланиладиган шу каби буюмлар (товар позицияси – 9209); (к) 94-гуруҳга оид буюмлар (масалан, мебель, ёриткичлар ва ёритувчи жиҳозлар); (л) 95-гуруҳга оид буюмлар (масалан, ўйинчоқлар, ўйинлар, спорт анжомлари); (м) тугмалар, кнопка, илгаклар, тугмалар учун шакл ёки улар учун қўлланиладиган бошқа буюмлар, товар позицияси 9606 бўлган тугмалар учун ярим маҳсулотлар;","4. 4203-товар позицияси бўйича “кийим ва кийимга тегишли нарсалар” inter alia атамаси, қўлқоплар ва махсус қўлқоплар (ҳимоя ва спортда қўлланиладиганлар ҳам киради), фартуклар ва бошқа ҳимоя кийимлари, илгаклар, камарлар, соат боғичларидан ташқари буюмлар киради"]},"43":{"title":"ТАБИИЙ ВА СУНЪИЙ МЎЙНА ВА УНДАН ТАЙЁРЛАНГАН МАҲСУЛОТЛАР","section":"VIII","notes":["1. Бутун номенклатура бўйича 4301-позициядаги момиқ мўйнали хомашёдан ташқари “табиий мўйна” атамаси жун қопламининг барча ҳайвонларнинг ошланган териларига нисбатан қўлланилади.","2. Ушбу гуруҳга қуйидагилар кирмайди: (а) қушларнинг терилари ёки уларнинг патлари (0505 ёки 6701 товар позицияси); (б) соч ёки жун билан ишлов берилмаган терилар, 41-гуруҳ (ушбу гуруҳнинг 1(в) изоҳига қаранг); (в) табиий чармдан ёки мўйнадан қўлқоплар (4203-позиция); (г) 64-гуруҳ маҳсулотлари; (д) бош кийимлар ёки уларнинг қисмлари 65 гуруҳ; ёки (е) 95 гуруҳ маҳсулотлари (масалан, ўйинчоқлар, ўйинлар, спорт анжомлари).","3. Мўйнали терилар ва бошқа материаллар қўшилган ҳолда ошланган мўйна терилари ва уларнинг қисмлари, кийим-кечак ёки унинг қисмлари ёки аксессуарлари ёки бошқа буюмлар сифатида тикилган мўйнали терилар ва уларнинг қисмлари 4303-позицияга киради.","4. Астар табиий ёки сунъий мўйна билан қопланган ёки ташқи томондан табиий ёки сунъий мўйна билан қопланган қийим буюмлари ва кийим-кечак учун аксессуарлар (юқорида 2- бандда кўрсатилганидан ташқари) таснифланишига кўра 4303- ёки 4304-гуруҳ.","5. Бутун номенклатура бўйича “сунъий мўйна” атамаси табиий мўйнанинг тўқилган ёки трикотаж тақлидларидан ташқари чарм, газлама ёки бошқа материалларга ёпиштирилган ёки тикилган жун, соч ёки бошқа толаларнинг ҳар қандай бириктирилганини билдиради (5801 ёки 6001 товар позициялари)."],"excl":["1. Бутун номенклатура бўйича 4301-позициядаги момиқ мўйнали хомашёдан ташқари “табиий мўйна” атамаси жун қопламининг барча ҳайвонларнинг ошланган териларига нисбатан қўлланилади.","2. Ушбу гуруҳга қуйидагилар кирмайди: (а) қушларнинг терилари ёки уларнинг патлари (0505 ёки 6701 товар позицияси); (б) соч ёки жун билан ишлов берилмаган терилар, 41-гуруҳ (ушбу гуруҳнинг 1(в) изоҳига қаранг); (в) табиий чармдан ёки мўйнадан қўлқоплар (4203-позиция); (г) 64-гуруҳ маҳсулотлари; (д) бош кийимлар ёки уларнинг қисмлари 65 гуруҳ; ёки (е) 95 гуруҳ маҳсулотлари (масалан, ўйинчоқлар, ўйинлар, спорт анжомлари).","4. Астар табиий ёки сунъий мўйна билан қопланган ёки ташқи томондан табиий ёки сунъий мўйна билан қопланган қийим буюмлари ва кийим-кечак учун аксессуарлар (юқорида 2- бандда кўрсатилганидан ташқари) таснифланишига кўра 4303- ёки 4304-гуруҳ.","5. Бутун номенклатура бўйича “сунъий мўйна” атамаси табиий мўйнанинг тўқилган ёки трикотаж тақлидларидан ташқари чарм, газлама ёки бошқа материалларга ёпиштирилган ёки тикилган жун, соч ёки бошқа толаларнинг ҳар қандай бириктирилганини билдиради (5801 ёки 6001 товар позициялари)."]},"44":{"title":"ЁҒОЧ ВА УНДАН ТАЙЁРЛАНГАН МАҲСУЛОТЛАР; ПИСТА КЎМИР","section":"IX","notes":["1. Ушбу гуруҳга киритилмайди: (а) асосан парфюмерияда, фармацевтикада ёхуд инсектицид, фунгицид ёки аналогик мақсадларда ишлатиладиган пайраҳа, қиринди, стружка ёки кукун кўринишидаги ёғоч (1211-товар позицияси); (б) асосан тўқишда ишлатиладиган бамбук ёки ёғоч табиатли бошқа материаллар, ишлов берилмаганлар, титилган ёки титилмаган, бўйлама арраланмаган ёки арраланган ёхуд узунасига кесилган ёки кесилмаган (1401-товар позицияси); (в) асосан бўяш ёки ошлаш учун ишлатиладиган пайраҳа, қиринди, стружка ёки кукун кўринишидаги ёғоч ( 1404-товар позицияси); (г) фаоллаштирилган писта кўмир (3802-товар позицияси); (д) 4202-товар позициясининг буюмлари; (е) 46-гуруҳ товарлари; (ж) 64-гуруҳнинг пойабзаллари ёки унинг қисмлари; (з) 66-гуруҳ товарлари (масалан, соябонлар, тростлар ва уларнинг қисмлари); (и) 6808-товар позициясининг товарлари; (к) 7117-товар позициясининг бижутериялари; (л) XVIII ёки XVII бўлим товарлари (масалан: машиналарнинг қисмлари, қопламалар, қопқоқлар, машина ва аппаратураларнинг корпуслари ва арава-соябон усталарининг маҳсулотлари); (м) XVIII бўлим товарлари (масалан, соат корпуслари, мусиқа асбоблари ва уларнинг қисмлари); (н) ўқотар қуролларнинг қисмлари (9305-товар позицияси); (о) 94-гуруҳ буюмлари (масалан, мебель, чироқлар ва ёритиш ускуналари, йиғиладиган қурилиш конструкциялари (п) 95-гуруҳ буюмлари (масалан, ўйинчоқлар, ўйинлар, спорт инвентари); (р) 96-гуруҳ буюмлари (масалан, чекиш трубкалари ва уларнинг қисмлари, тугмалар, қаламлар, бир оёқли, икки оёқли, уч оёқли тирговучлар ва аналогик буюмлар), 9603 товар позицияси буюмлари учун ёғочли корпуслар ва ушлагичлардан ташқари; (с) 97-гуруҳ буюмлари (масалан, санъат асарлари).","2. Ушбу гуруҳда “зичланган ёғоч” атамаси кимёвий ёки физикавий усулда ишлов берилган (қатламлар бир-бирига боғланадиган ҳолатда, оддий елимлашга қараганда, ишлов бериш кучлироқ бўлиши лозим), ва натижада юқори зичликка ёки қаттиқликка эришган, шу билан бирга механик мустаҳкамлиги, кимёвий ёки электр таъсирга қаршилиги яхшиланган ёғоч тушунилади.","3. 4414–4421-товар позицияларига тегишли тавсифли ёғоч-қиринди ёки аналогик плиталар, ёғоч-толали плиталар, ёғоч қатламларидан ёки ёғоч буюмларга аналогик прессланган ёғочдан тайёрланган буюмлар киритилади.","4. 4410-, 4411- ёки 4412-товар позициялари буюмларига, 4409-товар позициясидаги буюмлар учун хос бўлган, шакл-профиль берилиши мумкин. Улар буралиши, гофрировка ва перфаровка қилиниши, тўғри тўртбурчак ёки квадрат шаклидан бошқа шаклда кесилиши ёки шакллантирилиши, ёки бошқа ҳар қандай усулда ишлов берилиши мумкин, шу шарт билан, бундай ишлов бериш ушбу товарларга бошқа товар позицияларининг хусусиятларини бермайди.","5. Тиғи, ишчи қирраси, ишчи юзаси ёки бошқа иш қисми 82-гуруҳнинг 1-изоҳида кўрсатиб ўтилган материалларнинг ҳар қандай туридан тайёрланган асбоблар 4417-товар позициясига киритилмайди.","6. Юқоридаги 1-изоҳ талабларига риоя этиш шарти билан ва контекстдан бошқа нарса талаб этилмаган бўлмаса, мазкур гуруҳнинг товар позицияларидаги “ёғоч” атамаси бамбук ва ёғоч табиатли бошқа материалларга ҳам тааллуқли бўлади. Субпозицияларга изоҳлар:","1. 4401 31-субпозициясида “ёғоч гранулалари” атамаси ёғочни қайта ишлаш саноати, мебель саноати ёки ёғочга ишлов бериш бўйича бошқа саноатнинг қўшимча маҳсулоти бўлган, тўғридан тўғри пресслаб ёки 3 мас.% дан ошмайдиган миқдорда боғловчи модда қўшган ҳолда пресслаб агломерацияланган кесилган стружка, пайраҳа ва қириндиларни англатади. Ушбу гранулалар диаметри 25 мм дан ортиқ бўлмаган ва узунлиги 100 мм дан ортиқ бўлмаган цилиндр шаклига эга.","2. 4401 32-субпозициясида “ёғоч брикетлари” ибораси ёғочни қайта ишлаш саноати, мебель саноати ёки ёғочга ишлов бериш бўйича бошқа саноатнинг қўшимча маҳсулоти бўлган, тўғридан тўғри пресслаб ёки 3 мас.% дан ошмайдиган миқдорда боғловчи модда қўшган ҳолда пресслаб агломерацияланган кесилган стружка, пайраҳа ва қириндиларни англатади. Ушбу брикетлар кўндаланг кесимининг энг кичик ўлчами 25 мм дан ортиқ бўлган куб, кўпёқлик ёки цилиндр шаклига эга.","3. 4407 13-субпозициясида “S-P-F” аббревиатураси аралаш экилган қарағай, қорақарағай ва оққарағайдан олинган ёғочни англатади, ва бунда ҳар бир дарахт турининг миқдори ўзгариб туради ва аниқ эмас.","4. 4407 14-субпозициясида “Hem-fir” аббревиатураси аралаш экилган ғарб тсугаси ва оққарағайдан олинган ёғочни англатади, ва бунда ҳар бир дарахт турининг миқдори ўзгариб туради ва аниқ эмас."],"excl":["1. Ушбу гуруҳга киритилмайди: (а) асосан парфюмерияда, фармацевтикада ёхуд инсектицид, фунгицид ёки аналогик мақсадларда ишлатиладиган пайраҳа, қиринди, стружка ёки кукун кўринишидаги ёғоч (1211-товар позицияси); (б) асосан тўқишда ишлатиладиган бамбук ёки ёғоч табиатли бошқа материаллар, ишлов берилмаганлар, титилган ёки титилмаган, бўйлама арраланмаган ёки арраланган ёхуд узунасига кесилган ёки кесилмаган (1401-товар позицияси); (в) асосан бўяш ёки ошлаш учун ишлатиладиган пайраҳа, қиринди, стружка ёки кукун кўринишидаги ёғоч ( 1404-товар позицияси); (г) фаоллаштирилган писта кўмир (3802-товар позицияси); (д) 4202-товар позициясининг буюмлари; (е) 46-гуруҳ товарлари; (ж) 64-гуруҳнинг пойабзаллари ёки унинг қисмлари; (з) 66-гуруҳ товарлари (масалан, соябонлар, тростлар ва уларнинг қисмлари); (и) 6808-товар позициясининг товарлари; (к) 7117-товар позициясининг бижутериялари; (л) XVIII ёки XVII бўлим товарлари (масалан: машиналарнинг қисмлари, қопламалар, қопқоқлар, машина ва аппаратураларнинг корпуслари ва арава-соябон усталарининг маҳсулотлари); (м) XVIII бўлим товарлари (масалан, соат корпуслари, мусиқа асбоблари ва уларнинг қисмлари); (н) ўқотар қуролларнинг қисмлари (9305-товар позицияси); (о) 94-гуруҳ буюмлари (масалан, мебель, чироқлар ва ёритиш ускуналари, йиғиладиган қурилиш конструкциялари (п) 95-гуруҳ буюмлари (масалан, ўйинчоқлар, ўйинлар, спорт инвентари); (р) 96-гуруҳ буюмлари (масалан, чекиш трубкалари ва уларнинг қисмлари, тугмалар, қаламлар, бир оёқли, икки оёқли, уч оёқли тирговучлар ва аналогик буюмлар), 9603 товар позицияси буюмлари учун ёғочли корпуслар ва ушлагичлардан ташқари; (с) 97-гуруҳ буюмлари (масалан, санъат асарлари).","5. Тиғи, ишчи қирраси, ишчи юзаси ёки бошқа иш қисми 82-гуруҳнинг 1-изоҳида кўрсатиб ўтилган материалларнинг ҳар қандай туридан тайёрланган асбоблар 4417-товар позициясига киритилмайди."]},"45":{"title":"ПЎКАК ВА УНДАН ТАЙЁРЛАНГАН БУЮМЛАР","section":"IX","notes":[],"excl":[]},"46":{"title":"ПОХОЛ, СОМОН ВА БОШҚА ТЎҚИШ МАТЕРИАЛЛАРИДАН БУЮМЛАР;","section":"IX","notes":["1. Ушбу гуруҳдаги “тўқув материаллари” атамаси тўқиш, қайта тўқиш ёки шу каби жараёнлар учун ярайдиган кўринишда ёки ҳолатда бўлган материалларни англатади; бу материалларга сомон, тол, бамбук, ротанг пальмаси, қамиш, ёғоч тасмалар, бошқа ўсимлик материалларидан ясалган тасмалар (масалан, пўстлоғининг тасмалари, ингичка барглар ва рафия ёки кенг барглардан кесилган тасмалар), йигирилмаган табиий тўқимачилик толалари, пластмассадан тайёрланган моно ип ва тасма ёки лента ва шу каби шакллар ҳамда қоғоздан тайёрланган тасма ёки лента киради, лекин табиий теридан ёки композицион теридан, кигиз ёки фетрдан ёки нотўқима материаллардан тайёрланган тасма ва ленталар, инсон сочлари, от сочи, тўқимачилик хом ипи ёки йигирилган ип, ёки 54-гуруҳдаги моноип ва ясси ип ва шу каби иплар кирмайди.","2. Ушбу гуруҳга киритилмайди: (а) 4814-товар позициясидаги девор қопламалари; (б) чилвирлар, арқонлар, канатлар ва трослар, ўрилган ёки ўрилмаган (5607-товар позицияси); (в) 64- ва 65-гуруҳнинг пойабзаллари ёки бош кийимлари ёки уларнинг деталлари ёки қисмлари; (г) тўқув материалларидан транспорт воситалари ёки уларнинг кузовлари (87-гуруҳ); (д) 94-гуруҳнинг буюмлари (масалан, мебель, чироқлар ва ёритиш ускуналари).","3. 4601-товар позициясида “тўқиш учун материаллар, тўқилган ва тўқиш учун материаллардан параллел йигирилган ипларга боғланган шу каби буюмлар” атамаси тўқиш учун материалларни, тўқилган буюмларни ва тўқимачилик материалига бирлаштириш учун ишлатилиши ёки ишлатилмаслигидан қатъий назар, тўқиш учун материаллардан параллел йигирилган ипларга боғланган шу каби буюмларни англатади."],"excl":["1. Ушбу гуруҳдаги “тўқув материаллари” атамаси тўқиш, қайта тўқиш ёки шу каби жараёнлар учун ярайдиган кўринишда ёки ҳолатда бўлган материалларни англатади; бу материалларга сомон, тол, бамбук, ротанг пальмаси, қамиш, ёғоч тасмалар, бошқа ўсимлик материалларидан ясалган тасмалар (масалан, пўстлоғининг тасмалари, ингичка барглар ва рафия ёки кенг барглардан кесилган тасмалар), йигирилмаган табиий тўқимачилик толалари, пластмассадан тайёрланган моно ип ва тасма ёки лента ва шу каби шакллар ҳамда қоғоздан тайёрланган тасма ёки лента киради, лекин табиий теридан ёки композицион теридан, кигиз ёки фетрдан ёки нотўқима материаллардан тайёрланган тасма ва ленталар, инсон сочлари, от сочи, тўқимачилик хом ипи ёки йигирилган ип, ёки 54-гуруҳдаги моноип ва ясси ип ва шу каби иплар кирмайди.","2. Ушбу гуруҳга киритилмайди: (а) 4814-товар позициясидаги девор қопламалари; (б) чилвирлар, арқонлар, канатлар ва трослар, ўрилган ёки ўрилмаган (5607-товар позицияси); (в) 64- ва 65-гуруҳнинг пойабзаллари ёки бош кийимлари ёки уларнинг деталлари ёки қисмлари; (г) тўқув материалларидан транспорт воситалари ёки уларнинг кузовлари (87-гуруҳ); (д) 94-гуруҳнинг буюмлари (масалан, мебель, чироқлар ва ёритиш ускуналари)."]},"47":{"title":"ЁҒОЧ ЁКИ БОШҚА ТОЛАЛИ ЦЕЛЛЮЛОЗА МАТЕРИАЛЛАРИДАН ИБОРАТ МАССА; ҚАЙТА","section":"X","notes":[],"excl":[]},"48":{"title":"ҚОҒОЗ ВА КАРТОН: ҚОҒОЗ МАССАСИ, ҚОҒОЗ ЁКИ КАРТОНДАН ТАЙЁРЛАНГАН БУЮМЛАР","section":"X","notes":["1. Ушбу гуруҳда, агар матнда бошқа ҳолатлар назарда тутилмаган бўлса, “қоғоз” атамаси картонга нисбатан қўлланилади (қалинлиги ёки 1 м² нинг массасидан қатъий назар).","2. Қуйидагилар ушбу гуруҳга кирмайди: (а) 30-гуруҳдаги буюмлар; (б) 3212-товар позициясидаги босиб нақш тушириш учун фольга; (в) хушбўйлаштирилган қоғоз ёки косметика воситалари шимдирилган ёки қопланган қоғоз (33-гуруҳ); (г) совун ёки тозалаш воситаси (3401-товар позицияси) ёки полировкаловчи моддалар, кремлар ёки шунга ўхшаш воситалар (3405-товар позицияси) шимдирилган ёки қопланган қоғоз ёки целлюлоза вата; (д) 3701 – 3704-товар позицияларидаги таъсирчанлиги оширилган қоғоз ёки картон; (е) диагностика ёки лаборатория реагентлари (3822-товар позицияси) шимдирилган қоғоз; (ж) қоғоз тўлдирилган листли қатма-қат пластмасса ёки агар материалнинг бутун қалинлигининг ярмидан кўпини пластмасса ташкил қилса, пластмасса қатлами билан қопланган бир қават қоғоз ёки картон ёхуд шунга ўхшаш материаллардан буюмлар, 4814-товар позициясидаги (39-гуруҳ) деворга ишлатиладиган қопламалар бундан мустасно; (з) 4202-товар позициясидаги буюмлар (масалан, сафар буюмлари); (и) 46-гуруҳ буюмлари (тўқиш материалларидан тайёрланган буюмлар); (к) қоғоз ип ёки ундан тайёрланган тўқимачилик буюмлари (XI бўлим); (л) 64- ёки 65-гуруҳдаги буюмлар; (м) абразив қоғоз ёки картон (6805-товар позицияси) ёки асоси қоғоз ёки картонли слюда (6814-товар позицияси) (бироқ слюдали кукун билан қопланган қоғоз ёки картон ушбу гуруҳга киради); (н) асоси қоғоз ёки картон бўлган металл фольга (одатда XIV ёки XV бўлим); (о) 9209-товар позициясидаги буюмлар; (п) 95-гуруҳ буюмлари (масалан, ўйинчоқлар, ўйинлар, спорт анжомлари); ёки (р) 96-гуруҳ буюмлари (масалан, тугмалар, аёллар гигиеник прокладка ва тампонлари, болалар йўргаги ва тагликлар.","3. Ушбу гуруҳга 7-изоҳ қоидаларига амал қилинган тақдирда, 4801 – 4805-товар позицияларига каландерланган (ёйилган), супер-каландерланган, пардоз берилган ёки шунга ўхшаш ишлов берилган, сув белгиси туширилган ёки юзаси елимланган қоғоз ва картон, шунингдек, целлюлоза толасидан тайёрланган, ҳар қандай усулда бўялган ёки тўлиқ массаси мармар кўринишида ишланган қоғоз, картон, целлюлоза момиғи ҳамда матоси киради. 4803-товар позициясида алоҳида изоҳ берилган ҳоллардан ташқари ушбу товар позицияларига бошқача усулда ишлов берилган қоғоз, картон, целлюлоза ватаси ёки матоси кирмайди.","4. Ушбу гуруҳдаги “газета қоғози” атамаси таркибидаги тола умумий массасининг камида 50 фоизи механик ёки кимёвий-механик усул билан олинган тахта толасидан иборат бўлган, елимланмаган ёки енгил елимланган, ҳар тарафдан дағал юзали, 1 м2нинг массаси энг камида 40 г, лекин 65 г дан кўп бўлмаган, Parker Print Surf (1МПа) аппаратида ўлчанган, 2,5 мкм (микрон)дан кўп бўлган, газеталарни чоп этишда фойдаланиладиган, силлиқланмаган қоғоз ҳисобланади ҳамда фақат: (а) полосали ёки лентали, ёки эни 28 смдан кўп бўлган рулонлардаги; ёки (б) ёйиқ ҳолдаги ўлчови бир томони 28 смдан, бошқа томони эса 15 смдан кўп бўлган тўғри тўртбурчакли (шунингдек, квадрат) листлардаги қоғозга нисбатан қўлланилади.","5. 4802-товар позициясидаги “ёзув, босма ёки бошқа график мақсадларда фойдаланиладиган қоғоз ва картон” ва “тешилмаган карталар ва тешилмаган қоғоз ленталар” атамалари асосан оқартирилган масса ёки механик ёки кимёвий-механик усул билан олинган массадан тайёрланган ҳамда қуйидаги мезонларнинг ҳар қайсисига мос келадиган қоғоз ва картонни англатади: (А) 1 м²нинг массаси 150 г дан кўп бўлмаган қоғоз ёки картон учун: (а) таркибида механик ёки кимёвий-механик усул билан олинган тола 10 фоиз ёки ундан кўп бўлган, ва (1) 1 м²нинг массаси 80 г дан кўп бўлмаган, ёки (2) массаси бўялган; ёки (б) оҳорланганлик даражаси 8 фоиздан кўп бўлган, ва (1) 1 м²нинг массаси 80 г дан кўп бўлмаган, ёки (2) массаси бўялган; ёки (в) оҳорланганлик даражаси 3 фоиздан кўп ва оқартирилганлик даражаси 60 фоиз ёки ундан кўп бўлган; ёки (г) оҳорланганлик даражаси 3 фоиздан кўп, лекин 8 фоиздан кўп бўлмаган ҳамда босилганлик индекси 2,5 кПа·м²/г га тенг ёки ундан кам бўлган; ёки (д) оҳорланганлик даражаси 3 фоиздан кам, оқартирилганлик даражаси 60 фоиз ёки ундан кўп бўлган ҳамда 2,5 кПа·м²/г га тенг ёки ундан кам бўлган. (Б) 1 м²нинг массаси 150 г дан кўп бўлган қоғоз ёки картон учун: (а) массаси бўялган; ёки (б) оқартирилганлик даражаси 60 фоиз ёки ундан кўп бўлган ҳамда (1) қалинлиги 225 мкм (микрон) ёки ундан кам бўлган, ёки (2) қалинлиги 225 мкм (микрон) дан кўп, лекин 508 мкм (микрон)дан кўп бўлмаган ҳамда оҳорланганлик даражаси 3 фоиздан кўп бўлган; ёки (в) оқартирилганлик даражаси 60 фоиздан кам, қалинлиги 254 мкм (микрон) ёки ундан кам ва оҳорланганлик даражаси 8 фоиздан кўп бўлган. Бироқ 4802-товар позициясига фильтрлайдиган қоғоз ёки картон (жумладан пакетчали чой учун қоғозлар) ёки том ёпишда ишлатиладиган қоғоз ёки картон кирмайди.","6. Ушбу гуруҳда “крафт-қоғоз ва крафт-картон” атамаси таркибидаги умумий тола массасининг 80 фоизи кимёвий сульфатли ёки натрон усул билан олинган толадан иборат бўлган қоғоз ва картонни англатади.","7. 4801 дан 4811-позициягача икки ёки ундан ортиқ товар позицияларига киритилиши мумкин бўлган қоғоз, картон, целлюлоза момиғи ҳамда целлюлоза толаларидан тайёрланган мато товар позицияларида алоҳида изоҳ берилган ҳолатлардан ташқари, айтиб ўтилган товар позициялари орасида кодлар ўсиб бориши тартибида охирги товар позициясига киритилади.","8. 4803 – 4809-товар позицияларига фақат қоғоз, картон, целлюлоза момиғи ва целлюлоза толаларидан тайёрланган матоларнинг қуйидагилари киритилади: (a) эни 36 смдан кўп бўлган полосали ёки лентали, ёки рулонларда бўлган; ёки (б) ёйиқ ҳолда ўлчами бир томони 36 смдан, бошқа томони эса 15 смдан кўп бўлган тўғри тўртбурчакли (шунингдек, квадрат) листларда.","9. 4814-товар позициясидаги “гулқоғозлар ва шунга ўхшаш девор қопламалари” атамаси фақат қуйидагиларни англатади: (а) девор ёки шифтларни безатиш учун мўлжалланган, эни 45 см кам ва 160 смдан кўп бўлмаган қуйидаги рулонли қоғозлар: (i) дона-дона нақш босилган, рельефли расм солинган, сирти бўялган, босма расм туширилган ёки юзаси бошқача усулда безатилган (масалан, тукли мато билан), шаффоф пластмасса ҳимоя қатлами билан қопланган ёки қопланмаган; (ii) ёғоч-тахта, похол ва бошқа зарралардан иборат бўлган дағал юзали; (iii) юза қисми пластмасса қопламали, бунда ушбу қатламга дона-дона нақш босилган, рельефли расм солинган, бўялган, босма расм туширилган ёки бошқача безатилган бўлиши лозим; ёки (iv) юза тарафи тўқилган ёки тўқилмаган, ёки йигирилган ип билан параллель уланган ёки уланмаган тўқиш материаллари билан қопланган; (б) юқорида қайд этилган усуллар билан ишлов берилган, рулонларда ёки рулонларда бўлмаган, девор ва шифтларни безатиш учун яроқли қоғоз бордюрлар ва ҳошиялар; (в) биргаликда деворда пейзаж, расм ёки нақш ҳосил қилувчи, босма тасвирли, рулонлар ёки листлардаги, бир нечта панеллардан тайёрланган қоғоздан ясалган девор қопламалари. Ҳам пол қопламаси, ҳам девор қопламалари сифатида фойдаланиш учун яроқли, асоси қоғоз ёки картон бўлган буюмлар 4823-товар позициясига киритилади.","10. 4820-товар позициясига ўлчам бўйича кесилган, босилган ёки босилмаган, нақш солинган ёки солинмаган, тешилган ёки тешилмаган алоҳида листлар ва карталар киритилмайди.","11. 4823-товар позициясига, inter alia, жаккард ёки шунга ўхшаш машиналар учун тешилган қоғоз ёки картон перфокарталар ва қоғоздан ясалган тўрлар киритилади.","12. 4814- ёки 4821-товар позициясига киритилган буюмлардан ташқари, асосий мақсадига кўра махсус босма нақш, расм ёки тасвир туширилган қоғоз, картон, целлюлоза қоғози ва улардан тайёрланган буюмлар 49-гуруҳга киритилади. Субпозицияларга изоҳ:","1. 4804 11 ва 4804 19-субпозицияларидаги “крафт-лайнер” атамаси таркибидаги умумий тола массасининг камида 80 фоизи кимёвий сульфатли ёки натрон усул билан олинган ёғоч-тахта толадан иборат, рулонларда бўлган, машина усулида безак берилган ёки пардозланган қоғоз ва картонни англатади. Бундай буюмларнинг 1 м² массаси 115 г дан ошади ҳамда Мюллен бўйича босишга минимал қаршилиги қуйида келтирилган жадвалдаги кўрсаткичларга мос келади. 1 м² массанинг бошқа қийматларида босишга қаршилик даражаси чизиқли интерполяция ёки экстраполяция орқали аниқланади. Масса, Мюллен бўйича босишга минимал г/м² қаршилик, кПа 115 393 125 417 200 637 300 824 400 961","2. 4804 21- ва 4804 29-субпозицияларидаги “крафт-лайнер” атамаси таркибидаги умумий тола массасининг камида 80 фоизи кимёвий сульфатли ёки натрон усул билан олинган ёғоч-тахта толадан иборат, рулонларда бўлган, машина усулида пардозланган қоғозни англатади. 1 м² шундай қоғознинг массаси камида 60 г ва кўпи билан 115 г дан иборат; ушбу қоғоз қуйида келтирилган шартлардан бирига мос келиши лозим: (а) Мюллен бўйича босиш индекси камида 3,7 кПа·м²/г, тортишиш коэффициенти кўндаланг йўналишда 4,5 фоиздан кўп, узунасига йўналишда 2 фоиздан кўп бўлиши; (б) эзилишга минимал қаршилиги ҳамда узилишга мустаҳкамлиги қуйида келтирилган жадвалда кўрсатилган катталикларга мувофиқ келиши, 1 м² массанинг бошқа кўрсаткичларида улар чизиқли интерполяция усули билан аниқланади: Масса, Эзилишга минимал қаршилик, мН Узилишга минимал мустаҳкамлик, кН/м г/м² Узунасига ва Узунасига ва Узунасига Кўндаланг кўндаланг кўндаланг йўналишда йўналишда йўналишда йўналишда 60 700 1510 1,9 6 70 830 1790 2,3 7,2 80 965 2070 2,8 8,3 100 1230 2635 3,7 10,6 115 1425 3060 4,4 12,3","3. 4805 11-субпозициясидаги “яримцеллюлозадан гофрировка қилиш учун қоғоз” атамаси тола умумий массасининг 65 фоизи япроқли ёғоч тахтанинг оқланмаган, механик ва кимёвий жараёнлар бирикувидан олинган толаларидан ташкил топган рулондаги қоғоз бўлиб, унинг босимга қаршилиги CMT 30 усули билан ўлчанганда (30 дақиқа сақланадиган Corrugated Medium Test) 50 фоиз нисбий намлик ва 23°С ҳароратда 1,8 Н·м²/г дан ошади.","4. 4805 12-субпозициясига асосан механик ва кимёвий жараёнлар бирикувидан олинувчи похол целлюлозадан ишланган, 1 м² массаси 130 г ва ундан юқори бўлган рулондаги қоғоз киритилади. Унинг босимга қаршилиги CMT 30 усули билан ўлчанганда (30 дақиқа сақланадиган Corrugated Medium Test) 50 фоиз нисбий намлик ва 23°С ҳароратда 1,4 Н·м²/г дан ошади.","5. 4805 24- ва 4805 25-субпозицияларига тўлиқ ёки асосан регенерация қилинадиган қоғоз ёки картондан (макулатура ва чиқит) олинган массадан тайёрланадиган қоғоз ва картон киритилади. Тест-лайнер, шунингдек, бўялган ёки регенерация қилинмаган оқланган ёки оқланмаган массадан олинувчи қоғоздан иборат юза қатламга эга бўлиши мумкин. Бундай буюмлар Мюллен бўйича 2 кПа·м²/г дан кам бўлмаган босим индексига эга бўлади.","6. 4805 30-субпозициясида “сульфатли ўрам қоғози” атамаси машина усулида безак берилган, таркибидаги тола умумий массасининг 40 фоизидан ортиғи кимёвий сульфат йўли билан олинувчи ёғоч толадан иборат бўлган, оҳорланганлик даражаси 8 фоиздан кўп бўлмаган ва Мюллен бўйича босим индекси 1,47 кПа·м²/г дан кам бўлмаган қоғозни англатади.","7. 481022-субпозициясидаги “енгил оқланган қоғоз” атамаси ҳар икки томони оқланган, 1 м²нинг умумий массаси 72 г дан ошмайдиган ҳамда 1 м² массанинг қоплама қавати ҳар бир юза учун 15 г дан ошмайдиган ва тола умумий массасининг камида 50 фоизи механик усул билан олинган ёғоч-тахта толадан иборат қоғозни англатади."],"excl":["2. Қуйидагилар ушбу гуруҳга кирмайди: (а) 30-гуруҳдаги буюмлар; (б) 3212-товар позициясидаги босиб нақш тушириш учун фольга; (в) хушбўйлаштирилган қоғоз ёки косметика воситалари шимдирилган ёки қопланган қоғоз (33-гуруҳ); (г) совун ёки тозалаш воситаси (3401-товар позицияси) ёки полировкаловчи моддалар, кремлар ёки шунга ўхшаш воситалар (3405-товар позицияси) шимдирилган ёки қопланган қоғоз ёки целлюлоза вата; (д) 3701 – 3704-товар позицияларидаги таъсирчанлиги оширилган қоғоз ёки картон; (е) диагностика ёки лаборатория реагентлари (3822-товар позицияси) шимдирилган қоғоз; (ж) қоғоз тўлдирилган листли қатма-қат пластмасса ёки агар материалнинг бутун қалинлигининг ярмидан кўпини пластмасса ташкил қилса, пластмасса қатлами билан қопланган бир қават қоғоз ёки картон ёхуд шунга ўхшаш материаллардан буюмлар, 4814-товар позициясидаги (39-гуруҳ) деворга ишлатиладиган қопламалар бундан мустасно; (з) 4202-товар позициясидаги буюмлар (масалан, сафар буюмлари); (и) 46-гуруҳ буюмлари (тўқиш материалларидан тайёрланган буюмлар); (к) қоғоз ип ёки ундан тайёрланган тўқимачилик буюмлари (XI бўлим); (л) 64- ёки 65-гуруҳдаги буюмлар; (м) абразив қоғоз ёки картон (6805-товар позицияси) ёки асоси қоғоз ёки картонли слюда (6814-товар позицияси) (бироқ слюдали кукун билан қопланган қоғоз ёки картон ушбу гуруҳга киради); (н) асоси қоғоз ёки картон бўлган металл фольга (одатда XIV ёки XV бўлим); (о) 9209-товар позициясидаги буюмлар; (п) 95-гуруҳ буюмлари (масалан, ўйинчоқлар, ўйинлар, спорт анжомлари); ёки (р) 96-гуруҳ буюмлари (масалан, тугмалар, аёллар гигиеник прокладка ва тампонлари, болалар йўргаги ва тагликлар.","3. Ушбу гуруҳга 7-изоҳ қоидаларига амал қилинган тақдирда, 4801 – 4805-товар позицияларига каландерланган (ёйилган), супер-каландерланган, пардоз берилган ёки шунга ўхшаш ишлов берилган, сув белгиси туширилган ёки юзаси елимланган қоғоз ва картон, шунингдек, целлюлоза толасидан тайёрланган, ҳар қандай усулда бўялган ёки тўлиқ массаси мармар кўринишида ишланган қоғоз, картон, целлюлоза момиғи ҳамда матоси киради. 4803-товар позициясида алоҳида изоҳ берилган ҳоллардан ташқари ушбу товар позицияларига бошқача усулда ишлов берилган қоғоз, картон, целлюлоза ватаси ёки матоси кирмайди.","5. 4802-товар позициясидаги “ёзув, босма ёки бошқа график мақсадларда фойдаланиладиган қоғоз ва картон” ва “тешилмаган карталар ва тешилмаган қоғоз ленталар” атамалари асосан оқартирилган масса ёки механик ёки кимёвий-механик усул билан олинган массадан тайёрланган ҳамда қуйидаги мезонларнинг ҳар қайсисига мос келадиган қоғоз ва картонни англатади: (А) 1 м²нинг массаси 150 г дан кўп бўлмаган қоғоз ёки картон учун: (а) таркибида механик ёки кимёвий-механик усул билан олинган тола 10 фоиз ёки ундан кўп бўлган, ва (1) 1 м²нинг массаси 80 г дан кўп бўлмаган, ёки (2) массаси бўялган; ёки (б) оҳорланганлик даражаси 8 фоиздан кўп бўлган, ва (1) 1 м²нинг массаси 80 г дан кўп бўлмаган, ёки (2) массаси бўялган; ёки (в) оҳорланганлик даражаси 3 фоиздан кўп ва оқартирилганлик даражаси 60 фоиз ёки ундан кўп бўлган; ёки (г) оҳорланганлик даражаси 3 фоиздан кўп, лекин 8 фоиздан кўп бўлмаган ҳамда босилганлик индекси 2,5 кПа·м²/г га тенг ёки ундан кам бўлган; ёки (д) оҳорланганлик даражаси 3 фоиздан кам, оқартирилганлик даражаси 60 фоиз ёки ундан кўп бўлган ҳамда 2,5 кПа·м²/г га тенг ёки ундан кам бўлган. (Б) 1 м²нинг массаси 150 г дан кўп бўлган қоғоз ёки картон учун: (а) массаси бўялган; ёки (б) оқартирилганлик даражаси 60 фоиз ёки ундан кўп бўлган ҳамда (1) қалинлиги 225 мкм (микрон) ёки ундан кам бўлган, ёки (2) қалинлиги 225 мкм (микрон) дан кўп, лекин 508 мкм (микрон)дан кўп бўлмаган ҳамда оҳорланганлик даражаси 3 фоиздан кўп бўлган; ёки (в) оқартирилганлик даражаси 60 фоиздан кам, қалинлиги 254 мкм (микрон) ёки ундан кам ва оҳорланганлик даражаси 8 фоиздан кўп бўлган. Бироқ 4802-товар позициясига фильтрлайдиган қоғоз ёки картон (жумладан пакетчали чой учун қоғозлар) ёки том ёпишда ишлатиладиган қоғоз ёки картон кирмайди.","7. 4801 дан 4811-позициягача икки ёки ундан ортиқ товар позицияларига киритилиши мумкин бўлган қоғоз, картон, целлюлоза момиғи ҳамда целлюлоза толаларидан тайёрланган мато товар позицияларида алоҳида изоҳ берилган ҳолатлардан ташқари, айтиб ўтилган товар позициялари орасида кодлар ўсиб бориши тартибида охирги товар позициясига киритилади.","10. 4820-товар позициясига ўлчам бўйича кесилган, босилган ёки босилмаган, нақш солинган ёки солинмаган, тешилган ёки тешилмаган алоҳида листлар ва карталар киритилмайди.","12. 4814- ёки 4821-товар позициясига киритилган буюмлардан ташқари, асосий мақсадига кўра махсус босма нақш, расм ёки тасвир туширилган қоғоз, картон, целлюлоза қоғози ва улардан тайёрланган буюмлар 49-гуруҳга киритилади. Субпозицияларга изоҳ:"]},"49":{"title":"БОСМА КИТОБЛАР, ГАЗЕТАЛАР, РЕПРОДУКЦИЯЛАР ВА ПОЛИГРАФИЯ САНОАТИНИНГ БОШҚА","section":"X","notes":["1. Ушбу бўлимга қуйидагилар киритилмайди: (а) чўткалар тайёрлаш учун ҳайвонларнинг жун ва туклари (0502-товар позицияси); от сочи ёки унинг чиқиндилари (0511-товар позицияси); (б) одам сочи ва ундан тайёрланган буюмлар (0501-, 6703- ёки 6704-товар позицияси), фильтрловчи матодан ёки одатда мойни сиқиб олиш прессларида ёхуд шу каби мақсадларда қўлланилувчи сузгич матоларидан ташқари (5911-товар позицияси); (в) пахта линти ёки 14-гурухнинг келиб чиқиши ўсимликка оид бўлган бошқа материаллари; (г) 2524-товар позициясига кирувчи асбест ёки ушбу асбестдан ёхуд 6812- ёки 6813-товар позициясининг бошқа материалларидан тайёрланган буюмлар; (д) 3005- ёки 3006-товар позициясининг буюмлари; 3306-товар позициясининг чакана савдо учун мўлжалланган алоҳида қадоқда, тиш оралиғини тозалашда ишлатиладиган иплари; (е) 3701 –3704-товар позицияларининг сенсибилизацияланган (ёруғликка таъсирчан материал билан қопланган) тўқимачилик материаллари; (ж) кўндаланг кесими 1 мм дан катта бўлган моноиплар ёки эни 5 мм дан катта бўлган ясси иплар ёхуд шу каби шакллар (масалан, сунъий сомонча), пластмассадан тайёрланган (39- гуруҳ), ёки тўқилган буюмлар, ёки мато, ёки моно ипдан ёхуд ясси ипдан тўқилган бошқа саватчали ёки тўқилган буюмлар (46-гуруҳ); (з) 39-гуруҳнинг пластмасса шимдирилган, қопланган ёки юзаси дублиринланган матолари, қўлда ёки дастгоҳда тўқилган трикотаж матолари, намат ёки фетр ёхуд нотўқима материаллари ёки улардан тайёрланган буюмлари; (и) 40-гуруҳнинг резина шимдирилган, қопланган ёки юзаси дублиринланган матолари, қўлда ёки дастгоҳда тўқилган трикотаж матолари, намат ёки фетр ёхуд нотўқима материаллари ёки улардан тайёрланган буюмлари; (к) 4303- ёки 4304-товар позициясидаги тук ёки жун қопламали тери (41- ёки 43-гуруҳ) ёки табиий мўйнадан буюмлар, сунъий мўйна ёки улардан тайёрланган буюмлар; (л) 4201- ёки 4202-товар позициядаги тўқимачилик материалларидан тайёрланган буюмлар; (м) 48-гуруҳдаги товарлар ва буюмлар (масалан, целлюлоза ватаси); (н) 64-гуруҳдаги пойабзал ва унинг деталлари, гетрилар ёки гамашлар ёхуд шу каби буюмлар; (о) 65-гуруҳдаги соч учун тўр ёки бош кийимлар ёки уларнинг қисмлари; (п) 67-гуруҳ товарлари; (р) абразив қопламали тўқимачилик материаллари (6805 товар позицияси), ҳамда 6815 товар позициясидаги углерод толалар ёки улардан тайёрланган буюмлар; (с) шиша тола ёки улардан тайёрланган маҳсулотлар, шиша ипдан ишланиб, тагидаги фон кўриниб турадиган каштадан ташқари (70-гуруҳ); (т) 94-гуруҳ буюмлари (масалан, мебель, кўрпа-тўшак жиҳозлари, ёриткичлар ва ёритиш ускуналари); (у) 95-гуруҳ буюмлари (масалан, ўйинчоқлар, ўйинлар, спорт инвентарлари ва тўрлар); (ф) 96-гуруҳ маҳсулотлари (масалан, чўткалар, тикиш учун йўл жамланмаси, қистирғич- тақилма, ёзув машинкаси учун лента, аёллар гигиеник таглиги ва тампонлари, плёнка ва тагликлар); ёки (х) 97-гуруҳ буюмлари.","2. (А) 50 – 55-гуруҳларга ёки 5809- ёки 5902-товар позициясига киритилган ва икки ёки ундан ортиқ тўқимачилик материаллари аралашмасидан ташкил топган товарлар, мазкур товардаги барча тўқимачилик материаллари солиштирилганда, масса бўйича бошқаларидан ортиқ бўлган тўқимачилик материали бўйича таснифланиши лозим. Агар, бирорта ҳам тўқимачилик материали масса бўйича устунлик қилмаса, бундай товарлар кўриб чиқилаётган товар позициялари орасидан, кодларнинг ўсиш тартибида охиргисига тўғри келадиган тўқимачилик материалига кўра таснифланиши лозим. (Б) Юқоридаги қоида қўлланилганда: (а) от сочидан тайёрланган позумент ип (5110-товар позицияси) ва металлаштирилган ип (5605-товар позицияси) ягона тўқимачилик материали сифатида қаралиши лозим бўлиб, унинг массаси уни ташкил этувчи компонентлар массалари йиғиндисига тенг деб ҳисобланади; матолар таснифланганда металлаштирилган ип тўқимачилик материали сифатида қаралиши лозим; (б) мақбул товар позициясини танлашда аввал гуруҳ, сўнгра ушбу гуруҳ ичидаги тегишли товар позицияси аниқланади, мазкур гуруҳга киритилмайдиган материалларни инобатга олмаган ҳолатда; (в) 54- ва 55-гуруҳларнинг иккаласи бошқа ихтиёрий гуруҳ билан боғлиқ бўлган ҳолатларда, улар бир ягона гуруҳ сифатида қаралиши лозим; (г) гуруҳ ёки товар позициясига турли тўқимачилик материалларидан тайёрланган товарлар кирган ҳолатларда, улар ягона тўқимачилик материали сифатида қаралиши лозим. (В) Юқоридаги 2 (А) ва 2 (Б) изоҳларда келтирилган қоидалар қуйидаги 3 (А, Б), 4 (А, Б), 5 ёки 6 изоҳларда қайд этилган йигирилган ипни таснифлашда ҳам қўлланади.","3. (А) Ушбу бўлим доирасида, қуйида келтирилган 3 (Б) изоҳларда кўрсатилган истисноларга риоя қилган ҳолда, қуйида тавсифи келтирилган йигирилган ипни (бир ипли, кўп бурамли (эшилган) ёки бир бурамли) “бечевкалар, арқонлар, канатлар ва трослар” сифатида қараш керак: (а) 20 000 дтекс дан юқори чизиқли зичликдаги ипак ипларидан ёки ипак чиқиндиларидан тайёрланган; (б) 10 000 дтекс дан юқори чизиқли зичликдаги кимёвий иплардан тайёрланган (шу жумладан, 54-гуруҳдаги икки ёки ундан ортиқ моноиплардан иборат иплар); (в) каноптола ёки зиғир толалардан тайёрланган: (i) сайқалланган 1429 дтекс ёки ундан юқори чизиқли зичликдаги; ёки (ii) сайқалланмаган 20 000 дтекс дан юқори чизиқли зичликдаги; (г) кокос ёнғоғи толаларидан уч ва ундан ортиқ тахланиб олинган; (д) бошқа ўсимлик толаларидан олинган 20 000 дтекс дан юқори чизиқли зичликдаги; ёки (е) металлаштирилган ип билан армирланган. (Б) Истисно: (а) ҳайвонларнинг жунидан ёки бошқа юнглардан йигирилган ип ва қоғиздан йигирилган ип, метал иплар билан армирланган йигирилган ипдан ташқари; (б) 55-гуруҳдаги кимёвий ипларнинг жгути ва 54-гуруҳдаги бурамсиз ёки бурамаси 5 бр/м дан кам бўлган комплекс ип; (в) 5006-товар позициясидаги ипак қуртининг ипак ишлаб чиқарувчи безларидан толалар ва 54-гуруҳдаги моноиплар; (г) 5605-товар позициясидаги металлаштирилган иплар; йигирилган ип, метал иплар билан армирланган, юқорида кўрсатилган 3 (А) (е) изоҳларга асосланиб киритилади. (д) 5606-товар позициясидаги синель йигирилган ип, позумент ип ва шаклдор ҳалқали йигирилган ип.","4. (А) 50-, 51-, 52-, 54- ва 55-гуруҳларда қуйидаги 4 (Б) изоҳда кўрсатилган истисноларга риоя этган ҳолда, “чакана савдо учун қадоқланган” атамаси йигирилган ипни (бир ипли, кўп бурамли (эшилган) ёки бир бурамли) англатади: (а) картон пластиналар, ғалтаклар, патронлар ёки шу каби ташувчиларда массаси (ташувчиси билан бирга): (i) 85 г – ипак иплар, ипак чиқиндилар ёки кимёвий иплар учун; ёки (ii) 125 г – бошқа йигирилган иплар учун; (б) калава, пасма ёки моток шаклда, массаси қуйидагидан юқори бўлмаган: (i) 85 г – ипак иплари ёки ипак чиқиндилари, чизиқли зичлиги 3000 дтексдан кам кимёвий иплар учун; (ii) 125 г – чизиқли зичлиги 2000 дтекс дан кам бошқа йигирилган иплар учун; ёки (iii) 500 г – бошқа йигирилган иплар учун; (в) бир-биридан иплар билан ажратилиб, ушбу ажратилиш уларни бир-бирига боғлиқ бўлмаслигини таъминловчи бир нечта кичикроқ пасмалар ёки мотоклардан иборат пасмалар ёки мотоклар, шу билан бирга кичикроқ пасмалар ёки мотокларнинг ҳар бирининг массаси қуйидагидан ортиқ эмас: (i) 85 г – ипак иплар, ипак чиқиндилар ёки кимвий иплар учун; ёки (ii) 125 г – бошқа йигирилган иплар учун. (Б) Истисно: (а) ҳар қандай тўқимачилик маҳсулотидан тайёрланган бир иплик йигирилган ип, қуйидагидан ташқари: (i) ҳайвонларнинг жунидан ёки ингичка толасидан йигирилган бир иплик оқартирилмаган ип; ва (ii) ҳайвонларнинг жунидан ёки ингичка толасидан тайёрланган бир иплик йигирилган ип, оқартирилган, бўялган ёки гул босилган, чизиқли зичлиги 5000 дтекс дан юқори; (б) кўп бурамли (эшилган) ёки бир бурамли йигирилган ип, оқартирилмаган: (i) ипак ипларидан ёки ипак чиқиндиларидан, қадоқланган; ёки (ii) бошқа тўқимачилик материалларидан тайёрланган, ҳайвонларнинг жуни ёки ингичка толасидан ташқари, пасмаларда ёки мотокларда; (в) ипак ипларидан ёки ипак чиқиндиларидан кўп бурамли (эшилган) ёки бир бурамли йигирилган ип, оқартирилган, бўялган ёки гул босилган, чизиқли зичлиги 133 дтекс ёки кам бўлган; ва (г) ҳар қандай тўқимачилик материалидан бир ипли, кўп бурамли (эшилган) ёки бир бурамли йигирилган ип: (i) хочсимон ўрилишга эга пасма ёки мотокда; ёки (ii) ташувчиларга ўралган ёки унинг тўқимачилик саноатида ишлатилишини кўрсатадиган бошқа усулда ўралган (масалан, пачаткаларда, эшиш патронларида ва найчаларда, конуссимон бобинларда ёки урчуқларда ёки шпинделларда ёки пилла шаклидаги кашта тикиш машиналарида).","5. 5204-, 5401- ва 5508-товар позицияларида “тикув иплари” кўп бурамли ёки бир бурамли қуйидаги йигирилган ипни англатади: (а) ташувчига қадоқланган (масалан, найчалар, патронлар), массаси 1000 г (ташувчининг массаси қўшилганда) дан ортиқ эмас; (б) тикув иплари сифатида қўллаш учун аппретланган; ва (в) охирида ўнг томонга бурам берилган.","6. Мазкур бўлимда “юқори мустаҳкамликка эга йигирилган ип” атамаси сН/текс да (сантиньютон тақсим тексс) ўлчанадиган, қуйидагидан ортиқ нисбий узилиш кучига эга йигирилган ипни англатади: нейлон ёки бошқа полиамидлар ёхуд полиэфирлардан тайёрланган битта иплик йигирилган ип – 60 сН/текс; нейлон ёки бошқа полиамидлар ёки полиэфирлардан тайёрланган кўп бурамли (эшилган) ёки бир бурамли ип – 53 сН/текс; вискоза толасидан тайёрланган битта иплик, кўп бурамли (эшилган) ёки бир бурамли"],"excl":["1. Ушбу бўлимга қуйидагилар киритилмайди: (а) чўткалар тайёрлаш учун ҳайвонларнинг жун ва туклари (0502-товар позицияси); от сочи ёки унинг чиқиндилари (0511-товар позицияси); (б) одам сочи ва ундан тайёрланган буюмлар (0501-, 6703- ёки 6704-товар позицияси), фильтрловчи матодан ёки одатда мойни сиқиб олиш прессларида ёхуд шу каби мақсадларда қўлланилувчи сузгич матоларидан ташқари (5911-товар позицияси); (в) пахта линти ёки 14-гурухнинг келиб чиқиши ўсимликка оид бўлган бошқа материаллари; (г) 2524-товар позициясига кирувчи асбест ёки ушбу асбестдан ёхуд 6812- ёки 6813-товар позициясининг бошқа материалларидан тайёрланган буюмлар; (д) 3005- ёки 3006-товар позициясининг буюмлари; 3306-товар позициясининг чакана савдо учун мўлжалланган алоҳида қадоқда, тиш оралиғини тозалашда ишлатиладиган иплари; (е) 3701 –3704-товар позицияларининг сенсибилизацияланган (ёруғликка таъсирчан материал билан қопланган) тўқимачилик материаллари; (ж) кўндаланг кесими 1 мм дан катта бўлган моноиплар ёки эни 5 мм дан катта бўлган ясси иплар ёхуд шу каби шакллар (масалан, сунъий сомонча), пластмассадан тайёрланган (39- гуруҳ), ёки тўқилган буюмлар, ёки мато, ёки моно ипдан ёхуд ясси ипдан тўқилган бошқа саватчали ёки тўқилган буюмлар (46-гуруҳ); (з) 39-гуруҳнинг пластмасса шимдирилган, қопланган ёки юзаси дублиринланган матолари, қўлда ёки дастгоҳда тўқилган трикотаж матолари, намат ёки фетр ёхуд нотўқима материаллари ёки улардан тайёрланган буюмлари; (и) 40-гуруҳнинг резина шимдирилган, қопланган ёки юзаси дублиринланган матолари, қўлда ёки дастгоҳда тўқилган трикотаж матолари, намат ёки фетр ёхуд нотўқима материаллари ёки улардан тайёрланган буюмлари; (к) 4303- ёки 4304-товар позициясидаги тук ёки жун қопламали тери (41- ёки 43-гуруҳ) ёки табиий мўйнадан буюмлар, сунъий мўйна ёки улардан тайёрланган буюмлар; (л) 4201- ёки 4202-товар позициядаги тўқимачилик материалларидан тайёрланган буюмлар; (м) 48-гуруҳдаги товарлар ва буюмлар (масалан, целлюлоза ватаси); (н) 64-гуруҳдаги пойабзал ва унинг деталлари, гетрилар ёки гамашлар ёхуд шу каби буюмлар; (о) 65-гуруҳдаги соч учун тўр ёки бош кийимлар ёки уларнинг қисмлари; (п) 67-гуруҳ товарлари; (р) абразив қопламали тўқимачилик материаллари (6805 товар позицияси), ҳамда 6815 товар позициясидаги углерод толалар ёки улардан тайёрланган буюмлар; (с) шиша тола ёки улардан тайёрланган маҳсулотлар, шиша ипдан ишланиб, тагидаги фон кўриниб турадиган каштадан ташқари (70-гуруҳ); (т) 94-гуруҳ буюмлари (масалан, мебель, кўрпа-тўшак жиҳозлари, ёриткичлар ва ёритиш ускуналари); (у) 95-гуруҳ буюмлари (масалан, ўйинчоқлар, ўйинлар, спорт инвентарлари ва тўрлар); (ф) 96-гуруҳ маҳсулотлари (масалан, чўткалар, тикиш учун йўл жамланмаси, қистирғич- тақилма, ёзув машинкаси учун лента, аёллар гигиеник таглиги ва тампонлари, плёнка ва тагликлар); ёки (х) 97-гуруҳ буюмлари.","2. (А) 50 – 55-гуруҳларга ёки 5809- ёки 5902-товар позициясига киритилган ва икки ёки ундан ортиқ тўқимачилик материаллари аралашмасидан ташкил топган товарлар, мазкур товардаги барча тўқимачилик материаллари солиштирилганда, масса бўйича бошқаларидан ортиқ бўлган тўқимачилик материали бўйича таснифланиши лозим. Агар, бирорта ҳам тўқимачилик материали масса бўйича устунлик қилмаса, бундай товарлар кўриб чиқилаётган товар позициялари орасидан, кодларнинг ўсиш тартибида охиргисига тўғри келадиган тўқимачилик материалига кўра таснифланиши лозим. (Б) Юқоридаги қоида қўлланилганда: (а) от сочидан тайёрланган позумент ип (5110-товар позицияси) ва металлаштирилган ип (5605-товар позицияси) ягона тўқимачилик материали сифатида қаралиши лозим бўлиб, унинг массаси уни ташкил этувчи компонентлар массалари йиғиндисига тенг деб ҳисобланади; матолар таснифланганда металлаштирилган ип тўқимачилик материали сифатида қаралиши лозим; (б) мақбул товар позициясини танлашда аввал гуруҳ, сўнгра ушбу гуруҳ ичидаги тегишли товар позицияси аниқланади, мазкур гуруҳга киритилмайдиган материалларни инобатга олмаган ҳолатда; (в) 54- ва 55-гуруҳларнинг иккаласи бошқа ихтиёрий гуруҳ билан боғлиқ бўлган ҳолатларда, улар бир ягона гуруҳ сифатида қаралиши лозим; (г) гуруҳ ёки товар позициясига турли тўқимачилик материалларидан тайёрланган товарлар кирган ҳолатларда, улар ягона тўқимачилик материали сифатида қаралиши лозим. (В) Юқоридаги 2 (А) ва 2 (Б) изоҳларда келтирилган қоидалар қуйидаги 3 (А, Б), 4 (А, Б), 5 ёки 6 изоҳларда қайд этилган йигирилган ипни таснифлашда ҳам қўлланади.","3. (А) Ушбу бўлим доирасида, қуйида келтирилган 3 (Б) изоҳларда кўрсатилган истисноларга риоя қилган ҳолда, қуйида тавсифи келтирилган йигирилган ипни (бир ипли, кўп бурамли (эшилган) ёки бир бурамли) “бечевкалар, арқонлар, канатлар ва трослар” сифатида қараш керак: (а) 20 000 дтекс дан юқори чизиқли зичликдаги ипак ипларидан ёки ипак чиқиндиларидан тайёрланган; (б) 10 000 дтекс дан юқори чизиқли зичликдаги кимёвий иплардан тайёрланган (шу жумладан, 54-гуруҳдаги икки ёки ундан ортиқ моноиплардан иборат иплар); (в) каноптола ёки зиғир толалардан тайёрланган: (i) сайқалланган 1429 дтекс ёки ундан юқори чизиқли зичликдаги; ёки (ii) сайқалланмаган 20 000 дтекс дан юқори чизиқли зичликдаги; (г) кокос ёнғоғи толаларидан уч ва ундан ортиқ тахланиб олинган; (д) бошқа ўсимлик толаларидан олинган 20 000 дтекс дан юқори чизиқли зичликдаги; ёки (е) металлаштирилган ип билан армирланган. (Б) Истисно: (а) ҳайвонларнинг жунидан ёки бошқа юнглардан йигирилган ип ва қоғиздан йигирилган ип, метал иплар билан армирланган йигирилган ипдан ташқари; (б) 55-гуруҳдаги кимёвий ипларнинг жгути ва 54-гуруҳдаги бурамсиз ёки бурамаси 5 бр/м дан кам бўлган комплекс ип; (в) 5006-товар позициясидаги ипак қуртининг ипак ишлаб чиқарувчи безларидан толалар ва 54-гуруҳдаги моноиплар; (г) 5605-товар позициясидаги металлаштирилган иплар; йигирилган ип, метал иплар билан армирланган, юқорида кўрсатилган 3 (А) (е) изоҳларга асосланиб киритилади. (д) 5606-товар позициясидаги синель йигирилган ип, позумент ип ва шаклдор ҳалқали йигирилган ип.","4. (А) 50-, 51-, 52-, 54- ва 55-гуруҳларда қуйидаги 4 (Б) изоҳда кўрсатилган истисноларга риоя этган ҳолда, “чакана савдо учун қадоқланган” атамаси йигирилган ипни (бир ипли, кўп бурамли (эшилган) ёки бир бурамли) англатади: (а) картон пластиналар, ғалтаклар, патронлар ёки шу каби ташувчиларда массаси (ташувчиси билан бирга): (i) 85 г – ипак иплар, ипак чиқиндилар ёки кимёвий иплар учун; ёки (ii) 125 г – бошқа йигирилган иплар учун; (б) калава, пасма ёки моток шаклда, массаси қуйидагидан юқори бўлмаган: (i) 85 г – ипак иплари ёки ипак чиқиндилари, чизиқли зичлиги 3000 дтексдан кам кимёвий иплар учун; (ii) 125 г – чизиқли зичлиги 2000 дтекс дан кам бошқа йигирилган иплар учун; ёки (iii) 500 г – бошқа йигирилган иплар учун; (в) бир-биридан иплар билан ажратилиб, ушбу ажратилиш уларни бир-бирига боғлиқ бўлмаслигини таъминловчи бир нечта кичикроқ пасмалар ёки мотоклардан иборат пасмалар ёки мотоклар, шу билан бирга кичикроқ пасмалар ёки мотокларнинг ҳар бирининг массаси қуйидагидан ортиқ эмас: (i) 85 г – ипак иплар, ипак чиқиндилар ёки кимвий иплар учун; ёки (ii) 125 г – бошқа йигирилган иплар учун. (Б) Истисно: (а) ҳар қандай тўқимачилик маҳсулотидан тайёрланган бир иплик йигирилган ип, қуйидагидан ташқари: (i) ҳайвонларнинг жунидан ёки ингичка толасидан йигирилган бир иплик оқартирилмаган ип; ва (ii) ҳайвонларнинг жунидан ёки ингичка толасидан тайёрланган бир иплик йигирилган ип, оқартирилган, бўялган ёки гул босилган, чизиқли зичлиги 5000 дтекс дан юқори; (б) кўп бурамли (эшилган) ёки бир бурамли йигирилган ип, оқартирилмаган: (i) ипак ипларидан ёки ипак чиқиндиларидан, қадоқланган; ёки (ii) бошқа тўқимачилик материалларидан тайёрланган, ҳайвонларнинг жуни ёки ингичка толасидан ташқари, пасмаларда ёки мотокларда; (в) ипак ипларидан ёки ипак чиқиндиларидан кўп бурамли (эшилган) ёки бир бурамли йигирилган ип, оқартирилган, бўялган ёки гул босилган, чизиқли зичлиги 133 дтекс ёки кам бўлган; ва (г) ҳар қандай тўқимачилик материалидан бир ипли, кўп бурамли (эшилган) ёки бир бурамли йигирилган ип: (i) хочсимон ўрилишга эга пасма ёки мотокда; ёки (ii) ташувчиларга ўралган ёки унинг тўқимачилик саноатида ишлатилишини кўрсатадиган бошқа усулда ўралган (масалан, пачаткаларда, эшиш патронларида ва найчаларда, конуссимон бобинларда ёки урчуқларда ёки шпинделларда ёки пилла шаклидаги кашта тикиш машиналарида)."]},"50":{"title":"ИПАК","section":"XI","notes":[],"excl":[]},"51":{"title":"ҲАЙВОНЛАРНИНГ ЖУНИ, ИНГИЧКА ЁКИ ДАҒАЛ ТУКИ; ОТ СОЧИДАН ИП ВА МАТО","section":"XI","notes":[],"excl":[]},"52":{"title":"ПАХТА","section":"XI","notes":[],"excl":[]},"53":{"title":"БОШҚА ЎСИМЛИК ТЎҚИМАЧИЛИК ТОЛАЛАРИ;","section":"XI","notes":[],"excl":[]},"54":{"title":"КИМЁВИЙ ИПЛАР; КИМЁВИЙ ТЎҚИМАЧИЛИК МАТЕРИАЛЛАРИДАН","section":"XI","notes":["1. Бутун номенклатура бўйича “кимёвий толалар” атамаси органик полимерлардан қуйидаги икки саноат усулларидан бири бўйича олинган толалар ва ипларни англатади: (а) полиамидлар, полиэфирлар, полиолефинлар ва полиуретанлар каби полимерларни ишлаб чиқариш учун органик мономерларни полимерлаш, ёки ушбу жараёнлар асосида ишлаб чиқарилган полмерларни кимёвий модификациялаш (масалан, поливинилацетатни гидролизлаб поливинил спиртини олиш); (б) мисс-аммиакли ёки вискоза толалари каби полимерларни олиш учун табиий органик полимерларни эритиш, ёки уларга кимёвий ишлов бериш (масалан, целлюлоза), ёки целлюлоза ацетати ёки альгинатлар каби полимерларни олиш учун табиий органик полимерларни кимёвий модификациялаш (масалан, казеин ва бошқа протеинлар ва альгин кислоталари целлюлозалари). Толаларга нисбатан қўлланиладиган “синтетик” ва “сунъий” атамалари қуйидагиларни: синтетик – (a) пунктдаги толаларни; сунъий – (б) пунктдаги толаларни англатади. 5404- ёки 5405-товар позициясидаги ясси ва анологик иплар кимёвий толалар ҳисобланмайди. “Кимёвий”, “синтетик” ва “сунъий” атамалари “тўқимачилик материаллари”га қўлланилганда худди шундай маънога эга.","2. 5402- и 5403-товар позицияларига 55-гуруҳнинг синтетик ва сунъий ипларнинг жгутлари киритилмайди."],"excl":["2. 5402- и 5403-товар позицияларига 55-гуруҳнинг синтетик ва сунъий ипларнинг жгутлари киритилмайди."]},"55":{"title":"КИМЁВИЙ ТОЛАЛАР","section":"XI","notes":[],"excl":[]},"56":{"title":"ВАТА, КИГИЗ ЁКИ ФЕТР ВА НОТЎҚИМА МАТЕРИАЛЛАР; МАХСУС ЙИГИРИЛГАН ИП; ЧИЛВИРЛАР,","section":"XI","notes":["1. Мазкур гуруҳга киритилмайди: (а) Вата, кигиз ёки фетр ёхуд нотўқима матолар, моддалар ёки препаратлар билан шимдирилган ёки қопланган (масалан, 33-гуруҳдаги парфюмерия ёки косметика воситалари, 3401-товар позициясидаги совунлар ёки ювиш воситалари, 3405-товар позициясидаги сайқаллаш воситалари, кремлар ёки шунга ўхшаш препаратлар, 3809- товар позициясидаги матоларни юмшатувчи воситалар), бунда тўқимачилик материали оддийгина асос бўлади; (б) 5811-товар позициясининг тўқимачилик буюмлари; (в) кигиз ёки фетр ёхуд нотўқима матолар асосидаги табиий ёки сунъий абразив кукун ёки доначалар (6805-товар позицияси); (г) кигиз ёки фетр ёки нотўқима матолар асосидаги агломерацияланган ёки қайта тикланган слюда (6814-товар позицияси); (д) кигиз ёки фетр ёки нотўқима матолар асосидаги металл фольга (одатда, XIV ёки XV бўлим); ёки (е) аёллар учун гигеник прокладка ва тампонлар, пеленкалар ва тагликлар ва 9619-товар позициясидаги шу каби буюмлар.","2. “Кигиз ёки фетр” атамаси игна уриш усулида тайёрланган кигиз ёки фетр ва тўқимачилик толалари ҳолстидан иборат бўлган материалларни ўз ичига олади ва бунда игна билан уриш орқали холст толалари орасидаги илашувчанлик кучайтирилади.","3. 5602- ва 5603-товар позицияларига пластмасса ёки резина шимдирилган, қопланган ёки иккиланган, мос равишда, кигиз ёки фетр ва нотўқима матолар, резина структурасига (қаттиқ ёки ғовакли) боғлиқ бўлмаган ҳолда, киритилади. 5603-товар позициясига, шунингдек, бириктирувчиси пластмасса ёки резина бўлган нотўқима матолар киради. Лекин, 5602- ва 5603-товар позицияларига қуйидагилар киритилмайди: (а) таркибидаги тўқимачилик материали 50 мас.% дан кўп бўлмаган, пластмасса ёки резина шимдирилган, қопланган ёки дублирланган кигиз ёки фетр, ёхуд пластмассанинг ёки резинанинг ичига тўлиқ бекитилган кигиз ёки фетр (39- ёки 40-гуруҳ); (б) пластмассанинг ёки резинанинг ичига тўлиқ бекитилган ёхуд шундай материаллар билан икки томондан тўлиқ қопланган нотўқима материаллар, шу шарт биланки, бундай қопланиш ёки қобиқ қуролланмаган оддий кўз билан фарқланиши мумкин бўлади, бу билан қандайдир боғлиқ ранг ўзгаришини эътиборга олмаган ҳолда (39- ёки 40-гуруҳ); ёки (в) кигиз ёки фетр ёхуд нотўқима материаллар билан бириктирилган ғовакли пластмассадан плиталар, листлар ёки тасмалар ёхуд ленталар. Бунда, тўқимачилик материали армирлаш учун қўшилган (39- ёки 40-гуруҳ).","4. Шимдирилганлигини ёки қопламасини қуролланмаган оддий кўз билан кўриш мумкин бўлмаган тўқимачилик йигирилган иплари ёки 5404- ёки 5405-товар позициясининг ясси ёки шу каби иплари 5604-товар позициясига киритилмайди (одатда 50-55-гуруҳлар); бунда бу билан қандайдир боғлиқ ранг ўзгариши эътиборга олинмайди."],"excl":["1. Мазкур гуруҳга киритилмайди: (а) Вата, кигиз ёки фетр ёхуд нотўқима матолар, моддалар ёки препаратлар билан шимдирилган ёки қопланган (масалан, 33-гуруҳдаги парфюмерия ёки косметика воситалари, 3401-товар позициясидаги совунлар ёки ювиш воситалари, 3405-товар позициясидаги сайқаллаш воситалари, кремлар ёки шунга ўхшаш препаратлар, 3809- товар позициясидаги матоларни юмшатувчи воситалар), бунда тўқимачилик материали оддийгина асос бўлади; (б) 5811-товар позициясининг тўқимачилик буюмлари; (в) кигиз ёки фетр ёхуд нотўқима матолар асосидаги табиий ёки сунъий абразив кукун ёки доначалар (6805-товар позицияси); (г) кигиз ёки фетр ёки нотўқима матолар асосидаги агломерацияланган ёки қайта тикланган слюда (6814-товар позицияси); (д) кигиз ёки фетр ёки нотўқима матолар асосидаги металл фольга (одатда, XIV ёки XV бўлим); ёки (е) аёллар учун гигеник прокладка ва тампонлар, пеленкалар ва тагликлар ва 9619-товар позициясидаги шу каби буюмлар.","3. 5602- ва 5603-товар позицияларига пластмасса ёки резина шимдирилган, қопланган ёки иккиланган, мос равишда, кигиз ёки фетр ва нотўқима матолар, резина структурасига (қаттиқ ёки ғовакли) боғлиқ бўлмаган ҳолда, киритилади. 5603-товар позициясига, шунингдек, бириктирувчиси пластмасса ёки резина бўлган нотўқима матолар киради. Лекин, 5602- ва 5603-товар позицияларига қуйидагилар киритилмайди: (а) таркибидаги тўқимачилик материали 50 мас.% дан кўп бўлмаган, пластмасса ёки резина шимдирилган, қопланган ёки дублирланган кигиз ёки фетр, ёхуд пластмассанинг ёки резинанинг ичига тўлиқ бекитилган кигиз ёки фетр (39- ёки 40-гуруҳ); (б) пластмассанинг ёки резинанинг ичига тўлиқ бекитилган ёхуд шундай материаллар билан икки томондан тўлиқ қопланган нотўқима материаллар, шу шарт биланки, бундай қопланиш ёки қобиқ қуролланмаган оддий кўз билан фарқланиши мумкин бўлади, бу билан қандайдир боғлиқ ранг ўзгаришини эътиборга олмаган ҳолда (39- ёки 40-гуруҳ); ёки (в) кигиз ёки фетр ёхуд нотўқима материаллар билан бириктирилган ғовакли пластмассадан плиталар, листлар ёки тасмалар ёхуд ленталар. Бунда, тўқимачилик материали армирлаш учун қўшилган (39- ёки 40-гуруҳ).","4. Шимдирилганлигини ёки қопламасини қуролланмаган оддий кўз билан кўриш мумкин бўлмаган тўқимачилик йигирилган иплари ёки 5404- ёки 5405-товар позициясининг ясси ёки шу каби иплари 5604-товар позициясига киритилмайди (одатда 50-55-гуруҳлар); бунда бу билан қандайдир боғлиқ ранг ўзгариши эътиборга олинмайди."]},"57":{"title":"ГИЛАМЛАР ВА БОШҚА ТЎҚИМАЧИЛИК ПОЛ ҚОПЛАМАЛАРИ","section":"XI","notes":["1. Ушбу гуруҳда “гилам ва бошқа тўқимачилик пол қопламалари” атамаси эксплуатация жараёнида буюмнинг олд юзаси вазифасини тўқимачилик материаллари бажарадиган пол қопламаларини англатади ва тўқимачилик пол қопламалари хусусиятларига эга, лекин бошқа мақсадларда ишлатишга мўлжалланган буюмларни қамраб олади.","2. Ушбу гуруҳга пол қопламаларининг каркас тагликлари киритилмайди."],"excl":["2. Ушбу гуруҳга пол қопламаларининг каркас тагликлари киритилмайди."]},"58":{"title":"МАХСУС ГАЗЛАМАЛАР; ТАФТИНГ ТЎҚИМАЧИЛИК МАТЕРИАЛЛАРИ; КРУЖЕВА; ГОБЕЛЕНЛАР;","section":"XI","notes":["1. 59-гуруҳнинг 1-изоҳида кўрсатилган, шимдирилган, қопланган ёки иккиланган тўқимачилик материаллари, ёки 59-гуруҳнинг бошқа буюмлари ушбу гуруҳга киритилмайди.","2. 5801-товар позициясига, шунингдек, тук иплари ҳали қирқиб олинмаган ва бу босқичда ҳали тик ҳолатдаги тук иплари бўлмаган арқоқ тукли газламалар ҳам киритилади.","3. 5803-позициядаги маҳсулотлар учун “ўрама ўрилишли газлама” атамаси асоси тўлиқ ёки қисман маҳкамловчи ёки тўқима ўртаси иплардан ва кесишувчи ёки ўрамали иплардан, шунингдек, маҳкамловчи ёки тўқима ўртаси ипларини ярим бурилиш, тўлиқ бурилиш ёки ҳалқани кесиб ўтувчи арқоқ ипларидан ташкил топган газламани англатади.","4. 5804-товар позициясига 5608-товар позициясининг чилвир, арқон ва канатларидан ўрилган тўрли тўқималар киритилмайди.","5. 5806-товар позициясида “тор газламалар” атамаси қуйидагиларни англатади: (а) эни 30 см дан ортиқ бўлмаган, тўқилган газламалар ёки эни кенгроқ матолардан кесиб олинган, тўқиманинг иккала четида милки (газламали, ёпиштирилган ёки бошқа усулда олинган) бўлган газламалар; (б) яссилигининг эни 30 см дан ошмайдиган трубкасимон газламалар; (в) очилганда эни 30 см дан ошмайдиган, четлари қайрилган қия бейкалар. Газламали бахромаси бўлган тор газламалар 5808-товар позициясига киритилади.","6. 5810-товар позициясида “кашта” атамаси, жумладан, inter alia, металл ёки шиша иплар билан кўринадиган асосдаги (тўқимачилик материалидаги) тикилган кашталарни ва аппликация усулида ялтироқ безакларни тикиш, тўқимачилик ёки бошқа материаллардан тикилган бисерлар, мунчоқлар ёки каштали безакларни англатади. Мазкур товар позициясига игна билан кашта усулида тикилган гобеленлар киритилмайди (5805-товар позицияси).","7. 5809-товар позициясининг буюмларига қўшимча равишда, ушбу гуруҳга, шунингдек, металл иплардан тайёрланган ва кийим-кечакларни безаш учун, мебелбоп газламалар сифатида ёки аналогик мақсадларда ишлатиладиган буюмлар ҳам киритилади."],"excl":["1. 59-гуруҳнинг 1-изоҳида кўрсатилган, шимдирилган, қопланган ёки иккиланган тўқимачилик материаллари, ёки 59-гуруҳнинг бошқа буюмлари ушбу гуруҳга киритилмайди.","4. 5804-товар позициясига 5608-товар позициясининг чилвир, арқон ва канатларидан ўрилган тўрли тўқималар киритилмайди.","6. 5810-товар позициясида “кашта” атамаси, жумладан, inter alia, металл ёки шиша иплар билан кўринадиган асосдаги (тўқимачилик материалидаги) тикилган кашталарни ва аппликация усулида ялтироқ безакларни тикиш, тўқимачилик ёки бошқа материаллардан тикилган бисерлар, мунчоқлар ёки каштали безакларни англатади. Мазкур товар позициясига игна билан кашта усулида тикилган гобеленлар киритилмайди (5805-товар позицияси)."]},"59":{"title":"ТЎҚИМАЧИЛИК МАТЕРИАЛЛАРИ, ШИМДИРИЛГАН, ҚОПЛАНГАН ЁКИ ИККИЛАНГАН; ТЕХНИК","section":"XI","notes":["1. Агар контекстда бошқа фикр назарда тутилмаган бўлса бўлса, у ҳолда ушбу гуруҳда “тўқимачилик материаллари” атамаси фақат 50 – 55-гуруҳларнинг ҳамда 5803- ва 5806- товар позицияларининг газламаларига, 5808-товар позициясининг бўлагидаги ўрилган тасма ва пардозлаш материалларига ҳамда 6002–6006-товар позицияларининг машинада ёки қўлда тўқилган трикотаж матоларига тааллуқли.","2. 5903-товар позициясига киритилади: (а) ҳар қандай юза зичликдаги ва ҳар қандай табиатга эга пластмасса (зич ёки ғовакли) билан шимдирилган, қопланган ёки иккиланган тўқимачилик материаллар, қуйидагилардан ташқари: (1) шимдирилганлигини ёки қопламасини қуролланмаган оддий кўз билан кўриш мумкин бўлмаган материаллар (одатда 50-55, 58- ёки 60-гуруҳлар); бунда, рангнинг кейинги қандайдир ўзгариши эътиборга олинмайди;"],"excl":["2. 5903-товар позициясига киритилади: (а) ҳар қандай юза зичликдаги ва ҳар қандай табиатга эга пластмасса (зич ёки ғовакли) билан шимдирилган, қопланган ёки иккиланган тўқимачилик материаллар, қуйидагилардан ташқари: (1) шимдирилганлигини ёки қопламасини қуролланмаган оддий кўз билан кўриш мумкин бўлмаган материаллар (одатда 50-55, 58- ёки 60-гуруҳлар); бунда, рангнинг кейинги қандайдир ўзгариши эътиборга олинмайди;"]},"60":{"title":"МАШИНА ЁКИ ҚЎЛДА ТЎҚИЛГАН ТРИКОТАЖ МАТОЛАР","section":"XI","notes":["1. Ушбу гуруҳга қуйидагилар киритилмайди: (а) 5804-товар позициясининг қўлда тўқилган тўрлари; (б) 5807-товар позициясининг қўлда тўқилган трикотаждан ёрлиқлар, эмблемалар ва шу каби буюмлари; ёки (в) 59-гуруҳнинг шимдирилган, қопланган ёки иккиланган, машинада ёки қўлда тўқилган трикотаж матолари. Бироқ, шимдирилган, қопланган ёки иккиланган, машинада ёки қўлда тўқилган тукли трикотаж матолар 6001-товар позициясига киритилади.","2. Ушбу гуруҳга, шунингдек, металл ипдан тайёрланган ва кийим-кечакда, мебель газламаси сифатида ва шу каби мақсадларда қўлланиладиган матолар ҳам киритилади.","3. Бутун номенклатура бўйлаб “трикотаж” буюмларга кўрсатилган ҳар қандай ҳавола занжир тикувлари тўқимачилик иплари билан ҳосил қилинган “тўқилган-тикилган” буюмларни ҳам ўз ичига олади. Субпозицияларга изоҳ:","1. 6005 35-субпозициясига полиэтилен моноиплардан ёки полиэфир комплекс иплардан тайёрланган, юза зичлиги 30 г/м2 дан кам бўлмаган ва 55 г/м2 дан ортиқ бўлмаган, камида 20 тешик/м2 ва кўпи билан 100 тешик/см2 га эга бўлган, альфа–сиперметрин (ИСО), хлорфенапир (ИСО), дельтаметрин (ИНН, ИСО), ламбда-цигалотрин (ИСО), перметрин (ИСО) ёки пиримифос–метил (ИСО) билан шимдирилган ёки қопланган матолар киритилади."],"excl":["1. Ушбу гуруҳга қуйидагилар киритилмайди: (а) 5804-товар позициясининг қўлда тўқилган тўрлари; (б) 5807-товар позициясининг қўлда тўқилган трикотаждан ёрлиқлар, эмблемалар ва шу каби буюмлари; ёки (в) 59-гуруҳнинг шимдирилган, қопланган ёки иккиланган, машинада ёки қўлда тўқилган трикотаж матолари. Бироқ, шимдирилган, қопланган ёки иккиланган, машинада ёки қўлда тўқилган тукли трикотаж матолар 6001-товар позициясига киритилади."]},"61":{"title":"КИЙИМ-КЕЧАК ПРЕДМЕТЛАРИ ВА ЖИҲОЗЛАРИ,","section":"XI","notes":["1. Ушбу гуруҳга фақат машина ёки қўлда тўқилган тайёр трикотаж буюмлар киритилади.","2. Ушбу гуруҳга қуйидагилар киритилмайди: (а) 6212-товар позициясидаги буюмлар; (б) аввал фойдаланишда бўлган кийим-кечак ёки 6309-товар позициясининг аввал фойдаланишда бўлган бошқа буюмлари; ёки (в) ортопедик мосламалар, жарроҳлик тасмалари, бандажлар ёки шу каби буюмлар (9021- товар позицияси).","3. 6103- ва 6104-товар позицияларида: (а) “костюм” атамаси икки ёки уч предметдан иборат, ўнг томони айнан бир хил матодан тайёрланган ва таркибига қуйидагиларни киритган кийимлар тўпламини англатади: – ўнг томони енгларидан ташқари тўрт ёки ундан ортиқ қисмдан иборат бўлган, тананинг юқори қисми учун мўлжалланган, эҳтимол, олд қисми ушбу тўпламнинг бошқа компонентларининг ўнг томони материали билан айнан бир хил бўлган материалдан тайёрланган, курак томони эса пиджак ёки жакет астарининг материали билан айнан бир хил бўлган материалдан тайёрланган қўшимча сифатидаги сипо жилетли, битта пиджак ёки жакет ва – тананинг пастки қисми учун мўлжалланган ва шим, бриджи ёки шорти (сузиш кийимидан ташқари), юбка ёхуд лямкасиз ёки кўкракка тақиладиган қисмисиз юбка-шим ҳисобланувчи кийим-кечакнинг битта предмети. “Костюм”нинг барча компонентлари бир хил ўрилишга, рангга ва таркибга эга матодан тайёрланиши керак, шунингдек, улар бир хил фасонга ва мувофиқ ёки мос келувчи ўлчамда бўлиши лозим. Бироқ бу компонентларда бошқа матодан кант (чокка киритилиб тикилган мато бўлакчаси) мавжуд бўлиши мумкин. Агар тананинг пастки қисми учун мўлжалланган кийимнинг бир нечта алоҳида предметлари (масалан, икки жуфт шим ёки шим ва шорти, ёхуд юбка ёки юбка-шим ва шим) биргаликда тақдим этилса, бундай ҳолда костюмнинг танани пастки қисми учун мўлжалланган компоненти бўлиб бир жуфт шим ёки аёллар костюми ёки қизлар учун"],"excl":["2. Ушбу гуруҳга қуйидагилар киритилмайди: (а) 6212-товар позициясидаги буюмлар; (б) аввал фойдаланишда бўлган кийим-кечак ёки 6309-товар позициясининг аввал фойдаланишда бўлган бошқа буюмлари; ёки (в) ортопедик мосламалар, жарроҳлик тасмалари, бандажлар ёки шу каби буюмлар (9021- товар позицияси).","3. 6103- ва 6104-товар позицияларида: (а) “костюм” атамаси икки ёки уч предметдан иборат, ўнг томони айнан бир хил матодан тайёрланган ва таркибига қуйидагиларни киритган кийимлар тўпламини англатади: – ўнг томони енгларидан ташқари тўрт ёки ундан ортиқ қисмдан иборат бўлган, тананинг юқори қисми учун мўлжалланган, эҳтимол, олд қисми ушбу тўпламнинг бошқа компонентларининг ўнг томони материали билан айнан бир хил бўлган материалдан тайёрланган, курак томони эса пиджак ёки жакет астарининг материали билан айнан бир хил бўлган материалдан тайёрланган қўшимча сифатидаги сипо жилетли, битта пиджак ёки жакет ва – тананинг пастки қисми учун мўлжалланган ва шим, бриджи ёки шорти (сузиш кийимидан ташқари), юбка ёхуд лямкасиз ёки кўкракка тақиладиган қисмисиз юбка-шим ҳисобланувчи кийим-кечакнинг битта предмети. “Костюм”нинг барча компонентлари бир хил ўрилишга, рангга ва таркибга эга матодан тайёрланиши керак, шунингдек, улар бир хил фасонга ва мувофиқ ёки мос келувчи ўлчамда бўлиши лозим. Бироқ бу компонентларда бошқа матодан кант (чокка киритилиб тикилган мато бўлакчаси) мавжуд бўлиши мумкин. Агар тананинг пастки қисми учун мўлжалланган кийимнинг бир нечта алоҳида предметлари (масалан, икки жуфт шим ёки шим ва шорти, ёхуд юбка ёки юбка-шим ва шим) биргаликда тақдим этилса, бундай ҳолда костюмнинг танани пастки қисми учун мўлжалланган компоненти бўлиб бир жуфт шим ёки аёллар костюми ёки қизлар учун"]},"62":{"title":"КИЙИМ ПРЕДМЕТЛАРИ ВА КИЙИМ ЖИҲОЗЛАРИ,","section":"XI","notes":["1. Ушбу гуруҳга ҳар қандай тўқимачилик материалидан, ватадан ташқари тайёрланган фақат тайёр буюмлар киритилади, машинада ёки қўлда тўқилган трикотаж буюмларни чиқариб ташлаган ҳолда (6212-товар позициясига тааллуқли бўлганларидан ташқари).","2. Ушбу гуруҳга қуйидагилар киритилмайди: (а) аввал ишлатувда бўлган кийим-кечак ёки 6309-товар позициясининг аввал ишлатувда бўлган бошқа буюмлари; ёки (б) ортопедик мосламалар, жарроҳлик тасмалари, бандажлар ёки шу каби буюмлар (9021- товар позицияси).","3. 6203- ва 6204-товар позицияларида: (а) “костюм” атамаси икки ёки уч предметдан иборат ўнг томони айнан бир хил матодан тайёрланган ва таркибига қуйидагиларни киритган кийимлар тўпламини англатади: – ўнг томони, енгларидан ташқари, тўрт ёки ундан ортиқ қисмдан иборат бўлган, тананинг юқори қисми учун мўлжалланган, эҳтимол, олд қисми ушбу тўпламнинг бошқа компонентларининг ўнг томон материали билан айнан бир хил бўлган материалдан тайёрланган, курак томони эса пиджак ёки жакет астарининг материали билан айнан бир хил бўлган материалдан тайёрланган қўшимча сифатидаги сипо жилетли, битта пиджак ёки жакет; ва – тананинг пастки қисми учун мўлжалланган ва шим, бриджи ёки шорти (сузиш кийимидан ташқари), юбка ёхуд лямкасиз ёки кўкракка тақиладиган қисмисиз юбка-шим ҳисобланувчи кийим-кечакнинг битта предмети. “Костюм”нинг барча компонентлари бир хил ўрилишга, рангга ва таркибга эга матодан тайёрланган бўлиши керак; шунингдек, улар бир хил фасонга ва мувофиқ ёки мос келувчи ўлчамда бўлиши лозим. Бироқ, бу компонентларда бошқа матодан кант (чокка киритилиб тикилган мато бўлакчаси) мавжуд бўлиши мумкин. Агар тананинг пастки қисми учун мўлжалланган кийимнинг бир нечта алоҳида предметлари (масалан, икки жуфт шим ёки шим ва шорти, ёхуд юбка ёки юбка-шим ва шим) биргаликда тақдим этилса, бундай ҳолда костюмнинг танани пастки қисми учун мўлжалланган компоненти бўлиб, бир жуфт шим ёки аёллар костюми ёки қизлар учун"],"excl":["1. Ушбу гуруҳга ҳар қандай тўқимачилик материалидан, ватадан ташқари тайёрланган фақат тайёр буюмлар киритилади, машинада ёки қўлда тўқилган трикотаж буюмларни чиқариб ташлаган ҳолда (6212-товар позициясига тааллуқли бўлганларидан ташқари).","2. Ушбу гуруҳга қуйидагилар киритилмайди: (а) аввал ишлатувда бўлган кийим-кечак ёки 6309-товар позициясининг аввал ишлатувда бўлган бошқа буюмлари; ёки (б) ортопедик мосламалар, жарроҳлик тасмалари, бандажлар ёки шу каби буюмлар (9021- товар позицияси).","3. 6203- ва 6204-товар позицияларида: (а) “костюм” атамаси икки ёки уч предметдан иборат ўнг томони айнан бир хил матодан тайёрланган ва таркибига қуйидагиларни киритган кийимлар тўпламини англатади: – ўнг томони, енгларидан ташқари, тўрт ёки ундан ортиқ қисмдан иборат бўлган, тананинг юқори қисми учун мўлжалланган, эҳтимол, олд қисми ушбу тўпламнинг бошқа компонентларининг ўнг томон материали билан айнан бир хил бўлган материалдан тайёрланган, курак томони эса пиджак ёки жакет астарининг материали билан айнан бир хил бўлган материалдан тайёрланган қўшимча сифатидаги сипо жилетли, битта пиджак ёки жакет; ва – тананинг пастки қисми учун мўлжалланган ва шим, бриджи ёки шорти (сузиш кийимидан ташқари), юбка ёхуд лямкасиз ёки кўкракка тақиладиган қисмисиз юбка-шим ҳисобланувчи кийим-кечакнинг битта предмети. “Костюм”нинг барча компонентлари бир хил ўрилишга, рангга ва таркибга эга матодан тайёрланган бўлиши керак; шунингдек, улар бир хил фасонга ва мувофиқ ёки мос келувчи ўлчамда бўлиши лозим. Бироқ, бу компонентларда бошқа матодан кант (чокка киритилиб тикилган мато бўлакчаси) мавжуд бўлиши мумкин. Агар тананинг пастки қисми учун мўлжалланган кийимнинг бир нечта алоҳида предметлари (масалан, икки жуфт шим ёки шим ва шорти, ёхуд юбка ёки юбка-шим ва шим) биргаликда тақдим этилса, бундай ҳолда костюмнинг танани пастки қисми учун мўлжалланган компоненти бўлиб, бир жуфт шим ёки аёллар костюми ёки қизлар учун"]},"63":{"title":"БОШҚА ТАЙЁР ТЎҚИМАЧИЛИК БУЮМЛАРИ; ТЎПЛАМЛАР; АВВАЛ ИШЛАТИЛГАН КИЙИМ-","section":"XI","notes":["1. I кичик гуруҳга фақат ҳар қандай тўқимачилик материалидан тайёрланган тайёр буюмлар киритилади.","2. I кичик гуруҳга қуйидагилар киритилмайди: (а) 56–62-гуруҳларининг товарлари; ёки (б) аввал ишлатилган кийим-кечаклар ёки 6309 товар позициясининг аввал ишлатилган бошқа буюмлари.","3. 6309 товар позициясига фақат қуйидаги товарлар киритилади: а) тўқимачилик материалларидан тайёрланган буюмлар: (i) кийим-кечаклар ва кийим жиҳозлари ҳамда уларнинг қисмлари; (ii) одеяллар ва саёҳат пледлари; (iii) ётоқхона, ошхона, ювиниш-тараниш ва ошхона бельёлари (чойшаб, ёстиқ жилд, сочиқ, дастурхон ва ҳ.к.); (iv) безак буюмлари, 5701–5705 товар позицияларининг гиламлари ва 5805 товар позициясининг қўлда тўқилган гобеленлари бундан мустасно; (б) асбестдан бошқа ҳар қандай материалдан ясалган пойабзал ва бош кийимлар. Юқорида қайд этилган буюмлар мазкур товар позициясига киритилиши учун қуйидаги иккита талабга жавоб беришлари керак: (i) сезиларли эскириш белгиларига эга бўлиши керак ва (i) айқаш-уйқаш тўкилган ҳолда ёки бўхчаларда, қопларда ёки аналогик қадоқларда етказиб берилиши керак. Субпозицияга изоҳ:","1. 6304 20 субпозициясига альфа-сиперметрин (ISO), хлорфенапир (ISO), дельтаметрин (INN, ISO), ламбда-цигалотрин (ISO), перметрин (ISO) ёки пиримифос-метил (ISO) шимдирилган ёки қопланган асоси тўқилган тўқимачилик матолари киритилади."],"excl":["2. I кичик гуруҳга қуйидагилар киритилмайди: (а) 56–62-гуруҳларининг товарлари; ёки (б) аввал ишлатилган кийим-кечаклар ёки 6309 товар позициясининг аввал ишлатилган бошқа буюмлари."]},"64":{"title":"ПОЙАБЗАЛ, ГЕТР ВА ШУНГА ЎХШАШ МАҲСУЛОТЛАР; УЛАРНИНГ ҚИСМЛАРИ","section":"XII","notes":["1. Ушбу гуруҳга қуйидагилар киритилмайди: (а) таглиги бириктирилмаган бардошли бўлмаган материаллардан (масалан, қоғоз, пластмасса, плёнкалар) бир марта ишлатиладиган оёқ ёки пойабзал қопламалари; (б) тагликлари ёпиштирилмаган, тикилган ёки устки қисмига бошқа тарзда бириктирилмаган тўқимачилик материалларидан ясалган пойабзаллар (XI бўлим); (в) 6309-товар позициясидаги илгари ишлатилган пойабзаллар; (г) асбестдан тайёрланган буюмлар (6812-позициядаги); (д) ортопедик пойабзал ёки бошқа ортопедия асбоблари ёки уларнинг бутловчилари ёки қисмлари (9021-позиция); ёки (е) ўйинчоқ пойабзаллар ёки муз ёки конки билан боғланган этиклар; болдирларни ҳимоя қилувчи ёки шунга ўхшаш спорт ҳимоя воситалари (95-гуруҳ).","2. 6406-товар позициясидаги “қисмлар” атамаси дублонлар, ҳимоячилар, ҳалқалар, илгаклар, токалар, безаклар, дантеллар, тўрлар, помпонлар ёки бошқа безаклар (уларнинг тегишли товар позицияларига киритиладиганлари) ёки тугмачаларга ёки 9606-товар позициясининг бошқа буюмларига. тааллуқли эмас.","3. Мазкур гуруҳда: (а) “резина” ва “пластмасса” атамалари, шунингдек, ташқи томони каучук ёки пластмассадан иборат матолар ёки бошқа тўқимачилик материалларини англатади; бунда кейинги ранглардаги ўзгариш ҳисобга олинмайди; ва (б) “чарм” атамаси 4107- ва 4112-4114-товар позицияларидаги товарларга нисбатан айтилади.","4. Ушбу бобнинг 3 изоҳ қоидаларига риоя қилган ҳолда: (а) пойабзалнинг устки материаллари сифатида қавслар, декоратив деталлар, қисқичлар, илмоқлар, ёки шунга ўхшаш қурилмалар каби аксессуарлар ёки арматураларсиз бўлган энг катта ташқи сирт майдонига эга бўлган материаллар ҳисобланади; (б) Пойабзалнинг таглиги ишлаб чиқариладиган асосий материал замин билан алоқа қиладиган энг катта сирт майдонига эга бўлган материал ҳисобланади, аксессуар ёки арматура, масалан, тиргаклар, жантлар, михлар, процессорлар ва шунга ўхшаш буюмлар бундан мустасно. Подсубпозицияларга изоҳлар:","1. 6402 12, 6402 19, 6403 12, 6403 19 ва 6404 11-субпозицияландаги “спорт пойабзали” атамаси фақат: (а) спорт билан шуғулланиш учун мўлжалланган шкипли, тиргакли, тиқинли, қисқичли, жантли ва шунга ўхшаш мосламалари бўлган ёки тиқинлар, пинлар, қисқичлар, жантлар ёки шунга ўхшаш қурилмаларни бириктириш учун мўлжалланган пойабзаллар; С (б) конки ботинкалари, чанғи ботинкалари ва югурув чанғи ботинкалари, сноуборд ботинкалари, кураш, бокс ва велоспорт пойабзаллари."],"excl":["1. Ушбу гуруҳга қуйидагилар киритилмайди: (а) таглиги бириктирилмаган бардошли бўлмаган материаллардан (масалан, қоғоз, пластмасса, плёнкалар) бир марта ишлатиладиган оёқ ёки пойабзал қопламалари; (б) тагликлари ёпиштирилмаган, тикилган ёки устки қисмига бошқа тарзда бириктирилмаган тўқимачилик материалларидан ясалган пойабзаллар (XI бўлим); (в) 6309-товар позициясидаги илгари ишлатилган пойабзаллар; (г) асбестдан тайёрланган буюмлар (6812-позициядаги); (д) ортопедик пойабзал ёки бошқа ортопедия асбоблари ёки уларнинг бутловчилари ёки қисмлари (9021-позиция); ёки (е) ўйинчоқ пойабзаллар ёки муз ёки конки билан боғланган этиклар; болдирларни ҳимоя қилувчи ёки шунга ўхшаш спорт ҳимоя воситалари (95-гуруҳ).","2. 6406-товар позициясидаги “қисмлар” атамаси дублонлар, ҳимоячилар, ҳалқалар, илгаклар, токалар, безаклар, дантеллар, тўрлар, помпонлар ёки бошқа безаклар (уларнинг тегишли товар позицияларига киритиладиганлари) ёки тугмачаларга ёки 9606-товар позициясининг бошқа буюмларига. тааллуқли эмас."]},"65":{"title":"БОШ КИЙИМЛАР ВА УЛАРНИНГ ҚИСМЛАРИ","section":"XII","notes":["1. Мазкур гуруҳга қуйидагилар кирмайди: (а) 6309-товар позициясидаги муқаддам фойдаланилган бош кийимлар; (б) асбестдан бош кийимлар (6812-товар позицияси); ёки (в) қўғирчоқлар учун шляпалар, 95-гуруҳнинг бошқа ўйинчоқ бош кийимлари ёки карнавал буюмлари.","2. Тикилган шляпа ярим фабрикатлари, чизиқларни спирал йўли бўйлаб силлиқлаш орқали ишлаб чиқилган шляпа ярим фабрикатларидан ташқари 6502-товар позициясига кирмайди."],"excl":["1. Мазкур гуруҳга қуйидагилар кирмайди: (а) 6309-товар позициясидаги муқаддам фойдаланилган бош кийимлар; (б) асбестдан бош кийимлар (6812-товар позицияси); ёки (в) қўғирчоқлар учун шляпалар, 95-гуруҳнинг бошқа ўйинчоқ бош кийимлари ёки карнавал буюмлари.","2. Тикилган шляпа ярим фабрикатлари, чизиқларни спирал йўли бўйлаб силлиқлаш орқали ишлаб чиқилган шляпа ярим фабрикатларидан ташқари 6502-товар позициясига кирмайди."]},"66":{"title":"СОЯБОНЛАР, ҚУЁШ СОЯБОНЛАРИ, ҲАССА, ҲАССА-ЎРИНДИҚЛАР, МИНИШ УЧУН ҚАМЧИ,","section":"XII","notes":["1. Мазкур гуруҳга қуйидагилар кирмайди: (а) ўлчов ҳассалари ва шунга ўхшаш буюмлар (9017-товар позицияси); (б) ёки шунга ўхшаш нарсалар билан тўлдирилган, ўқотар қуролли, шпага қўйиладиган, қўрғошиндан қуйилган ҳассалар ва шунга ўхшаш буюмлар (93-гуруҳ); ёки (в) 95-гуруҳ товарлари (масалан, ўйинчоқ соябонлар, ўйинчоқ қуёш соябонлари).","2. 6603-товар позицияга тўқимачилик материаллардан безак қисмлари ёки жиҳозлари, шунингдек, ҳар қандай материаллардан қопламалар, мўйқаламлар, камарлар, соябон қутилари ёки шунга ўхшаш буюмлар кирмайди. Шунга ўхшаш товарлар, 6601- ёки 6602-товар позиция буюмлари билан бирга, аммо уларга маҳкамланмаган ҳолда тақдим этилганда, улар алоҳида таснифланади ва ушбу товарларнинг ажралмас қисми сифатида кўрилмайди. Позиция номи ўлчов Код"],"excl":["1. Мазкур гуруҳга қуйидагилар кирмайди: (а) ўлчов ҳассалари ва шунга ўхшаш буюмлар (9017-товар позицияси); (б) ёки шунга ўхшаш нарсалар билан тўлдирилган, ўқотар қуролли, шпага қўйиладиган, қўрғошиндан қуйилган ҳассалар ва шунга ўхшаш буюмлар (93-гуруҳ); ёки (в) 95-гуруҳ товарлари (масалан, ўйинчоқ соябонлар, ўйинчоқ қуёш соябонлари).","2. 6603-товар позицияга тўқимачилик материаллардан безак қисмлари ёки жиҳозлари, шунингдек, ҳар қандай материаллардан қопламалар, мўйқаламлар, камарлар, соябон қутилари ёки шунга ўхшаш буюмлар кирмайди. Шунга ўхшаш товарлар, 6601- ёки 6602-товар позиция буюмлари билан бирга, аммо уларга маҳкамланмаган ҳолда тақдим этилганда, улар алоҳида таснифланади ва ушбу товарларнинг ажралмас қисми сифатида кўрилмайди. Позиция номи ўлчов Код"]},"67":{"title":"ИШЛОВ БЕРИЛГАН ПАТЛАР ВА ПАРЛАР ВА ПАТ ЁКИ ПАРЛАРДАН ТАЙЁРЛАНГАН МАҲСУЛОТЛАР,","section":"XII","notes":["1. Мазкур гуруҳга қуйидагилар кирмайди: (а) инсон сочларидан бўлган фильтрловчи матолар (5911-товар позицияси); (б) тўр, кашта ёки ўсимлик нақшли бошқа тўқимачилик материаллари (XI бўлим); (в) пойабзал (64-гуруҳ); (г) бош кийимлар ёки соч тўрлари (65-гуруҳ); (д) ўйинчоқлар, спорт анжомлари ёки карнавал учун буюмлар (95-гуруҳд); ёки (е) патлардан супургилар, упа учун парлар ёки соч учун тўрлар (96-гуруҳ).","2. 6701 товар позицияга қуйидагилар кирмайди: (а) патлар ёки парлар фақат тўлдирувчи сифатида ишлатиладиган маҳсулотлар (масалан, 9404-позициядаги ётоқ анжомлари) (б) патлар ёки парлар фақат пардоз ёки тўлдирувчи сифатида ишлатиладиган кийим-кечаклар ёки кийим-кечак анжомлари ёки (в) сунъий гул ёки барглар ёки уларнинг қисмлари ёки 6702-товар позициясидаги тайёр маҳсулотлари","3. 6702-товар позицияга қуйидагилар кирмайди: (а) шишадан бўлган буюмлар (70-гуруҳ) ёки (б) қуйиш, болғалаш, ўймакорлик, штамплаш ёки бошқа йўл билан бутун маҳсулот сифатида олинган ёки тўқиш, елимлаш, йиғиш ва ўхшаш усуллардан ташқари бошқа усулда бириктирилган ва қисмлардан иборат бўлган чинни, тош, металл, ёғоч ёки бошқа материаллардан сунъий гуллар, барглар ёки мевалар."],"excl":["1. Мазкур гуруҳга қуйидагилар кирмайди: (а) инсон сочларидан бўлган фильтрловчи матолар (5911-товар позицияси); (б) тўр, кашта ёки ўсимлик нақшли бошқа тўқимачилик материаллари (XI бўлим); (в) пойабзал (64-гуруҳ); (г) бош кийимлар ёки соч тўрлари (65-гуруҳ); (д) ўйинчоқлар, спорт анжомлари ёки карнавал учун буюмлар (95-гуруҳд); ёки (е) патлардан супургилар, упа учун парлар ёки соч учун тўрлар (96-гуруҳ).","2. 6701 товар позицияга қуйидагилар кирмайди: (а) патлар ёки парлар фақат тўлдирувчи сифатида ишлатиладиган маҳсулотлар (масалан, 9404-позициядаги ётоқ анжомлари) (б) патлар ёки парлар фақат пардоз ёки тўлдирувчи сифатида ишлатиладиган кийим-кечаклар ёки кийим-кечак анжомлари ёки (в) сунъий гул ёки барглар ёки уларнинг қисмлари ёки 6702-товар позициясидаги тайёр маҳсулотлари","3. 6702-товар позицияга қуйидагилар кирмайди: (а) шишадан бўлган буюмлар (70-гуруҳ) ёки (б) қуйиш, болғалаш, ўймакорлик, штамплаш ёки бошқа йўл билан бутун маҳсулот сифатида олинган ёки тўқиш, елимлаш, йиғиш ва ўхшаш усуллардан ташқари бошқа усулда бириктирилган ва қисмлардан иборат бўлган чинни, тош, металл, ёғоч ёки бошқа материаллардан сунъий гуллар, барглар ёки мевалар."]},"68":{"title":"ТОШ, ГИПС, ЦЕМЕНТ, АСБЕСТ, СЛЮДА ЁКИ ЎХШАШ МАТЕРИАЛЛАРДАН ТАЙЁРЛАНГАН БУЮМЛАР","section":"XIII","notes":["1. Мазкур гуруҳга қуйидагилар киритилмайди: (а) 25-гуруҳнинг товарлари; (б) 4810- ёки 4811-товар позициясининг шимдирилган ёки қопламали қоғози ва картони (масалан, слюда ёки графит кукуни билан қопланган, битумлаштирилган ёки асфальтлаштирилган қоғоз ва картон); (в) 56- ёки 59-гуруҳнинг шимдирилган ёки қопланган тўқимачилик матолари (масалан, слюда кукуни билан қопланган, битумли ёки асфальтланган мато); (г) 71-гуруҳнинг буюмлари; (д) 82-гуруҳнинг асбоблари ёки уларнинг қисмлари; (е) 8442-товар позициясининг литографик тошлари; (ж) электр изоляторлар (8546-товар позицияси) ёки 8547-товар позициясининг изоляцион материалларидан арматуралар; (з) тиш бурғилари (9018-товар позицияси); (и) 91-гуруҳнинг буюмлари (масалан, ўзида ва ўзи билан олиб юриш учун мўлжалланмаган соатлар ва улар учун корпуслар); (к) 94-гуруҳнинг буюмлари (масалан, мебель, чироқлар ва ёритиш ускуналари, йиғма қурилиш конструкциялари); (л) 95-гуруҳнинг буюмлари (масалан, ўйинчоқлар, ўйинлар ва спорт инвентари); (м) 96-гуруҳнинг 2(б)-изоҳида кўрсатилган материаллардан тайёрланган 9602-товар позициясининг буюмлари, ёки 9606-товар позициясининг буюмлари (масалан, тугмалар), 9609-товар позициясининг буюмлари (масалан, қаламларнинг грифеллари), 9610-товар позициясининг буюмлари (масалан, грифель тахталар) ёки 9620-товар позициясининг буюмлари (масалан, якка таянчлилар, икки оёқлилар, уч оёқлилар ва шу каби буюмлар); ёки (н) 97-гуруҳнинг буюмлари (масалан, санъат асарлари)","2. 6802-товар позициясида “ёдгорлик ёки қурилиш учун ишлов берилган тош” термини нафақат 2515- ёки 2516-товар позициясининг турли тошларини, балки шу каби тарзда ишлов берилган табиий тошларнинг барча турларини (масалан, кварцит, кремень, доломит ва стеатит) англатади, сланцдан ташқари."],"excl":["1. Мазкур гуруҳга қуйидагилар киритилмайди: (а) 25-гуруҳнинг товарлари; (б) 4810- ёки 4811-товар позициясининг шимдирилган ёки қопламали қоғози ва картони (масалан, слюда ёки графит кукуни билан қопланган, битумлаштирилган ёки асфальтлаштирилган қоғоз ва картон); (в) 56- ёки 59-гуруҳнинг шимдирилган ёки қопланган тўқимачилик матолари (масалан, слюда кукуни билан қопланган, битумли ёки асфальтланган мато); (г) 71-гуруҳнинг буюмлари; (д) 82-гуруҳнинг асбоблари ёки уларнинг қисмлари; (е) 8442-товар позициясининг литографик тошлари; (ж) электр изоляторлар (8546-товар позицияси) ёки 8547-товар позициясининг изоляцион материалларидан арматуралар; (з) тиш бурғилари (9018-товар позицияси); (и) 91-гуруҳнинг буюмлари (масалан, ўзида ва ўзи билан олиб юриш учун мўлжалланмаган соатлар ва улар учун корпуслар); (к) 94-гуруҳнинг буюмлари (масалан, мебель, чироқлар ва ёритиш ускуналари, йиғма қурилиш конструкциялари); (л) 95-гуруҳнинг буюмлари (масалан, ўйинчоқлар, ўйинлар ва спорт инвентари); (м) 96-гуруҳнинг 2(б)-изоҳида кўрсатилган материаллардан тайёрланган 9602-товар позициясининг буюмлари, ёки 9606-товар позициясининг буюмлари (масалан, тугмалар), 9609-товар позициясининг буюмлари (масалан, қаламларнинг грифеллари), 9610-товар позициясининг буюмлари (масалан, грифель тахталар) ёки 9620-товар позициясининг буюмлари (масалан, якка таянчлилар, икки оёқлилар, уч оёқлилар ва шу каби буюмлар); ёки (н) 97-гуруҳнинг буюмлари (масалан, санъат асарлари)","2. 6802-товар позициясида “ёдгорлик ёки қурилиш учун ишлов берилган тош” термини нафақат 2515- ёки 2516-товар позициясининг турли тошларини, балки шу каби тарзда ишлов берилган табиий тошларнинг барча турларини (масалан, кварцит, кремень, доломит ва стеатит) англатади, сланцдан ташқари."]},"69":{"title":"КЕРАМИКА БУЮМЛАР","section":"XIII","notes":["1. Ушбу гуруҳга фақат шакл берилгандан кейин пиширилган керамика буюмлари киритилади: (а) 6904 – 6914-товар позицияларига фақат шундай буюмлар киритиладики, улар 6901 – 6903-товар позицияларига киритилмайди; (б) қатронни қаттиқлаштириш, гидратация реакциясини тезлаштириш мақсадида ёки сувни ёки бошқа учувчи компонентларни таркибдан чиқариб ташлаш учун 800 С дан паст ҳароратгача қиздирилган буюмлар пиширилган ҳисобланмайди. Бундай маҳсулотлар 69-гуруҳдан чиқариб ташланади; ва (в) одатда, хона ҳароратида аввалдан тайёрланган ва шакл берилган ноорганик металл бўлмаган материалларни қиздириш натижасида олинган керамика буюмлар. Хомашё материалларига, inter alia, лой, таркибида кремний оксиди бўлган материаллар, шу жумладан эритилган кремний оксиди, юқори эриш ҳароратига эга материаллар, яъни оксидлар, карбидлар, нитридлар, графит ёки углероднинг бошқа шакллари каби ва баъзи ҳолларда оловга чидамли лой ёки фосфатлар каби боғловчи моддалар киради.","2. Ушбу гуруҳга қуйидагилар киритилмайди: (а) 2844-товар позициясининг товарлари; (б) 6804-товар позициясининг буюмлари; (в) 71-гуруҳнинг буюмлари (масалан, бижутерия); (г) 8113-товар позициясининг метаоллокерамикаси; (д) 82-гуруҳ буюмлари; (е) электр изоляторлари (8546-товар позицияси) ёки 8547-товар позициясининг изоляцион материаллардан арматуралар; (ж) сунъий тишлар (9021-товар позицияси); (з) 91-гуруҳнинг буюмлари (масалан, ўзида ва ўзи билан олиб юриш учун мўлжалланмаган соатлар ва улар учун корпуслар); (и) 94-гуруҳнинг буюмлари (масалан, мебель, чироқлар ва ёритиш ускуналари, йиғма қурилиш конструкциялари); (к) 95-гуруҳнинг буюмлари (масалан, ўйинчоқлар, ўйинлар ва спорт инвентари); (л) 9606-товар позициясининг буюмлари (масалан, тугмалар) ёки 9614-товар позициясининг буюмлари (масалан, чекиш трубкалари); ёки (м) 97-гуруҳнинг буюмлари (масалан, санъат асарлари)."],"excl":["1. Ушбу гуруҳга фақат шакл берилгандан кейин пиширилган керамика буюмлари киритилади: (а) 6904 – 6914-товар позицияларига фақат шундай буюмлар киритиладики, улар 6901 – 6903-товар позицияларига киритилмайди; (б) қатронни қаттиқлаштириш, гидратация реакциясини тезлаштириш мақсадида ёки сувни ёки бошқа учувчи компонентларни таркибдан чиқариб ташлаш учун 800 С дан паст ҳароратгача қиздирилган буюмлар пиширилган ҳисобланмайди. Бундай маҳсулотлар 69-гуруҳдан чиқариб ташланади; ва (в) одатда, хона ҳароратида аввалдан тайёрланган ва шакл берилган ноорганик металл бўлмаган материалларни қиздириш натижасида олинган керамика буюмлар. Хомашё материалларига, inter alia, лой, таркибида кремний оксиди бўлган материаллар, шу жумладан эритилган кремний оксиди, юқори эриш ҳароратига эга материаллар, яъни оксидлар, карбидлар, нитридлар, графит ёки углероднинг бошқа шакллари каби ва баъзи ҳолларда оловга чидамли лой ёки фосфатлар каби боғловчи моддалар киради.","2. Ушбу гуруҳга қуйидагилар киритилмайди: (а) 2844-товар позициясининг товарлари; (б) 6804-товар позициясининг буюмлари; (в) 71-гуруҳнинг буюмлари (масалан, бижутерия); (г) 8113-товар позициясининг метаоллокерамикаси; (д) 82-гуруҳ буюмлари; (е) электр изоляторлари (8546-товар позицияси) ёки 8547-товар позициясининг изоляцион материаллардан арматуралар; (ж) сунъий тишлар (9021-товар позицияси); (з) 91-гуруҳнинг буюмлари (масалан, ўзида ва ўзи билан олиб юриш учун мўлжалланмаган соатлар ва улар учун корпуслар); (и) 94-гуруҳнинг буюмлари (масалан, мебель, чироқлар ва ёритиш ускуналари, йиғма қурилиш конструкциялари); (к) 95-гуруҳнинг буюмлари (масалан, ўйинчоқлар, ўйинлар ва спорт инвентари); (л) 9606-товар позициясининг буюмлари (масалан, тугмалар) ёки 9614-товар позициясининг буюмлари (масалан, чекиш трубкалари); ёки (м) 97-гуруҳнинг буюмлари (масалан, санъат асарлари)."]},"70":{"title":"ШИША ВА ШИШАДАН ТАЙЁРЛАНГАН БУЮМЛАР","section":"XIII","notes":["1. Ушбу гуруҳга қуйидагилар киритилмайди: (а) 3207-товар позициясининг товарлари (масалан, шишасимон эмаллар ва сирлар (глазурь), шишасимон фритлар, бошқа шишаларнинг кукуни, гранулалари ёки пағасимон парчалари); (б) 71-гуруҳ буюмлари (масалан, бижутерия); (в) 8544-товар позициясининг оптик толали кабеллари, электр изоляторлари (8546-товар позицияси) ёки 8547-товар позициясининг изоляцион материалларидан арматуралар; (г) 86 – 88-гуруҳлар транспорт воситалари учун олдинги шамолга қарши ойналар, орқа ва бошқа ойналар, рамкага ўрнатилган; (д) 86 – 88-гуруҳлар транспорт воситалари учун олдинги шамолга қарши ойналар, орқа ва бошқа ойналар, рамкага ўрнатилган ёки ўрнатилмаган, таркибида иситиш ёки бошқа электр ёки электрон қурилмаларни ўз ичига олган; (е) оптик толалар, оптик қайта ишланган оптик элементлар, тери ости инъекцияси учун шприцлар, сунъий кўзлар, термометрлар, барометрлар, гидрометрлар ёки 90-гуруҳнинг бошқа буюмлари; (ж) 9405-товар позициясининг чироқлари ва ёритиш ускуналари, ёруғликли вивескалар, исм ёки ном ёки манзил кўрсатилган ёруғликли табличкалар ёки ўрнатилган ёруғлик манбаига эга шу каби буюмлар ёки уларнинг қисмлари; (з) ўйинчоқлар, ўйинлар, спорт инвентари, янги йил арча безаклари ёки 95-гуруҳнинг бошқа товарлари (қўғирчоқлар учун ёки 95-гуруҳнинг бошқа буюмлари учун мўлжалланган механизмсиз шиша кўзлар бундан мустасно); ёки (и) тугмалар, йиғилган ҳолатдаги вакуум идишлар, чанглатгичлар ёки шу каби пуркагичлар ёки 96-гуруҳнинг бошқа буюмлари.","2. 7003-, 7004- ва 7005- товар позицияларида: (а) қандай жараёнлардан ўтган бўлишидан қатъи назар термик ишлов берилгунга қадар шиша “ишлов берилган” деб ҳисобланмайди; (б) шишани шаклга солиб кесиш уни лист шаклидаги шиша сифатида таснифланишини ўзгартирмайди; (в) “ютувчи, қайтарувчи ёки қайтармайдиган қатлам” атамаси, масалан, инфрақизил нурланишни ютадиган ёки шишанинг шаффофлик ёки ўтказувчанлик даражасини сақлаб қолган ҳолда унинг қайтариш хусусиятини яхшилайдиган металл ёки кимёвий бирикманинг (масалан, металл оксиди) микроскопик юпқа қопламасини англатади.","3. 7006-товар позициясига киритиладиган буюмлар, улар тайёр буюм хусусиятига эга бўлган тақдирда ҳам шу товар позициясига киритилади.","4. 7019-товар позициясидаги “шиша вата” атамаси: (а) таркибида кремний оксиди (SiO )60 мас.% дан кам бўлмаган минерал ватани; (б) таркибида кремний оксиди(SiO )60 мас.% дан кам, ишқорли металл оксиди (К О ёки 2 2 Nа О) 5 мас.% дан ортиқ ёки бор оксиди (Б О ) 2 мас.% дан ортиқ бўлган минерал ватани 2 2 3 англатади. Минерал ватанинг бошқа турлари 6806-товар позициясига киритилади.","5. Бутун номенклатурада “шиша” атамаси эритилган кварц ва бошқа эритилган кремнозёмларни англатади. Субпозицияларга изоҳ:","1. 7013 22, 7013 33, 7013 41 ва 7013 91-субпозицияларда “қўрғошинли хрусталь” атамаси фақат таркибидаги қўрғошин моноксидининг (PbO) миқдори 24 мас.% дан кам бўлмаган шишани англатади."],"excl":["1. Ушбу гуруҳга қуйидагилар киритилмайди: (а) 3207-товар позициясининг товарлари (масалан, шишасимон эмаллар ва сирлар (глазурь), шишасимон фритлар, бошқа шишаларнинг кукуни, гранулалари ёки пағасимон парчалари); (б) 71-гуруҳ буюмлари (масалан, бижутерия); (в) 8544-товар позициясининг оптик толали кабеллари, электр изоляторлари (8546-товар позицияси) ёки 8547-товар позициясининг изоляцион материалларидан арматуралар; (г) 86 – 88-гуруҳлар транспорт воситалари учун олдинги шамолга қарши ойналар, орқа ва бошқа ойналар, рамкага ўрнатилган; (д) 86 – 88-гуруҳлар транспорт воситалари учун олдинги шамолга қарши ойналар, орқа ва бошқа ойналар, рамкага ўрнатилган ёки ўрнатилмаган, таркибида иситиш ёки бошқа электр ёки электрон қурилмаларни ўз ичига олган; (е) оптик толалар, оптик қайта ишланган оптик элементлар, тери ости инъекцияси учун шприцлар, сунъий кўзлар, термометрлар, барометрлар, гидрометрлар ёки 90-гуруҳнинг бошқа буюмлари; (ж) 9405-товар позициясининг чироқлари ва ёритиш ускуналари, ёруғликли вивескалар, исм ёки ном ёки манзил кўрсатилган ёруғликли табличкалар ёки ўрнатилган ёруғлик манбаига эга шу каби буюмлар ёки уларнинг қисмлари; (з) ўйинчоқлар, ўйинлар, спорт инвентари, янги йил арча безаклари ёки 95-гуруҳнинг бошқа товарлари (қўғирчоқлар учун ёки 95-гуруҳнинг бошқа буюмлари учун мўлжалланган механизмсиз шиша кўзлар бундан мустасно); ёки (и) тугмалар, йиғилган ҳолатдаги вакуум идишлар, чанглатгичлар ёки шу каби пуркагичлар ёки 96-гуруҳнинг бошқа буюмлари."]},"71":{"title":"ТАБИИЙ ЁКИ СУНЪИЙ ЕТИШТИРИЛГАН МАРВАРИД, ҚИММАТБАҲО ЁКИ ЯРИМ ҚИММАТБАҲО","section":"XIV","notes":["1. VI бўлимга тегишли 1 (А) изоҳ талабларига ва қуйида келтирилган истисноларга риоя қилган ҳолда, ушбу гуруҳга тўлиқ ёки қисман иборат барча буюмлар киради: (а) табиий ёки сунъий равишда етиштирилган марваридлар ёки қимматбаҳо ёки ярим қимматбаҳо тошлар (табиий, сунъий ёки реконструкция қилинган) ёки (б) қимматбаҳо металлар ёки қимматбаҳо металлар билан қопланган.","2. (А) 7113, 7114 ва 7115-товар позицияларига қуйидаги буюмлар кирмайди: таркибида қимматбаҳо металл ёки қимматбаҳо металл билан қопланган металл фақат иккинчи даражали таркиб сифатида мавжуд бўлганида, яъни майда фурнитура ёки иккиламчи пардоз (масалан, монограммалар, гардишлар, ҳошиялар) ҳамда ушбу буюмларга 1 (б) изоҳ талаблари татбиқ этилмайди. (Б) 7116-товар позициясига таркибида қимматбаҳо металлар ёки қимматбаҳо металлар билан қопланган металлар бўлган (майда таркибий қисмлардан ташқари) буюмлар кирмайди.","3. Бу гуруҳ ўз ичига олмайди: (а) коллоид ҳолатидаги қимматбаҳо металлар ёки қимматбаҳо металларнинг амальгамалари (2843-товар позицияси); (б) жарроҳлик чоклари, тиш пломбалари ёки 30-гуруҳ буюмларига кирувчи бошқа стерилланган материаллар; (в) 32-гуруҳ буюмлари (масалан, силлиқ, ялтироқ); (г) ташувчи катализаторлар (3815-товар позицияси); (д) 4202 ёки 4203-товар позициясига кирувчи буюмлар (42-гуруҳга кирувчи 3 (Б) изоҳга қаралсин); (е) 4303 ёки 4304-товар позициясига кирувчи буюмлар; (ж) XI бўлим маҳсулотлари (тўқимачилик буюмлари ва тўқимачилик материаллари); (з) 64 ёки 65 гуруҳи буюмларига кирувчи пойабзал, бош кийимлари ёки бошқа буюмлар; (и) соябонлар, ҳассалар ёки 66-гуруҳнинг бошқа буюмлари; (к) қимматбаҳо ёки ярим қимматбаҳо (табиий ёки сунъий) тошларнинг кичик бўлаги ёки кукунидан таркиб топган 6804 ёки 6805-товар позициясидаги абразив материаллари ёки 82-гуруҳ буюмларига кирувчи ишчи қисми қимматбаҳо ёки ярим қимматбаҳо тошлардан (табиий, сунъий ёки реконструкция қилинган) буюмлар; XVI бўлимига оид машиналар, ускуналар, механизмлар, электр товарлари ёки уларнинг қисмлари. Лекин, тўлиқ қимматбаҳо ёки ярим қимматбаҳо тошлардан (табиий, сунъий ёки реконструкция қилинган) буюмлар ва уларнинг қисмлари ушбу бобга тааллуқли, овозни етказувчи игналар учун ўрнатилмаган ишлов берилган сапфирлар ва олмослар бундан мустасно (8522-товар позицияси); (л) 90, 91 ёки 92-гуруҳ буюмлари (илмий асбоблар, барча турдаги соатлар, мусиқа асбоблари); (м) қурол ёки унинг қисмлари (93-гуруҳ); (н) 95-гуруҳига кирувчи 2- изоҳда кўрсатилган буюмлар; (о) 96-гуруҳи буюмлари, ёки 4- изоҳга мувофиқ 96-гуруҳга тааллуқли буюмлар; ёки (п) асл ҳайкалтарошликлар ёки ҳайкалчалар (9703-товар позицияси), коллекция буюмлари (9705-товар позицияси) ёки ёши юз ёшдан ошган антиквар буюмлар (9706-товар позицияси), табиий ёки сунъий равишда етиштирилган марваридлар, қимматбаҳо ёки ярим қимматбаҳо тошлардан ташқари.","4. (А) “Қимматбаҳо металл” атамаси кумуш, олтин ва платина деган маънони англатади. (Б) “Платина” атамаси платина, иридий, осмий, палладий, родий ва рутенийни англатади. (В) “Қимматбаҳо ёки ярим қимматбаҳо тошлар” атамаси 96-гуруҳига кирувчи 2(б) изоҳда кўрсатилган материалларга тааллуқли эмас.","5. Ушбу гуруҳдаги таркибида қимматбаҳо металл бўлган ҳар қандай қотишмани (агломерирланган аралашма ва интерметалл бирикмалар билан биргаликда), агар қимматбаҳо металлнинг қотишма таркибидаги оғирлик нисбати 2% дан кам бўлмаса, қимматбаҳо металл қотишмаси деб ҳисоблаш мумкин. Қимматбаҳо металлар қотишмалари қуйидаги қоидаларга мувофиқ таснифланади: (а) таркибида оғирлик нисбати 2% ва ундан ортиқ платина бўлган қотишма – платина қотишмаси сифатида; (б) таркибида оғирлик нисбати 2% ёки ундан ортиқ олтин бўлган, лекин платина бўлмаган ёки оғирлик нисбати 2 % дан кам бўлган қотишма – олтин қотишмаси сифатида; (в) таркибида оғирлик нисбати 2% ёки ундан ортиқ кумуш бўлган бошқа қотишмалар – кумуш қотишмалари сифатида.","6. Агар контекстда бошқача қоида назарда тутилмаган бўлса, Номенклатурадаги қимматбаҳо металларга ёки муайян қимматбаҳо металлга ҳар қандай ҳавола юқоридаги 5- изоҳда кўрсатилган қоидаларга мувофиқ, қимматбаҳо металларнинг ёки муайян металл қотишмаларига ҳаволани ўз ичига олади. Аммо, бу қимматбаҳо металлар билан қопланган металларга, гальваник усулда қимматбаҳо металл билан қопланган ноқимматбаҳо металлар ёки нометалларга тааллуқли эмас.","7. Бутун Номенклатурада “қимматбаҳо металл билан қопланган металл” атамаси, металл асосида тайёрланган кавшарлаш, пайвандлаш, иссиқ ҳолда прокатка қилиш (жўвалаш, ёйиш) йўли билан ёки шу каби механик усулда бир ёки бир неча сиртларни қимматбаҳо металл билан қопланган материални англатади. Агар контекстда бошқа ҳолат кўрсатилмаган бўлса, бу атама, шунингдек, қимматбаҳо металл билан нақшинкор безак берилган ноқимматбаҳо металларни ҳам англатади.","8. VI бўлимга тегишли 1(А) изоҳ талабларига риоя қилган ҳолатда 7112-товар позициясига кирувчи товарлар таснифига мувофиқ, айнан ушбу товар позициясига киритилиши шарт ва Номенклатуранинг бошқа ҳеч қандай позициясига киритилмайди.","9. 7113-товар позициясидаги “заргарлик буюмлари” атамаси қуйидагиларни билдиради: (а) шахсий зеб-зийнатнинг ҳар қандай кичик буюмлари (масалан, узуклар, билагузуклар (браслетлар), бўйин безаклари, тўғноғичлар, сирғалар, соат учун занжирлар, брелоклар, кулонлар, бўйинбоғ учун қисқичлар, илма тугмалар, диний ёки бошқа медаллар ва нишонлар); ва (б) шахсий фойдаланиш учун, одатда ҳамёнларда, аёллар ёки эркаклар сумкаларида ёки танада олиб юриладиган буюмлар (масалан, портсигарлар, тамакидонлар, таблеткалар учун қутичалар, упадонлар, занжирли ҳамёнлар ёки тасбеҳлар). Ушбу буюмлар, масалан, табиий ёки сунъий равишда етиштирилган марваридлар, қимматбаҳо ёки ярим қимматбаҳо тошлар, сунъий ёки реконструкция қилинган қимматбаҳо ёки ярим қимматбаҳо тошлар, тошбақа косаси, садаф, фил суяги, натурал ёки реконструкция қилинган каҳрабо, гагат ёки корал билан бирлаштирилиши ёки безатилган бўлиши мумкин.","10. 7114-товар позициясидаги “олтин ёки кумуш буюмлари усталарининг иши” атамаси зеб-зийнат, идиш-товоқ, пардоз, чекиш воситалари ва бошқа рўзғор ёки муассаса учун буюмлар ёки диний буюмларни англатади.","11. 7117-товар позициясидаги “бижутерия” атамаси юқорида 9 (а) изоҳда келтирилган заргарлик буюмларини билдиради (9606-позициядаги тугмалар ва бошқа буюмлар ёки 9615-позициядаги тароқлар, ва соч қисқичларидан ташқари) табиий ёки маданий марваридларсиз, қимматбаҳо ёки ярим қимматбаҳо тошларсиз (табиий, сунъий ёки реконструкция қилинган), қимматбаҳо металларсиз ёки қимматбаҳо металлар билан қопланган металларсиз (қимматбаҳо металлар ёки қимматбаҳо металлар билан гальваника усулида қопланган ёки иккиламчи қисмлари қимматбаҳо металлдан ёки қимматбаҳо металл билан қопланган металлни ҳисобга олмаганда). Субпозицияларига изоҳлар:","1. 7106 10, 7108 11, 7110 11, 7110 21, 7110 31 ва 7110 41-субпозициялардаги “кукун” атамаси ва “кукун шаклида” ибораси оғирлик нисбати бўйича 90% ёки ундан кўпроғи 0,5 мм ли элакдан ўтувчи маҳсулотларни билдиради.","2. Ушбу низомнинг 4(Б) изоҳ қоидаларига қарамасдан, ушбу гуруҳнинг 7110 11 ва 7110 19- субпозицияларидаги “платина” атамаси иридий, осмий, палладий, родий ёки рутенийни англатмайди.","3. 7110-позициядаги ҳар бир қотишма платина, палладий, родий, иридий, осмий ёки рутений бўлсин, массаси бўйича устун бўлган металлга кўра таснифланади.","1. Мазкур бўлимга киритилмайди: (а) тайёр бўёқлар, сиёҳ ёки металл қопламалари ёки кукуни асосидаги бошқа буюмлар (3207 – 3210, 3212, 3213 ёки 3215-товар позициялари); (б) ферроцерий ёки пирофор қотишмалар, бошқалари (3606-товар позицияси); (в) 6506 ёки 6507-товар позициясининг бош кийимлари ва уларнинг қисмлари; (г) соябон каркаси ёки 6603-товар позициясининг бошқа буюмлари; (д) 71-гурух товарлари (масалан, қимматбаҳо металлар қотишмалари, қимматбаҳо металлар билан қопланган ноқимматбаҳо металлар, бижутерия); (е) XVI бўлим буюмлари (машиналар, ускуналар, механизмлар ва электр товарлари); (ж) темир йўл ёки трамвай йўлларининг йиғилган звенолари (8608-товар позицияси) ёки XVII бўлимнинг бошқа буюмлари (транспорт воситалари, кемалар ва қайиқлар, учиш аппаратлари); (з) XVIII бўлимнинг асбоблари ёки аппаратураси, шу жумладан соатларнинг барча турлари учун пружиналар; (и) ўқ дорилар учун қўрғошинли питра (9306-товар позицияси) ёки или XIX бўлимнинг бошқа буюмлари (қурол ва ўқ дорилар); (к) 94-гурух буюмлари (масалан, мебель, матрацли асослар, чироқлар ва ёритиш ускуналари, чироқли дарпардалар, йиғма қурилиш конструкциялари); (л) 95-гурух буюмлари (масалан, ўйинчоқлар, ўйинлар, спорт инвентари); (м) қўл элаклари, тугмачалар, хатлар учун ручкалар, қаламлар учун тутқичлар, авторучкалар учун перолар, монотиргаклар, иккиоёқлар, учоёқлар ва шу каби буюмлар ёки 96-гурухнинг бошқа буюмлари (турли тайёр буюмлар); ёки (н) 97-гурух буюмлари (масалан, санъат асарлари).","2. Бутун Номенклатура бўйича “умумий мақсаддаги қисмлар” атамаси қуйидагиларни англатади: (а) 7307, 7312, 7315, 7317 ёки 7318-товар позициясининг буюмлари ва бошқа ноқимматбаҳо металлардан шу каби буюмлар, фақат тиббиётда, жарроҳликда, стоматологияда ёки ветеринарияда қўлланиладиган имплантларда ишлатиш учун махсус мўлжалланган буюмлардан ташқари (9021-товар позицияси); (б) пружиналар, рессорлар ва улар учун ноқимматбаҳо металлардан листлар, барча турдаги соатлар учун пружиналардан ташқари (9114-товар позицияси); ва (в) 8301, 8302, 8308, 8310-товар позицияларининг буюмлари, шунингдек, 8306-товар позициясининг ноқимматбаҳо металлардан ромлари ва кўзгулари."],"excl":["2. (А) 7113, 7114 ва 7115-товар позицияларига қуйидаги буюмлар кирмайди: таркибида қимматбаҳо металл ёки қимматбаҳо металл билан қопланган металл фақат иккинчи даражали таркиб сифатида мавжуд бўлганида, яъни майда фурнитура ёки иккиламчи пардоз (масалан, монограммалар, гардишлар, ҳошиялар) ҳамда ушбу буюмларга 1 (б) изоҳ талаблари татбиқ этилмайди. (Б) 7116-товар позициясига таркибида қимматбаҳо металлар ёки қимматбаҳо металлар билан қопланган металлар бўлган (майда таркибий қисмлардан ташқари) буюмлар кирмайди.","3. Бу гуруҳ ўз ичига олмайди: (а) коллоид ҳолатидаги қимматбаҳо металлар ёки қимматбаҳо металларнинг амальгамалари (2843-товар позицияси); (б) жарроҳлик чоклари, тиш пломбалари ёки 30-гуруҳ буюмларига кирувчи бошқа стерилланган материаллар; (в) 32-гуруҳ буюмлари (масалан, силлиқ, ялтироқ); (г) ташувчи катализаторлар (3815-товар позицияси); (д) 4202 ёки 4203-товар позициясига кирувчи буюмлар (42-гуруҳга кирувчи 3 (Б) изоҳга қаралсин); (е) 4303 ёки 4304-товар позициясига кирувчи буюмлар; (ж) XI бўлим маҳсулотлари (тўқимачилик буюмлари ва тўқимачилик материаллари); (з) 64 ёки 65 гуруҳи буюмларига кирувчи пойабзал, бош кийимлари ёки бошқа буюмлар; (и) соябонлар, ҳассалар ёки 66-гуруҳнинг бошқа буюмлари; (к) қимматбаҳо ёки ярим қимматбаҳо (табиий ёки сунъий) тошларнинг кичик бўлаги ёки кукунидан таркиб топган 6804 ёки 6805-товар позициясидаги абразив материаллари ёки 82-гуруҳ буюмларига кирувчи ишчи қисми қимматбаҳо ёки ярим қимматбаҳо тошлардан (табиий, сунъий ёки реконструкция қилинган) буюмлар; XVI бўлимига оид машиналар, ускуналар, механизмлар, электр товарлари ёки уларнинг қисмлари. Лекин, тўлиқ қимматбаҳо ёки ярим қимматбаҳо тошлардан (табиий, сунъий ёки реконструкция қилинган) буюмлар ва уларнинг қисмлари ушбу бобга тааллуқли, овозни етказувчи игналар учун ўрнатилмаган ишлов берилган сапфирлар ва олмослар бундан мустасно (8522-товар позицияси); (л) 90, 91 ёки 92-гуруҳ буюмлари (илмий асбоблар, барча турдаги соатлар, мусиқа асбоблари); (м) қурол ёки унинг қисмлари (93-гуруҳ); (н) 95-гуруҳига кирувчи 2- изоҳда кўрсатилган буюмлар; (о) 96-гуруҳи буюмлари, ёки 4- изоҳга мувофиқ 96-гуруҳга тааллуқли буюмлар; ёки (п) асл ҳайкалтарошликлар ёки ҳайкалчалар (9703-товар позицияси), коллекция буюмлари (9705-товар позицияси) ёки ёши юз ёшдан ошган антиквар буюмлар (9706-товар позицияси), табиий ёки сунъий равишда етиштирилган марваридлар, қимматбаҳо ёки ярим қимматбаҳо тошлардан ташқари.","4. (А) “Қимматбаҳо металл” атамаси кумуш, олтин ва платина деган маънони англатади. (Б) “Платина” атамаси платина, иридий, осмий, палладий, родий ва рутенийни англатади. (В) “Қимматбаҳо ёки ярим қимматбаҳо тошлар” атамаси 96-гуруҳига кирувчи 2(б) изоҳда кўрсатилган материалларга тааллуқли эмас.","6. Агар контекстда бошқача қоида назарда тутилмаган бўлса, Номенклатурадаги қимматбаҳо металларга ёки муайян қимматбаҳо металлга ҳар қандай ҳавола юқоридаги 5- изоҳда кўрсатилган қоидаларга мувофиқ, қимматбаҳо металларнинг ёки муайян металл қотишмаларига ҳаволани ўз ичига олади. Аммо, бу қимматбаҳо металлар билан қопланган металларга, гальваник усулда қимматбаҳо металл билан қопланган ноқимматбаҳо металлар ёки нометалларга тааллуқли эмас.","8. VI бўлимга тегишли 1(А) изоҳ талабларига риоя қилган ҳолатда 7112-товар позициясига кирувчи товарлар таснифига мувофиқ, айнан ушбу товар позициясига киритилиши шарт ва Номенклатуранинг бошқа ҳеч қандай позициясига киритилмайди.","11. 7117-товар позициясидаги “бижутерия” атамаси юқорида 9 (а) изоҳда келтирилган заргарлик буюмларини билдиради (9606-позициядаги тугмалар ва бошқа буюмлар ёки 9615-позициядаги тароқлар, ва соч қисқичларидан ташқари) табиий ёки маданий марваридларсиз, қимматбаҳо ёки ярим қимматбаҳо тошларсиз (табиий, сунъий ёки реконструкция қилинган), қимматбаҳо металларсиз ёки қимматбаҳо металлар билан қопланган металларсиз (қимматбаҳо металлар ёки қимматбаҳо металлар билан гальваника усулида қопланган ёки иккиламчи қисмлари қимматбаҳо металлдан ёки қимматбаҳо металл билан қопланган металлни ҳисобга олмаганда). Субпозицияларига изоҳлар:","1. Мазкур бўлимга киритилмайди: (а) тайёр бўёқлар, сиёҳ ёки металл қопламалари ёки кукуни асосидаги бошқа буюмлар (3207 – 3210, 3212, 3213 ёки 3215-товар позициялари); (б) ферроцерий ёки пирофор қотишмалар, бошқалари (3606-товар позицияси); (в) 6506 ёки 6507-товар позициясининг бош кийимлари ва уларнинг қисмлари; (г) соябон каркаси ёки 6603-товар позициясининг бошқа буюмлари; (д) 71-гурух товарлари (масалан, қимматбаҳо металлар қотишмалари, қимматбаҳо металлар билан қопланган ноқимматбаҳо металлар, бижутерия); (е) XVI бўлим буюмлари (машиналар, ускуналар, механизмлар ва электр товарлари); (ж) темир йўл ёки трамвай йўлларининг йиғилган звенолари (8608-товар позицияси) ёки XVII бўлимнинг бошқа буюмлари (транспорт воситалари, кемалар ва қайиқлар, учиш аппаратлари); (з) XVIII бўлимнинг асбоблари ёки аппаратураси, шу жумладан соатларнинг барча турлари учун пружиналар; (и) ўқ дорилар учун қўрғошинли питра (9306-товар позицияси) ёки или XIX бўлимнинг бошқа буюмлари (қурол ва ўқ дорилар); (к) 94-гурух буюмлари (масалан, мебель, матрацли асослар, чироқлар ва ёритиш ускуналари, чироқли дарпардалар, йиғма қурилиш конструкциялари); (л) 95-гурух буюмлари (масалан, ўйинчоқлар, ўйинлар, спорт инвентари); (м) қўл элаклари, тугмачалар, хатлар учун ручкалар, қаламлар учун тутқичлар, авторучкалар учун перолар, монотиргаклар, иккиоёқлар, учоёқлар ва шу каби буюмлар ёки 96-гурухнинг бошқа буюмлари (турли тайёр буюмлар); ёки (н) 97-гурух буюмлари (масалан, санъат асарлари).","2. Бутун Номенклатура бўйича “умумий мақсаддаги қисмлар” атамаси қуйидагиларни англатади: (а) 7307, 7312, 7315, 7317 ёки 7318-товар позициясининг буюмлари ва бошқа ноқимматбаҳо металлардан шу каби буюмлар, фақат тиббиётда, жарроҳликда, стоматологияда ёки ветеринарияда қўлланиладиган имплантларда ишлатиш учун махсус мўлжалланган буюмлардан ташқари (9021-товар позицияси); (б) пружиналар, рессорлар ва улар учун ноқимматбаҳо металлардан листлар, барча турдаги соатлар учун пружиналардан ташқари (9114-товар позицияси); ва (в) 8301, 8302, 8308, 8310-товар позицияларининг буюмлари, шунингдек, 8306-товар позициясининг ноқимматбаҳо металлардан ромлари ва кўзгулари."]},"72":{"title":"ҚОРА МЕТАЛЛАР","section":"XV","notes":["1. Мазкур гурухда, 1 (г), 1 (д) ва 1 (е) изоҳлар ҳолатида эса бутун Номенклатура бўйича қуйида келтирилган атамалар қуйидагиларни англатади: (а) “ишловдан ўтган чўян” – болғалаш учун яроқсиз бўлган, таркибида 2 мас.% дан кўп углерод бўлган ва таркибида қуйидаги чегараларда бир ёки ундан кўп элементлар бўлиши мумкин бўлган темирнинг углерод билан қотишмаси: – хром 10 мас.% дан ортиқ эмас, – марганец 6 мас.% дан ортиқ эмас, – фосфор 3 мас.% дан ортиқ эмас, – кремний 8 мас.% дан ортиқ эмас, – бошқа элементлар, жами бўлиб 10 мас.% дан ортиқ эмас,; (б) “кўзгу чўян (шпигель)” – таркибида 6 мас.% дан кўп, лекин 30 мас.% дан кўп бўлмаган марганец бўлган, бошқа компонентлар бўйича юқорида, мазкур изоҳнинг (а) пунктида кўрсатилган шартларга мос келадиган темирнинг углерод билан қотишмаси;"],"excl":[]},"73":{"title":"ҚОРА МЕТАЛЛДАН ТАЙЁРЛАНГАН БУЮМЛАР","section":"XV","notes":["1. Ушбу гуруҳда “қуйма чўян” атамаси қуйиш йўли билан олинган, темир қотишма таркибидаги бошқа элементларнинг ҳар бирига нисбатан оғирлиги бўйича устунлик қиладиган ва кимёвий таркиби бўйича пўлат таърифига 72-гуруҳга 1 (г) изоҳга мос келмайдиган маҳсулотларни англатади.","2. Ушбу гуруҳда “сим” атамаси 16 мм дан ошмайдиган ҳар қандай шаклдаги иссиқ ёки совуқ ишлов берилган маҳсулотларни англатади."],"excl":[]},"74":{"title":"МИС ВА УНДАН ТАЙЁРЛАНГАН БУЮМЛАР","section":"XV","notes":[],"excl":[]},"75":{"title":"НИКЕЛЬ ВА УНДАН ТАЙЁРЛАНГАН БУЮМЛАР","section":"XV","notes":[],"excl":[]},"76":{"title":"АЛЮМИНИЙ ВА УНДАН ТАЙЁРЛАНАДИГАН БУЮМЛАР","section":"XV","notes":[],"excl":[]},"78":{"title":"ҚЎРҒОШИН ВА УНДАН ТАЙЁРЛАНГАН БУЮМЛАР","section":"XV","notes":[],"excl":[]},"79":{"title":"РУХ ВA УНДАН ТАЙЁРЛАНГАН БУЮМЛАР","section":"XV","notes":[],"excl":[]},"80":{"title":"ҚAЛAЙ ВA УНДАН ТАЙЁРЛАНГАН БУЮМЛАР","section":"XV","notes":[],"excl":[]},"81":{"title":"БОШҚА НОҚИММАТБАҲО МЕТАЛЛАР; МЕТАЛЛ КЕРАМИКА; УЛАРДАН ТАЙЁРЛАНГАН БУЮМЛАР","section":"XV","notes":[],"excl":[]},"82":{"title":"НОҚИММАТБАҲО МЕТАЛЛАРДАН ТАЙЁРЛАНГАН АСБОБЛАР, ПИЧОҚ, ҚОШИҚ ВА ВИЛКАЛАР;","section":"XV","notes":["1. 8209-позициядаги пайвандлаш лампаларидан, портатив ўчоқ, таянч конструкцияли силлиқлаш ускунаси маникюр ва педикюр тўпламлари ва маҳсулотларидан ташқари, ушбу гуруҳга фақат тиғли, кесиш қиррали, иш юзаси ёки бошқа ишчи қисми қуйидагилардан тайёрланган маҳсулотлар киради: (а) ноқимматбаҳо металл маҳсулотдан; (б) металл карбид ёки металл керамикалардан; (в) қимматбаҳо ёки ярим қимматбаҳо тошлардан (табиий, сунъий ёки реконструкция қилинган), асосий металл, металл карбид ёки сорметдан ясалган таянчдан; (г) агар маҳсулотларда абразив материал қўлланилгандан сўнг ўз хусусиятлари ва функцияларини сақлаб турадиган асосий металлни кесувчи тишлари, кичкина ариқча, чуқурча ва шунга ўхшаш ишчи қисмлари бўлиши шарти билан, асосий металлнинг таги ва абразив материаллардан.","2. Махсус номланган қисмлардан ва қўл асбоблари учун ишчи асбобларни ушлаб туриш учун мўлжалланган мосламалардан (8466-товар позициясида) ташқари, ушбу гуруҳдаги ноқимматбаҳо металлдан тайёрланадиган буюм қисмлари ўзига тегишли бўлган буюм билан бирга киритилади. Бироқ, XV бобнинг 2-изоҳида белгиланган умумий мақсадлардаги қисмлар, ушбу гуруҳга киритилмайди. Электр устара ва соч олиш ускунасининг тиғли бош қисми ва пластинали пичоқлари 8510-товар позициясига киради.","3. 8211-товар позициясининг бир ёки бир нечта пичоқларидан ва тенг миқдордаги 8215-товар позициясининг бошқа буюмларидан иборат тўпламлари 8215-товар позициясига киради Қўшим ча"],"excl":["1. 8209-позициядаги пайвандлаш лампаларидан, портатив ўчоқ, таянч конструкцияли силлиқлаш ускунаси маникюр ва педикюр тўпламлари ва маҳсулотларидан ташқари, ушбу гуруҳга фақат тиғли, кесиш қиррали, иш юзаси ёки бошқа ишчи қисми қуйидагилардан тайёрланган маҳсулотлар киради: (а) ноқимматбаҳо металл маҳсулотдан; (б) металл карбид ёки металл керамикалардан; (в) қимматбаҳо ёки ярим қимматбаҳо тошлардан (табиий, сунъий ёки реконструкция қилинган), асосий металл, металл карбид ёки сорметдан ясалган таянчдан; (г) агар маҳсулотларда абразив материал қўлланилгандан сўнг ўз хусусиятлари ва функцияларини сақлаб турадиган асосий металлни кесувчи тишлари, кичкина ариқча, чуқурча ва шунга ўхшаш ишчи қисмлари бўлиши шарти билан, асосий металлнинг таги ва абразив материаллардан.","2. Махсус номланган қисмлардан ва қўл асбоблари учун ишчи асбобларни ушлаб туриш учун мўлжалланган мосламалардан (8466-товар позициясида) ташқари, ушбу гуруҳдаги ноқимматбаҳо металлдан тайёрланадиган буюм қисмлари ўзига тегишли бўлган буюм билан бирга киритилади. Бироқ, XV бобнинг 2-изоҳида белгиланган умумий мақсадлардаги қисмлар, ушбу гуруҳга киритилмайди. Электр устара ва соч олиш ускунасининг тиғли бош қисми ва пластинали пичоқлари 8510-товар позициясига киради."]},"83":{"title":"НОҚИММАТБАҲО МЕТАЛЛАРДАН БОШҚА БУЮМЛАР","section":"XV","notes":["1. Мазкур гуруҳда ноқимматбаҳо металлардан тайёрланган буюмлар қисмлари уларнинг таркибига мувофиқ худди шу товар позицияларига киритилиши керак. Бироқ, 7312, 7315, 7317, 7318 ёки 7320 товар позицияларининг қора металлдан буюмлари ёки бошқа товар позицияларининг ноқимматбаҳо металларидан ўхшаш бўлган буюмлари (74-76 ва 78-81 гуруҳлар) шу гуруҳга киритиладиган буюмлар сифатида кўриб чиқилмаслиги керак.","2. 8302 товар позициясида “мебель ғилдираклар” термини диаметри 75 мм дан кўп бўлмаган мебел ғилдиракларини (тегишли ҳолатларда шинани киритган ҳолда) ёки диаметри 75 ммдан кўпроқ бўлган (тегишли ҳолатларда шинани киритган ҳолда) роликларни англатади, шу шартлардаки, ғилдирак ёки шина кенглиги унга кийдирилгандан 30 мм дан камроқни ташкил этади.","1. Мазкур бўлимга қуйидагилар киритилмайди: (а) 39-гуруҳ пластмассасидан ёки вулканизацияланган резинадан конвейер ленталари ёки айлантирувчи камарлар ёки бельтинг (4010 товар позицияси), машиналарда ёки механик ёхуд электрик қурилмаларда ёки бошқа техник мақсадлар учун ишлатиладиган, вулканизацияланган резинадан тайёрланган, қаттиқ резинадан ташқари, қурилмалар ёки бошқа буюмлар (4016товар позицияси); (б) машиналарда ёки механик қурилмаларда ёхуд бошқа техник мақсадларда фойдаланиладиган, табиий теридан ёки композицион теридан буюмлар (4205 товар позицияси) ёхуд табиий мўйнадан буюмлар (4303 товар позицияси); (в) бобиналар, ғалтаклар, шпуллар, конуслар, ўзаклар, гильзалар ёки ҳар қандай материаллардан шу каби ташувчилар (масалан, 39, 40, 44 ёки 48-гуруҳ ёхуд XV бўлим); (г) жаккард машиналари ёки шу каби машиналар учун перфокарталар (масалан, 39 ёки 48-гуруҳ ёхуд XV бўлим); (д) тўқимачилик материалларидан конвейер ленталари ёки айлантирувчи камарлар ёки бельтинг (5910 товар позицияси) ёки техник мақсадлар учун тўқимачилик материалларидан бошқа буюмлар (5911товар позицияси); (е) 7102 – 7104 товар позицияларининг қимматбаҳо ёки ярим қимматбаҳо тошлари (табиий, сунъий ёки реконструкция қилинган) ёки тўлиқ юқорида кўрсатилган тошлардан тайёрланган 7116 товар позициясининг буюмлари, товуш олувчи игналар учун мўлжалланган ва уларга маҳкамланмаган, ишлов берилган сапфир ва олмослардан ташқари (8522 товар позицияси); (ж) ноқимматбаҳо металлдан тайёрланган, XV бўлим изоҳларининг 2-бандида тавсифланган умумий мақсад учун қисмлар (XV бўлим), ёки пластмассадан тайёрланган шу каби товарлар (39-гуруҳ); (з) одатий бурғилаш қувурлари (7304товар позицияси); (и) металл сим ёки полосадан чексиз ленталар (XV бўлим); (к) 82 ёки 83-гуруҳ буюмлари; (л) XVII бўлим буюмлари; (м) 90-гуруҳ буюмлари; (н) барча турдаги соатлар ёки 91-гуруҳнинг бошқа буюмлари; (о) 8207 товар позициясининг алмашинадиган ишчи асбоблари ёки машиналарнинг қисмлари ҳисобланувчи четкалар (9603 товар позицияси); ишчи қисми тайёрланган материал билан мувофиқликда таснифланадиган шу каби алмашинадиган асбоблар (масалан, 40, 42, 43, 45 ёки 59-гуруҳларда ёхуд 6804 ёки 6909 товар позицияларида); (п) 95-гуруҳ буюмлари; ёки (р) ёзув машинкалари учун ленталар ёки ғалтакларда ёки кассеталарда ёки уларсиз шу каби ленталар (тайёрланган материали билан мувофиқликда таснифланади ёки агар улар сиёҳ билан шимдирилган бўлса ёки изларни олиш учун бошқа усулда ишлов берилган бўлса, 9612 товар позициясида таснифланади), ёки якка тиргаклар, икки оёқлик тиргаклар, уч оёқлик тиргаклар ва 9620 товар позициясининг шу каби буюмлари.","2. Ушбу бўлим изоҳларининг 1-банди, 84-гуруҳ изоҳларининг 1-банди ва 85-гуруҳ изоҳларининг 1-банди талабларига риоя қилиш шарти билан, машиналарнинг қисмлари (8484, 8544, 8545, 8546 ёки 8547 товар позициялари буюмларининг қисмларидан ташқари) қуйидаги қоидаларга мувофиқ таснифланиши керак: (а) 84 ёки 85-гуруҳларнинг бирорта товар позициясига (8409, 8431, 8448, 8466, 8473, 8487, 8503, 8522, 8529, 8538 ва 8548 товар позицияларидан ташқари) киритилган товарлар ҳисобланувчи қисмлар барча ҳолатларда улар учун кўзда тутилган товар позицияларида таснифланиши керак. (б) фақат ёки асосан машиналарнинг бир типи билан ёки худди шу товар позициясининг бир қанча машиналарида (шу жумладан 8479 ёки 8543 товар позицияларининг машиналари) ишлатиш учун учун мўлжалланган бошқа қисмлар шу машиналар билан бирга ёки мос равишда 8409, 8431, 8448, 8466, 8473, 8503, 8522, 8529 ёки 8538 товар позициясида таснифланиши керак. Бироқ, асосан, 8517 ва 8525 – 8528 товар позицияларининг товарлари билан ишлатиш учун тенг яроқли бўлган қисмлар 8517 товар позициясида таснифланади, фақат ёки асосан 8524 товар позициясининг товарлари билан ишлатиш учун яроқли бўлган қисмлар эса 8529 товар позициясида таснифланиши керак; (в) қолган барча бошқа қисмлар мос равишда 8409, 8431, 8448, 8466, 8473, 8503, 8522, 8529 ёки 8538 товар позициясида ёхуд бундан ташқари 8487 ёки 8548 товар позициясида тавсифланади.","3. Икки ёки ундан ортиқ ўзаро бир-бирини тўлдирувчи ёки бир-бири билан боғлиқ бўлмаган функцияларни бажаришга мўлжалланган, бир яхлитликни хосил қилиш учун бирга боғланган икки ёки ундан ортиқ машиналардан ташкил топган комбинацияланган машиналар, ва бошқа машиналар, агар контекстда бошқа нарса белгиланган бўлмаса, фақат асосий функцияни бажарувчи компонентдан иборат ёки шундай машина сифатида таснифланиши керак.","4. Агар машина (шу жумладан комбинацияланган машина) 84 ёки 85-гуруҳ товар позицияларидан бири билан қамраб олинган, аниқ белгиланган функцияни биргаликда бажариш учун мўлжалланган алоҳида компонентлардан ташкил топган бўлса (улар алоҳида жойлашганлиги ёки ўтказувчи қувурлар, трансмиссион қурилмалар, электр кабеллар ёхуд бошқа қурилмалар орқали боғланганлигидан қатъий назар), бундай машина белгиланган функцияга мувофиқ бўлган товар позициясида таснифланади.","5. Мазкур изоҳларда “машина” атамаси 84 ёки 85-гуруҳ товар позицияларига кирувчи исталган машина, ускуна, механизм, агрегат, қурилма, аппарат ёки мосламани англатади.","6. (A) Бутун Номенклатура бўйича “электротехник ёки электрон буюмларнинг чиқиндилари ва ломи” ифодаси электрик ёки электрон йиғмалар, босма платалар, шунингдек, электротехник ёки электрон буюмларни англатадики, улар: (i) бузилиш, кесилиш ёки бошқа сабаблар оқибатида бошланғич вазифасини бажариши учун ишлатишга яроқсиз бўлиб қолган ёки уларни таъмирлаш, тиклаш ёки бошланғич вазифасига мувофиқ бўлиши учун модернизация қилиш иқтисодий жиҳатдан мақсадга мувофиқ эмас; ва (ii) ташиш, юклаш ва туширишдаги шикастланишдан алоҳида буюмларнинг ҳимоясини таъминлай олмайдиган услуб билан қадоқланган ва юкланган. (Б) “Электротехник ёки электрон буюмларнинг чиқиндилари ва ломи” ҳамда бошқа чиқиндилар ва ломнинг аралашмасидан иборат партиялар 8549 товар позициясида таснифланиши керак. (В) Мазкур бўлимга 38-гуруҳ изоҳларининг 4-бандида таърифи келтирилган шаҳар хўжалиги чиқиндилари киритилмайди."],"excl":["1. Мазкур бўлимга қуйидагилар киритилмайди: (а) 39-гуруҳ пластмассасидан ёки вулканизацияланган резинадан конвейер ленталари ёки айлантирувчи камарлар ёки бельтинг (4010 товар позицияси), машиналарда ёки механик ёхуд электрик қурилмаларда ёки бошқа техник мақсадлар учун ишлатиладиган, вулканизацияланган резинадан тайёрланган, қаттиқ резинадан ташқари, қурилмалар ёки бошқа буюмлар (4016товар позицияси); (б) машиналарда ёки механик қурилмаларда ёхуд бошқа техник мақсадларда фойдаланиладиган, табиий теридан ёки композицион теридан буюмлар (4205 товар позицияси) ёхуд табиий мўйнадан буюмлар (4303 товар позицияси); (в) бобиналар, ғалтаклар, шпуллар, конуслар, ўзаклар, гильзалар ёки ҳар қандай материаллардан шу каби ташувчилар (масалан, 39, 40, 44 ёки 48-гуруҳ ёхуд XV бўлим); (г) жаккард машиналари ёки шу каби машиналар учун перфокарталар (масалан, 39 ёки 48-гуруҳ ёхуд XV бўлим); (д) тўқимачилик материалларидан конвейер ленталари ёки айлантирувчи камарлар ёки бельтинг (5910 товар позицияси) ёки техник мақсадлар учун тўқимачилик материалларидан бошқа буюмлар (5911товар позицияси); (е) 7102 – 7104 товар позицияларининг қимматбаҳо ёки ярим қимматбаҳо тошлари (табиий, сунъий ёки реконструкция қилинган) ёки тўлиқ юқорида кўрсатилган тошлардан тайёрланган 7116 товар позициясининг буюмлари, товуш олувчи игналар учун мўлжалланган ва уларга маҳкамланмаган, ишлов берилган сапфир ва олмослардан ташқари (8522 товар позицияси); (ж) ноқимматбаҳо металлдан тайёрланган, XV бўлим изоҳларининг 2-бандида тавсифланган умумий мақсад учун қисмлар (XV бўлим), ёки пластмассадан тайёрланган шу каби товарлар (39-гуруҳ); (з) одатий бурғилаш қувурлари (7304товар позицияси); (и) металл сим ёки полосадан чексиз ленталар (XV бўлим); (к) 82 ёки 83-гуруҳ буюмлари; (л) XVII бўлим буюмлари; (м) 90-гуруҳ буюмлари; (н) барча турдаги соатлар ёки 91-гуруҳнинг бошқа буюмлари; (о) 8207 товар позициясининг алмашинадиган ишчи асбоблари ёки машиналарнинг қисмлари ҳисобланувчи четкалар (9603 товар позицияси); ишчи қисми тайёрланган материал билан мувофиқликда таснифланадиган шу каби алмашинадиган асбоблар (масалан, 40, 42, 43, 45 ёки 59-гуруҳларда ёхуд 6804 ёки 6909 товар позицияларида); (п) 95-гуруҳ буюмлари; ёки (р) ёзув машинкалари учун ленталар ёки ғалтакларда ёки кассеталарда ёки уларсиз шу каби ленталар (тайёрланган материали билан мувофиқликда таснифланади ёки агар улар сиёҳ билан шимдирилган бўлса ёки изларни олиш учун бошқа усулда ишлов берилган бўлса, 9612 товар позициясида таснифланади), ёки якка тиргаклар, икки оёқлик тиргаклар, уч оёқлик тиргаклар ва 9620 товар позициясининг шу каби буюмлари.","2. Ушбу бўлим изоҳларининг 1-банди, 84-гуруҳ изоҳларининг 1-банди ва 85-гуруҳ изоҳларининг 1-банди талабларига риоя қилиш шарти билан, машиналарнинг қисмлари (8484, 8544, 8545, 8546 ёки 8547 товар позициялари буюмларининг қисмларидан ташқари) қуйидаги қоидаларга мувофиқ таснифланиши керак: (а) 84 ёки 85-гуруҳларнинг бирорта товар позициясига (8409, 8431, 8448, 8466, 8473, 8487, 8503, 8522, 8529, 8538 ва 8548 товар позицияларидан ташқари) киритилган товарлар ҳисобланувчи қисмлар барча ҳолатларда улар учун кўзда тутилган товар позицияларида таснифланиши керак. (б) фақат ёки асосан машиналарнинг бир типи билан ёки худди шу товар позициясининг бир қанча машиналарида (шу жумладан 8479 ёки 8543 товар позицияларининг машиналари) ишлатиш учун учун мўлжалланган бошқа қисмлар шу машиналар билан бирга ёки мос равишда 8409, 8431, 8448, 8466, 8473, 8503, 8522, 8529 ёки 8538 товар позициясида таснифланиши керак. Бироқ, асосан, 8517 ва 8525 – 8528 товар позицияларининг товарлари билан ишлатиш учун тенг яроқли бўлган қисмлар 8517 товар позициясида таснифланади, фақат ёки асосан 8524 товар позициясининг товарлари билан ишлатиш учун яроқли бўлган қисмлар эса 8529 товар позициясида таснифланиши керак; (в) қолган барча бошқа қисмлар мос равишда 8409, 8431, 8448, 8466, 8473, 8503, 8522, 8529 ёки 8538 товар позициясида ёхуд бундан ташқари 8487 ёки 8548 товар позициясида тавсифланади.","6. (A) Бутун Номенклатура бўйича “электротехник ёки электрон буюмларнинг чиқиндилари ва ломи” ифодаси электрик ёки электрон йиғмалар, босма платалар, шунингдек, электротехник ёки электрон буюмларни англатадики, улар: (i) бузилиш, кесилиш ёки бошқа сабаблар оқибатида бошланғич вазифасини бажариши учун ишлатишга яроқсиз бўлиб қолган ёки уларни таъмирлаш, тиклаш ёки бошланғич вазифасига мувофиқ бўлиши учун модернизация қилиш иқтисодий жиҳатдан мақсадга мувофиқ эмас; ва (ii) ташиш, юклаш ва туширишдаги шикастланишдан алоҳида буюмларнинг ҳимоясини таъминлай олмайдиган услуб билан қадоқланган ва юкланган. (Б) “Электротехник ёки электрон буюмларнинг чиқиндилари ва ломи” ҳамда бошқа чиқиндилар ва ломнинг аралашмасидан иборат партиялар 8549 товар позициясида таснифланиши керак. (В) Мазкур бўлимга 38-гуруҳ изоҳларининг 4-бандида таърифи келтирилган шаҳар хўжалиги чиқиндилари киритилмайди."]},"84":{"title":"ЯДРОВИЙ РЕАКТОРЛАР; ҚОЗОНЛАР, УСКУНАЛАР ВА МЕХАНИК","section":"XVI","notes":["1. Қуйидагилар мазкур гуруҳга киритилмайди: (а) тегирмон тоши, чархлаш тошлари ёки 68-гуруҳнинг бошқа буюмлари; (б) керамика материалларидан ускуналар ва қурилмалар (масалан, насослар) ва ҳар қандай материалдан тайёрланган машина ёки қурилмаларнинг керамика қисмлари (69-гуруҳ); (в) лаборатория шиша идишлари (7017 товар позицияси); техник мақсадлар учун шишадан ускуна, қурилма ёки бошқа буюмлар ёхуд уларнинг қисмлари (7019 ёки 7020 товар позицияси); (г) 7321 ёки 7322 товар позициясига киритиладиган буюмлар ёки бошқа ноқимматбаҳо металлардан шу каби буюмлар (74 – 76 ёки 78 – 81-гуруҳлар); (д) 8508 товар позициясининг чангюткичлари; (е) 8509 товар позициясининг электромеханик маиший машиналари; 8525 товар позициясининг рақамли камералари; (ж) XVII бўлим буюмлари учун радиаторлар; ёки (з) полларни тозалаш учун механик қўл чўткалари, двигателсиз (9603 товар позицияси).","2. XVI бўлим изоҳларининг 3-банди ва мазкур гуруҳ изоҳларининг 11-банди қоидаларига риоя қилинган тақдирда, 8401 – 8424 товар позициялари ёки 8486 товар позициясининг бири ёки кўпроғидаги тавсифга ва шу вақтнинг ўзида 8425 – 8480 товар позицияларининг бири ёки кўпроғидаги тавсифга мос келадиган машина ва қурилмалар, аниқ ҳолатга боғлиқ ҳолда, биринчи қайд этилган товар позициялари қаторидаги мос товар позициясига ёки 8486 товар позициясига киритилади, иккинчи қайд этилган товар позициялари қаторига эмас. (А) Бироқ, 8419 товар позициясига киритилмайди: (i) уруғларни ундириш учун ускуналар, инкубаторлар ёки брудерлар (8436 товар позицияси); (ii) донни намлаш учун машиналар (8437 товар позицияси); (iii) таркибида сахароза сақлаган шарбатни ажратиб олиш учун диффузион аппаратлар (8438 товар позицияси); (iv) йигирилган тўқимачилик ипларига, тўқимачилик материалларига ёки тайёр тўқимачилик буюмларига термик ишлов бериш ускуналари (8451 товар позицияси); ёки (v) ишлов беришда ҳарорат ўзгариши зарур бўлганда ҳам, у ёрдамчи жараён бўладиган механик ишлов бериш ускуналари, агрегатлар ёки лаборатория ускуналари. (Б) 8422 товар позициясига киритилмайди: (i) қопни ёки шу каби тараларнинг оғзини тикиш учун тикув машиналари (8452 товар позицияси); ёки (ii) 8472 товар позициясининг идора ускуналари. (В) 8424 товар позициясига киритилмайди: (i) бўёқ пурковчи босма машиналар (8443 товар позицияси); ёки (ii) сув пурковчи кесиш машиналари (8456 товар позицияси).","3. 8456 товар позициясининг тавсифига жавоб берадиган ва бир вақтнинг ўзида 8457 – 8461, 8464 ёки 8465 товар позициясининг тавсифига жавоб берадиган, исталган материалга ишлов бериш учун станок 8456 товар позициясига киритилади.","4. 8457 товар позициясига турли типдаги ишлов бериш операцияларини бажариши мумкин бўлган токарлик станокларидан (шу жумладан кўп мақсадли токарлик станокларидан) бошқа, ишлов беришнинг турли операцияларини қуйидаги йўл билан бажарувчи, фақат металлга ишлов берувчи станоклар киритилади: (а) инструментни унинг магазинидан ёки ўхшаш қурилмадан автоматик тарзда ишлов бериш дастурига мувофиқ алмаштириш (ишлов бериш марказлари); (б) ҳаракатланмайдиган заготовкада ишлайдиган, турлича ишлов берадиган головкаларни бир вақтда ёки кетма-кетликда автоматик қўллаш (бир позицияли агрегат станоклари); ёки (в) заготовкани турлича ишлов берадиган головкаларга автоматик кўчириш (кўп позицияли агрегат станоклари).","5. 8462 товар позициясида ясси буюмлар учун “бўйлама кесиш линияси” атамаси чуватиб ечувчи, тўғрилаш қурилмаси, бўйлама кесиш қурилмаси ва ўраш қурилмасидан ташкил топган технологик линияни англатади. Ясси буюмлар учун “кўндаланг кесиш линияси” атамаси чуватиб ечувчи, тўғрилаш қурилмаси ва кесиш қурилмасидан ташкил топган технологик линияни англатади.","6. (A) 8471 товар позициясида “ҳисоблаш машиналари” атамаси қуйидагиларни бажара оладиган машиналарни билдиради: (i) дастурни ёки қайта ишлаш дастурларини ва ҳеч бўлмаганда, дастурни бажариш учун айнан шу пайтда зарур бўлган маълумотни сақлай олади; (ii) фойдаланувчи талабларига мувофиқ эркин қайта дастурланади; (iii) фойдаланувчи томонидан белгиланадиган арифметик ҳисоблашларни бажара олади; ва (iv) қайта ишлаш жараёнида ҳисоблаш машинасидан мантиқий қарорларни қабул қилиш йўли орқали ҳаракатларни ўзгартиришни талаб қилувчи, инсон аралашувисиз қайта ишлаш дастурларини бажаради. (Б) Ҳисоблаш машиналари турли сондаги алоҳида блоклардан иборат тизимлар кўринишида бажарилиши мумкин. (В) Қуйида баён қилинган (Г) ва (Д) изоҳларнинг талабларига риоя қилиш шарти билан, агар блок қуйидаги барча шартларга мос келса, у ҳисоблаш тизимининг қисми сифатида қаралиши керак: (i) фақат ёки асосан ҳисоблаш тизимида фойдаланилади; (ii) маълумотларни қайта ишлаш марказий блокига бевосита ёки бир ёхуд бир нечта бошқа блоклар орқали уланиш имкониятига эга; ва (iii) маълумотни тизим фойдаланиши мумкин бўлган шаклда (кодлар ёки сигналлар) қабул қила олади ёки тақдим эта олади. Алоҳида тақдим этилган ҳисоблаш машинасининг блоклари 8471 товар позициясига киритилади. Бироқ, юқоридаги (В) (ii) ва (В) (iii) изоҳларда баён қилинган шартларга жавоб берадиган клавиатура, X–Y-координатали киритиш қурилмалари ва маълумотларни дискларда сақловчи блоклар барча ҳолатларда 8471 товар позициясидаги блоклар сифатида қаралиши керак. (Г) Алоҳида тақдим этилган қуйидаги қурилмалар 8471 товар позициясига киритилмайди, хатто улар юқорида баён қилинган 6 (В) изоҳидаги барча шартларга жавоб берганда ҳам: (i) принтерлар, нусха кўчириш аппаратлари, факс аппаратлари, бирлаштирилган ёки бирлаштирилмаган; (ii) товуш, тасвирлар ёки бошқа маълумотларни қабул қилиш ёки узатиш учун аппаратура, шу жумладан симли ёки симсиз алоқа тармоғида коммуникацияларни таъминлаш аппаратураси (масалан, локал ёки глобал тармоқда); (iii) радиокарнайлар ва микрофонлар; (iv) телевизион камералар, рақамли камералар ва ёзиб олувчи видеокамералар; (v) қабул қилиш телевизион аппаратураси билан бирлаштирилмаган мониторлар ва проекторлар. (Д) Ўз таркибида ҳисоблаш машинаси бўлган ёки ҳисоблаш машинаси билан биргаликда ишлайдиган ва ахборотни қайта ишлашдан фарқли махсус функцияларни бажарувчи машиналар уларнинг махсус функцияларига мувофиқ товар позицияларига киритилади ёки бунинг имкони бўлмаса – қолдиқ товар позицияларига киритилади.","7. 8482 товар позициясига, inter alia, қайси бири кичикроқ бўлишига боғлиқ ҳолда, максимал ва минимал диаметрлари номинал диаметридан 1 % дан кўпроққа ёки 0,05 мм дан кўпроққа фарқ қилмайдиган полировкаланган пўлат шарчалар киритилади. Бошқа пўлат шарчалар 7326 товар позициясига киритилади.","8. Бир мақсаддан кўпроқ бўлган вазифалар учун ишлатиладиган машина таснифланганда унинг асосий мақсади ягона вазифа сифатида қаралиши керак. Ушбу бўлим изоҳларининг 2-банди ва XVI бўлим изоҳларининг 3-банди талабларига риоя қилиш шарти билан, асосий ишлатиш мақсади ҳеч бир товар позициясида тавсифланмаган машина, ёки ишлатиш мақсадларининг бирортаси ҳам асосий ҳисобланмайдиган машина 8479 товар позициясида таснифланади, агар контекстда бошқа нарса қайд этилмаган бўлса. 8479 товар позициясига металл симдан, йигирилган текстиль ипдан ёки бошқа материаллардан ёхуд шундай материалларнинг комбинациясидан арқонлар ёки трослар тайёрлаш учун машиналар (масалан, тўқиш-эшиш учун машиналар) ҳам киритилади.","9. 8470 товар позициясида “чўнтак қурилмалари” атамаси ўлчамлари 170 х 100 х 45 мм дан ошмайдиган қурилмаларга нисбатан қўлланилади.","10. 8485 товар позициясида “аддитив ишлаб чиқариш” атамаси (3D босиб чиқариш деб ҳам аталади) физик объектларни рақамли модель асосида, материални кетма-кетликда қўшиш ҳамда қатламлаш, зичлаш ва қотириш йўли билан шакллантиришни билдиради. XVI бўлим изоҳларининг 1-банди ва 84-гуруҳ изоҳларининг 1-банди талабларига риоя қилиш шарти билан, 8485 товар позициясидаги тавсифга жавоб берадиган станоклар ушбу товар позициясида таснифланади ва Номенклатуранинг бошқа ҳеч қандай товар позициясида тавсифланмайди.","11. (A) 85-гуруҳдаги изоҳларнинг 12(а) ва 12(б) бандлари мазкур изоҳда ва 8486 товар позициясида фойдаланиладиган, мос равишда, “ярим ўтказгичли асбоблар” ва “электрон интеграл схемалар” атамаларига ҳам қўлланилади. Бироқ, мазкур изоҳда ва 8486 товар позициясида “ярим ўтказгичли асбоблар” атамаси фотосезувчан ярим ўтказгичли асбобларга ва светодиодларга (LED) ҳам тегишлидир. (Б) Ушбу изоҳда ва 8486 товар позициясида “ясси дисплейли панелларни ишлаб чиқариш” атамаси подложкалардан ясси панелни тайёрлашга тегишлидир. Бу атама шишани ишлаб чиқариш ёки босма платаларни ёки ясси панеллардаги бошқа электрон компонентларни монтаж қилишга тегишли эмас. “Ясси дисплейли панел” атамаси электрон-нурли трубкалар технологиясига тегишли эмас. (В) 8486 товар позициясига фақат ёки асосан қуйидагилар учун фойдаланиладиган машиналар ва аппаратура ҳам киритилади: (i) маскалар ва шаблонларни ишлаб чиқариш ёки улардаги нуқсонларни бартараф этиш; (ii) Ярим ўтказгичли асбоблар ёки электрон интеграл схемаларни йиғиш; (iii) булларни, пластиналар, ярим ўтказгичли асбоблар, электрон интеграл схемалар ва ясси панелли дисплейларни кўтариш, манипуляция қилиш, юклаш ёки тушириш учун. (Г) XVI бўлим изоҳларининг 1-банди ва 84-гуруҳ изоҳларининг 1-банди талабларига риоя қилиш шарти билан, 8485 товар позициясидаги тавсифга жавоб берадиган машиналар ва аппаратура ушбу товар позициясига киритилади ва Номенклатуранинг бошқа ҳеч қандай товар позициясига киритилмайди. Субпозицияларга изоҳлар:","1. 8465 20 субпозициясидаги “ишлов бериш марказлари” атамаси фақат ишлов бериш дастурига мувофиқ инструментни уларнинг магазинидан ёки шу каби қурилмани автоматик алмаштириш йўли орқали ишлов беришнинг турли хил операцияларини бажара оладиган, ёғоч, пробка, суяк, қаттиқ резина, қаттиқ пластмасса ёки шу каби қаттиқ материалларга ишлов бериш учун мўлжалланган станокларга қўлланилади.","2. 8471 49 субпозициясида “тизимлар” атамаси блоклари 84-гуруҳ изоҳларининг 6 (В) бандида баён қилинган талабларга жавоб берадиган ва ўз ичига камида маълумотларни қайта ишлаш марказий блокини, битта киритиш блокини (масалан, клавиатура ёки сканер) ва битта чиқариш блокини (масалан, дисплей ёки принтер) оладиган ҳисоблаш машиналарини билдиради.","3. 8481 20 субпозициясидаги “мой-гидравлик ёки пневматик трансмиссиялар учун клапанлар” ибораси энергия манбаи босим остидаги оқувчан муҳит (суюқлик ёки газ) бўлган гидравлик ёки пневматик тизимда “оқувчан муҳит энергияси”ни кўчиришда бевосита қўлланиладиган клапанларни билдиради. Бу клапанлар исталган турда бўлиши мумкин (масалан, редукцион, қарама-қарши томонга йўналган). 8481 20 субпозицияси 8481 товар позициясида биринчи даражали аҳамиятга эга.","4. 8482 40 субпозициясига фақат диаметри 5 мм дан ошмайдиган, узунлиги эса камида уч диаметрдан иборат цилиндр роликли подшипниклар киритилади. Роликларнинг учлари юмалоқланган бўлиши мумкин."],"excl":["1. Қуйидагилар мазкур гуруҳга киритилмайди: (а) тегирмон тоши, чархлаш тошлари ёки 68-гуруҳнинг бошқа буюмлари; (б) керамика материалларидан ускуналар ва қурилмалар (масалан, насослар) ва ҳар қандай материалдан тайёрланган машина ёки қурилмаларнинг керамика қисмлари (69-гуруҳ); (в) лаборатория шиша идишлари (7017 товар позицияси); техник мақсадлар учун шишадан ускуна, қурилма ёки бошқа буюмлар ёхуд уларнинг қисмлари (7019 ёки 7020 товар позицияси); (г) 7321 ёки 7322 товар позициясига киритиладиган буюмлар ёки бошқа ноқимматбаҳо металлардан шу каби буюмлар (74 – 76 ёки 78 – 81-гуруҳлар); (д) 8508 товар позициясининг чангюткичлари; (е) 8509 товар позициясининг электромеханик маиший машиналари; 8525 товар позициясининг рақамли камералари; (ж) XVII бўлим буюмлари учун радиаторлар; ёки (з) полларни тозалаш учун механик қўл чўткалари, двигателсиз (9603 товар позицияси).","2. XVI бўлим изоҳларининг 3-банди ва мазкур гуруҳ изоҳларининг 11-банди қоидаларига риоя қилинган тақдирда, 8401 – 8424 товар позициялари ёки 8486 товар позициясининг бири ёки кўпроғидаги тавсифга ва шу вақтнинг ўзида 8425 – 8480 товар позицияларининг бири ёки кўпроғидаги тавсифга мос келадиган машина ва қурилмалар, аниқ ҳолатга боғлиқ ҳолда, биринчи қайд этилган товар позициялари қаторидаги мос товар позициясига ёки 8486 товар позициясига киритилади, иккинчи қайд этилган товар позициялари қаторига эмас. (А) Бироқ, 8419 товар позициясига киритилмайди: (i) уруғларни ундириш учун ускуналар, инкубаторлар ёки брудерлар (8436 товар позицияси); (ii) донни намлаш учун машиналар (8437 товар позицияси); (iii) таркибида сахароза сақлаган шарбатни ажратиб олиш учун диффузион аппаратлар (8438 товар позицияси); (iv) йигирилган тўқимачилик ипларига, тўқимачилик материалларига ёки тайёр тўқимачилик буюмларига термик ишлов бериш ускуналари (8451 товар позицияси); ёки (v) ишлов беришда ҳарорат ўзгариши зарур бўлганда ҳам, у ёрдамчи жараён бўладиган механик ишлов бериш ускуналари, агрегатлар ёки лаборатория ускуналари. (Б) 8422 товар позициясига киритилмайди: (i) қопни ёки шу каби тараларнинг оғзини тикиш учун тикув машиналари (8452 товар позицияси); ёки (ii) 8472 товар позициясининг идора ускуналари. (В) 8424 товар позициясига киритилмайди: (i) бўёқ пурковчи босма машиналар (8443 товар позицияси); ёки (ii) сув пурковчи кесиш машиналари (8456 товар позицияси).","6. (A) 8471 товар позициясида “ҳисоблаш машиналари” атамаси қуйидагиларни бажара оладиган машиналарни билдиради: (i) дастурни ёки қайта ишлаш дастурларини ва ҳеч бўлмаганда, дастурни бажариш учун айнан шу пайтда зарур бўлган маълумотни сақлай олади; (ii) фойдаланувчи талабларига мувофиқ эркин қайта дастурланади; (iii) фойдаланувчи томонидан белгиланадиган арифметик ҳисоблашларни бажара олади; ва (iv) қайта ишлаш жараёнида ҳисоблаш машинасидан мантиқий қарорларни қабул қилиш йўли орқали ҳаракатларни ўзгартиришни талаб қилувчи, инсон аралашувисиз қайта ишлаш дастурларини бажаради. (Б) Ҳисоблаш машиналари турли сондаги алоҳида блоклардан иборат тизимлар кўринишида бажарилиши мумкин. (В) Қуйида баён қилинган (Г) ва (Д) изоҳларнинг талабларига риоя қилиш шарти билан, агар блок қуйидаги барча шартларга мос келса, у ҳисоблаш тизимининг қисми сифатида қаралиши керак: (i) фақат ёки асосан ҳисоблаш тизимида фойдаланилади; (ii) маълумотларни қайта ишлаш марказий блокига бевосита ёки бир ёхуд бир нечта бошқа блоклар орқали уланиш имкониятига эга; ва (iii) маълумотни тизим фойдаланиши мумкин бўлган шаклда (кодлар ёки сигналлар) қабул қила олади ёки тақдим эта олади. Алоҳида тақдим этилган ҳисоблаш машинасининг блоклари 8471 товар позициясига киритилади. Бироқ, юқоридаги (В) (ii) ва (В) (iii) изоҳларда баён қилинган шартларга жавоб берадиган клавиатура, X–Y-координатали киритиш қурилмалари ва маълумотларни дискларда сақловчи блоклар барча ҳолатларда 8471 товар позициясидаги блоклар сифатида қаралиши керак. (Г) Алоҳида тақдим этилган қуйидаги қурилмалар 8471 товар позициясига киритилмайди, хатто улар юқорида баён қилинган 6 (В) изоҳидаги барча шартларга жавоб берганда ҳам: (i) принтерлар, нусха кўчириш аппаратлари, факс аппаратлари, бирлаштирилган ёки бирлаштирилмаган; (ii) товуш, тасвирлар ёки бошқа маълумотларни қабул қилиш ёки узатиш учун аппаратура, шу жумладан симли ёки симсиз алоқа тармоғида коммуникацияларни таъминлаш аппаратураси (масалан, локал ёки глобал тармоқда); (iii) радиокарнайлар ва микрофонлар; (iv) телевизион камералар, рақамли камералар ва ёзиб олувчи видеокамералар; (v) қабул қилиш телевизион аппаратураси билан бирлаштирилмаган мониторлар ва проекторлар. (Д) Ўз таркибида ҳисоблаш машинаси бўлган ёки ҳисоблаш машинаси билан биргаликда ишлайдиган ва ахборотни қайта ишлашдан фарқли махсус функцияларни бажарувчи машиналар уларнинг махсус функцияларига мувофиқ товар позицияларига киритилади ёки бунинг имкони бўлмаса – қолдиқ товар позицияларига киритилади.","11. (A) 85-гуруҳдаги изоҳларнинг 12(а) ва 12(б) бандлари мазкур изоҳда ва 8486 товар позициясида фойдаланиладиган, мос равишда, “ярим ўтказгичли асбоблар” ва “электрон интеграл схемалар” атамаларига ҳам қўлланилади. Бироқ, мазкур изоҳда ва 8486 товар позициясида “ярим ўтказгичли асбоблар” атамаси фотосезувчан ярим ўтказгичли асбобларга ва светодиодларга (LED) ҳам тегишлидир. (Б) Ушбу изоҳда ва 8486 товар позициясида “ясси дисплейли панелларни ишлаб чиқариш” атамаси подложкалардан ясси панелни тайёрлашга тегишлидир. Бу атама шишани ишлаб чиқариш ёки босма платаларни ёки ясси панеллардаги бошқа электрон компонентларни монтаж қилишга тегишли эмас. “Ясси дисплейли панел” атамаси электрон-нурли трубкалар технологиясига тегишли эмас. (В) 8486 товар позициясига фақат ёки асосан қуйидагилар учун фойдаланиладиган машиналар ва аппаратура ҳам киритилади: (i) маскалар ва шаблонларни ишлаб чиқариш ёки улардаги нуқсонларни бартараф этиш; (ii) Ярим ўтказгичли асбоблар ёки электрон интеграл схемаларни йиғиш; (iii) булларни, пластиналар, ярим ўтказгичли асбоблар, электрон интеграл схемалар ва ясси панелли дисплейларни кўтариш, манипуляция қилиш, юклаш ёки тушириш учун. (Г) XVI бўлим изоҳларининг 1-банди ва 84-гуруҳ изоҳларининг 1-банди талабларига риоя қилиш шарти билан, 8485 товар позициясидаги тавсифга жавоб берадиган машиналар ва аппаратура ушбу товар позициясига киритилади ва Номенклатуранинг бошқа ҳеч қандай товар позициясига киритилмайди. Субпозицияларга изоҳлар:"]},"85":{"title":"ЭЛЕКТР МАШИНАЛАР ВА УСКУНАЛАР, УЛАРНИНГ ҚИСМЛАРИ; ОВОЗ ЁЗИБ ОЛУВЧИ ВА ОВОЗНИ","section":"XVI","notes":["1. Мазкур гуруҳга қуйидагилар кирмайди: (а) адёл, матрацлар, ёстиқлар, оёқ иситиш грелкаси, электрда иситиладиган ёки ўхшаш маҳсулотлар; кийим, пойабзал ёки наушниклар ёки инсон томонидан ишлатиладиган бошқа электрда иситиладиган предметлар; (б) 7011 товар позициясидаги шиша идишлар; (в) 8486 товар позициясидаги машиналар ва аппаратлар; (г) тиббиёт, жарроҳлик, стоматология ёки ветеринария тадқиқотларида фойдаланиладиган вакуумли аппаратлар (9018 товар позицияси); (д) 94-гуруҳнинг электрда иситиладиган мебеллари.","2. 8501 – 8504 товар позициясидаги товарлар 8511, 8512, 8540, 8541 ёки 8542 товар позицияларидаги товарларни ўз ичига олмайди. Бироқ, метал сиғимли симоб-электр ёйидан фондаланишга асосланган тўғрилагичларни 8504 товар позициясига киради.","3. 8507 товар позициясидаги “электрли аккумуляторлар” атамаси электр ажраткичлар, терморегуляторлар (масалан, терморезисторлар) ва ҳимоя қурилмалари каби энергияни сақлаш ва таъминлаш бўйича аккумулятор функциясининг бажарилишига ёрдам берадиган ёки уни шикастланишдан ҳимоялайдиган қўшимча компонентлар билан тақдим этилган электр аккумуляторларга тегишлидир. Улар, шунингдек, фойдаланиладиган товарларнинг ҳимоя ғилофининг қисмини ҳам ўз ичига олиши мумкин.","4. 8509 товар позициясига фақат маиший мақсадларда ишлатиладиган электромеханик машиналарнинг қуйидаги турлари киради: (а) полотерлар, озиқ-овқат майдалагичлари, миксерлар ва мева ёки сабзавотлар учун шарбат чиқаргичлар‚ ҳар қандай вазнга эга; (б) оғирлиги 20 кг дан кўп бўлмаган бошқа машиналар. Бироқ, бу товар позициясига вентиляторлар ёки вентиляция ёки тортувчи рециркуляция колпаклари ёки вентиляторли шкафлар, фильтрли ёки фильтрсиз (8414 товар позицияси), марказдан қочувчи кийим қуриткичлар (8421 товар позицияси), идишларни ювиш машиналари (8422 товар позицияси), маиший кир ювиш машиналари (8450 товар позицияси), роликли ёки бошқа дазмоллаш машиналари (8420 ёки 8451 товар позицияси), тикув машиналари (8452 товар позицияси), электр қайчилар (8467 товар позицияси) ёки электр иситкич приборлари (8516 товар позицияси) киритилмайди","5. 8517 товар позициясидаги “смартфонлар” атамаси ҳисоблаш машинасининг бир нечта иловаларни юклаб олиш ва уларнинг бир вақтда ишлаши, шу жумладан, ичига рақамли камералар ва навигация тизимлари каби бошқа компонентлар ўрнатилганлиги ёки ўрнатилмаганлигидан қатъий назар ташқи иловалар каби функцияларини бажариш учун мўлжалланган мобил операцион тизим билан таъминланган алоқа тармоқлари учун мўлжалланган телефонларни англатади.","6. 8523 товар позициясида: (a) “қаттиқ жисмли энергия таъминоти мустақил бўлган маълумотларни сақлаш қурилмалари” (масалан, “флэш-хотира карталари” ёки “электрон флэш-хотира карталари”) босма платага ўрнатилган битта корпусдаги интеграл схемалар кўринишидаги бир ёки бир нечта флэш-хотира қурилмалари бўлган уловчи ажраткичга эга маълумотларни сақлаш қурилмаларини англатади (масалан, “флэш-ЭС ППЗУ”). Улар таркибига интеграл схема кўринишидаги контроллёр ҳамда конденсаторлар ва резисторлар каби дискрет пассив компонентлар бўлиши мумкин; (б) “интеллектуал карточкалар” атамаси кристаллар кўринишидаги бир ёки бир нечта электрон интеграл схемалар (микропроцессор, ихтиёрий танлаб оладиган доимий хотирлаш қурилмаси (ИТХҚ) ёки доимий хотирлаш қурилмаси (ДХҚ)га эга карточкаларни билдиради. Бу карточкалар контактлар, магнит чизиқ ёки ичига ўрнатилган антеннага эга бўлиши мумкин, аммо уларда бошқа ҳеч қандай актив ёки пассив элементлар мавжуд эмас.","7. 8524 товар позициясида “ясси дисплей панелли модуллар” ифодаси фойдаланишдан аввал бошқа товар позицияларидаги маҳсулотларга ўрнатиш учун конструкцияланган камида дисплей экрани билан жиҳозланган ахборотни акс эттирувчи қурилмалар ёки аппаратларга тегишли. Шаклига кўра бундай модулларнинг дисплей экранлари ясси, букланган, эгилувчан, тахланадиган, чўзиладиган ёки бошқа шаклларда бўлиши мумкин. Ясси дисплей панелли модуллар ўз ичига қўшимча компонентларни, шу жумладан, видеосигналларни қабул қилиш ва уларни экран пикселлари бўйлаб тақсимлаш учун зарур бўлган компонентларни олиши мумкин. Аммо 8524 товар позициясига видеосигналларни қайта ўзгартириш учун мўлжалланган компонентлар (масалан, видеоформатни ўзгартирувчи интеграл схема, декодер интеграл схемаси ёки иловалар процессори) билан жиҳозланган ёки бошқа усул билан товар позицияларидаги маҳсулотлар хусусиятини қабул қилган дисплей модуллари киритилмайди. Ушбу изоҳда кўрсатилган ясси дисплей панели бўлган модулларни таснифлашда 8524 товар позицияси номенклатурадаги ҳар қандай бошқа товар позициясидан устувор бўлади.","8. 8534 товар позициясида “босма схемалар” атамаси ҳар қандай босиб чиқариш жараёни (масалан, гальванизация, ўйма) ёрдамида ёки алоҳида ёки маълум бир тартибда бирлаштирилган ўтказгичлар, контактлар ёки бошқа босма элементлар (масалан, индуктивлик, резисторлар, сиғимлар)нинг “плёнкали” технологияси ёрдамида изоляцияловчи тагликда шакллантириш йўли орқали бажарилган схемаларни билдиради, электр сигнални яратиш, тўғрилаш, модуляциялаш ёки кучайтириш қобилиятига эга элементлар (масалан, ярим ўтказгичли элементлар) бундан мустасно. “Босма схемалар” атамаси босиб чиқариш жараёнида олинган элементлардан фарқли элементлар билан бирлашган схемаларни, шунингдек алоҳида дискрет резисторлар, конденсаторлар ёки индуктивлик схемаларини ўз ичига олмайди. Аммо босма схемалар босма технологиядан фарқли бўлган бошқа технология бўйича тайёрланган боғловчи элементлар билан жиҳозланиши мумкин. Айнан ўша технологик жараён давомида олинган пассив ва актив элементлардан фойдаланилган ингичка ёки қалин плёнкали схемалар 8542 товар позициясига киритилади.","9. 8536 товар позициясида “оптик, оптик-толали жгутлар ёки кабеллар толалари учун улагичлар” атамаси рақамли алоқа линияси тизимидаги оптик толаларнинг учларини механик бирлаштирувчи улагичларни билдиради. Улар сигнални кучайтириш, тиклаш ёки ўзгартириш каби бошқа ҳеч қандай функцияларни бажармайди.","10. 8537 товар позициясига телевизион қабул қилгичлар ёки бошқа электр ускуналарини масофадан бошқариш учун мўлжалланган симсиз инфрақизил қурилмалар киритилмайди (8543 товар позицияси).","11. 8539 товар позициясида “ёруғлик диоди ёруғлик манбалари (LED)” ифодаси қуйидагиларни қамраб олади: (a) “ёруғлик диоди модуллари (LED)”, электр занжирларига бирлаштирилган ва электр, механик, термик ёки оптик элементлар каби қўшимча элементларни ўз ичига олган ёруғлик диодлари асосидаги электр ёруғлик манбалари (LED). Таъминотни узатиш ёки назорат қилиш учун бу модуллар дискрет актив элементлар, дискрет пассив элементлар ёки 8536 ёки 8542 товар позициясидаги маҳсулотларни ўз ичига олади. Ёруғлик диоди модуллари (LED) ёриткичда ўрнатилиши ёки алмаштирилишини осонлаштирувчи ҳамда механик ва электр контактни таъминловчи цоколь билан жиҳозланмаган. (б) Электр, механик, термик ёки оптик элементлар каби қўшимча компонентларни ўз ичига олган бир ёки бир нечта ёруғлик диодли модуллари (LED)га эга ёруғликнинг электр манбаларидан иборат “ёруғлик диодли лампалар (LED)”. Ёруғлик диодли модуллар (LED)нинг ёруғлик диодли лампалар (LED) дан фарқи шундан иборатки, ёруғлик диодли лампалар ёриткичга ўрнатилиши ёки алмаштирилишини осонлаштирувчи ҳамда механик ва электр контактни таъминловчи цоколга эга.","12. 8541 ва 8542 товар позицияларида: (a) (i) “ярим ўтказгичли асбоблар” уларнинг ишлаши электр майдонининг таъсири остида улар қаршилигининг ўзгаришига асосланган ёки ярим ўтказгичлар асосидаги ўзгартиргичларни билдиради. Ярим ўтказгичли асбоблар улар актив ва пассив ёрдамчи функциялар билан таъминланганлиги ёки таъминланмаганлигидан қатъи назар кўплаб элементлардан йиғилган бўлиши ҳам мумкин. Ушбу таъриф мақсади учун “ярим ўтказгичлар асосидаги ўзгартиргичлар” улар белгиланган функцияни бажарувчи ва ҳар қандай физик ёки кимёвий ҳодисаларни ёки электр сигналга таъсирларни ёки электр сигнални қандайдир физик ҳодисага ёки хатти-ҳаракатга ўзгартириш қобилиятига эга ярим ўтказгичлар асосидаги датчиклар, ярим ўтказгичлар асосидаги приводлар, ярим ўтказгичлар асосидаги резонаторлар ва ярим ўтказгичлар асосидаги генераторлардан ташкил топган. Ярим ўтказгичлар асосидаги ўзгартиргичларнинг барча элементлари узвий равишда ўзаро боғланган, шунингдек уларнинг тузилиши ёки ишлаши учун зарур бўлган уларга ўзаро узвий боғланган материалларни ўз ичига олиши мумкин. Қуйида кўрсатилган ифодалар қуйидаги маъноларга эга: (1) “ярим ўтказгич асосида” ярим ўтказгичли тагликда яратилган ёки тайёрланган ёки ярим ўтказгичли технология бўйича ярим ўтказгичли материаллардан тайёрланган, бу технологияга кўра ярим ўтказгичли таглик ёки материал ўзгартиргич ўз функциясини бажаришида энг муҳим ва ҳеч ким бажара олмайдиган вазифани бажаради, ўзгартиргич ишлаши ярим ўтказгичнинг хусусиятларига, шу жумладан, физик, электр, кимёвий ва оптик хоссаларига асосланади. (2) “физик ёки кимёвий ҳодисалар” босим, акустик тўлқинлар, тезланиш, тебраниш, ҳаракатланиш, ориентация, кучланганлик, магнит майдонинг кучланиши, электр майдонининг кучланиши, радиоактивлик, намлик, сарфлаш, кимёвий элементлар концентрацияси ва шу каби ҳодисаларга тегишли. (3) “ярим ўтказгич асосидаги датчик” ярим ўтказгич массасида ёки юзасида яратиладиган микроэлектрон ёки механик структуралардан иборат ва физик ёки кимёвий таъсир катталикларини аниқлаш ҳамда электр хоссаларининг ўзгариши ёки механик структуранинг силжиши сабаб бўлган уларнинг электр сигналларига ўзгартириш функциясига эга ярим ўтказгичли асбоб типидан ташкил топган. (4) “ярим ўтказгич асосидаги привод” ярим ўтказгич массасида ёки юзасида яратиладиган ва электр сигналларини физик ҳаракатга ўзгартириш функциясига эга микроэлектрон ёки механик структуралардан иборат ярим ўтказгичли асбоб типидан ташкил топган. (5) “ярим ўтказгич асосидаги резонатор” ярим ўтказгич массасида ёки юзасида яратиладиган ва ташқи кириш сигналига жавоб қайтарувчи микроэлектрон ёки механик структураларнинг физик геометриясига боғлиқ бўлган белгиланган частотадаги механик ёки электр тебранишларни генерациялаш функциясига эга ушбу микроэлектрон ёки механик структуралардан иборат ярим ўтказгичли асбобнинг типидан ташкил топган. (6) “ярим ўтказгич асосидаги генератор” ярим ўтказгич массасида ёки юзасида яратиладиган ва ташқи кириш сигналига жавоб қайтарувчи микроэлектрон ёки механик структураларнинг физик геометриясига боғлиқ бўлган белгиланган частотадаги механик ёки электр тебранишларни генерациялаш функциясига эга ушбу микроэлектрон ёки механик структуралардан иборат ярим ўтказгичли асбобнинг типидан ташкил топган. (ii) “ёруғлик диодлари (LED)” электр энергиясини кўзга кўринадиган, инфрақизил ёки ультрабинафша нурланишга ўзгартирадиган ярим ўтказгичли материаллардан ташкил топган, бу материаллар ўзаро электр боғланган ёки боғланмаганлигидан қатъи назар, шунингдек ҳимоя диодлари билан бирлашган ёки бирлашмаган. 8541 товар позициясидаги ёруғлик диодлари (LED)да электр таъминоти билан таъминлаш ёки электр таъминотини назорат қилиш учун мўлжалланган компонентлар мавжуд эмас; (б) “электрон интеграл схемалар”: (i) монолит интеграл схемалар, улардаги схема элементлари (диодлар, транзисторлар, резисторлар, конденсаторлар, индуктивлик ва ҳ.) ярим ўтказгич ёки мураккаб ярим ўтказгичли материал (масалан, бойитилган кремний, галлий арсенид, силиконли германий, индий фосфиди) массаси (асосан) юзасида бажарилади; (ii) гибрид интеграл схемалар, улардаги ингичка ёки қалин плёнкали технология жараёнлари ёрдамида бажарилган пассив элементлар (резисторлар, конденсаторлар, индуктивлик ва ҳ.), ва ярим ўтказгичли технология жараёнлари ёрдамида олинган актив элементлар (диодлар, транзисторлар, монолит интеграл схемалар ва ҳ.) битта изоляцияловчи подложка (шиша, керамика ва ҳ.)даги элементлараро бирикмалар ёки уловчи кабеллар орқали ягона ажралмас бир бутунга бирлашади. Бундай схемалар таркибида дискрет компонентлар бўлиши мумкин; (iii) бир ёки бир нечта изоляцияловчи тагликларда жойлашган ёки жойлашмаган, чиқариш рамкаларига эга бўлган ёки эга бўлмаган, аммо бошқа ҳеч қандай актив ёки пассив элементларни ўз ичига олмаган, ажралмас равишда ягона бир бутунга бирлаштирилган ўзаро бириктирилган икки ёки ундан ортиқ яхлит интеграл схемалардан ташкил топган кўп кристалли интеграл схемалар; (iv) ҳеч бўлмаганда қуйидаги компонентлардан бири: кремний асосидаги датчиклар, кремний асосидаги приводлар, кремний асосидаги генераторлар, кремний асосидаги резонаторлар ёки уларнинг комбинациялари ёки 8532, 8533, 8541 товар позицияларида таснифланадиган маҳсулотлар функцияларини бажарувчи компонентлар билан, ёки 8504 товар позициясида таснифланадиган индукторлар бирлаштирилган, контактлар, ўтказгичлар, шарикли қулоқлар, ерга уланувчилар, қулоқлар ёки контакт майдончаларига уланиш йўли орқали босма платада ёки бошқа ташувчига ўрнатиладиган компонентдан иборат ягона бир бутун интеграл схема сифатида ажралмас равишда бирлаштирилган бир ёки бирдан ортиқ яхлит, гибрид ёки кўп кристалли интеграл схемалар ташкил топган кўп компонентли интеграл схемалар. Ушбу таърифда: (1) “компонентлар” мустақил ишлаб чиқилган, кейинги кўп компонентли интеграл схеманинг қолган қисмига ўрнатилган ёки бошқа компонентларга интеграциялашган дискрет бўлиши мумкин. (2) “кремний асосида” кремний асосида ишланганлигини ёки кремнийдан ишланганлигини ёки интеграл схема кристалли асосида тайёрланганлигини билдиради. (3) (a) “кремний асосидаги датчиклар” ярим ўтказгич массасида ёки юзасида яратиладиган ва физик ёки кимёвий ҳодисаларни аниқлаш ҳамда уларни электр хусусиятларнинг ўзгариши ёки механик структуранинг силжиши сабаб бўлган уларни электр сигналларга ўзгартириш функциясига эга микроэлектрон ёки механик структуралардан иборат. “Физик ёки кимёвий ҳодисалар” босим, акустик тўлқинлар, тезланиш, тебраниш, ҳаракатланиш, ориентация, кучланиш, магнит майдон кучланганлиги, электрон майдон кучланганлиги, ёруғлик, радиоактивлик, намлик, кимёвий моддаларнинг сарфланиши, концентрацияси ва ҳ. (б) “кремний асосидаги ҳайдовчилар” ярим ўтказгич массасида ёки юзасида яратиладиган ва электр сигналларини физик ҳаракатга ўзгартириш функциясига эга микроэлектрон ва механик структуралардан иборат. (в) “кремний асосидаги резонаторлар” ярим ўтказгич массасида ёки юзасида яратиладиган ва ташқи кириш сигналига жавоб қайтарувчи микроэлектрон ёки механик структураларнинг физик геометриясига боғлиқ бўлган берилган частотали механик ёки электр тебранишларни генерациялаш функциясига эга ушбу микроэлектрон ёки механик структуралардан ташкил топган. (г) “кремний асосидаги генераторлар” ярим ўтказгич массасида ёки юзасида яратиладиган ва микроэлектрон ёки механик структураларнинг физик геометриясига боғлиқ бўлган берилган частотада механик ёки электр тебранишларни генерациялаш функциясига эга ушбу микроэлектрон ёки механик структуралардан ташкил топган. Ушбу изоҳда кўрсатилган маҳсулотларни таснифлашда 8541 ва 8542 товар позициялари Номенклатурадаги ҳар қандай товар позициядан устуворликка эга, бу Номенклатура ушбу маҳсулотларни уларнинг функциясига мувофиқ ўз ичига олиши мумкин, 8523 товар позицияси бундан мустасно. Субпозицияларга изоҳлар:","1. 8525 81 субпозицияга фақат бир ёки бир нечта қуйидаги характеристикаларга эга юқори тезликдаги телевизион камералар, рақамли камералар ва ёзиб олувчи видеокамералар киритилади: - ёзиб олиш тезлиги микросекундига 0,5 мм; - вақт бўйича ажратиш 50 наносекунд ёки ундан кам; - кадрлар частотаси секундига 225 000 кадр.","2. 8525 82 субпозициясида радиация даражаси юқори бўлган муҳитда ишлаш имконияти учун ишлаб чиқилган ёки экранланган радиацион-барқарор ёки радиацион-ҳимояланган телевизион камералар, рақамли камералар ва ёзиб олувчи видеокамералар. Бундай камераларнинг конструкцияси радиациянинг умумий дозаси камида 50 х 103 Гр (кремний) (5 х 106 рад (кремний) бўлганда ишчи характеристикалари камаймаган ҳолда қарши туриш имконини беради.","3. 8525 83 субпозициясига ёруғлик кўринадиган тасвирни олиш учун кучайтирилиши ва ўзгартирилиши мумкин бўлган электронларга ўзгартириш учун фотокатоддан фойдаланувчи телевизион камералар, рақамли камералар ва ёзиб олувчи тунги кўриш видеокамералари киритилади. Ушбу субпозицияга тепловизион камералар киритилмайди (қоидага кўра 8525 89 субпозиция).","4. 8527 12 субпозиция фақат ичига кучайтиргич ўрнатилган, ичига овоз кучайтиргич ўрнатилмаган, ташқи электр таъминот манбаидан ишлай оладиган, ўлчами 170 x 100 x 45 мм дан ошмайдиган кассетали плеерларни ўз ичига олади.","5. 8549 11 – 8549 19 субпозицияларида “ишлатилган бирламчи элементлар, ишлатилган бирламчи батареялар ва ишлатилган электр аккумуляторлар” синиши, кесилиши, эскириши ёки бошқа сабаблар оқибатида ёки қайта зарядлаш имкони бўлмаганда улар мўлжалланган сифатда фойдаланиш учун яроқли бўлмаган қурилмаларни билдиради."],"excl":["1. Мазкур гуруҳга қуйидагилар кирмайди: (а) адёл, матрацлар, ёстиқлар, оёқ иситиш грелкаси, электрда иситиладиган ёки ўхшаш маҳсулотлар; кийим, пойабзал ёки наушниклар ёки инсон томонидан ишлатиладиган бошқа электрда иситиладиган предметлар; (б) 7011 товар позициясидаги шиша идишлар; (в) 8486 товар позициясидаги машиналар ва аппаратлар; (г) тиббиёт, жарроҳлик, стоматология ёки ветеринария тадқиқотларида фойдаланиладиган вакуумли аппаратлар (9018 товар позицияси); (д) 94-гуруҳнинг электрда иситиладиган мебеллари.","4. 8509 товар позициясига фақат маиший мақсадларда ишлатиладиган электромеханик машиналарнинг қуйидаги турлари киради: (а) полотерлар, озиқ-овқат майдалагичлари, миксерлар ва мева ёки сабзавотлар учун шарбат чиқаргичлар‚ ҳар қандай вазнга эга; (б) оғирлиги 20 кг дан кўп бўлмаган бошқа машиналар. Бироқ, бу товар позициясига вентиляторлар ёки вентиляция ёки тортувчи рециркуляция колпаклари ёки вентиляторли шкафлар, фильтрли ёки фильтрсиз (8414 товар позицияси), марказдан қочувчи кийим қуриткичлар (8421 товар позицияси), идишларни ювиш машиналари (8422 товар позицияси), маиший кир ювиш машиналари (8450 товар позицияси), роликли ёки бошқа дазмоллаш машиналари (8420 ёки 8451 товар позицияси), тикув машиналари (8452 товар позицияси), электр қайчилар (8467 товар позицияси) ёки электр иситкич приборлари (8516 товар позицияси) киритилмайди","7. 8524 товар позициясида “ясси дисплей панелли модуллар” ифодаси фойдаланишдан аввал бошқа товар позицияларидаги маҳсулотларга ўрнатиш учун конструкцияланган камида дисплей экрани билан жиҳозланган ахборотни акс эттирувчи қурилмалар ёки аппаратларга тегишли. Шаклига кўра бундай модулларнинг дисплей экранлари ясси, букланган, эгилувчан, тахланадиган, чўзиладиган ёки бошқа шаклларда бўлиши мумкин. Ясси дисплей панелли модуллар ўз ичига қўшимча компонентларни, шу жумладан, видеосигналларни қабул қилиш ва уларни экран пикселлари бўйлаб тақсимлаш учун зарур бўлган компонентларни олиши мумкин. Аммо 8524 товар позициясига видеосигналларни қайта ўзгартириш учун мўлжалланган компонентлар (масалан, видеоформатни ўзгартирувчи интеграл схема, декодер интеграл схемаси ёки иловалар процессори) билан жиҳозланган ёки бошқа усул билан товар позицияларидаги маҳсулотлар хусусиятини қабул қилган дисплей модуллари киритилмайди. Ушбу изоҳда кўрсатилган ясси дисплей панели бўлган модулларни таснифлашда 8524 товар позицияси номенклатурадаги ҳар қандай бошқа товар позициясидан устувор бўлади.","10. 8537 товар позициясига телевизион қабул қилгичлар ёки бошқа электр ускуналарини масофадан бошқариш учун мўлжалланган симсиз инфрақизил қурилмалар киритилмайди (8543 товар позицияси).","3. 8525 83 субпозициясига ёруғлик кўринадиган тасвирни олиш учун кучайтирилиши ва ўзгартирилиши мумкин бўлган электронларга ўзгартириш учун фотокатоддан фойдаланувчи телевизион камералар, рақамли камералар ва ёзиб олувчи тунги кўриш видеокамералари киритилади. Ушбу субпозицияга тепловизион камералар киритилмайди (қоидага кўра 8525 89 субпозиция)."]},"86":{"title":"ТЕМИР ЙЎЛ ЛОКОМОТИВЛАРИ ЁКИ ТРАМВАЙ МОТОР ВАГОНЛАРИ, ҲАРАКАТДАГИ ТАРКИБ ВА","section":"XVII","notes":["1. Қуйидагилар ушбу гуруҳга киритилмайди: (а) ёғоч ёки бетондан тайёрланган темир йўл ёки трамвай шпаллари ёхуд ҳаво ёстиғида ҳаракатланадиган поездлар учун йўналиш йўли бетон секциялари (4406 ёки 6810-товар позицияси); (б) 7302-товар позицияси темир йўл ёки трамвай йўллари учун ишлатиладиган қора металлдан тайёрланган маҳсулотлар; ёки (в) 8530-товар позицияси сигнализация электр мосламалари, хавфсизликни таъминлаш ёки ҳаракатни бошқаришни мосламалари.","2. 8607-товар позициясига, inter alia, қуйидагилар киритилади: (а) ғилдираклар ўқлари, ғилдираклар, ғилдирак жуфтлари (ҳаракат қисми), ғилдирак металл бандажлари, ғилдираклар тўғини, гупчаги ва бошқа деталлари; (б) рамалар, рама қисмлари, аравачалар; (в) ғилдираклар ўқи буксалари; тормоз механизмлари; (г) ҳаракатдаги таркиб учун буферлар; илгаклар ва шатакка олиш учун бошқа мосламалар, шунингдек, вагонларни ўзаро боғловчи мосламалар; (д) кузовлар.","3. 1-изоҳ қоидаларига амал қилиш шартига кўра 8608-товар позициясига, inter alia, қуйидагилар киритилади: (а) йиғилган темир йўл полотноси, бурилиш доиралари, тўхтатиш тиргаклари, габаритни текшириш аркалари; (б) семафорлар, механик сигнал дискалари, темир йўл кесишмаларида ҳаракатни механик бошқариш мосламалари, сигналлар ва ўтказгичларни бошқариш механизмлари ва электр ёритиш билан жиҳозланган ёки жиҳозланмаган бўлишидан қатъи назар темир йўллар, трамвай йўллари, автомобиль йўллари, ички сув йўллари, тўхтаб туриш иншоотлари, портлар ёки аэродромлар учун бошқа механик (шу жумладан электромеханик) сигнал ускуналари, хавфсизликни таъминлаш ёки ҳаракатни бошқариш мосламалари"],"excl":["1. Қуйидагилар ушбу гуруҳга киритилмайди: (а) ёғоч ёки бетондан тайёрланган темир йўл ёки трамвай шпаллари ёхуд ҳаво ёстиғида ҳаракатланадиган поездлар учун йўналиш йўли бетон секциялари (4406 ёки 6810-товар позицияси); (б) 7302-товар позицияси темир йўл ёки трамвай йўллари учун ишлатиладиган қора металлдан тайёрланган маҳсулотлар; ёки (в) 8530-товар позицияси сигнализация электр мосламалари, хавфсизликни таъминлаш ёки ҳаракатни бошқаришни мосламалари."]},"87":{"title":"ЕР УСТИ ТРАНСПОРТ ВОСИТАЛАРИ: ТЕМИР ЙЎЛ ЁКИ ТРАМВАЙ ҲАРАКАТЛАНУВЧИ ТАРКИБИДАН","section":"XVII","notes":["1. Фақат рельслар бўйлаб ҳаракатланиш учун мўлжалланган темир йўл ёки трамвайга оид ҳаракатланувчи таркиб ушбу гуруҳга киритилмайди.","2. Ушбу гуруҳда “тракторлар” атамаси, асосан бошқа транспорти воситалари, қурилмалар ёки юкларни шатакка олиб тортиш ёки итариш учун мўлжалланган транспорт воситаларини англатади, бунда тракторнинг асосий мақсади билан бирга, улар асбоб-ускуналар, уруғлик, ўғит ёки бошқа юкларни ташиш учун мўлжалланган қўшимча мосламаларга эга ёки эга эмаслигидан қатъи назар. Алмаштириладиган ускуналар сифатида 8701 товар позициясидаги тракторларга ўрнатиш учун лойиҳалаштирилган механизмлар ва ишчи асбоблар тегишли товар позицияларига киритилади, ҳатто улар тракторлар билан бирга тақдим этилган ҳолларда ҳам, тракторларга ўрнатилган ёки ўрнатилмаганлигидан қатъи назар.","3. Кабинаси билан бирга бўлган автомобил шассилари 8702 – 8704 товар позицияларига киритилади, 8706 товар позициясига эмас.","4. 8712 товар позициясига барча икки ғилдиракли болалар велосипедлари киритилади. Бошқа турдаги болалар велосипедлари 9503 товар позициясига киритилади. Субпозицияга изоҳ:","1. 8708 22 субпозициясига қуйидагилар киритилади: (а) шамолга қарши олд тараф ойналари (“пешона” ойналари), рамка ичига ўрнатилган орқа тараф ва бошқа ойналар; ва (б) шамолга қарши олд тараф ойналари (“пешона” ойналари), рамка ичига ўрнатилган ва ўрнатилмаган, иситиш қурилмалари ёки бошқа электр ёки электрон қурилмалари бўлган орқа тараф ва бошқа ойналар; фақат ёки асосан 8701 – 8705 товар позицияларидаги моторли транспорт воситаларида ишлатиладиганлар."],"excl":["1. Фақат рельслар бўйлаб ҳаракатланиш учун мўлжалланган темир йўл ёки трамвайга оид ҳаракатланувчи таркиб ушбу гуруҳга киритилмайди."]},"88":{"title":"УЧИШ АППАРАТЛАРИ, КОСМИК АППАРАТЛАР ВА УЛАРНИНГ ҚИСМЛАРИ","section":"XVII","notes":[],"excl":[]},"89":{"title":"КЕМАЛАР, ҚАЙИҚЛАР ВА СУЗУВЧИ ҚУРИЛМАЛАР","section":"XVII","notes":[],"excl":[]},"90":{"title":"ОПТИК, ФОТОГРАФИК, КИНЕМАТОГРАФИК, ЎЛЧОВ, НАЗОРАТ, АНИҚЛИК, ТИББИЙ ЁКИ","section":"XVIII","notes":["1. Ушбу гуруҳга қуйидагилар киритилмайди: (а) машиналарда, мосламаларда ёки бошқа техник мақсадлар учун ишлатиладиган, вулканизацияланган резинадан, қаттиқ резинадан ташқари (4016 товар позицияси), табиий ёки композит теридан (4205 товар позицияси) ёки тўқимачилик материалларидан (5911 товар позицияси) тайёрланган буюмлар; (б) тутиб туриладиган ёки қўзғалмас ҳолатдаги органга мақсадли таъсири фақат ўзининг эластиклиги туфайли амалга ошириладиган, тўқимачлик материалларидан тайёрланган тутиб турувчи камарлар ёки бошқа таянч буюмлар (масалан, ҳомиладор аёллар учун бандажлар, кўкрак бандажлари, қорин учун бандажлар, бўғим ёки мушаклар фиксаторлари) (ХI бўлим); (в) 6903 товар позициядаги ўтга чидамли маҳсулотлар; 6909 товар позициядаги лаборатория, кимёвий ёки бошқа техник мақсадлар учун керамика буюмлари; (г) 7009 товар позициядаги оптик ишлов берилмаган шиша ойналар ёки оптик элементлардан ташқари асосий ёки қимматбаҳо металлардан ясалган нометаллар (8306 товар позиция ёки 71–гуруҳ); (д) 7007, 7008, 7011, 7014, 7015 ёки 7017 товар позицияларидаги товарлар; (е) ХV бўлимдаги изоҳларнинг 2–бандида кўрсатилган, ноқимматбаҳо металлардан (ХV бўлим) ёки пластмассадан тайёрланган (39–гуруҳ) умумий фойдаланиш қисмлари; бироқ, фақат тиббиёт, жарроҳлик, стоматология ёки ветеринарияда қўллаш учун мўлжалланган имплантларда фойдаланиш учун махсус мўлжалланган буюмлар 9021 товар позициясида таснифланиши керак; (ж) 8413 товар позициядаги ўлчов асбоблари бўлган насослар; тортилиши керак бўлган юкнинг оғирлиги билан ишлайдиган ҳисоблаш ёки назорат қилиш ускуналари ёки алоҳида етказиб бериладиган тарози тошлари (8423 товар позицияси); кўтариш ёки юклаш–тушириш ускуналари (8425 – 8428 товар позициялари); қоғоз ёки картонни кесиш учун барча турдаги машиналар (8441 товар позицияси); 8466 товар позициясидаги станокларда ёки сув оқими билан кесиш дастгоҳларида ишлов бериладиган қисмлар ёки асбобларнинг ҳолатини созлаш учун мосламалар, шу жумладан асбобларнинг кўрсаткичларини ўқиш учун оптик элементлари бўлган мосламалар (масалан, “оптик” бўлиниш бошлари), лекин ўзлари соф оптик қурилма бўлган мосламалар бундан мустасно (масалан, созлаш телескоплари); ҳисоблаш машиналари (8470 товар позицияси); 8481 товар позициясидаги клапанлар ва бошқа арматура; 8486 товар позициясининг машиналари ва аппаратлари (шу жумладан, сезгир ярим ўтказгичли материалларга ниқобларни чизиш ёки нақшлаш учун асбоблар); (з) велосипедлар ёки автотранспорт воситаларида ишлатиладиган прожекторлар ёки лампалар (8512 товар позицияси); 8513 товар позициясидаги портатив электр лампалар; товушни ёзиш, такрорлаш ёки қайта ёзиш учун кинематографик аппаратлар (8519 товар позицияси); товуш бошлари (8522 товар позицияси); телекамералар, рақамли камералар ва видеорегистраторлар (8525 товар позицияси); радар ускуналари, радионавигация ускуналари ёки масофадан бошқариладиган радио жиҳозлари (8526 товар позицияси); оптик толалар, оптик толали тўпламлар ёки кабеллар учун улагичлар (8536 товар позицияси); 8537 товар позициясидаги рақамли бошқарув аппарати; 8539–позициядаги муҳрланган йўналишли лампалар; 8544 товар позициясидаги оптик толали кабеллар; (и) 9405 товар позициясидаги прожекторлар ёки фаралар; (к) 95–гуруҳнинг моддалари; (л) 9620 товар позициясидаги якка таянчлар, икки оёқлар, уч оёқлар ва шунга ўхшаш буюмлар: (м) ўзи тайёрланган материалга қараб таснифланадиган ҳажмни ўлчаш учун идишлар; ёки (н) ғалтаклар, бобиналар ёки шунга ўхшаш ташувчилар (улар ўзи тайёрланган материалга кўра таснифланиши керак, масалан, 3923 товар позициясида ёки XV бўлимда).","2. 1–изоҳ талабларига риоя этилган ҳолда, ушбу гуруҳга киритилган машиналар, аппаратлар, асбоблар ёки буюмларнинг қисмлари ва жихозлари қуйидаги қоидаларга мувофиқ таснифланади: (а) ушбу гуруҳнинг ёки 84, 85 ёки 91–гуруҳларнинг (8487, 8548 ёки 9033 товар позицияларидан ташқари) товар позицияларидан бирига киритилган товар ҳисобланувчи қисмлар ва жиҳозлар барча ҳолларда тегишли товар позицияларида таснифланади; (б) эксклюзив ёки, асосан, маълум турдаги машиналар, асбоблар ёки қурилмаларда ёки бир товар позициясининг бир нечта машиналари, асбоблари ёки аппаратларида (жумладан, 9010, 9013 ёки 9031 товар позициясидаги машиналар, асбоблар ёки аппаратлар) фойдаланиш учун мўлжалланган бошқа қисмлар ва жиҳозлари, ушбу машиналар, асбоблар ёки қурилмаларга киритилган; (в) барча бошқа қисмлар ва жиҳозлар 9033 товар позициясига киритилган.","3. XVI бўлимдаги изохларнинг 3–чи ва 4–бандлари талаблари ушбу гуруҳга ҳам татбиқ этилади.","4. 9005 товар позициясига қуролларга ўрнатиш учун телескопик нишонлар, сув ости кемалари ёки танклар учун телескопик перископлар ёки ушбу гуруҳнинг ёки XVI бўлимнинг машиналари, қурилмалари, мосламалари ёки асбобларига ўрнатилган аниқловчи объектлар кирмайди; бундай телескопик нишонлар ва кўриш қувурлари 9013 товар позицияга киритилади.","5. Агар ушбу изоҳ бўлмаган тақдирда, ҳам 9013 товар позициясига ҳам 9031 товар позициясига киритиш мумкин бўлган ўлчаш ёки текшириш оптик асбоблари, мосламалар ёки машиналар 9031 товар позициясига киритилади.","6. 9021 товар позициясидаги “ортопедия мослама” атамаси қуйидагилар учун мосламани англатади: – тана деформациясининг олдини олиш ёки тузатиш; ёки – касаллик, жарроҳлик ёки жароҳатлардан кейин тана қисмларини қўллаб–қувватлаш ёки тузатиш. Ортопедик мосламаларга, агар улар (1) буюртма асосида ишлаб чиқарилган ёки (2) оммавий ишлаб чиқарилган бўлса, жуфт бўлиб эмас, бир бўлакда тақдим этилган ва ҳар қандай оёқ учун бир хил даражада мос келадиган тарзда ишлаб чиқарилган бўлса, ортопедик шароитларни тузатиш учун тайёрланган поябзал ва махсус ички тагликларни ўз ичига олади. 9032 товар позициясига фақат қуйидагилар киради: (а) суюқликлар ёки газларнинг оқимини, даражасини, босимини ёки бошқа ўзгарувчан параметрларини автоматик бошқариш, ёки ҳароратни автоматик бошқариш учун асбоблар ва қурилмалар, уларнинг ишлашини назорат қиладиган параметрга мувофиқ ўзгарувчан электр ҳодисасига асосланганми ёки йўқми, бу параметрни керакли қийматга етказиш ва уни ушлаб туриш, барқарорлаштириш, доимий ёки бузилишларга қарши барқарорлаштириш, доимий ёки вақти–вақти билан ҳақиқий қийматни ўлчаш учун мўлжалланган; ва (б) электр катталикларининг автоматик регуляторлари ва электр бўлмаган катталикларни автоматик тартибга солиш учун асбоблар ёки қурилмалар, уларнинг ишлаши бошқариладиган параметрга қараб ўзгариб турадиган электр ҳодисасига асосланган бўлиб, улар ушбу параметрни керакли қийматга етказиш учун мўлжалланган ва доимий ёки вақти–вақти билан ҳақиқий қийматни ўлчаб, бузилишларга қарши барқарорликни сақлаш."],"excl":["1. Ушбу гуруҳга қуйидагилар киритилмайди: (а) машиналарда, мосламаларда ёки бошқа техник мақсадлар учун ишлатиладиган, вулканизацияланган резинадан, қаттиқ резинадан ташқари (4016 товар позицияси), табиий ёки композит теридан (4205 товар позицияси) ёки тўқимачилик материалларидан (5911 товар позицияси) тайёрланган буюмлар; (б) тутиб туриладиган ёки қўзғалмас ҳолатдаги органга мақсадли таъсири фақат ўзининг эластиклиги туфайли амалга ошириладиган, тўқимачлик материалларидан тайёрланган тутиб турувчи камарлар ёки бошқа таянч буюмлар (масалан, ҳомиладор аёллар учун бандажлар, кўкрак бандажлари, қорин учун бандажлар, бўғим ёки мушаклар фиксаторлари) (ХI бўлим); (в) 6903 товар позициядаги ўтга чидамли маҳсулотлар; 6909 товар позициядаги лаборатория, кимёвий ёки бошқа техник мақсадлар учун керамика буюмлари; (г) 7009 товар позициядаги оптик ишлов берилмаган шиша ойналар ёки оптик элементлардан ташқари асосий ёки қимматбаҳо металлардан ясалган нометаллар (8306 товар позиция ёки 71–гуруҳ); (д) 7007, 7008, 7011, 7014, 7015 ёки 7017 товар позицияларидаги товарлар; (е) ХV бўлимдаги изоҳларнинг 2–бандида кўрсатилган, ноқимматбаҳо металлардан (ХV бўлим) ёки пластмассадан тайёрланган (39–гуруҳ) умумий фойдаланиш қисмлари; бироқ, фақат тиббиёт, жарроҳлик, стоматология ёки ветеринарияда қўллаш учун мўлжалланган имплантларда фойдаланиш учун махсус мўлжалланган буюмлар 9021 товар позициясида таснифланиши керак; (ж) 8413 товар позициядаги ўлчов асбоблари бўлган насослар; тортилиши керак бўлган юкнинг оғирлиги билан ишлайдиган ҳисоблаш ёки назорат қилиш ускуналари ёки алоҳида етказиб бериладиган тарози тошлари (8423 товар позицияси); кўтариш ёки юклаш–тушириш ускуналари (8425 – 8428 товар позициялари); қоғоз ёки картонни кесиш учун барча турдаги машиналар (8441 товар позицияси); 8466 товар позициясидаги станокларда ёки сув оқими билан кесиш дастгоҳларида ишлов бериладиган қисмлар ёки асбобларнинг ҳолатини созлаш учун мосламалар, шу жумладан асбобларнинг кўрсаткичларини ўқиш учун оптик элементлари бўлган мосламалар (масалан, “оптик” бўлиниш бошлари), лекин ўзлари соф оптик қурилма бўлган мосламалар бундан мустасно (масалан, созлаш телескоплари); ҳисоблаш машиналари (8470 товар позицияси); 8481 товар позициясидаги клапанлар ва бошқа арматура; 8486 товар позициясининг машиналари ва аппаратлари (шу жумладан, сезгир ярим ўтказгичли материалларга ниқобларни чизиш ёки нақшлаш учун асбоблар); (з) велосипедлар ёки автотранспорт воситаларида ишлатиладиган прожекторлар ёки лампалар (8512 товар позицияси); 8513 товар позициясидаги портатив электр лампалар; товушни ёзиш, такрорлаш ёки қайта ёзиш учун кинематографик аппаратлар (8519 товар позицияси); товуш бошлари (8522 товар позицияси); телекамералар, рақамли камералар ва видеорегистраторлар (8525 товар позицияси); радар ускуналари, радионавигация ускуналари ёки масофадан бошқариладиган радио жиҳозлари (8526 товар позицияси); оптик толалар, оптик толали тўпламлар ёки кабеллар учун улагичлар (8536 товар позицияси); 8537 товар позициясидаги рақамли бошқарув аппарати; 8539–позициядаги муҳрланган йўналишли лампалар; 8544 товар позициясидаги оптик толали кабеллар; (и) 9405 товар позициясидаги прожекторлар ёки фаралар; (к) 95–гуруҳнинг моддалари; (л) 9620 товар позициясидаги якка таянчлар, икки оёқлар, уч оёқлар ва шунга ўхшаш буюмлар: (м) ўзи тайёрланган материалга қараб таснифланадиган ҳажмни ўлчаш учун идишлар; ёки (н) ғалтаклар, бобиналар ёки шунга ўхшаш ташувчилар (улар ўзи тайёрланган материалга кўра таснифланиши керак, масалан, 3923 товар позициясида ёки XV бўлимда).","2. 1–изоҳ талабларига риоя этилган ҳолда, ушбу гуруҳга киритилган машиналар, аппаратлар, асбоблар ёки буюмларнинг қисмлари ва жихозлари қуйидаги қоидаларга мувофиқ таснифланади: (а) ушбу гуруҳнинг ёки 84, 85 ёки 91–гуруҳларнинг (8487, 8548 ёки 9033 товар позицияларидан ташқари) товар позицияларидан бирига киритилган товар ҳисобланувчи қисмлар ва жиҳозлар барча ҳолларда тегишли товар позицияларида таснифланади; (б) эксклюзив ёки, асосан, маълум турдаги машиналар, асбоблар ёки қурилмаларда ёки бир товар позициясининг бир нечта машиналари, асбоблари ёки аппаратларида (жумладан, 9010, 9013 ёки 9031 товар позициясидаги машиналар, асбоблар ёки аппаратлар) фойдаланиш учун мўлжалланган бошқа қисмлар ва жиҳозлари, ушбу машиналар, асбоблар ёки қурилмаларга киритилган; (в) барча бошқа қисмлар ва жиҳозлар 9033 товар позициясига киритилган.","4. 9005 товар позициясига қуролларга ўрнатиш учун телескопик нишонлар, сув ости кемалари ёки танклар учун телескопик перископлар ёки ушбу гуруҳнинг ёки XVI бўлимнинг машиналари, қурилмалари, мосламалари ёки асбобларига ўрнатилган аниқловчи объектлар кирмайди; бундай телескопик нишонлар ва кўриш қувурлари 9013 товар позицияга киритилади."]},"91":{"title":"БАРЧА ТУРДАГИ СОАТЛАР ВА УЛАРНИНГ ҚИСМЛАРИ","section":"XVIII","notes":["1. Ушбу гуруҳга қуйидагилар кирмайди: (а) барча турдаги соат ойнаклари ёки гири (ишлаб чиқарилган материалига қараб таснифланадиганлар); (б) соат занжирлари (аниқ ҳолатга боғлиқ ҳолда 7113 ёки 7117 товар позицияларида); (в) ноқимматбаҳо металлардан (XV бўлим) ёки пластмассадан тайёрланган (39–гуруҳ) ёҳуд қимматбаҳо металлардан ёки сирти қимматбаҳо металл билан қопланган бошқа металлардан тайёрланган (одатда 7115–товар позицияси), XV бўлим изоҳларининг 2–бандида кўрсатилган умумий мақсадлар учун қисмлар; бироқ, соат пружиналари барча турдаги соатларнинг бир қисми сифатида таснифланади (9114 товар позицияси); (г) шарикли подшипниклар учун шариклар (материалига қараб 7326 ёки 8482 товар позицияси); (д) лангар механизмисиз ишлашга мўлжалланган 8412 товар позициядаги буюмлар; (е) шарикли подшипниклар (8482 товар позицияси); ёки (ж) 85–гуруҳнинг буюмлари, ҳали бирга ёки бошқа компонентлар билан соат механизмларига ёхуд фақат ёки асосан бундай механизмларнинг қисмлари сифатида фойдаланишга мўлжалланган буюмларга йиғилмаган (85–гурух).","2. 9101 товар позициясига фақат ўзига тақиб юриш ёки ўзида олиб юриш учун мўлжалланган, корпуси қимматбаҳо металлдан ясалган ёки қимматбаҳо металлар билан қопланган металлдан ёки 7101 – 7104 товар позицияларидаги табиий, маданий марваридлар, қимматбаҳо ёки ярим қимматбаҳо тошлар (табиий, сунъий ёки реконструкция қилинган) билан тайёрланган соатлар киритилади. Ўзига тақиб юриш ёки ўзида олиб юриш учун мўлжалланган, корпуси ноқимматбаҳо металлдан тайёрланган, қимматбаҳо металлар билан инкрустацияланган соатлар 9102 товар позициясига киритилади.","3. Ушбу гуруҳда “ўзига тақиб юриш ёки ўзида олиб юриш учун мўлжалланган соатлар учун соат механизмлари” атамаси ишлаши баланс–спираль тизими, кварц осцилятори ёхуд индикаторли ёки механик индикатор ўрнатиш мумкин бўлган тизимли вақт оралиғини белгиловчи бошқа тизим билан тартибга солинадиган қурилмаларни англатади. Бундай соат механизмларининг қалинлиги 12 мм дан, кенглиги, узунлиги ёки диаметри эса 50 мм дан ортиқ бўлмаслиги керак.","4. Ҳам барча турдаги соатларда ҳам бошқа буюмларда (масалан, прецизион асбобларда) фойдаланиш учун мўлжалланган соатлар механизмлари ва бошқа қисмлар ушбу гуруҳга киритилади, 1–изоҳда кўрсатилган ҳоллар мустасно."],"excl":["1. Ушбу гуруҳга қуйидагилар кирмайди: (а) барча турдаги соат ойнаклари ёки гири (ишлаб чиқарилган материалига қараб таснифланадиганлар); (б) соат занжирлари (аниқ ҳолатга боғлиқ ҳолда 7113 ёки 7117 товар позицияларида); (в) ноқимматбаҳо металлардан (XV бўлим) ёки пластмассадан тайёрланган (39–гуруҳ) ёҳуд қимматбаҳо металлардан ёки сирти қимматбаҳо металл билан қопланган бошқа металлардан тайёрланган (одатда 7115–товар позицияси), XV бўлим изоҳларининг 2–бандида кўрсатилган умумий мақсадлар учун қисмлар; бироқ, соат пружиналари барча турдаги соатларнинг бир қисми сифатида таснифланади (9114 товар позицияси); (г) шарикли подшипниклар учун шариклар (материалига қараб 7326 ёки 8482 товар позицияси); (д) лангар механизмисиз ишлашга мўлжалланган 8412 товар позициядаги буюмлар; (е) шарикли подшипниклар (8482 товар позицияси); ёки (ж) 85–гуруҳнинг буюмлари, ҳали бирга ёки бошқа компонентлар билан соат механизмларига ёхуд фақат ёки асосан бундай механизмларнинг қисмлари сифатида фойдаланишга мўлжалланган буюмларга йиғилмаган (85–гурух)."]},"92":{"title":"МУСИҚА АСБОБЛАРИ; УЛАРНИНГ ҚИСМЛАРИ ВА ЖИҲОЗЛАРИ","section":"XVIII","notes":["1. Мазкур гуруҳга киритилмайди: (а) XV бўлим изоҳларининг 2-бандида кўрсатилган ноқимматбаҳо металлардан тайёрланган умумий мақсад учун қисмлар (XV бўлим), ёки пластмассадан тайёрланган шу каби товарлар (39-гуруҳ); (б) 85 ёки 90-гуруҳларнинг мазкур гуруҳга киритиладиган асбоблари билан бирга ишлатиш учун мўлжалланган, лекин улар билан бирлаштирилмаган ёки бу асбоблар билан битта корпусга ўрнатилмаган аппаратура ва ускуналар, микрофонлар, овоз кучайтиргичлар, радиокарнайлар, асосий телефонлар, электр токи йўналишини ўзгартирувчилар, стробоскоплар ва бошқа ёрдамчи қурилмалар; (в) ўйинчоқ мусиқа асбоблари ва қурилмалари (9503 товар позицияси); (г) мусиқа асбобларини тозалаш учун чўткалар (9603 товар позицияси) ёки моно- тиргаклар, икки оёқ, уч оёқ ва ўхшаш буюмлар (9620 товар позицияси); ёки (д) коллекция ёки антиквариат предметлари (9705 ёки 9706 товар позицияси).","2. 9202 ёки 9206 товар позициясининг мусиқа асбобларидаги ўйинлар учун ишлатиладиган камонча ва таёқчалар, бундай мусиқа асбоблари билан зарур бўлган миқдорда тақдим этиладиган ва чамаси улар билан ишлатишга мўлжалланган камонча ва таёқчалар тегишли мусиқа асбоблари киритилган товар позициясига киритилади. 9209 товар позициясининг мусиқа асбоблари билан тақлим этилган карталар, дисклар ва валиклар кўрсатилган мусиқа асбобларининг таркибий қисми бўлмаган мустақил буюмлар ҳисобланади. Қўшим ча"],"excl":["1. Мазкур гуруҳга киритилмайди: (а) XV бўлим изоҳларининг 2-бандида кўрсатилган ноқимматбаҳо металлардан тайёрланган умумий мақсад учун қисмлар (XV бўлим), ёки пластмассадан тайёрланган шу каби товарлар (39-гуруҳ); (б) 85 ёки 90-гуруҳларнинг мазкур гуруҳга киритиладиган асбоблари билан бирга ишлатиш учун мўлжалланган, лекин улар билан бирлаштирилмаган ёки бу асбоблар билан битта корпусга ўрнатилмаган аппаратура ва ускуналар, микрофонлар, овоз кучайтиргичлар, радиокарнайлар, асосий телефонлар, электр токи йўналишини ўзгартирувчилар, стробоскоплар ва бошқа ёрдамчи қурилмалар; (в) ўйинчоқ мусиқа асбоблари ва қурилмалари (9503 товар позицияси); (г) мусиқа асбобларини тозалаш учун чўткалар (9603 товар позицияси) ёки моно- тиргаклар, икки оёқ, уч оёқ ва ўхшаш буюмлар (9620 товар позицияси); ёки (д) коллекция ёки антиквариат предметлари (9705 ёки 9706 товар позицияси)."]},"93":{"title":"ҚУРОЛ ВА ЎҚ-ДОРИЛАР; УЛАРНИНГ ҚИСМ ВА ЖИҲОЗЛАРИ","section":"XIX","notes":["1. Мазкур гуруҳга қуйидагилар кирмайди: (а) 36-бўлимнинг товарлари (мисол учун зарбдор капсулалар, детонаторлар, сигнал ракеталари); (б) XV бўлимнинг 2 изоҳ қисмида кўрсатилган қимматбаҳо бўлмаган металлдан умумий фойдаланиш учун ишлатиладиган қисмлар ёки пластмассадан тайёрланган шунга ўхшаш қисмлар (гуруҳ 39); (в) жанговар ўзиюрар зирҳли транспорт воситалари (товар позиция 8710); (г) телескопик нишонгич ёки қурол билан ишлатиш учун мос бўлган бошқа оптик ускуналар, агар улар ўқотар қуролга ўрнатилмаган бўлса ёки улар ўрнатилиши керак бўлган ўқотар қурол билан бирга тақдим этилмаган бўлса (гуруҳ 90); (д) камон, камон ўқлари, қиличбозлик рапиралари ёки ўйинчоқ қуроллар (гуруҳ 95); ёки (е) коллекция буюмлари ёки антиквар буюмлар (товар позиция 9705 ёки 9706).","2. 9306-товар позициясида “қисмларга” қилинган ҳавола 8526-товар позициясининг радио ёки радиолокацион ускуналарга тааллуқли эмас."],"excl":["1. Мазкур гуруҳга қуйидагилар кирмайди: (а) 36-бўлимнинг товарлари (мисол учун зарбдор капсулалар, детонаторлар, сигнал ракеталари); (б) XV бўлимнинг 2 изоҳ қисмида кўрсатилган қимматбаҳо бўлмаган металлдан умумий фойдаланиш учун ишлатиладиган қисмлар ёки пластмассадан тайёрланган шунга ўхшаш қисмлар (гуруҳ 39); (в) жанговар ўзиюрар зирҳли транспорт воситалари (товар позиция 8710); (г) телескопик нишонгич ёки қурол билан ишлатиш учун мос бўлган бошқа оптик ускуналар, агар улар ўқотар қуролга ўрнатилмаган бўлса ёки улар ўрнатилиши керак бўлган ўқотар қурол билан бирга тақдим этилмаган бўлса (гуруҳ 90); (д) камон, камон ўқлари, қиличбозлик рапиралари ёки ўйинчоқ қуроллар (гуруҳ 95); ёки (е) коллекция буюмлари ёки антиквар буюмлар (товар позиция 9705 ёки 9706).","2. 9306-товар позициясида “қисмларга” қилинган ҳавола 8526-товар позициясининг радио ёки радиолокацион ускуналарга тааллуқли эмас."]},"94":{"title":"МЕБЕЛЬ; ТЎШАК БУЮМЛАРИ, МАТРАСЛАР, МАТРАС МАҒЗЛАРИ, ДИВАН ЁСТИҚЛАРИ ВА","section":"XX","notes":["1. Мазкур гуруҳга киритилмайди: (а) ҳавога тўлдирилган матраслар ёки сувли матраслар, 39, 40 ёки 63 гуруҳлардаги ёстиқ ёки диван ёстиқлари; (б) 7009 товар позициясидаги полга ёки ерга ўрнатиш учун мўлжалланган кўзгулар (масалан, ҳаракатланувчан ромга ўрнатилган кўзгулар (псише – айланувчан кўзгулар)); (в) 71-гуруҳ буюмлари; (г) XV бўлим изоҳларининг 2-бандида кўрсатилган ноқимматбаҳо металлардан тайёрланган умумий мақсад учун қисмлар (XV бўлим), ёки пластмассадан тайёрланган шу каби қисмлар (39-гуруҳ), ёки 8303 товар позициясидаги сейфлар; (д) 8418 товар позициясида совутиш ёки музлатиш ускуналари қисми сифатида махсус лойиҳа асосида ишлаб чиқарилган мебель; тикув машиналари учун махсус лойиҳа асосида ишлаб чиқарилган мебель (8452 товар позицияси); (е) 85-гуруҳдаги чироқлар ёки ёритиш манбалари ва уларнинг қисмлари; (ж) 8518 товар позициясидаги (8518 товар позицияси), 8519 ёки 8521 товар позициясидаги (8522 товар позицияси) ёки 8525 – 8528 товар позицияларидаги (8529 товар позицияси) ускуналарнинг қисми сифатида махсус лойиҳа асосида ишлаб чиқарилган мебель; (з) 8714 товар позициясидаги буюмлар; (и) 9018 товар позициясидаги стоматологик ускуналар ёки стоматологик тупдонлар билан жиҳозланган стоматологик креслолар (9018 товар позицияси); (к) 91-гуруҳ буюмлари (масалан, соатлар ва соат қисмлари); (л) ўйинчоқ мебель ёки ўйинчоқ лампалар ва ўйинчоқ ёритиш ускуналари (9503 товар позицияси), биллярд столлари ёки ўйин учун махсус мўлжалланган бошқа мебеллар (9504 товар позицияси), фокуслар учун ёки безатиш учун буюмлар (ёруғлик гирляндларидан ташқари) масалан Хитой фонариклари каби (9505 товар позицияси); ёки (м) бир таянч оёқли, жуфт оёқли, уч оёқли ва шунга ўхшаш буюмлар (9620 товар позицияси).","2. 9401 – 9403 товар позицияларидаги товарлар (уларнинг қисмларидан ташқари) фақат агар улар полга ёки ерга ўрнатишга мўлжалланган бўлсагина ушбу товар позицияларига киритилади. (а) идиш шкафлари ва китоб жавонлари, жавонли бошқа мебеллар (деворга маҳкамлаш учун маҳкамлагичлар билан жиҳозланадиган алоҳида мебеллар) ва махсус бўлмали мебеллар; (б) ўтириш учун мебеллар ва каравотлар.","3. (А) 9401 – 9403 товар позицияларида товарлар қисмларига ҳаволалар шиша (шу жумладан кўзгу), мармар ёки бошқа тошлар ёки 68 ёки 69-гуруҳларда кўрсатилган бошқа материаллар (шакл бўйича кесилган ёки кесилмаган бироқ бошқа қисмлар билан бирлаштирилмаган) бўлаклари ёки пластиналарига ҳаволаларни ўз ичига олмайди. (Б) 9404 товар позициясининг алоҳида кўрсатилган буюмлари 9401, 9402 ёки 9403 товар позицияларига товар қисмлари сифатида киритилмаслиги керак.","4. 9406 товар позициясида “йиғма қурилиш конструкциялари” атамаси корхонада тўлиқ тайёрланган ёки жойида йиғиладиган қисмлар тўплами сифатида етказиб бериладиган қурилмалар, масалан турар жой ёки ишлаб чиқариш бинолари, идоралар, мактаблар, дўконлар, айвонлар, гаражлар ёки ўхшаш қурилмаларни ифодалайди. “Йиғма қурилиш конструкциялари” таркибига одатда стандарт транспорт контейнери ўлчами ва шаклига эга бўлган, ички ускуналари билан олдиндан асосан ёки тўлиқ жиҳозланган пўлат “модулли қурилиш блоклари” киради. Бундай модулли қурилиш блоклари одатда бир-бири билан йиғишга мўлжалланган бўлиб, натижада стационар қурилмалар вужудга келади."],"excl":["1. Мазкур гуруҳга киритилмайди: (а) ҳавога тўлдирилган матраслар ёки сувли матраслар, 39, 40 ёки 63 гуруҳлардаги ёстиқ ёки диван ёстиқлари; (б) 7009 товар позициясидаги полга ёки ерга ўрнатиш учун мўлжалланган кўзгулар (масалан, ҳаракатланувчан ромга ўрнатилган кўзгулар (псише – айланувчан кўзгулар)); (в) 71-гуруҳ буюмлари; (г) XV бўлим изоҳларининг 2-бандида кўрсатилган ноқимматбаҳо металлардан тайёрланган умумий мақсад учун қисмлар (XV бўлим), ёки пластмассадан тайёрланган шу каби қисмлар (39-гуруҳ), ёки 8303 товар позициясидаги сейфлар; (д) 8418 товар позициясида совутиш ёки музлатиш ускуналари қисми сифатида махсус лойиҳа асосида ишлаб чиқарилган мебель; тикув машиналари учун махсус лойиҳа асосида ишлаб чиқарилган мебель (8452 товар позицияси); (е) 85-гуруҳдаги чироқлар ёки ёритиш манбалари ва уларнинг қисмлари; (ж) 8518 товар позициясидаги (8518 товар позицияси), 8519 ёки 8521 товар позициясидаги (8522 товар позицияси) ёки 8525 – 8528 товар позицияларидаги (8529 товар позицияси) ускуналарнинг қисми сифатида махсус лойиҳа асосида ишлаб чиқарилган мебель; (з) 8714 товар позициясидаги буюмлар; (и) 9018 товар позициясидаги стоматологик ускуналар ёки стоматологик тупдонлар билан жиҳозланган стоматологик креслолар (9018 товар позицияси); (к) 91-гуруҳ буюмлари (масалан, соатлар ва соат қисмлари); (л) ўйинчоқ мебель ёки ўйинчоқ лампалар ва ўйинчоқ ёритиш ускуналари (9503 товар позицияси), биллярд столлари ёки ўйин учун махсус мўлжалланган бошқа мебеллар (9504 товар позицияси), фокуслар учун ёки безатиш учун буюмлар (ёруғлик гирляндларидан ташқари) масалан Хитой фонариклари каби (9505 товар позицияси); ёки (м) бир таянч оёқли, жуфт оёқли, уч оёқли ва шунга ўхшаш буюмлар (9620 товар позицияси).","2. 9401 – 9403 товар позицияларидаги товарлар (уларнинг қисмларидан ташқари) фақат агар улар полга ёки ерга ўрнатишга мўлжалланган бўлсагина ушбу товар позицияларига киритилади. (а) идиш шкафлари ва китоб жавонлари, жавонли бошқа мебеллар (деворга маҳкамлаш учун маҳкамлагичлар билан жиҳозланадиган алоҳида мебеллар) ва махсус бўлмали мебеллар; (б) ўтириш учун мебеллар ва каравотлар."]},"95":{"title":"ЎЙИНЧОҚЛАР, ЎЙИНЛАР ВА СПОРТ ИНВЕНТАРИ; УЛАРНИНГ ҚИСМЛАРИ ВА ЖИҲОЗЛАРИ","section":"XX","notes":["1. Ушбу гуруҳга қуйидагилар киритилмайди: (а) шамлар (3406 товар позицияси); (б) 3604 товар позициясидаги мушакбозлик ёки бошқа пиротехник буюмлари; (в) йигирилган иплар, моноиплар, шнурлар ёки торлар (струна) ёки балиқ ови учун маълум узунликка эга бўлган, бироқ 39-гуруҳ, 4206 товар позицияси ёки XI бўлимга кирувчи балиқ ови учун чилвир шаклида тайёрланмаган шунга ўхшаш буюмлар; (г) спорт сумкалари ёки 4202, 4303 ёки 4304 товар позицияларининг бошқа буюмлари; (д) тўқимачилик материалларидан тайёрланган маскарад либослари (61 ёки 62-гуруҳ), спорт кийимлари ва тўқимачилик материалларидан тайёрланган махсус кийимлар (61 ёки 62-гуруҳлар) хусусан, тирсак сохасида тўлдирилган қатламли ямоқлар каби химоя қисмларига эга бўлган ёки бўлмаган, тиззалар ёки чов қисмида ҳимоя компонентларига эга бўлган ёки эга бўлмаган махсус предметлари (масалан, қиличбозлик кийимлари ёки футбол дарвозабонларининг свитерлари); (е) тўқимачилик материалларидан тайёрланган байроқлар ёки матолар ёки қайиқлар учун елканлар, тахталарга ўрнатилган виндсерфинг ёки қуруқлик транспорт воситаларига 63-гуруҳ; (ж) спорт пойабзали (муз ёки ролик конкилар ўрнатилган конкида учиш ботинкаларидан ташқари) 64-гуруҳда ёки спорт бош кийимлари 65-гуруҳда; (з) отда юриш учун таёқ, хивич ва қамчилар ёки ўхшаш буюмлар(6602 товар позицияси) ёки уларнинг қисмлари (6603 товар позицияси); (и) қўғирчоқ ёки 7018 товар позициясининг бошқа ўйинчоқлари учун ўрнатилмаган шиша кўзлар; (к) XV бўлим изоҳларининг 2-бандида кўрсатилган ноқимматбаҳо металлардан тайёрланган умумий мақсад учун қисмлари (XV бўлим), ёки пластмассадан тайёрланган шу каби қисмлар (39-гуруҳ); (л) 8306 товар позициясидаги қўнғироқлар, бонглар ёки шу каби буюмлар; (м) суюқлик насослари (8413 товар позицияси), суюқлик ёки газларни фильтрлаш ёки тозалаш учун ускуна ва қурилмалар (8421 товар позицияси), электр моторлари (8501 товар позицияси), электр трансформаторлари (8504 товар позицияси), маълумотларни сақлаш дисклари, тасмалари, қаттиқ жисмли энергияга боғлиқ бўлмаган қурилмалари, “интеллектуаль карточкалар” ва овозни ёки бошқа ҳодисаларни ёзиб олиш учун мўлжалланган бошқа ташувчилар, ёзилган ёки ёзилмаган (8523 товар позицияси), масофадан бошқариш радиоаппарати (8526 товар позицияси) ёки масофадан бошқариш учун симсиз инфрақизил қурилмалар (8543 товар позицияси); (н) XVII бўлимдаги спорт транспорт воситалари (бобслей чаналари, тобогганлар ва шунга ўхшаш буюмлардан ташқари); (о) икки ғилдиракли болалар велосипедлари (8712 товар позицияси); (п) учувчисиз учиш аппаратлари (8806 товар позицияси); (р) каноэ ва скифлар каби спорт қайиқлари (89-гуруҳ) ёки уларни ҳаракатга келтириш воситалари (ёғочдан тайёрланганлари 44-гуруҳга киритилади); (с) кўзойнаклар, ҳимоя кўзойнаклари ёки спорт ёки очиқ ҳаводаги ўйинлар учун шу каби буюмлар (9004 товар позицияси); (т) маноклар ёки ҳуштаклар (9208 товар позицияси); (у) 93-гуруҳдаги қурол ёки бошқа буюмлар; (ф) барча турдаги чироқ гирляндлари ( 9405 товар позицияси); (х) якка таянчлар, икки оёқлар, уч оёқлар ва шу каби буюмлар (9620 товар позицияси) (ц) ракетка симлари, чодирлар (палатка) ёки кемпинг учун бошқа жиҳозлар, ёки бармоқлари ажратилган қўлқоплар, бошмалдоқдан бошқа бармоқлари ажратилмаган қўлқоплар ва митенкалар (тайёрланган материалига қараб таснифланадиганлар); ёки (ч) овқатланиш хонаси ва ошхона идишлари, овқатланиш ва ошхона анжомлари, пардоз- андоз буюмлари, гиламлар ва бошқа тўқимачилик пол қопламалари, кийим-кечаклар, амалиётда фойдаланиш учун мўлжалланган кўрпа-тўшак, овқатланиш хонаси, пардоз- андоз, ошхона бельёлари ва шу каби буюмлар (тайёрланган материалига қараб таснифланади).","2. Ушбу гуруҳга таркибидаги табиий ёки ўстирилган марварид, қиматбаҳо ёки яримқимматбаҳо тошлар (табиий, суньий ёки тикланган), қимматбаҳо металлар ёки қимматбаҳо металлар билан қопланган ноқимматбаҳо металлар аҳамиятсиз қисмни ташкил қиладиган буюмлар киритилади.","3. Ушбу гуруҳ изоҳларининг 1-банди талаблари риоя қилган ҳолда, фақат ёки асосан ушбу гуруҳнинг товарлари билан биргаликда фойдаланиш учун мўлжалланган қисмлар ва жихозлар ушбу товарлар билан биргаликда таснифланиши керак.","4. Юқоридаги 1-изоҳнинг талаблари риоя қилган ҳолда, 9503 товар позициясига, inter alia, ушбу товар позицияси буюмларининг талқин этишнинг асосий қоидаларининг 3(б) қоидасига мувофиқ тўпламлар сифатида қаралиши мумкин бўлмаган ва агар алоҳида тақдим этилса, бошқа товар позицияларида таснифланиши мумкин бўлган битта ёки бир нечта предметлар билан бирга қўшилгани киритилади, шу шарт биланки буюмлар бирга чакана савдода сотиш учун қадоқланган ва уларнинг қўшилганлиги ўйинчоқларнинг асосий хусусиятига эга.","5. 9503 товар позициясига вазифаси, шакли ёки улар тайёрланган материалига мувофиқ фақат ҳайвонлар учун мўлжалланганлигини аниқлаш мумкин бўлган товарлар киритилмайди, масалан “уй ҳайвонлари учун ўйинчоқлар” (улар ўзларига тегишли мос позицияларда таснифланади).","6. 9508 товар позициясида: (а) “томоша боғ аттракционлар” ибораси ўйин кулги ёки кўнгилочар мақсадларда, одамларнинг кўнглини чоғ қилиш, овунтириш мақсадида уларни белгиланган ёки чегараланган йўналиш бўйлаб, шу жумладан сув оқимлари бўйлаб олиб юрадиган, ташийдиган ёки бошқарадиган қурилма ёки қурилмалар комбинацияси ва ускуналарни англатади. Бундай аттракционлар томоша боғларда, мавзумий боғда, сувли боғда ёки ярмарка майдончасида жойлашган бўлиши мумкин. Ушбу томоша боғ аттракционларда одатда турар жой бинолари ёки ўйин майдончаларида ўрнатиладиган ускуналарни ўз ичига олмайди; (б) “аквапарк аттракционлар” ибораси тартибга солинадиган маршрутга эга бўлмаган маълум бир сув минтақаси ҳудудига ўрнатиладиган қурилма ёки қурилмалар ва ускуналарнинг жамланмасини англатади. Аквапарк аттракционлар фақат махсус аквапарклар учун мўлжалланган ускуналарни ўз ичига олади; ва (в) “ярмарка аттракционлар” ибораси одатда оператор ёки хизмат кўрсатувчи шахс иштирок этадиган, стационар бинолар ёки савдо павильонларида ташкил этилиши мумкин бўлган тасодифий ҳолатлар, куч ёки махорат намоён бўлиши билан боғлиқ ўйин кулгуларни ва томошаларни англатади. Ярмарка аттракционларига 9504 товар позициясидаги ускуналар кирмайди. Ушбу товар позициясига Номенклатуранинг бошқа жойида тавсифи аниқроқ берилган ускуналар киритилмайди. Субпозицияларга изоҳ:","1. 9504 50 субпозициясига қўйидагилар киради: (а) телевизион қабул қилувчи, монитор ёки бошқа ташқи экран ёки сирт ёрдамида тасвир қайта тикланадиган консоллар; ёки (б) экран ўрнатилган видео ўйинлар учун ускуналар, портатив ёки портатив бўлмаган. Ушбу субпозицияга тангалар, банкноталар, банк карточкалари, жетонлар ёки ҳар қандай бошқа тўлов воситалари билан ишга тушириладиган видео ўйинлар учун консоллар ва ускуналар киритилмайди (9504 30 субпозиция). Қўшим ча"],"excl":["1. Ушбу гуруҳга қуйидагилар киритилмайди: (а) шамлар (3406 товар позицияси); (б) 3604 товар позициясидаги мушакбозлик ёки бошқа пиротехник буюмлари; (в) йигирилган иплар, моноиплар, шнурлар ёки торлар (струна) ёки балиқ ови учун маълум узунликка эга бўлган, бироқ 39-гуруҳ, 4206 товар позицияси ёки XI бўлимга кирувчи балиқ ови учун чилвир шаклида тайёрланмаган шунга ўхшаш буюмлар; (г) спорт сумкалари ёки 4202, 4303 ёки 4304 товар позицияларининг бошқа буюмлари; (д) тўқимачилик материалларидан тайёрланган маскарад либослари (61 ёки 62-гуруҳ), спорт кийимлари ва тўқимачилик материалларидан тайёрланган махсус кийимлар (61 ёки 62-гуруҳлар) хусусан, тирсак сохасида тўлдирилган қатламли ямоқлар каби химоя қисмларига эга бўлган ёки бўлмаган, тиззалар ёки чов қисмида ҳимоя компонентларига эга бўлган ёки эга бўлмаган махсус предметлари (масалан, қиличбозлик кийимлари ёки футбол дарвозабонларининг свитерлари); (е) тўқимачилик материалларидан тайёрланган байроқлар ёки матолар ёки қайиқлар учун елканлар, тахталарга ўрнатилган виндсерфинг ёки қуруқлик транспорт воситаларига 63-гуруҳ; (ж) спорт пойабзали (муз ёки ролик конкилар ўрнатилган конкида учиш ботинкаларидан ташқари) 64-гуруҳда ёки спорт бош кийимлари 65-гуруҳда; (з) отда юриш учун таёқ, хивич ва қамчилар ёки ўхшаш буюмлар(6602 товар позицияси) ёки уларнинг қисмлари (6603 товар позицияси); (и) қўғирчоқ ёки 7018 товар позициясининг бошқа ўйинчоқлари учун ўрнатилмаган шиша кўзлар; (к) XV бўлим изоҳларининг 2-бандида кўрсатилган ноқимматбаҳо металлардан тайёрланган умумий мақсад учун қисмлари (XV бўлим), ёки пластмассадан тайёрланган шу каби қисмлар (39-гуруҳ); (л) 8306 товар позициясидаги қўнғироқлар, бонглар ёки шу каби буюмлар; (м) суюқлик насослари (8413 товар позицияси), суюқлик ёки газларни фильтрлаш ёки тозалаш учун ускуна ва қурилмалар (8421 товар позицияси), электр моторлари (8501 товар позицияси), электр трансформаторлари (8504 товар позицияси), маълумотларни сақлаш дисклари, тасмалари, қаттиқ жисмли энергияга боғлиқ бўлмаган қурилмалари, “интеллектуаль карточкалар” ва овозни ёки бошқа ҳодисаларни ёзиб олиш учун мўлжалланган бошқа ташувчилар, ёзилган ёки ёзилмаган (8523 товар позицияси), масофадан бошқариш радиоаппарати (8526 товар позицияси) ёки масофадан бошқариш учун симсиз инфрақизил қурилмалар (8543 товар позицияси); (н) XVII бўлимдаги спорт транспорт воситалари (бобслей чаналари, тобогганлар ва шунга ўхшаш буюмлардан ташқари); (о) икки ғилдиракли болалар велосипедлари (8712 товар позицияси); (п) учувчисиз учиш аппаратлари (8806 товар позицияси); (р) каноэ ва скифлар каби спорт қайиқлари (89-гуруҳ) ёки уларни ҳаракатга келтириш воситалари (ёғочдан тайёрланганлари 44-гуруҳга киритилади); (с) кўзойнаклар, ҳимоя кўзойнаклари ёки спорт ёки очиқ ҳаводаги ўйинлар учун шу каби буюмлар (9004 товар позицияси); (т) маноклар ёки ҳуштаклар (9208 товар позицияси); (у) 93-гуруҳдаги қурол ёки бошқа буюмлар; (ф) барча турдаги чироқ гирляндлари ( 9405 товар позицияси); (х) якка таянчлар, икки оёқлар, уч оёқлар ва шу каби буюмлар (9620 товар позицияси) (ц) ракетка симлари, чодирлар (палатка) ёки кемпинг учун бошқа жиҳозлар, ёки бармоқлари ажратилган қўлқоплар, бошмалдоқдан бошқа бармоқлари ажратилмаган қўлқоплар ва митенкалар (тайёрланган материалига қараб таснифланадиганлар); ёки (ч) овқатланиш хонаси ва ошхона идишлари, овқатланиш ва ошхона анжомлари, пардоз- андоз буюмлари, гиламлар ва бошқа тўқимачилик пол қопламалари, кийим-кечаклар, амалиётда фойдаланиш учун мўлжалланган кўрпа-тўшак, овқатланиш хонаси, пардоз- андоз, ошхона бельёлари ва шу каби буюмлар (тайёрланган материалига қараб таснифланади).","5. 9503 товар позициясига вазифаси, шакли ёки улар тайёрланган материалига мувофиқ фақат ҳайвонлар учун мўлжалланганлигини аниқлаш мумкин бўлган товарлар киритилмайди, масалан “уй ҳайвонлари учун ўйинчоқлар” (улар ўзларига тегишли мос позицияларда таснифланади).","6. 9508 товар позициясида: (а) “томоша боғ аттракционлар” ибораси ўйин кулги ёки кўнгилочар мақсадларда, одамларнинг кўнглини чоғ қилиш, овунтириш мақсадида уларни белгиланган ёки чегараланган йўналиш бўйлаб, шу жумладан сув оқимлари бўйлаб олиб юрадиган, ташийдиган ёки бошқарадиган қурилма ёки қурилмалар комбинацияси ва ускуналарни англатади. Бундай аттракционлар томоша боғларда, мавзумий боғда, сувли боғда ёки ярмарка майдончасида жойлашган бўлиши мумкин. Ушбу томоша боғ аттракционларда одатда турар жой бинолари ёки ўйин майдончаларида ўрнатиладиган ускуналарни ўз ичига олмайди; (б) “аквапарк аттракционлар” ибораси тартибга солинадиган маршрутга эга бўлмаган маълум бир сув минтақаси ҳудудига ўрнатиладиган қурилма ёки қурилмалар ва ускуналарнинг жамланмасини англатади. Аквапарк аттракционлар фақат махсус аквапарклар учун мўлжалланган ускуналарни ўз ичига олади; ва (в) “ярмарка аттракционлар” ибораси одатда оператор ёки хизмат кўрсатувчи шахс иштирок этадиган, стационар бинолар ёки савдо павильонларида ташкил этилиши мумкин бўлган тасодифий ҳолатлар, куч ёки махорат намоён бўлиши билан боғлиқ ўйин кулгуларни ва томошаларни англатади. Ярмарка аттракционларига 9504 товар позициясидаги ускуналар кирмайди. Ушбу товар позициясига Номенклатуранинг бошқа жойида тавсифи аниқроқ берилган ускуналар киритилмайди. Субпозицияларга изоҳ:","1. 9504 50 субпозициясига қўйидагилар киради: (а) телевизион қабул қилувчи, монитор ёки бошқа ташқи экран ёки сирт ёрдамида тасвир қайта тикланадиган консоллар; ёки (б) экран ўрнатилган видео ўйинлар учун ускуналар, портатив ёки портатив бўлмаган. Ушбу субпозицияга тангалар, банкноталар, банк карточкалари, жетонлар ёки ҳар қандай бошқа тўлов воситалари билан ишга тушириладиган видео ўйинлар учун консоллар ва ускуналар киритилмайди (9504 30 субпозиция). Қўшим ча"]},"96":{"title":"ТУРЛИ ТАЙЁР БУЮМЛАР","section":"XX","notes":["1. Ушбу гуруҳга киритилмайди: (а) косметика ёки гигиена мақсадлари учун қаламлар (33-гуруҳ); (б) 66-гуруҳ буюмлари (масалан, соябонларнинг ёки тростларнинг қисмлари); (в) бижутерия (7117 товар позицияси); (г) XV бўлим изоҳларининг 2-бандида кўрсатилган ноқимматбаҳо металлардан тайёрланган умумий мақсад учун қисмлар (XV бўлим), ёки пластмассадан тайёрланган шу каби қисмлар (39-гуруҳ); (д) 82-гуруҳнинг соплари ёки бошқа қисмлари ўймакорлик ёки қуйма материаллардан бўлган пичоқ ва бошқа буюмлари; бироқ бу буюмларнинг алоҳида тақдим этилган соплари ёки бошқа қисмлари 9601 ёки 9602 товар позициясига киритилади; (е) 90-гуруҳ буюмлари (масалан, кўзойнак учун оправалар (9003 товар позицияси), рейсфедерлар (9017 товар позицияси), стоматологияда ёки терапевтик, жарроҳлик ёки ветеринария мақсадлари учун ишлатишга мўлжалланган чўткалар (9018 товар позицияси)); (ж) 91-гуруҳ буюмлари (масалан, барча турдаги соатлар корпуслари); (з) мусиқа асбоблари ёки уларнинг қисм ва жихозлари (92-гуруҳ); (и) 93-гуруҳ буюмлари (қурол ва унинг қисмлари); (к) 94-гуруҳ буюмлари (масалан, мебель, ёритгичлар ва ёритиш ускуналари); (л) 95-гуруҳ буюмлари (ўйинчоқлар, ўйинлар, спорт анжомлари); ёки (м) санъат асарлари, коллекциялаш предметлари ёки антиквариат (97-гуруҳ).","2. 9602 товар позициясида “ўймакорлик учун яроқли ўсимлик ёки минераллардан тайёрланган материаллар” атамаси қуйидагиларни ифодалайди: (а) қаттиқ уруғлар, донлар, ёнғоқлар, ёнғоқ пўчоқлари ва ўймакорлик учун фойдаланиладиган ўсимлик материаллари (масалан, корозо ва дум); (б) қаҳрабо ва сепиолит, табиий ва йирик агромерацияланган, гагату ва гагатуга ўхшаш минераллар.","3. 9603 товар позициясида “супурги ёки чўткали буюмлар тайёрлаш учун ҳозирланган тугун ва боғламлар” атамаси ҳайвонлар жуни, ўсимлик толалари ёки бошқа материаллардан супурги ёки чўткаларни тайёрлашга қайта боғламасдан тайёр бўлган ёки уларни йиғишга тайёрлаш учун сиртини текислаш ва маълум шаклда кесиш каби арзимас ишлов талаб қиладиган тартибланмаган тугун ва боғламларни англатади.","4. Ушбу гуруҳга қуйидаги буюмлар (9601 – 9606 ёки 9615 товар позицияларида кўрсатилганларидан ташқари) тўлиқ ёки қисман қимматбаҳо металлардан, табиий ёки ўстирилган марварид, қимматбаҳо ёки яримқимматбаҳо (табиий, суньий ёки тикланган) тошлардан иборат бўлиши ёки қимматбаҳо металлар билан қопланганлигидан қатьий назар киритилади. Бироқ 9601 – 9606 ёки 9615 товар позицияларига таркибидаги табиий ёки ўстирилган марварид, қиматбаҳо ёки яримқимматбаҳо тошлар (табиий, суньий ёки тикланган), қимматбаҳо металлар ёки қимматбаҳо металлар билан қопланган металлар фақат аҳамиятсиз қисмни ташкил қиладиган буюмлар киритилади."],"excl":["1. Ушбу гуруҳга киритилмайди: (а) косметика ёки гигиена мақсадлари учун қаламлар (33-гуруҳ); (б) 66-гуруҳ буюмлари (масалан, соябонларнинг ёки тростларнинг қисмлари); (в) бижутерия (7117 товар позицияси); (г) XV бўлим изоҳларининг 2-бандида кўрсатилган ноқимматбаҳо металлардан тайёрланган умумий мақсад учун қисмлар (XV бўлим), ёки пластмассадан тайёрланган шу каби қисмлар (39-гуруҳ); (д) 82-гуруҳнинг соплари ёки бошқа қисмлари ўймакорлик ёки қуйма материаллардан бўлган пичоқ ва бошқа буюмлари; бироқ бу буюмларнинг алоҳида тақдим этилган соплари ёки бошқа қисмлари 9601 ёки 9602 товар позициясига киритилади; (е) 90-гуруҳ буюмлари (масалан, кўзойнак учун оправалар (9003 товар позицияси), рейсфедерлар (9017 товар позицияси), стоматологияда ёки терапевтик, жарроҳлик ёки ветеринария мақсадлари учун ишлатишга мўлжалланган чўткалар (9018 товар позицияси)); (ж) 91-гуруҳ буюмлари (масалан, барча турдаги соатлар корпуслари); (з) мусиқа асбоблари ёки уларнинг қисм ва жихозлари (92-гуруҳ); (и) 93-гуруҳ буюмлари (қурол ва унинг қисмлари); (к) 94-гуруҳ буюмлари (масалан, мебель, ёритгичлар ва ёритиш ускуналари); (л) 95-гуруҳ буюмлари (ўйинчоқлар, ўйинлар, спорт анжомлари); ёки (м) санъат асарлари, коллекциялаш предметлари ёки антиквариат (97-гуруҳ).","4. Ушбу гуруҳга қуйидаги буюмлар (9601 – 9606 ёки 9615 товар позицияларида кўрсатилганларидан ташқари) тўлиқ ёки қисман қимматбаҳо металлардан, табиий ёки ўстирилган марварид, қимматбаҳо ёки яримқимматбаҳо (табиий, суньий ёки тикланган) тошлардан иборат бўлиши ёки қимматбаҳо металлар билан қопланганлигидан қатьий назар киритилади. Бироқ 9601 – 9606 ёки 9615 товар позицияларига таркибидаги табиий ёки ўстирилган марварид, қиматбаҳо ёки яримқимматбаҳо тошлар (табиий, суньий ёки тикланган), қимматбаҳо металлар ёки қимматбаҳо металлар билан қопланган металлар фақат аҳамиятсиз қисмни ташкил қиладиган буюмлар киритилади."]},"97":{"title":"САНЪАТ АСАРЛАРИ, КОЛЛEКЦИЯЛАШ БУЮМЛАРИ ВА АНТИКВАРИАТ","section":"XXI","notes":["1. Ушбу гуруҳга қуйидагилар кирмайди: (а) почта маркалари ёки бекор қилинмаган давлат божи маркалари, почта канцелярия жихозлари (гербли қоғоз) ёки 4907 позициядаги шу каби товарлар; (б) театр декорациялари, бадиий студия тўри декарациялари ёки матога чизилган шу каби буюмлар (5907 товар позицияси), 9706 товар позициясига киритилиши мумкин бўлганлардан ташқари; ёки (в) марваридлар, табиий ёки маданийлаштирилган, ёки қимматбаҳо ёки ярим қимматбаҳо"],"excl":["1. Ушбу гуруҳга қуйидагилар кирмайди: (а) почта маркалари ёки бекор қилинмаган давлат божи маркалари, почта канцелярия жихозлари (гербли қоғоз) ёки 4907 позициядаги шу каби товарлар; (б) театр декорациялари, бадиий студия тўри декарациялари ёки матога чизилган шу каби буюмлар (5907 товар позицияси), 9706 товар позициясига киритилиши мумкин бўлганлардан ташқари; ёки (в) марваридлар, табиий ёки маданийлаштирилган, ёки қимматбаҳо ёки ярим қимматбаҳо"]}},"opi":[{"rule":1,"text":"Бўлимларнинг, гуруҳларнинг ва кичик гуруҳларнинг номлари ТИФ ТНдан фойдаланишда қулайлик бўлиши учунгина келтирилган; юридик мақсадлар учун товарларни ТИФ ТН бўйича таснифлаш товар позицияларининг номлари ва бўлимларга ёки гуруҳларга берилган тегишли изолардан келиб чиққан ҳолда ва агар бундай матнларда бошқа қоида назарда тутилмаган бўлса, қуйидаги қоидаларга мувофиқ амалга оширилади:"},{"rule":2,"text":"(а) Агар тўлиқ бўлмаган ёки тугалланмаган шаклда тақдим этилган товар тўлиқ ёки тугалланган товарнинг асосий хусусиятларига эга бўлса, товар позицияси номида бирор товарга кўрсатилган ҳар қандай ҳавола тўлиқ бўлмаган ёки тугалланмаган шаклдаги шундай товарга ҳам кўрсатилган ҳавола, шунингдек, йиғилмаган ёки қисмларга ажратилган ҳолатда тақдим этилган тўлиқ ёки тугалланган товарга кўрсатилган ҳавола (ёки мазкур Қоидага биноан кўриб чиқилаётган товар позициясида комплект ёки тугалланган товар сифатида таснифланувчи) деб қаралиши зарур. (б) Товар позицияси номида бирор материал ёки моддага келтирилган ҳар қандай ҳавола ушбу материалнинг ёки модданинг бошқа материал ёки моддалар билан аралашмаси ёки бирикмасига ҳам келтирилган ҳавола деб қаралиши зарур. Муайян бир материал ёки моддадан тайёрланган товарга келтирилган ҳар қандай ҳавола тўлиқ ёки қисман ушбу материал ёки моддадан иборат бўлган товарларга ҳам келтирилган ҳавола деб қаралиши зарур. Бирдан ортиқ материал ёки моддадан ташкил топган товарларни таснифлаш 3- Қоида талабларига мувофиқ амалга оширилади."},{"rule":3,"text":"Агар, 2(б) Қоидага мувофиқ ёки бошқа сабабга кўра, prima facie, товарларни икки ёки ундан ортиқ товар позициясига киритиш имконияти мавжуд бўлса, бундай товарларни таснифлаш қуйидагича амалга оширилади: (а) Умумий тавсифга эга бўлган товар позицияси номларига қараганда товарларнинг нисбатан аниқроқ тавсифини ўз ичига олган товар позицияси номларига устунлик берилади. Бироқ, икки ёки ундан ортиқ товар позицияларининг ҳар бири фақат аралаш ёки кўп компонентли буюмлар таркибидаги материаллар ёки моддаларнинг бир қисмига ёки чакана савдо учун тўпламда тақдим этилган товарларнинг фақат бир қисмига тегишли бўлса, бу ҳолда мазкур товар позициялари, ҳатто улардан бири товарнинг анча тўлиқ ёки аниқ тавсифини берсада, ушбу товарга нисбатан эквивалент сифатида қаралиши керак. (б) Таснифланишини 3(а) Қоида талабларига мувофиқ амалга ошириб бўлмайдиган аралашмалар, турли материаллардан таркиб топган ёки турли компонентлардан тайёрланган кўп компонентли буюмлар, ҳамда чакана савдода сотишга мўлжалланган тўпламда тақдим этилган товарлар, ушбу меъзонни қўллаш шарти билан, уларга асосий хусусиятларни берадиган материаллар ёки таркибий қисмлар бўйича таснифланиши керак. 2 (в) Таснифланишини 3(а) ва 3(б) Қоида талабларига мувофиқ амалга ошириб бўлмайдиган товарлар, мазкур товарларни таснифлашда кўриб чиқиш учун тенг даражада мақбул бўлган товар позициялари орасидан, кодларни ортиб бориш тартибида охирги товар позициясида таснифланиши зарур."},{"rule":4,"text":"Таснифланиши юқорида баён қилинган Қоидаларнинг талабларига мувофиқ амалга ошириб бўлмайдиган товарлар, кўриб чиқилаётган товарлар билан энг ўхшаш (яқин) бўлган товарларга мос келувчи товар позициясида таснифланади."},{"rule":5,"text":"Юқорида келтирилган қоидаларга қўшимча равишда, қуйида қайд этилган товарларга нисбатан қуйидаги қоидалар қўлланиши зарур: (а) Фотоаппаратлар, мусиқа асбоблари, қурол-яроғлар, чизмачилик анжомлари, тақинчоқлар учун ғилофлар ва жилдлар, шунингдек уларга ўхшаш, тегишли буюмни ёки буюмлар тўпламини жойлаштириш учун махсус шаклга эга ёки мослаштирилган, узоқ муддат фойдаланиш учун яроқли ва ўзига мўлжалланган буюмлар билан бирга тақдим этилган таралар, агар шундай кўринишдаги тара одатда савдога мазкур буюмлар билан бирга чиқариладиган бўлса, уларга қадоқланган буюмлар билан биргаликда таснифланиши лозим. Аммо, мазкур Қоида қадоқланган буюм билан бир яхлитликни ташкил этган ҳолда, ушбу яхлитликнинг асосий хусусиятини берадиган тарага нисбатан қўлланилмайди. (б) Юқорида келтирилган 5(а) Қоида талабларига мувофиқ, ичидаги товарлар билан бирга етказиб бериладиган ўров материаллари ва таралар, агар улар одатда мазкур товарларни ўраш учун қўлланиладиган кўринишда бўлса, улар биргаликда таснифланиши лозим. Лекин, бундай ўров материали ва тараларнинг такроран қўллаш учун яроқлилиги шубҳасиз бўлса, мазкур қоида мажбурий ҳисобланмайди."},{"rule":6,"text":"Юридик мақсадларда товарларни товар позициясининг субпозицияларида таснифлаш субпозицияларнинг номлари ва субпозицияларга тааллуқли бўлган изоҳларга мувофиқ, шунингдек, mutatis mutandis, таққослашлар фақат битта даражадаги субпозициялар ўртасида амалга оширилиши шарти билан юқорида айтиб ўтилган Қоидалар талабига кўра амалга оширилиши зарур. Агар контекстда бошқача талқин бўлмаса, мазкур Қоида мақсадларида бўлимлар ва гуруҳларга берилган тегишли изоҳлар ҳам қўлланилиши мумкин. 3"}],"units_ref":[{"code":"166","label":"Килограмм кг"},{"code":"163","label":"Грамм г"},{"code":"306","label":"Парчаланувчи изотопларнинг грамми г Д/И"},{"code":"055","label":"Квадрат метр м2"},{"code":"861","label":"Килограмм азот кг N"},{"code":"859","label":"Килограмм калий гидроксид кг KOH"},{"code":"863","label":"Килограмм натрий гидроксид кгNaOH"},{"code":"852","label":"Килограмм калий оксид кг K O"},{"code":"841","label":"Килограмм пероксид водород кг H O"},{"code":"865","label":"Килограмм пятиокис фосфор кг P O"},{"code":"845","label":"Килограмм 90-фоизлик қуруқ модда кг 90% қ/м"},{"code":"867","label":"Килограмм уран кг U"},{"code":"113","label":"Куб метр м3"},{"code":"305","label":"Кюри Ки"},{"code":"112","label":"Литр л"},{"code":"831","label":"Тоза (100%) спирт литри л 100% спирт"},{"code":"006","label":"Метр м"},{"code":"162","label":"Метрик карат (1 карат= 200 мг =2·10-4 кг) кар"},{"code":"715","label":"Жуфт жуфт"},{"code":"797","label":"Юз дона 100 дона"},{"code":"798","label":"Минг дона 1000 дона"},{"code":"796","label":"Дона дона"},{"code":"246","label":"1000 киловатт-соат 1000 кВт·ч"},{"code":"114","label":"1000 кубметр 1000 м3"},{"code":"130","label":"1000 литр 1000 л"}]};
